INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('b3ca5dec-7ea2-5f48-a4cc-96555aa2eb1d', '369c66c4-34af-5b53-ae43-2d89c2a79f6b', '91f46a74-7011-557c-ada4-b5be9cd46ed8', 5, 5, 'በአራተኛውም ቀን ማልደው ተነሡ፤ እርሱም ለመሄድ ተነሣ፤ የብላቴናዪቱም አባት አማቹን፥ “ሰውነትህን በቁራሽ እንጀራ አበርታ፤ ከዚያም በኋላ ትሄዳላችሁ” አለው።'),
  ('3b06d8d7-5a5e-5c6d-a6d9-f2a82c099a1f', '369c66c4-34af-5b53-ae43-2d89c2a79f6b', '91f46a74-7011-557c-ada4-b5be9cd46ed8', 6, 6, 'ሁለቱም በአንድ ላይ ተቀመጡ፤ በሉም፤ ጠጡም፤ የብላቴናዪቱም አባት ሰውዬውን፥ “ዛሬ ደግሞ ከዚህ እደር ልብህንም ደስ ይበለው” አለው።'),
  ('dec2e39e-304c-55fe-a72e-6ca88fc9d3be', '369c66c4-34af-5b53-ae43-2d89c2a79f6b', '91f46a74-7011-557c-ada4-b5be9cd46ed8', 7, 7, 'ሰውዬውም ሊሄድ ተነሣ፤ አማቱ ግን ግድ አለው፤ ዳግመኛም በዚያ አደረ።'),
  ('14e6ca7a-ff1c-5637-abdf-4cfb0206a8eb', '369c66c4-34af-5b53-ae43-2d89c2a79f6b', '91f46a74-7011-557c-ada4-b5be9cd46ed8', 8, 8, 'በአምስተኛውም ቀን ለመሄድ ማልዶ ተነሣ፤ የብላቴናዪቱም አባት፥ “እህል ብላ፤ ከዚህም በኋላ ፀሐይ ሲበርድ ትሄዳለህ” አለው። ሁለቱም በሉ፤ ጠጡም።'),
  ('fa86c787-1ccc-507f-ac42-15e47bbf7b3d', '369c66c4-34af-5b53-ae43-2d89c2a79f6b', '91f46a74-7011-557c-ada4-b5be9cd46ed8', 9, 9, 'ሰውዬውም ከዕቅብቱና ከብላቴናው ጋር ለመሄድ ተነሣ፤ የብላቴናዪቱ አባት አማቱም፥ “እነሆ፥ መሽትዋል፤ ፀሐዩም ሊጠልቅ ደርሷል፤ ዛሬም እዚህ እደር፤ በዚህም ተቀመጥ፤ ልብህም ደስ ይበለው፤ በጥዋትም መንገዳችሁን ትገሠግሣላችሁ፤ ወደ ቤትህም ትገባለህ” አለው።'),
  ('0ea5fff6-e9e1-5a39-ac53-47242bc1da50', '369c66c4-34af-5b53-ae43-2d89c2a79f6b', '91f46a74-7011-557c-ada4-b5be9cd46ed8', 10, 10, 'ሰውዬው ግን በዚያ ሌሊት ለማደር አልፈቀደም፤ ተነሥቶም ሄደ፤ ኢየሩሳሌምም ወደ ተባለችው ወደ ኢያቡስ ፊት ለፊት ደረሰ። ከእርሱም ጋር ሁለት የተጫኑ አህዮች ነበሩ፤ ዕቅብቱም ከእርሱ ጋር ነበረች።'),
  ('523fb5ba-6738-5fe9-a345-6216d526f243', '369c66c4-34af-5b53-ae43-2d89c2a79f6b', '91f46a74-7011-557c-ada4-b5be9cd46ed8', 11, 11, 'በኢያቡስም አንጻር ገና ሳሉ ፀሐይዋ ተቈለቈለች፤ ብላቴናውም ጌታውን፥ “ና፤ ወደዚህች ወደ ኢያቡሳውያን ከተማ፥ እባክህ እናቅና፤ በእርስዋም እንደር” አለው።'),
  ('dae0f772-a18c-5fb2-a8c5-a8692cd5b1f4', '369c66c4-34af-5b53-ae43-2d89c2a79f6b', '91f46a74-7011-557c-ada4-b5be9cd46ed8', 12, 12, 'ጌታውም፥ “ከእስራኤል ልጆች ወዳልሆነች ወደ እንግዳ ከተማ አንገባም፤ እኛ ወደ ገባዖን እንለፍ” አለው።'),
  ('6d648446-ad87-5c6d-af33-961bef72b770', '369c66c4-34af-5b53-ae43-2d89c2a79f6b', '91f46a74-7011-557c-ada4-b5be9cd46ed8', 13, 13, 'ብላቴናውንም፥ “ና፤ ከእነዚህ ስፍራ ወደ አንዱ እንቅረብ፤ በገባዖን ወይም በራማ እንደር” አለው።'),
  ('48131eff-ec7f-5e24-a35a-0a38ab267d9b', '369c66c4-34af-5b53-ae43-2d89c2a79f6b', '91f46a74-7011-557c-ada4-b5be9cd46ed8', 14, 14, 'አልፈውም ሄዱ፤ የብንያምም ነገድ በምትሆነው በገባዖን አጠገብ ሳሉ ፀሐይ ገባችባቸው።'),
  ('f5a8b737-e635-57e6-a9bf-9fdf5d6f6ad4', '369c66c4-34af-5b53-ae43-2d89c2a79f6b', '91f46a74-7011-557c-ada4-b5be9cd46ed8', 15, 15, 'በገባዖንም ገብተው ያድሩ ዘንድ ወደዚያ አቀኑ። ገብተውም በከተማው አደባባይ በተቀመጡ ጊዜ ወደ ቤቱ የሚያስገባቸውና የሚያሳድራቸው አልነበረም።'),
  ('7680ec70-13e4-5bac-a642-ba86c33f882d', '369c66c4-34af-5b53-ae43-2d89c2a79f6b', '91f46a74-7011-557c-ada4-b5be9cd46ed8', 16, 16, 'እነሆም አንድ ሽማግሌ ከእርሻው ሥራ ወደ ማታ መጣ፤ ይህም ሰው ከተራራማው ከኤፍሬም ሀገር ነበረ፤ በገባዖንም በእንግድነት ተቀምጦ ነበር፤ የዚያ ሀገር ሰዎች ግን የብንያም ልጆች ነበሩ።'),
  ('50343146-4deb-5310-aa64-08f75c06593f', '369c66c4-34af-5b53-ae43-2d89c2a79f6b', '91f46a74-7011-557c-ada4-b5be9cd46ed8', 17, 17, 'ዐይኑንም አንሥቶ መንገደኛውን በከተማው አደባባይ አየ፤ ሽማግሌውም፥ “ወዴት ትሄዳለህ? ከወዴትስ መጣህ?” አለው።'),
  ('d8e72ed9-6b5a-5bc8-abfd-f02a0e615ff5', '369c66c4-34af-5b53-ae43-2d89c2a79f6b', '91f46a74-7011-557c-ada4-b5be9cd46ed8', 18, 18, 'እርሱም፥ “እኛ ከይሁዳ ቤተ ልሔም ወደ ተራራማው ወደ ኤፍሬም ሀገር ማዶ እናልፋለን፤ እኔ ከዚያ ነኝ፤ ወደ ይሁዳ ቤተ ልሔምም ሄጄ ነበር፥ አሁንም ወደ ቤቴ እሄዳለሁ፤ በቤቱም የሚያሳድረኝ አጣሁ፤'),
  ('bc03137f-d993-524b-a5da-ab887abf9b1a', '369c66c4-34af-5b53-ae43-2d89c2a79f6b', '91f46a74-7011-557c-ada4-b5be9cd46ed8', 19, 19, 'ለአህዮቻችን ገለባና ገፈራ አለን፤ ለእኔና ለገረድህ ከባሪያዎችህም ጋር ላለው ብላቴና እንጀራና የወይን ጠጅ አለን፤ ከሚያስፈልገን ሁሉ አንዳችም አላጣንም” አለው።'),
  ('a48d36c1-d568-5c0e-a254-7730645cdb34', '369c66c4-34af-5b53-ae43-2d89c2a79f6b', '91f46a74-7011-557c-ada4-b5be9cd46ed8', 20, 20, 'ሽማግሌውም ሰው፥ “ሰላም ከአንተ ጋር ይሁን፤ የምትሻውንም ሁሉ እኔ እሰጥሃለሁ፤ በአደባባይ ግን አትደር” አለው።'),
  ('f7c67ed0-519b-5e95-a054-0403edef3b45', '369c66c4-34af-5b53-ae43-2d89c2a79f6b', '91f46a74-7011-557c-ada4-b5be9cd46ed8', 21, 21, 'ወደ ቤቱም አስገባው፤ ለአህዮቹም ገፈራ ጣለላቸው፤ እግራቸውንም ታጠቡ፤ በሉም፤ ጠጡም።'),
  ('7cad3e09-e798-5cbb-aea2-0d32a274c836', '369c66c4-34af-5b53-ae43-2d89c2a79f6b', '1906bcd1-8295-5d4c-a2c0-2c5db141379d', 1, 22, 'ሰውነታቸውንም ደስ ባሰኙ ጊዜ የኃጥኣን ልጆች የሆኑ የከተማው ሰዎች ቤቱን ከበቡ፤ በሩንም ይደበድቡ ነበር፤ ባለቤቱንም ሽማግሌውን ሰው፥ “ወደ ቤትህ የገባውን ሰው እንድንደርስበት አውጣልን” አሉት።'),
  ('da011178-7605-58fd-af9e-37906e8ddf98', '369c66c4-34af-5b53-ae43-2d89c2a79f6b', '1906bcd1-8295-5d4c-a2c0-2c5db141379d', 2, 23, 'ባለቤቱም ሽማግሌው ወደ እነርሱ ወጥቶ፥ “ወንድሞቼ ሆይ! ይህን ክፉ ነገር ታደርጉ ዘንድ አይገባችሁም፤ ይህ ሰው ወደ ቤቴ ከገባ በኋላ እንደዚህ ያለ ስንፍና አትሥሩ።'),
  ('06e6209c-3657-56a5-a845-17a72d27d64d', '369c66c4-34af-5b53-ae43-2d89c2a79f6b', '1906bcd1-8295-5d4c-a2c0-2c5db141379d', 3, 24, 'ድንግል ልጄና የእርሱም ዕቅብት እነሆ፥ አሉ፤ አሁንም አወጣቸዋለሁ፤ አዋርዱአቸው፤ በዐይናችሁም ፊት ደስ የሚላችሁን አድርጉባቸው፤ ነገር ግን በዚህ ሰው ላይ እንደዚህ ያለ የስንፍና ሥራ አታድርጉ” አላቸው።'),
  ('9ec67805-27fb-5e9d-aff6-5b1f78b7a92e', '369c66c4-34af-5b53-ae43-2d89c2a79f6b', '1906bcd1-8295-5d4c-a2c0-2c5db141379d', 4, 25, 'ሰዎቹ ግን ሊሰሙት አልፈቀዱም፤ ሰውየውም ዕቅብቱን ይዞ ወደ እነርሱ አወጣላቸው፤ አዋረድዋትም፤ ሌሊቱንም ሁሉ እስኪነጋ ድረስ አመነዘሩባት፤ ጎህም በቀደደ ጊዜ ለቀቁአት።'),
  ('00cc1e17-62a9-525c-ac01-b1e8a1b954d7', '369c66c4-34af-5b53-ae43-2d89c2a79f6b', '1906bcd1-8295-5d4c-a2c0-2c5db141379d', 5, 26, 'ሴቲቱም ማለዳ መጣች፤ ጌታዋም ባለበት በሰውዬው ቤት ደጅ ወድቃ እስኪነጋ ድረስ በዚያ ቀረች።'),
  ('6e832a97-9c19-5bcc-a525-f0b5703e0eac', '369c66c4-34af-5b53-ae43-2d89c2a79f6b', '1906bcd1-8295-5d4c-a2c0-2c5db141379d', 6, 27, 'ጌታዋም ማለዳ ተነሣ፤ የቤቱንም ደጅ ከፈተ፤ መንገዱንም ለመሄድ ወጣ፤ እነሆም፥ ዕቅብቱ ሴት በቤቱ ደጃፍ ላይ ወድቃ፥ እጆችዋም በመድረኩ ላይ ወድቀው አገኛት።'),
  ('9f37b617-93c3-5129-af89-e66ed5f0c3d4', '369c66c4-34af-5b53-ae43-2d89c2a79f6b', '1906bcd1-8295-5d4c-a2c0-2c5db141379d', 7, 28, 'እርሱም፥ “ተነሺ እንሂድ” አላት፤ እርስዋ ግን ሞታ ነበርና አልመለሰችም፤ በዚያ ጊዜም በአህያው ላይ ጫናት፤ ተነሥቶም ወደ ስፍራው ተመለሰ።'),
  ('0a1a85ce-87f8-5869-a441-6ae2757d78ee', '369c66c4-34af-5b53-ae43-2d89c2a79f6b', '1906bcd1-8295-5d4c-a2c0-2c5db141379d', 8, 29, 'ወደ ቤቱም በገባ ጊዜ ካራ አነሣ፤ ዕቅብቱንም ይዞ ከአጥንቶችዋ መለያያ ላይ ለዐሥራ ሁለት ቈራርጦ ወደ እስራኤል ሀገር ሁሉ ሰደደ።'),
  ('34876110-0017-5676-adbb-c1be2d707f02', '369c66c4-34af-5b53-ae43-2d89c2a79f6b', '1906bcd1-8295-5d4c-a2c0-2c5db141379d', 9, 30, 'ከዚያም በኋላ ያያት ሁሉ እንዲህ አለ፥ “እስራኤል ከግብፅ ከወጡ ጀምሮ እስከ ዛሬ ድረስ እንዲህ ያለ ነገር የሆነበት ጊዜ የለም፤ የታየበትም ጊዜ የለም፤” ያም ሰው እነዚያን የላካቸውን ሰዎች እንዲህ ብሎ አዘዛቸው፥ “የእስራኤልን ሰዎች እንዲህ በሏቸው፦ እስራኤል ከግብፅ ከወጡ ጊዜ ጀምሮ እስከ ዛሬ እንዲህ የሆነበት ጊዜ አለን? እናንተ ተመካከሩበት፤ የሚበጀውንም ተነጋገሩ።”'),
  ('1ebc1bc0-bc95-58f8-a2cc-1f301a7cbfea', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', '20712acb-8c23-56d0-ac3c-c5eec12f51f5', 1, 1, 'የእስራኤልም ልጆች ሁሉ ወጡ፤ ማኅበሩም ከዳን እስከ ቤርሳቤህ ድረስ፥ ከገለዓድም ሰዎች ጋር፥ ወደ እግዚአብሔር ወደ መሴፋ እንደ አንድ ሰው ሆነው ተሰበሰቡ።'),
  ('3ff44ef4-3e82-54ac-aba6-e0a825abab9f', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', '20712acb-8c23-56d0-ac3c-c5eec12f51f5', 2, 2, 'ከእስራኤልም ነገድ ሁሉ የሕዝቡ ሁሉ አለቆች ሰይፍ በሚመዝዙ፥ በቍጥርም አራት መቶ ሺህ እግረኞች በሆኑ በእግዚአብሔር ሕዝብ ጉባኤ በእግዚአብሔር ፊት ቆሙ።'),
  ('68c17621-4f73-56bc-a14a-ef93e1298777', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', '20712acb-8c23-56d0-ac3c-c5eec12f51f5', 3, 3, 'የብንያምም ልጆች የእስራኤል ልጆች ወደ መሴፋ እንደ ወጡ ሰሙ። የእስራኤልም ልጆች፥ “ይህ ክፉ ነገር እንደምን እንደ ተደረገ ንገሩን” አሉ።'),
  ('12549bc4-3d91-559e-ad17-3754c63e0d55', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', '20712acb-8c23-56d0-ac3c-c5eec12f51f5', 4, 4, 'የተገደለችውም ሴት ባል ሌዋዊዉ እንዲህ ብሎ መለሰላቸው፥ “እኔና ዕቅብቴ በዚያ ለማደር ወደ ብንያም ሀገር ወደ ገባዖን መጣን።'),
  ('8e6084d5-9fe2-59f5-a247-ffe81b698e26', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', '20712acb-8c23-56d0-ac3c-c5eec12f51f5', 5, 5, 'የገባዖንም ሰዎች ተነሡብን፤ ቤቱንም በሌሊት በእኛ ላይ ከበቡት፤ ሊገድሉኝም ወደዱ፤ ዕቅብቴንም አዋረድዋት፤ አመነዘሩባትም፤ እርስዋም ሞተች።'),
  ('a4940797-dc39-591c-adcb-90edeff61713', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', '20712acb-8c23-56d0-ac3c-c5eec12f51f5', 6, 6, 'እኔም ዕቅብቴን ይዤ በመለያያዋ ቈራረጥኋት፤ በእስራኤልም ዘንድ እንደዚህ ያለ ስንፍና ስለ ሠሩ ወደ እስራኤል ርስት አውራጃ ሁሉ ሰደድሁ።'),
  ('81e24ec6-6709-53d0-a231-f3ef8b652eb6', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', '20712acb-8c23-56d0-ac3c-c5eec12f51f5', 7, 7, 'እነሆ፥ የእስራኤል ልጆች ሆይ፥ ሁላችሁ፥ ምክራችሁንና እዝናታችሁን በዚህ ስጡ።”'),
  ('8618df2d-9e2f-53b5-a659-52681d78b60a', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', '20712acb-8c23-56d0-ac3c-c5eec12f51f5', 8, 8, 'ሕዝቡም ሁሉ እንደ አንድ ሰው ተነሥተው እንዲህ አሉ፥ “ከእኛ ዘንድ ማንም ወደ ሀገሩ አይሄድም፤ ወደ ቤቱም አይመለስም።'),
  ('787f592a-e28e-5f21-a213-b722a2e781ae', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', '20712acb-8c23-56d0-ac3c-c5eec12f51f5', 9, 9, 'አሁንም በገባዖን ላይ እንዲህ አድርጉ፤ በየዕጣችን እንዘምትባቸዋለን።'),
  ('dab195fb-7901-5446-ad5c-c116516e58fe', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', '20712acb-8c23-56d0-ac3c-c5eec12f51f5', 10, 10, 'በእስራኤል ላይ ስላደረጉት ስንፍና ሁሉ የብንያም ገባዖንን ይወጉ ዘንድ ለሚሄዱ ሕዝብ በመንገድ ስንቅ የሚይዙ ከእስራኤል ነገድ ሁሉ ከመቶው ዐሥር ሰው፥ ከሺሁም መቶ ሰው፥ ከዐሥሩም ሺህ አንድ ሺህ ሰው እንወስዳለን።”'),
  ('a5bfb505-6f90-5b70-a42d-5bf430c96a23', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', '20712acb-8c23-56d0-ac3c-c5eec12f51f5', 11, 11, 'የእስራኤልም ሰዎች ሁሉ እንደ አንድ ሰው ሆነው በከተማዪቱ ላይ ተሰበሰቡ።'),
  ('404d9209-5d3f-5aee-aa93-b78deca169bf', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', '20712acb-8c23-56d0-ac3c-c5eec12f51f5', 12, 12, 'የእስራኤልም ነገዶች፥ “በእናንተ መካከል የተደረገ ይህ ክፉ ነገር ምንድን ነው?” ብለው ወደ ብንያም ነገድ ሁሉ ሰዎችን ላኩ።'),
  ('ce78e735-857a-508d-a9f8-4d5fa01f26a6', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', '20712acb-8c23-56d0-ac3c-c5eec12f51f5', 13, 13, '“አሁንም በገባዖን ውስጥ የበደሉ የዐመፅ ሰዎችን እንድንገድላቸው አውጥታችሁ ስጡን፤ ከእስራኤልም ልጆች ክፋትን እናርቃለን።” የብንያም ልጆች ግን የወንድሞቻቸውን የእስራኤልን ልጆች ቃል ሊሰሙ አልወደዱም።'),
  ('25cbb475-a9da-5688-aeba-dc74c43d93de', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', '20712acb-8c23-56d0-ac3c-c5eec12f51f5', 14, 14, 'የብንያምም ልጆች ከእስራኤል ልጆች ጋር ሊዋጉ ከየከተማዎቻቸው ወደ ገባዖን ተሰበሰቡ።'),
  ('f0004966-ccc5-564c-ae7a-98ad2358ae85', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', '20712acb-8c23-56d0-ac3c-c5eec12f51f5', 15, 15, 'በዚያም ቀን ከየከተማው የመጡ የብንያም ልጆች ተቈጠሩ፤ ቍጥራቸውም ከገባዖን ሰዎች ሌላ ሃያ አምስት ሺህ ሰይፍ የሚመዝዙ ሰዎች ነበሩ፤ ከገባዖንም ሰባት መቶ የተመረጡ ሰዎች ተቈጠሩ፤'),
  ('55a456ed-1c72-5cc9-a242-29c08eeda91b', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', '20712acb-8c23-56d0-ac3c-c5eec12f51f5', 16, 16, 'ከእነዚያም ሕዝብ ሁሉ ሰባት መቶ የተመረጡ፥ ሁለቱም እጆቻቸው ቀኝ የሆኑላቸው ሰዎች ነበሩ፤ እነዚህም ሁሉ ድንጋይ ይወነጭፉ ነበር፤ አንዲት ጠጕርስ እንኳ አይስቱም ነበር።'),
  ('1e1b75a3-67a6-55e5-acc9-4027017603b5', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', '20712acb-8c23-56d0-ac3c-c5eec12f51f5', 17, 17, 'ከብንያምም ልጆች ሌላ የእስራኤል ሰዎች አራት መቶ ሺህ ሰይፍ የሚመዝዙ ሰዎች ተቈጠሩ፤ እነዚህም ሁሉ ሰልፈኞች ነበሩ።'),
  ('38cb0d16-5099-5ec5-a86e-74fd80decdf4', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', '20712acb-8c23-56d0-ac3c-c5eec12f51f5', 18, 18, 'የእስራኤልም ልጆች ተነሥተው ወደ ቤቴል ወጡ፤ እግዚአብሔርንም፥ “የብንያምን ልጆች ለመውጋት መሪ ሆኖ ማን ይውጣልን?” ብለው ጠየቁት፤ እግዚአብሔርም፥ “ይሁዳ መሪ ይሁን” አለ፤'),
  ('2d52c76f-8ab6-5873-ab1c-a56ba4e1cbac', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', '20712acb-8c23-56d0-ac3c-c5eec12f51f5', 19, 19, 'የእስራኤልም ልጆች በማለዳ ተነሥተው በገባዖን ፊት ሰፈሩ።'),
  ('1567445c-5ac5-5000-ab28-dbc0521bff5b', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', '20712acb-8c23-56d0-ac3c-c5eec12f51f5', 20, 20, 'የእስራኤልም ሰዎች ሁሉ ከብንያም ጋር ሊዋጉ ወጡ፤ በገባዖንም ገጠሙአቸው።'),
  ('793bd25b-2485-5653-acd8-23fc2297ff7c', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', '20712acb-8c23-56d0-ac3c-c5eec12f51f5', 21, 21, 'የብንያምም ልጆች ከገባዖን ወጡ፤ በዚያም ቀን ከእስራኤላውያን ሃያ ሁለት ሺህ ሰዎችን በምድር ላይ ገደሉ።'),
  ('96dce94b-5de1-5a95-a08d-be815dd95604', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', '20712acb-8c23-56d0-ac3c-c5eec12f51f5', 22, 22, 'የእስራኤልም ሰዎች ተበራቱ፤ በፊተኛውም ቀን በተሰለፉበት ስፍራ ደግመው ተሰለፉ።'),
  ('9561cb6b-4331-5acf-a1a4-23f41eca2e36', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', '20712acb-8c23-56d0-ac3c-c5eec12f51f5', 23, 23, 'የእስራኤልም ልጆች ወጥተው በእግዚአብሔር ፊት እስከ ማታ ድረስ አለቀሱ፤ እግዚአብሔርንም፥ “ከወንድሞቻችን ከብንያም ልጆች ጋር ለመዋጋት ዳግመኛ እንቀርባለን?” ብለው ጠየቁ። እግዚአብሔርም “በእነርሱ ላይ ውጡ” አለ።'),
  ('66d0a866-8051-5e1a-acc1-05a6e069d4ea', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', '20712acb-8c23-56d0-ac3c-c5eec12f51f5', 24, 24, 'በሁለተኛውም ቀን የእስራኤል ልጆች ከብንያም ልጆች ጋር ሊዋጉ ቀረቡ።'),
  ('bb410db3-9ef4-5704-a68e-65ea5524ed7d', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', '20712acb-8c23-56d0-ac3c-c5eec12f51f5', 25, 25, 'በሁለተኛውም ቀን የብንያም ልጆች ሊገጥሙአቸው ከገባዖን ወጡ፤ ከእስራኤልም ልጆች ደግሞ ዐሥራ ስምንት ሺህ ሰዎችን በምድር ላይ ገደሉ፤ እነዚህም ሁሉ ሰይፍ የሚመዝዙ ነበሩ።'),
  ('b50369ef-c696-5f17-a525-16bf44b98617', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', '20712acb-8c23-56d0-ac3c-c5eec12f51f5', 26, 26, 'የእስራኤልም ልጆች ሁሉ ሕዝቡም ሁሉ ወጥተው ወደ ቤቴል መጡ፤ አለቀሱም፤ በዚያም በእግዚአብሔር ፊት ተቀመጡ፤ በዚያም ቀን እስከ ማታ ድረስ ጾሙ፤ በእግዚአብሔርም ፊት የሚቃጠል መሥዋዕትንና የደኅንነት መሥዋዕትን አቀረቡ።'),
  ('e8a05215-1f43-5974-a64e-ebf1726ac0f3', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', '20712acb-8c23-56d0-ac3c-c5eec12f51f5', 27, 27, 'በዚያም ዘመን የእግዚአብሔር የቃል ኪዳኑ ታቦት በዚያ ነበረችና፥ የእስራኤል ልጆች እግዚአብሔርን ጠየቁ፤'),
  ('d7275ff9-29ef-5d08-a677-a451228a591b', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', '20712acb-8c23-56d0-ac3c-c5eec12f51f5', 28, 28, 'በዚያም ዘመን የአሮን ልጅ የአልዓዛር ልጅ ፊንሐስ በፊቷ ይቆም ነበርና። “ከወንድሞቻችን ከብንያም ልጆች ጋር ለመዋጋት ዳግመኛ እንውጣን? ወይስ እንቅር?” አሉ። እግዚአብሔርም፥ “ነገ በእጃችሁ አሳልፌ እሰጣቸዋለሁና ውጡ” አላቸው።'),
  ('c97dfea0-7ddf-5503-a952-c28115bbeabc', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', '20712acb-8c23-56d0-ac3c-c5eec12f51f5', 29, 29, 'የእስራኤልም ልጆች ገባዖንን የሚከብቡአት ሰዎችን በዙሪያዋ አኖሩባት።'),
  ('3012f823-e291-5bc8-ac0c-29f2eb806cba', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', '20712acb-8c23-56d0-ac3c-c5eec12f51f5', 30, 30, 'በሦስተኛውም ቀን የእስራኤል ልጆች ወደ ብንያም ልጆች ወጡ፤ በገባዖንም ፊት እንደ ቀድሞው ጊዜ ተዋጉአቸው።'),
  ('02d0e903-636c-5637-ad60-072f8ed4ff31', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', '20712acb-8c23-56d0-ac3c-c5eec12f51f5', 31, 31, 'የብንያምም ልጆች በሕዝቡ ላይ ወጡ፤ ከከተማዪቱም ሸሹ፤ እንደ ቀድሞውም ጊዜ፥ በአውራዎቹ መንገዶች፥ አንደኛው ወደ ቤቴል፥ ሁለተኛውም ወደ ገባዖን ሜዳ በሚወስዱት መንገዶች ላይ ሕዝቡን ይመቱ፥ ይገድሉም ጀመር፤ ከእስራኤልም ሠላሳ የሚያህሉ ሰዎች ነበሩ።'),
  ('f901a6ad-2b54-5cee-a0d4-83eca4985b2b', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', '20712acb-8c23-56d0-ac3c-c5eec12f51f5', 32, 32, 'የብንያምም ልጆች፥ “እንደ ቀድሞው በፊታችን ይሞታሉ” አሉ። የእስራኤል ልጆች ግን፥ “እንሽሽ፤ ከከተማም ወደ መንገድ እናርቃቸው” አሉ።'),
  ('eab93a46-fcff-594b-ab94-065c4dd4fcf1', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', '20712acb-8c23-56d0-ac3c-c5eec12f51f5', 33, 33, 'የእስራኤልም ሰዎች ሁሉ ከስፍራቸው ተነሥተው በበዓልታምር ተዋጉ። ከእስራኤልም አድፍጠው የነበሩት ከስፍራቸው ከገባዖን ምዕራብ ወጡ።'),
  ('0e3999ff-c0cb-5545-a805-4a2c380242e8', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', '20712acb-8c23-56d0-ac3c-c5eec12f51f5', 34, 34, 'ከእስራኤልም ሁሉ የተመረጡ ዐሥር ሺህ ሰዎች ወደ ገባዖን አንጻር መጡ፤ ውጊያውም በርትቶ ነበር፤ መከራም እንዲያገኛቸው አላወቁም ነበር።'),
  ('9820ccd4-319e-59ab-a608-4ee4409f8c3a', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', '20712acb-8c23-56d0-ac3c-c5eec12f51f5', 35, 35, 'እግዚአብሔርም ብንያምን በእስራኤል ፊት ጣላቸው፤ በዚያም ቀን የእስራኤል ልጆች ከብንያም ሃያ አምስት ሺህ አንድ መቶ ሰዎችን ገደሉ፤ እነዚህም ሁሉ ሰይፍ የሚመዝዙ ነበሩ።'),
  ('66929499-238a-56a8-ad9a-1a6bd0474011', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', 'f9717411-3e4e-52e7-a778-f6f006da272b', 1, 36, 'የብንያም ልጆችም እንደ ተመቱ አዩ፤ የእስራኤል ልጆች ግን በገባዖን ላይ ባኖሩት ድብቅ ጦር ታምነዋልና ለብንያም ስፍራ ለቀቁላቸው።'),
  ('4df91c82-9422-50f9-aed9-fa2fd1d60661', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', 'f9717411-3e4e-52e7-a778-f6f006da272b', 2, 37, 'ተደብቀው የነበሩትም ፈጥነው ወደ ገባዖን ሮጡ፤ ተደብቀው የነበሩትም መጥተው ከተማውን ሁሉ በሰይፍ ስለት መቱ።'),
  ('a96fb896-1f18-5764-a789-38a0003f3307', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', 'f9717411-3e4e-52e7-a778-f6f006da272b', 3, 38, 'የተደበቁትም ሰዎች ከከተማው ብዙ ጢስ እንደ ደመና እንዲያስነሡ በእስራኤል ልጆችና በተደበቁት ሰዎች መካከል ምልክት ተደርጎ ነበር።'),
  ('d6bc2a16-e97f-558d-affd-87a1d4b0f8f7', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', 'f9717411-3e4e-52e7-a778-f6f006da272b', 4, 39, 'የእስራኤልም አርበኞች ከሰልፉ ተመለሱ፤ ብንያማውያንም እንደ ቀድሞው ሰልፍ በፊታችን ተመትተዋል እያሉ ከእስራኤል ሰዎች ሠላሳ የሚያህሉ ሰዎችን መምታትና መግደል ጀመሩ።'),
  ('742f67c5-6d25-5b16-a753-cc139c8dc329', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', 'f9717411-3e4e-52e7-a778-f6f006da272b', 5, 40, 'ምልክቱም በጢሱ ዐምድ ከከተማው ሊወጣ በጀመረ ጊዜ ብንያማውያን ወደኋላቸው ተመለከቱ፤ እነሆም፥ የሞላ ከተማው ጥፋት ወደ ሰማይ ወጣ።'),
  ('2931d79b-3da3-5dcf-a226-bba0d1acc0d4', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', 'f9717411-3e4e-52e7-a778-f6f006da272b', 6, 41, 'የእስራኤልም ልጆች ተመለሱ፤ የብንያምም ሰዎች ተሸበሩ፤ ክፉ ነገር እንደ ደረሰባቸውም አዩ።'),
  ('25c12927-e436-5faf-a144-0d64eaa98d17', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', 'f9717411-3e4e-52e7-a778-f6f006da272b', 7, 42, 'ከእስራኤልም ሰዎች ፊት ወደ ምድረ በዳ መንገድ ሸሹ፤ ሰልፉም ደረሰባቸው፤ ከየከተማውም የወጡት በመካከላቸው ገደሉአቸው።'),
  ('3a46831d-faa9-5114-a725-189606cca86f', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', 'f9717411-3e4e-52e7-a778-f6f006da272b', 8, 43, 'ብንያማውያንንም ወግተው አጠፉአቸው፤ በምሥራቅ በኩል ባለው በገባዖንም ፈጽመው ደመሰሱአቸው።'),
  ('09e4c97b-3415-508a-a042-1f263effdfa4', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', 'f9717411-3e4e-52e7-a778-f6f006da272b', 9, 44, 'ከብንያምም ዐሥራ ስምንት ሺህ ሰው ሞተ፤ እነዚህም ሁሉ ጽኑዓን ሰዎች ነበሩ።'),
  ('9db7fd99-5663-52f0-a431-1e2b8da5f685', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', 'f9717411-3e4e-52e7-a778-f6f006da272b', 10, 45, 'ከእነርሱም የተረፉት ተመልሰው ወደ ምድረ በዳ ወደ ሬሞን ዓለት ሸሹ፤ ከእነርሱም በየመንገዱ ላይ አምስት ሺህ ሰውን ለቀሙ፤ ወደ ጊድዓምም አሳደዱአቸው፤ ከእነርሱም ሁለት ሺህ ሰዎችን ገደሉ።'),
  ('f775de50-14d7-52f1-a3ff-62c262d0b51d', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', 'f9717411-3e4e-52e7-a778-f6f006da272b', 11, 46, 'እንዲሁም በዚያ ቀን ከብንያም የሞቱት ሃያ አምስት ሺህ ሰይፍ የሚመዝዙ ሰዎች ነበሩ፤ እነዚህ ሁሉ ጽኑዓን ሰዎች ነበሩ።'),
  ('ee0a9a65-c14c-5977-abda-a5157fd365cd', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', 'f9717411-3e4e-52e7-a778-f6f006da272b', 12, 47, 'ስድስቱም መቶ ሰዎች ተመልሰው ወደ ምድረ በዳ ወደ ሬሞን ዓለት ሸሹ፤ በሬሞንም ዓለት አራት ወር ተቀመጡ።'),
  ('dc96a4e1-4c29-5188-a632-ad6d93b53e40', 'ce7f1c1d-8ed8-5fc8-a155-20eccbe89b07', 'f9717411-3e4e-52e7-a778-f6f006da272b', 13, 48, 'የእስራኤልም ሰዎች በብንያም ልጆች ላይ ዳግመኛ ተመለሱ፤ ሞላውን ከተማ፥ ከብቱንም፥ ያገኙትንም ሁሉ በሰይፍ ስለት አጠፉ፤ ያገኙትንም ከተማ ሁሉ በእሳት አቃጠሉ።'),
  ('a35e651b-6cde-50cd-ad1d-529031d98244', '3f19e825-58f2-558a-a928-93f46156db3c', 'ba1a1569-df5f-5b09-a935-f6033ccf4e51', 1, 1, 'የእስራኤልም ሰዎች፥ “ከእኛ ማንም ሰው ሴት ልጁን ለብንያም ልጆች በጋብቻ አይስጥ” ብለው በመሴፋ ተማማሉ።'),
  ('db87aea1-2f17-50e1-ab05-7f3814eb5910', '3f19e825-58f2-558a-a928-93f46156db3c', 'ba1a1569-df5f-5b09-a935-f6033ccf4e51', 2, 2, 'ሕዝቡም ወደ ቤቴል መጥተው በዚያ በእግዚአብሔር ፊት እስከ ማታ ድረስ ተቀመጡ፤ ድምፃቸውንም ከፍ አድርገው ጽኑዕ ልቅሶ አለቀሱ።'),
  ('e475a9a4-6be7-5f66-a9a8-6a0173e00bb5', '3f19e825-58f2-558a-a928-93f46156db3c', 'ba1a1569-df5f-5b09-a935-f6033ccf4e51', 3, 3, 'እነርሱም፥ “አቤቱ፥ የእስራኤል አምላክ ሆይ፥ ዛሬ ከእስራኤል አንድ ነገድ መታጣቱ፥ ስለምን ይህ በእስራኤል ላይ ሆነ?” አሉ።'),
  ('f3cd92b8-4287-53c2-ad18-ffc64b85cb92', '3f19e825-58f2-558a-a928-93f46156db3c', 'ba1a1569-df5f-5b09-a935-f6033ccf4e51', 4, 4, 'በነጋውም ሕዝቡ ማልደው ተነሡ፤ በዚያም መሠዊያ ሠሩ፤ የሚቃጠልና የደኅንነት መሥዋዕትንም አቀረቡ።'),
  ('178da1e8-5caf-5845-a1bb-71b179193ab4', '3f19e825-58f2-558a-a928-93f46156db3c', 'ba1a1569-df5f-5b09-a935-f6033ccf4e51', 5, 5, 'የእስራኤልም ልጆች ወደ እግዚአብሔር ወደ መሴፋ ስላልወጣ ሰው፥ “እርሱ ፈጽሞ ይገደል” ብለው ታላቅ መሐላ ምለው ነበርና፥ “ከእስራኤል ነገድ ሁሉ ወደ ጉባኤ ወደ እግዚአብሔር ያልወጣ ማን ነው?” አሉ።'),
  ('851dcc75-d1b0-5590-a197-4852f034e4e4', '3f19e825-58f2-558a-a928-93f46156db3c', 'ba1a1569-df5f-5b09-a935-f6033ccf4e51', 6, 6, 'የእስራኤልም ልጆች ስለ ወንድማቸው ስለ ብንያም ልጆች አዝነው እንዲህ አሉ፥ “ዛሬ ከእስራኤል አንድ ነገድ ጠፍቶአል።'),
  ('b2fdb7c7-2769-589d-afdc-26942d700015', '3f19e825-58f2-558a-a928-93f46156db3c', 'ba1a1569-df5f-5b09-a935-f6033ccf4e51', 7, 7, 'እኛ ልጆቻችንን እንዳንድርላቸው በእግዚአብሔር ምለናልና የተረፉት ሚስቶችን እንዲያገኙ ምን እንድርግ?”'),
  ('4a85fbd1-d259-572c-a02a-2357a2b5c742', '3f19e825-58f2-558a-a928-93f46156db3c', 'ba1a1569-df5f-5b09-a935-f6033ccf4e51', 8, 8, 'እነርሱም፥ “ከእስራኤል ነገድ ወደ እግዚአብሔር ወደ መሴፋ ያልወጣ ማን ነው?” አሉ። እነሆም፥ ከኢያቢስ ገለዓድ ወደ ሰፈሩ ወደ ጉባኤው ማንም አልወጣም ነበር።'),
  ('c37132ae-296f-5319-a1a9-4f6611f4c396', '3f19e825-58f2-558a-a928-93f46156db3c', 'ba1a1569-df5f-5b09-a935-f6033ccf4e51', 9, 9, 'ሕዝቡም በተቈጠሩ ጊዜ፥ እነሆ፥ ከኢያቢስ ገለዓድ ነዋሪዎች ሰው አልተገኘም።'),
  ('4f33ea08-3f6a-512c-af75-d36fbc44e2e1', '3f19e825-58f2-558a-a928-93f46156db3c', 'ba1a1569-df5f-5b09-a935-f6033ccf4e51', 10, 10, 'ማኅበሩም ወደዚያ ዐሥራ ሁለት ሺህ ኀያላን ሰዎችን ልከው፥ “ሂዱ በኢያቢስ ገለዓድም ያሉትን ሰዎች ሴቶችንም ሕዝቡንም በሰይፍ ስለት ግደሉ።'),
  ('6cac7d1d-d7c8-5d90-a635-85941313dc2e', '3f19e825-58f2-558a-a928-93f46156db3c', 'ba1a1569-df5f-5b09-a935-f6033ccf4e51', 11, 11, 'የምታደርጉትም ይህ ነው፤ ወንዱን ሁሉ፥ ወንድ የሚያውቁትንም ሴቶች ሁሉ ፈጽማችሁ አጥፉ፤ ደናግሉን ግን አትግደሉአቸው፤” ብለው አዘዙአቸው፤ እንዲሁም አደረጉ።'),
  ('f2c525b2-411f-5d99-abd7-41d5edffd3c0', '3f19e825-58f2-558a-a928-93f46156db3c', 'ba1a1569-df5f-5b09-a935-f6033ccf4e51', 12, 12, 'በኢያቢስ ገለዓድ በሚኖሩ መካከልም ወንድ ያላወቁ አራት መቶ ቆነጃጅት ደናግልን አገኙ፤ በከነዓንም ሀገር ወዳለችው ወደ ሴሎ ወደ ሰፈሩ አመጡአቸው።'),
  ('08367ea4-1d0e-5f0c-a8d8-2f7ae2d848ab', '3f19e825-58f2-558a-a928-93f46156db3c', 'ba1a1569-df5f-5b09-a935-f6033ccf4e51', 13, 13, 'ማኅበሩም ሁሉ በሬሞን ዐለት ወዳሉት ወደ ብንያም ልጆች መልእክተኞችን ላኩ፤ በሰላምም ጠሩአቸው።'),
  ('38127132-0001-5184-a04b-71c0247c1b20', '3f19e825-58f2-558a-a928-93f46156db3c', 'ba1a1569-df5f-5b09-a935-f6033ccf4e51', 14, 14, 'በዚያም ጊዜ የብንያም ልጆች ወደ እስራኤል ልጆች ተመለሱ፤ የእስራኤልም ልጆች ከኢያቢስ ገለዓድ ሴቶች ያዳኑአቸውን ሴቶች ሰጡአቸው። በዚህም ተስማሙ።'),
  ('19021ae6-4a4b-5889-a264-bfe3b5b80ecb', '3f19e825-58f2-558a-a928-93f46156db3c', 'ba1a1569-df5f-5b09-a935-f6033ccf4e51', 15, 15, 'እግዚአብሔርም በእስራኤል ነገድ ውስጥ ስብራት ስላደረገ ሕዝቡ ስለ ብንያም አዘኑ።'),
  ('0b77fd20-8540-58b6-ade3-c757904baca8', '3f19e825-58f2-558a-a928-93f46156db3c', 'ba1a1569-df5f-5b09-a935-f6033ccf4e51', 16, 16, 'የማኅበሩ ሽማግሌዎችም፥ “ከብንያም ሴቶች ጠፍተዋልና የቀሩት ስዎች ሚስት እንዲያገኙ ምን እናደርጋለን?” አሉ።'),
  ('02668fea-abf3-5ff9-a7ec-564e9a1b37e9', '3f19e825-58f2-558a-a928-93f46156db3c', 'ba1a1569-df5f-5b09-a935-f6033ccf4e51', 17, 17, 'ደግሞም፥ “ከእስራኤል አንድ ነገድ እንዳይደመሰስ ከብንያም ላመለጡት ርስት ይኑር።'),
  ('836709d1-d7c7-5f64-aeba-c4b131839395', '3f19e825-58f2-558a-a928-93f46156db3c', 'ba1a1569-df5f-5b09-a935-f6033ccf4e51', 18, 18, 'የእስራኤልም ልጆች፥ “ልጁን ለብንያም የሚሰጥ ርጉም ይሁን ብለው ምለዋልና እኛ ከልጆቻችን ሚስቶችን ለእነርሱ መስጠት አንችልም” አሉ።'),
  ('e1dd083e-48e2-58d4-a17e-49e80a20e9dd', '3f19e825-58f2-558a-a928-93f46156db3c', 'ba1a1569-df5f-5b09-a935-f6033ccf4e51', 19, 19, 'እነርሱም፥ “እነሆ፥ በቤቴል በመስዕ በኩል፥ ከቤቴልም ወደ ሰቂማ በሚወስደው መንገድ በምሥራቅ በኩል በሌብና በዐዜብ በኩል ባለችው በሴሎ የእግዚአብሔር በዓል በየዓመቱ አለ” አሉ።'),
  ('c9799ff4-6164-5f45-a87e-284ed239be61', '3f19e825-58f2-558a-a928-93f46156db3c', 'ba1a1569-df5f-5b09-a935-f6033ccf4e51', 20, 20, 'የብንያምንም ልጆች እንዲህ ብለው አዘዙአቸው፥ “ሂዱ በወይኑም ስፍራ ተደበቁ፤'),
  ('ef5b97c9-f2b0-5aee-a0df-16249b886a4e', '3f19e825-58f2-558a-a928-93f46156db3c', 'ba1a1569-df5f-5b09-a935-f6033ccf4e51', 21, 21, 'ተመልከቱም፤ እነሆ፥ የሴሎ ሴቶች ልጆች አታሞ ይዘው ለዘፈን ሲወጡ ከወይኑ ስፍራ ውጡ፤ ከሴሎ ሴቶች ልጆችም ለየራሳችሁ ሚስትን ንጠቁ፤ ወደ ብንያም ምድርም ሂዱ።'),
  ('ace42643-3be8-5bc4-aeec-2edc134822de', '3f19e825-58f2-558a-a928-93f46156db3c', 'ba1a1569-df5f-5b09-a935-f6033ccf4e51', 22, 22, 'አባቶቻቸውና ወንድሞቻቸውም ሊጣሉአችሁ ወደ እኛ በመጡ ጊዜ፦ ስለ እኛ ማሩአቸው፥ እኛ ሚስት ለያንዳንዳቸው በሰልፍ አልወሰድንላቸውምና፥ እናንተም በደል ይሆንባችሁ ስለ ነበር አላጋባችኋቸውምና፥” እንላቸዋለን።'),
  ('7eb78b23-9588-5e5d-a1ae-f44b15c9d506', '3f19e825-58f2-558a-a928-93f46156db3c', 'ba1a1569-df5f-5b09-a935-f6033ccf4e51', 23, 23, 'የብንያምም ልጆች እንዲሁ አደረጉ፤ በቍጥራቸውም መጠን ከተነጠቁት ዘፋኞች ሚስትን ወሰዱ፤ ወደ ርስታቸውም ተመልሰው ሄዱ፤ ከተሞችንም ሠርተው ተቀመጡባቸው።'),
  ('665dc686-aa9e-5093-aa83-ab37cd9f1340', '3f19e825-58f2-558a-a928-93f46156db3c', 'ba1a1569-df5f-5b09-a935-f6033ccf4e51', 24, 24, 'በዚያ ጊዜም የእስራኤል ልጆች ከዚያ ተነሡ፤ እያንዳንዱም ወደ ወገኑና ወደ ነገዱ ሄደ፤ ሰውም ሁሉ ከዚያ ወደ ርስቱ ተመለሰ።'),
  ('dfb5165d-28b7-52d5-a307-836fe9d15d37', '3f19e825-58f2-558a-a928-93f46156db3c', 'ba1a1569-df5f-5b09-a935-f6033ccf4e51', 25, 25, 'በዚያም ዘመን በእስራኤል ዘንድ ንጉሥ አልነበረም፤ ሰው ሁሉ በፊቱ መልካም መስሎ የታየውን ያደርግ ነበር።'),
  ('bc7c4449-76b9-5a6f-ae0c-a9fe0330b678', 'a12059e8-40a9-5b94-a020-649877570994', '6ccbb809-76a4-53e3-ac39-6a72efe5ea1f', 1, 1, 'እንዲህም ሆነ፥ መሳፍንት ይፈርዱ በነበረ ጊዜ በአገሩ ላይ ራብ ሆነ። አንድ ሰውም ከሚስቱና ከሁለቱ ልጆቹ ጋር በሞዓብ ምድር ሊቀመጥ ከቤተ ልሔም ይሁዳ ተነሥቶ ሄደ።'),
  ('54d4cad7-aab7-5930-a208-2bb0499143c5', 'a12059e8-40a9-5b94-a020-649877570994', '6ccbb809-76a4-53e3-ac39-6a72efe5ea1f', 2, 2, 'የሰውዮውም ስም አቤሜሌክ፥ የሚስቱም ስም ኑኃሚን፥ የሁለቱም ልጆች ስም መሐሎንና ኬሌዎን ነበረ፥ የቤተ ልሔም ይሁዳም የኤፍራታ ሰዎች ነበሩ። ወደ ሞዓብም ምድር መጡ በዚያም ተቀመጡ።'),
  ('f2faa338-3a26-52ac-a1ad-507776027e4b', 'a12059e8-40a9-5b94-a020-649877570994', '6ccbb809-76a4-53e3-ac39-6a72efe5ea1f', 3, 3, 'የኑኃሚንም ባል አቤሜሌክ ሞተ፣ እርስዋና ሁለቱ ልጆችዋ ቀሩ።'),
  ('34cd437f-399b-5f6a-a36e-cd08b557566a', 'a12059e8-40a9-5b94-a020-649877570994', '6ccbb809-76a4-53e3-ac39-6a72efe5ea1f', 4, 4, 'እነርሱም ከሞዓባውያን ሴቶች ሚስት አገቡ፣ የአንዲቱ ስም ዖርፋ የሁለተኛይቱም ስም ሩት ነበረ። በዚያም አሥር ዓመት ያህል ተቀመጡ።'),
  ('575c0183-54ff-5416-a792-21ede3f69cba', 'a12059e8-40a9-5b94-a020-649877570994', '6ccbb809-76a4-53e3-ac39-6a72efe5ea1f', 5, 5, 'መሐሎንና ኬሌዎንም ሁለቱ ሞቱ፣ ሴቲቱም ከሁለቱ ልጆችዋና ከባልዋ ተለይታ ቀረች።'),
  ('711fcad2-4402-5e45-aadb-31668c257546', 'a12059e8-40a9-5b94-a020-649877570994', '6ccbb809-76a4-53e3-ac39-6a72efe5ea1f', 6, 6, 'እርስዋም በሞዓብ ምድር ሳለች እግዚአብሔር ሕዝቡን እንደ ጐበኘ እንጀራም እንደ ሰጣቸው ስለ ሰማች፥ ከሞዓብ ምድር ልትመለስ ከሁለቱ ምራቶችዋ ጋር ተነሣች።'),
  ('f0063534-d4ad-504d-a867-fc9012fb5ee3', 'a12059e8-40a9-5b94-a020-649877570994', '6ccbb809-76a4-53e3-ac39-6a72efe5ea1f', 7, 7, 'እርስዋም ከሁለቱ ምራቶችዋ ጋር ከተቀመጠችበት ስፍራ ወጣች፣ ወደ ይሁዳም ምድር ሊመለሱ በመንገድ ሄዱ።'),
  ('ede4a12a-df50-535f-a195-447ce3134a2b', 'a12059e8-40a9-5b94-a020-649877570994', '6ccbb809-76a4-53e3-ac39-6a72efe5ea1f', 8, 8, 'ኑኃሚንም ምራቶችዋን፦ ሂዱ፥ ወደ እናቶቻችሁም ቤት ተመለሱ፣ በእኔና በሞቱት እንዳደረጋችሁ፥ እግዚአብሔር ቸርነት ያድርግላችሁ።'),
  ('fe4238b7-d059-53c0-a7be-b9fc564b4ba6', 'a12059e8-40a9-5b94-a020-649877570994', '6ccbb809-76a4-53e3-ac39-6a72efe5ea1f', 9, 9, 'እግዚአብሔር በየባላችሁ ቤት ዕረፍት ይስጣችሁ አለቻቸው። ሳመቻቸውም፣ ድምፃቸውንም ከፍ አድርገው አለቀሱ።'),
  ('2d56692e-2c47-5b9d-ad63-fc3951913cbd', 'a12059e8-40a9-5b94-a020-649877570994', '6ccbb809-76a4-53e3-ac39-6a72efe5ea1f', 10, 10, 'እነርሱም፦ ከአንቺ ጋር ወደ ሕዝብሽ እንመለሳለን አሉአት።'),
  ('aacd764f-a130-5fe4-a2e4-a55db2768ef6', 'a12059e8-40a9-5b94-a020-649877570994', '6ccbb809-76a4-53e3-ac39-6a72efe5ea1f', 11, 11, 'ኑኃሚንም አለች፦ ልጆቼ ሆይ፥ ተመለሱ፣ ለምን ከእኔ ጋር ትሄዳላችሁ? ባሎቻችሁ የሚሆኑ ልጆች በሆዴ አሉኝን?'),
  ('303c356d-6f79-51e8-a67d-8c5ed17bbb70', 'a12059e8-40a9-5b94-a020-649877570994', '6ccbb809-76a4-53e3-ac39-6a72efe5ea1f', 12, 12, 'ልጆቼ ሆይ፥ ተመለሱ፣ ባል ለማግባት አርጅቻለሁና ሂዱ፣ ተስፋ አለኝ ብል፥ ዛሬ ሌሊትስ እንኳ ባል ባገባ፥ ወንዶች ልጆችም ብወልድ፥'),
  ('b01932d8-7d0b-5447-a93d-da7ec4ea1cd7', 'a12059e8-40a9-5b94-a020-649877570994', '6ccbb809-76a4-53e3-ac39-6a72efe5ea1f', 13, 13, 'እነርሱ እስኪያድጉ ድረስ ትቆያላችሁን? ስለ እነርሱስ ባል ማግባት ትተዋላችሁን? ልጆቼ ሆይ፥ እንዲህ አይደለም፣ የእግዚአብሔር እጅ በእኔ ወጥቶአልና ከእናንተ የተነሣ እጅግ ተመርሬአለሁ።'),
  ('2914f000-9e35-577f-af88-7ac529f87e69', 'a12059e8-40a9-5b94-a020-649877570994', '6ccbb809-76a4-53e3-ac39-6a72efe5ea1f', 14, 14, 'ድምፃቸውንም ከፍ አድርገው እንደ ገና አለቀሱ፣ ዖርፋም አማትዋን ሳመች፣ ሩት ግን ተጠጋቻት።'),
  ('15bcefa2-8325-5546-a597-2b7396953af9', 'a12059e8-40a9-5b94-a020-649877570994', '6ccbb809-76a4-53e3-ac39-6a72efe5ea1f', 15, 15, 'ኑኃሚንም፦ እነሆ፥ ባልንጀራሽ ወደ ሕዝብዋና ወደ አማልክትዋ ተመልሳለች፣ አንቺም ደግሞ ከባልንጀራሽ ጋር ተመለሽ አለቻት።'),
  ('5f4fb051-7a37-5609-a65b-0a87e1ab3c84', 'a12059e8-40a9-5b94-a020-649877570994', '6ccbb809-76a4-53e3-ac39-6a72efe5ea1f', 16, 16, 'ሩትም፦ ወደምትሄጅበት እሄዳለሁና፥ በምታድሪበትም አድራለሁና እንድተውሽ ከአንቺም ዘንድ እንድመለስ አታስቸግሪኝ፣ ሕዝብሽ ሕዝቤ፥ አምላክሽም አምላኬ ይሆናል፣'),
  ('23a6d341-609b-58ad-a351-6699f427f322', 'a12059e8-40a9-5b94-a020-649877570994', '6ccbb809-76a4-53e3-ac39-6a72efe5ea1f', 17, 17, 'በምትሞችበትም ስፍራ እሞታለሁ፥ በዚያም እቀበራለሁ፣ ከሞት በቀር አንቺንና እኔን አንዳች ቢለየን እግዚአብሔር ይህን ያድርግብኝ እንዲሁም ይጨምርብኝ አለች።'),
  ('a7d9d8f2-834a-5cfa-a8af-b61a96e07908', 'a12059e8-40a9-5b94-a020-649877570994', '6ccbb809-76a4-53e3-ac39-6a72efe5ea1f', 18, 18, 'ኑኃሚንም ከእርስዋ ጋር ለመሄድ እንደ ቈረጠች ባየች ጊዜ እርስዋን ከመናገር ዝም አለች።'),
  ('82939c1c-9507-5c69-a5b3-fb3c30f9801f', 'a12059e8-40a9-5b94-a020-649877570994', '6ccbb809-76a4-53e3-ac39-6a72efe5ea1f', 19, 19, 'ሁለቱም እስከ ቤተ ልሔም ድረስ ሄዱ። ወደ ቤተ ልሔምም በደረሱ ጊዜ የከተማይቱ ሰዎች ሁሉ ስለ እነርሱ፦ ይህች ኑኃሚን ናትን? እያሉ ተንጫጩ።'),
  ('95c2bde1-669c-51d1-a2e4-093d3c07cb63', 'a12059e8-40a9-5b94-a020-649877570994', '6ccbb809-76a4-53e3-ac39-6a72efe5ea1f', 20, 20, 'እርስዋም፦ ሁሉን የሚችል አምላክ አስመርሮኛልና ማራ በሉኝ እንጂ ኑኃሚን አትበሉኝ።'),
  ('c9b52b46-bb23-5c28-a95c-0f7b0cf912a5', 'a12059e8-40a9-5b94-a020-649877570994', '6ccbb809-76a4-53e3-ac39-6a72efe5ea1f', 21, 21, 'በሙላት ወጣሁ፥ እግዚአብሔርም ወደ ቤቴ ባዶዬን መለሰኝ፣ እግዚአብሔር አዋርዶኛልና፥ ሁሉንም የሚችል አምላክ አስጨንቆኛልና ኑኃሚን ለምን ትሉኛላችሁ? አለቻቸው።'),
  ('5cee633f-e937-57b7-aa50-b9cf6141514e', 'a12059e8-40a9-5b94-a020-649877570994', '6ccbb809-76a4-53e3-ac39-6a72efe5ea1f', 22, 22, 'ኑኃሚንም ከእርስዋም ጋር ከሞዓብ ምድር የተመለሰችው ሞዓባዊቱ ምራትዋ ሩት ተመለሱ። የገብስም መከር በተጀመረ ጊዜ ወደ ቤተልሔም መጡ።'),
  ('098b3d39-e78d-59e3-a850-d01373e94dbc', '5bac2103-cab8-583e-a026-68f3f03d6626', '958fa8ba-aca1-5a1e-a05c-bc7714fbca5b', 1, 1, 'ለኑኃሚንም ባል የሚዛመደው ከአቤሜሌክ ወገን የሆነ ኃያል ሰው ስሙ ቦዔዝ የተባለ ሰው ነበረ።'),
  ('b026fd84-271a-5c46-ae8d-3e56c167e29b', '5bac2103-cab8-583e-a026-68f3f03d6626', '958fa8ba-aca1-5a1e-a05c-bc7714fbca5b', 2, 2, 'ሞዓባዊቱም ሩት ኑኃሚንን፦ በፊቱ ሞገስ የማገኘውን ተከትዬ እህል እንድቃርም ወደ እርሻ ልሂድ አለቻት። እርስዋም፦ ልጄ ሆይ፥ ሂጂ አለቻት።'),
  ('b8513368-fae1-5a3d-a0aa-20b45007c14f', '5bac2103-cab8-583e-a026-68f3f03d6626', '958fa8ba-aca1-5a1e-a05c-bc7714fbca5b', 3, 3, 'ሄደችም፥ ከአጫጆችም በኋላ በእርሻ ውስጥ ቃረመች፣ እንደ አጋጣሚውም የአቤሜሌክ ወገን ወደ ነበረው ወደ ቦዔዝ እርሻ ደረሰች።'),
  ('63fae456-97ce-5c74-ae55-09611e0e6ae2', '5bac2103-cab8-583e-a026-68f3f03d6626', '958fa8ba-aca1-5a1e-a05c-bc7714fbca5b', 4, 4, 'እነሆም፥ ቦዔዝ ከቤተ ልሔም መጣ፥ አጫጆችንም፦ እግዚአብሔር ከእናንተ ጋር ይሁን አላቸው። እነርሱም፦ እግዚአብሔር ይባርክህ ብለው መለሱለት።'),
  ('d6e82fbc-bcd5-53c8-a1b6-ac76206d24ec', '5bac2103-cab8-583e-a026-68f3f03d6626', '958fa8ba-aca1-5a1e-a05c-bc7714fbca5b', 5, 5, 'ቦዔዝም በአጫጆች ላይ አዛዥ የነበረውን ሎሌውን፦ ይህች ቆንጆ የማን ናት? አለው።'),
  ('18d3fdb4-f7da-5d6e-acef-8d9fe7727be7', '5bac2103-cab8-583e-a026-68f3f03d6626', '958fa8ba-aca1-5a1e-a05c-bc7714fbca5b', 6, 6, 'የአጫጆቹም አዛዥ፦ ይህችማ ከሞዓብ ምድር ከኑኃሚን ጋር የመጣች ሞዓባዊቱ ቆንጆ ናት፣'),
  ('ef044f44-315c-5cd4-ad7d-5a86f6ce7387', '5bac2103-cab8-583e-a026-68f3f03d6626', '958fa8ba-aca1-5a1e-a05c-bc7714fbca5b', 7, 7, 'እርስዋም፦ ከአጫጆቹ በኋላ በነዶው መካከል እንድቃርምና እንድለቅም፥ እባክህ፥ ፍቀድልኝ አለች፣ መጣችም፥ ከማለዳም ጀምራ እስከ አሁን ድረስ ቆይታለች፣ በቤትም ጥቂት ጊዜ እንኳ አላረፈችም አለው።'),
  ('3bad4f57-0768-5007-a8e9-919f0476082e', '5bac2103-cab8-583e-a026-68f3f03d6626', '958fa8ba-aca1-5a1e-a05c-bc7714fbca5b', 8, 8, 'ቦዔዝም ሩትን፦ ልጄ ሆይ፥ ትሰሚያለሽን? ቃርሚያ ለመቃረም ወደ ሌላ እርሻ አትሂጂ፥ ከዚህም አትላወሺ፥ ነገር ግን ገረዶቼን ተጠጊ።'),
  ('2d544232-faea-5589-a1d9-93a5790f6555', '5bac2103-cab8-583e-a026-68f3f03d6626', '958fa8ba-aca1-5a1e-a05c-bc7714fbca5b', 9, 9, 'ወደሚያጭዱበትም ስፍራ ተመልከቺ፥ ተከተያቸውም፣ እንዳያስቸግሩሽም ጐበዛዝቱን አዝዣለሁ፣ በተጠማሽም ጊዜ ወደ ማድጋው ሄደሽ ጐበዛዝቱ ከቀዱት ውኃ ጠጪ አላት።'),
  ('5d023ad4-eeb1-5b28-a254-bcdebb7b69e0', '5bac2103-cab8-583e-a026-68f3f03d6626', '958fa8ba-aca1-5a1e-a05c-bc7714fbca5b', 10, 10, 'በግምባርዋም ተደፍታ በምድር ላይ ሰገደችለት፦ እኔንስ ለመቀበል በምን ነገር በፊትህ ሞገስ አገኘሁ? እኔ እንግዳ አይደለሁምን? አለችው።'),
  ('28b174a1-4305-5c22-a506-82b49e4af5cc', '5bac2103-cab8-583e-a026-68f3f03d6626', '958fa8ba-aca1-5a1e-a05c-bc7714fbca5b', 11, 11, 'ቦዔዝም፦ ባልሽ ከሞተ በኋላ አባትሽንና እናትሽን የተወለድሽባትንም ምድር ትተሽ ቀድሞ ወደማታውቂው ሕዝብ እንደ መጣሽ፥ ለአማትሽ ያደረግሽውን ነገር ሁሉ ፈጽሞ ሰምቻለሁ።'),
  ('910bd255-8bb5-5503-aba7-69ae526f738a', '5bac2103-cab8-583e-a026-68f3f03d6626', '958fa8ba-aca1-5a1e-a05c-bc7714fbca5b', 12, 12, 'እግዚአብሔር እንደ ሥራሽ ይስጥሽ፣ ከክንፉም በታች መጠጊያ እንድታገኚ በመጣሽበት በእስራኤል አምላክ በእግዚአብሔር ዘንድ ደመወዝሽ ፍጹም ይሁን አላት።'),
  ('d0f4e716-f01c-5067-ab01-c8b8ec8e4faa', '5bac2103-cab8-583e-a026-68f3f03d6626', '958fa8ba-aca1-5a1e-a05c-bc7714fbca5b', 13, 13, 'እርስዋም፦ ጌታዬ ሆይ፥ ከባሪያዎችህ እንደ አንዲቱ ሳልሆን አጽናንተኽኛልና፥ የባሪያህንም ልብ ደስ አሰኝተሃልና በዓይንህ ሞገስ ላግኝ አለችው።'),
  ('0926c2b8-ddd9-560e-afe3-229852b8bfc5', '5bac2103-cab8-583e-a026-68f3f03d6626', '958fa8ba-aca1-5a1e-a05c-bc7714fbca5b', 14, 14, 'በምሳም ጊዜ ቦዔዝ፦ ወደዚህ ቅረቢ፣ ምሳ ብዪ፥ እንጀራሽንም በሆምጣጤው አጥቅሽ አላት። በአጫጆቹም አጠገብ ተቀመጠች የተጠበሰም እሸት ሰጣት፥ በልታም ጠገበች፥ አተረፈችም።'),
  ('2efbab3c-3c59-5cae-ae73-d1922cc16134', '5bac2103-cab8-583e-a026-68f3f03d6626', '958fa8ba-aca1-5a1e-a05c-bc7714fbca5b', 15, 15, 'ደግሞም ልትቃርም በተነሣች ጊዜ ቦዔዝ ጐበዛዝቱን፦ በነዶው መካከል ትቃርም፥ እናንተም አታሳፍሩአት፣'),
  ('3df14f2a-f2b0-5fae-ad9d-5e9049516a53', '5bac2103-cab8-583e-a026-68f3f03d6626', '958fa8ba-aca1-5a1e-a05c-bc7714fbca5b', 16, 16, 'ደግሞ ከነዶው አስቀርታችሁ ተዉላት፣ እርስዋም ትቃርም፥ አትውቀሱአትም ብሎ አዘዛቸው።'),
  ('f8eda618-e5a2-57e0-a786-717680585ecc', '5bac2103-cab8-583e-a026-68f3f03d6626', '958fa8ba-aca1-5a1e-a05c-bc7714fbca5b', 17, 17, 'በእርሻውም ውስጥ እስከ ማታ ድረስ ቃረመች፣ የቃረመችውንም ወቃችው፣ አንድ የኢፍ መስፈሪያ ያህልም ገብስ ሆነ።'),
  ('f6c671ac-da8d-5cd4-a0cb-4c503bf1a794', '5bac2103-cab8-583e-a026-68f3f03d6626', '958fa8ba-aca1-5a1e-a05c-bc7714fbca5b', 18, 18, 'ተሸክማውም ወደ ከተማ ገባች፥ አማትዋም የቃረመችውን አየች፣ ከጠገበችም በኋላ የተረፋትን አውጥታ ሰጠቻት።'),
  ('a9cea670-c4ea-57e9-afc6-35b337d246e8', '5bac2103-cab8-583e-a026-68f3f03d6626', '958fa8ba-aca1-5a1e-a05c-bc7714fbca5b', 19, 19, 'አማትዋም፦ ዛሬ ወዴት ቃረምሽ? ወዴትስ ሠራሽ? የተቀበለሽ የተባረከ ይሁን አለቻት። እርስዋም፦ ዛሬ የሠራሁበት ሰው ስም ቦዔዝ ይባላል ብላ በማን ዘንድ እንደ ሠራች ለአማትዋ ነገረቻት።'),
  ('b53b62b3-0c0a-555c-a1cf-06215f7a2c7c', '5bac2103-cab8-583e-a026-68f3f03d6626', '958fa8ba-aca1-5a1e-a05c-bc7714fbca5b', 20, 20, 'ኑኃሚንም ምራትዋን፦ ቸርነቱን በሕያዋንና በሙታን ላይ አልተወምና በእግዚአብሔር የተባረከ ይሁን አለቻት። ኑኃሚንም ደግሞ፦ ይህ ሰው የቅርብ ዘመዳችን ነው፥ እርሱም ሊቤዡን ከሚችሉት አንዱ ነው አለቻት።'),
  ('8e9d3ab8-b5e8-5411-a329-25e188b9197b', '5bac2103-cab8-583e-a026-68f3f03d6626', '958fa8ba-aca1-5a1e-a05c-bc7714fbca5b', 21, 21, 'ሞዓባዊቱ ሩትም፦ ደግሞ፦ መከሬን እስኪጨርሱ ድረስ ጐበዛዝቴን ተጠጊ አለኝ አለቻት።'),
  ('89b6d224-5496-5dc1-a444-7b5f5e16e47f', '5bac2103-cab8-583e-a026-68f3f03d6626', '958fa8ba-aca1-5a1e-a05c-bc7714fbca5b', 22, 22, 'ኑኃሚንም ምራትዋን ሩትን፦ ልጄ ሆይ፥ ከገረዶቹ ጋር ብትወጪ፥ በሌላም እርሻ ባያገኙሽ መልካም ነው አለቻት።'),
  ('c34285f7-51f6-5377-a3ad-e65ff07d7a3a', '5bac2103-cab8-583e-a026-68f3f03d6626', '958fa8ba-aca1-5a1e-a05c-bc7714fbca5b', 23, 23, 'ሩትም የገብሱና የስንዴው መከር እስኪጨረስ ድረስ ልትቃርም የቦዔዝን ገረዶች ተጠጋች፣ በአማትዋም ዘንድ ትቀመጥ ነበር።'),
  ('8f94ee8c-c624-54e4-ad81-ee88a644ee8f', '6e173706-bde4-5864-a641-690825b4c870', '42cc1191-7af6-59b7-a788-77e4e1784640', 1, 1, 'አማትዋም ኑኃሚን አለቻት፦ ልጄ ሆይ፥ መልካም እንዲሆንልሽ ዕረፍት አልፈልግልሽምን?'),
  ('a2ab0ef6-e999-51aa-a3a4-90b376768b6f', '6e173706-bde4-5864-a641-690825b4c870', '42cc1191-7af6-59b7-a788-77e4e1784640', 2, 2, 'አሁንም ከገረዶቹ ጋር የነበርሽበት ቦዔዝ ዘመዳችን አይደለምን? እነሆ፥ እርሱ በዛሬ ሌሊት በአውድማው ላይ ገብሱን በመንሽ ይበትናል።'),
  ('f0752c59-e101-5797-a4a8-9cc632855631', '6e173706-bde4-5864-a641-690825b4c870', '42cc1191-7af6-59b7-a788-77e4e1784640', 3, 3, 'እንግዲህ ታጠቢ፥ ተቀቢ፥ ልብስሽን ተላበሺ፥ ወደ አውድማውም ውረጂ፣ ነገር ግን መብሉንና መጠጡን እስኪጨርስ ድረስ ለሰውዮው አትታዪው።'),
  ('3647a83f-30e4-5ade-a631-cdec2b4c07e0', '6e173706-bde4-5864-a641-690825b4c870', '42cc1191-7af6-59b7-a788-77e4e1784640', 4, 4, 'በተኛም ጊዜ የሚተኛበትን ስፍራ ተመልከቺ፥ ገብተሽም እግሩን ግለጪ፥ ተጋደሚም፣ የምታደርጊውንም እርሱ ይነግርሻል።'),
  ('86143825-f2f8-5d00-a307-719013989327', '6e173706-bde4-5864-a641-690825b4c870', '42cc1191-7af6-59b7-a788-77e4e1784640', 5, 5, 'ሩትም፦ የተናገርሽኝን ሁሉ አደርጋለሁ አለቻት።'),
  ('c69990bb-ef76-5798-a3c2-80cd6ad79625', '6e173706-bde4-5864-a641-690825b4c870', '42cc1191-7af6-59b7-a788-77e4e1784640', 6, 6, 'ወደ አውድማውም ወረደች፥ አማትዋም ያዘዘቻትን ሁሉ አደረገች።'),
  ('25624bf6-6bb0-5449-a8a4-f120cdee8c74', '6e173706-bde4-5864-a641-690825b4c870', '42cc1191-7af6-59b7-a788-77e4e1784640', 7, 7, 'ቦዔዝም ከበላና ከጠጣ ሰውነቱንም ደስ ካሰኘ በኋላ፥ በእህሉ ክምር አጠገብ ሊተኛ ሄደ፣ ሩትም በቀስታ መጣች፥ እግሩንም ገልጣ ተኛች።'),
  ('e99eaf4d-2631-548c-a4b4-d51951dfe0b6', '6e173706-bde4-5864-a641-690825b4c870', '42cc1191-7af6-59b7-a788-77e4e1784640', 8, 8, 'መንፈቀ ሌሊትም በሆነ ጊዜ ሰውዮው ደነገጠ፥ ዘወርም አለ፣ እነሆም፥ አንዲት ሴት በእግርጌው ተኝታ ነበረች።'),
  ('ed335ea3-13ff-5e64-ae87-33497bffeec1', '6e173706-bde4-5864-a641-690825b4c870', '42cc1191-7af6-59b7-a788-77e4e1784640', 9, 9, 'እርሱም፦ ማን ነሽ? አለ። እርስዋም፦ እኔ ባሪያህ ሩት ነኝ፣ ዋርሳዬ ነህና ልብስህን በባሪያህ ላይ ዘርጋ አለችው።'),
  ('2947b5f6-e9a4-5b39-ab10-cb9cfcc82ca7', '6e173706-bde4-5864-a641-690825b4c870', '42cc1191-7af6-59b7-a788-77e4e1784640', 10, 10, 'ቦዔዝም አላት፦ ልጄ ሆይ፥ በእግዚአብሔር የተባረክሽ ሁኚ፣ ባለጠጋም ድሀም ብለሽ ጐበዛዝትን አልተከተልሽምና ከፊተኛው ይልቅ በመጨረሻው ጊዜ ቸርነት አድርገሻል።'),
  ('e7b761f3-f211-5c38-a2fa-648557171931', '6e173706-bde4-5864-a641-690825b4c870', '42cc1191-7af6-59b7-a788-77e4e1784640', 11, 11, 'አሁንም፥ ልጄ ሆይ፥ አትፍሪ፣ በአገሬ ያሉ ሕዝብ ሁሉ ምግባረ መልካም ሴት እንደ ሆንሽ ያውቃሉና ያልሽውን ነገር ሁሉ አደርግልሻለሁ።'),
  ('df6c773a-09bc-5755-a442-40c179f1eafd', '6e173706-bde4-5864-a641-690825b4c870', '42cc1191-7af6-59b7-a788-77e4e1784640', 12, 12, 'የቅርብ ዘመድ መሆኔ እውነት ነው፣ ነገር ግን ከእኔ የቀረበ ዘመድ አለ።'),
  ('acdf4706-bcbf-5174-ae7e-1617d0bda396', '6e173706-bde4-5864-a641-690825b4c870', '42cc1191-7af6-59b7-a788-77e4e1784640', 13, 13, 'ዛሬ ሌሊት እደሪ፣ ነገም እርሱ ዋርሳ መሆን ቢወድድ መልካም ነው፥ ዋርሳ ይሁን፣ ዋርሳ ሊሆን ባይወድድ ግን፥ ሕያው እግዚአብሔርን እኔ ዋርሳ እሆንሻለሁ፣ እስኪነጋ ድረስ ተኚ።'),
  ('2aa3e968-7e8c-5c38-a1fd-28ced26eef16', '6e173706-bde4-5864-a641-690825b4c870', '42cc1191-7af6-59b7-a788-77e4e1784640', 14, 14, 'እስኪነጋም በእግርጌው ተኛች፣ ቦዔዝም፦ ሴት ወደ አውድማው እንደ መጣች ማንም እንዳያውቅ ብሎ ነበርና ገና ሰውና ሰው ሳይተያይ ተነሣች።'),
  ('55b3591a-2be6-5b18-a297-2b13d8978cc1', '6e173706-bde4-5864-a641-690825b4c870', '42cc1191-7af6-59b7-a788-77e4e1784640', 15, 15, 'እርሱም፦ የለበስሽውን ኩታ አምጥተሽ ያዢው አላት፣ በያዘችም ጊዜ ስድስት መስፈሪያ ገብስ ሰፈረላት አሸከማትም።'),
  ('7893c561-0194-51a6-ad6d-2eb4f55af791', '6e173706-bde4-5864-a641-690825b4c870', '42cc1191-7af6-59b7-a788-77e4e1784640', 16, 16, 'እርሱም ወደ ከተማይቱ ሄደ። ወደ አማትዋም መጣች፥ አማትዋም፦ ልጄ ሆይ እንዴት ነሽ? አለቻት፣ እርስዋም ሰውዮው ያደረገላትን ሁሉ ነገረቻት።'),
  ('11848666-34f5-5a8d-a7e0-cd35d2725396', '6e173706-bde4-5864-a641-690825b4c870', '42cc1191-7af6-59b7-a788-77e4e1784640', 17, 17, 'ወደ አማትሽ ባዶ እጅሽን አትሂጂ ብሎ ይህን ስድስት መስፈሪያ ገብስ ሰጠኝ አለቻት።'),
  ('43746424-40b2-5fe6-a3c1-2e87adb9bbf1', '6e173706-bde4-5864-a641-690825b4c870', '42cc1191-7af6-59b7-a788-77e4e1784640', 18, 18, 'እርስዋም፦ ልጄ ሆይ፥ ሰውዮው ይህን ነገር ዛሬ እስኪጨርስ ድረስ አያርፍምና ፍጻሜው እስኪታወቅ ድረስ ዝም በዪ አለች።'),
  ('8b6115e7-c1b0-5cee-a97d-4f7f49e0091b', 'fb9f07d2-6197-5eca-a93c-08699db9bfd7', '20920397-2896-5349-acdb-300c09f001e9', 1, 1, 'ቦዓዝም ወደ ከተማይቱ በር አደባባይ ወጥቶ በዚያ ተቀመጠ። እነሆም፥ ቦዔዝ ስለ እርሱ ይናገር የነበረው የቅርብ ዘመድ ሲያልፍ ቦዔዝ፦ አንተ ቀርበህ በዚህ ተቀመጥ አለው። እርሱም ቀረብ ብሎ ተቀመጠ።'),
  ('5f799d87-5a14-5121-a6cd-0f896fdc61c4', 'fb9f07d2-6197-5eca-a93c-08699db9bfd7', '20920397-2896-5349-acdb-300c09f001e9', 2, 2, 'ቦዔዝም ከከተማይቱ ሽማግሌዎች አሥር ሰዎች ጠርቶ፦ በዚህ ተቀመጡ አላቸው። እነርሱም ተቀመጡ።'),
  ('14ee06c4-d231-50b7-abcc-4b13e44e3164', 'fb9f07d2-6197-5eca-a93c-08699db9bfd7', '20920397-2896-5349-acdb-300c09f001e9', 3, 3, 'ቦዔዝም የቅርብ ዘመዱን፦ ከሞዓብ ምድር የተመለሰችው ኑኃሚን የወንድማችንን የአቤሜሌክን ጢንጦ ትሸጣለች።'),
  ('a3a1504f-10c0-5c2f-adcc-1fea990fdd79', 'fb9f07d2-6197-5eca-a93c-08699db9bfd7', '20920397-2896-5349-acdb-300c09f001e9', 4, 4, 'እኔም በዚህ በተቀመጡት በሕዝቤ ሽማግሌዎች ፊት እንድትገዛው አስታውቅህ ዘንድ አሰብሁ። መቤዠት ብትወድድ ተቤዥው፣ መቤዥት ባትወድድ ግን ከአንተ በቀር ሌላ ወራሽ የለምና፥ እኔም ከእንተ በኋላ ነኝና እንዳውቀው ንገረኝ አለው። እርሱም፦ እቤዥዋለሁ አለው።'),
  ('de8ca37e-f924-50f8-a0b3-69cd15a871bb', 'fb9f07d2-6197-5eca-a93c-08699db9bfd7', '20920397-2896-5349-acdb-300c09f001e9', 5, 5, 'ቦዔዝም፦ እርሻውን ከኑኃሚን እጅ በምትገዛበት ቀን፥ ለሞተው በርስቱ ስሙን እንድታስነሣለት ከምዋቹ ሚስት ከሞዓባዊቱ ከሩት ደግሞ ትገዛለህ አለ።'),
  ('32da61b7-a72e-5d50-a300-b909d8a0fdad', 'fb9f07d2-6197-5eca-a93c-08699db9bfd7', '20920397-2896-5349-acdb-300c09f001e9', 6, 6, 'የቅርብ ዘመዱም፦ የራሴን ርስት እንዳላበላሽ መቤዠት አልችልም፣ እኔ መቤዠቱን አልችልምና አንተ ከእኔ መቤዠቱን ውሰደው አለ።'),
  ('ceff2b93-3078-5b97-a88b-f3a6449ad22d', 'fb9f07d2-6197-5eca-a93c-08699db9bfd7', '20920397-2896-5349-acdb-300c09f001e9', 7, 7, 'በጥንት ጊዜም፥ ማንም ቢሸጥ ቢለውጥም፥ ነገሩን ለማጽናት ሰው ጫማውን እንዲያወልቅ ለባልንጀራውም እንዲሰጠው በእስራኤል ዘንድ ልማድ ነበረ። ይህም በእስራኤል ምስክር ነበረ።'),
  ('e64b5f6f-dc08-5edd-a8f5-e9ecd3d37c54', 'fb9f07d2-6197-5eca-a93c-08699db9bfd7', '20920397-2896-5349-acdb-300c09f001e9', 8, 8, 'የቅርብ ዘመዱም ቦዔዝን፦ አንተ ግዛው አለው፣ ጫማውንም አወለቀ።'),
  ('b7268d92-4d8d-5e9c-a3aa-c751a70de297', 'fb9f07d2-6197-5eca-a93c-08699db9bfd7', '20920397-2896-5349-acdb-300c09f001e9', 9, 9, 'ቦዔዝም ሽማግሌዎችንና ሕዝቡን ሁሉ፦ ለአቤሜሌክና ለኬሌዎን ለመሐሎንም የነበረውን ሁሉ ከኑኃሚን እጅ እንደ ገዛሁ እናንተ ዛሬ ምስክሮች ናችሁ።'),
  ('c3e1f602-4fbe-540b-aeed-5775a181a1c1', 'fb9f07d2-6197-5eca-a93c-08699db9bfd7', '20920397-2896-5349-acdb-300c09f001e9', 10, 10, 'ደግሞም የምዋቹ ስም ከወንድሞቹ መካከል ከአገሩም ደጅ እንዳይጠፋ፥ የምዋቹን ስም በርስቱ ላይ እንዳስነሣ የመሐሎንን ሚስት ሞዓባዊቱን ሩትን ሚስት ትሆነኝ ዘንድ ወሰድሁአት፣ እናንተም ዛሬ ምስክሮች ናችሁ አላቸው።'),
  ('a95cef48-009d-5dc2-a3d3-241b5a4f7c41', 'fb9f07d2-6197-5eca-a93c-08699db9bfd7', '20920397-2896-5349-acdb-300c09f001e9', 11, 11, 'በከተማይቱ በር አደባባይም የነበሩ ሕዝብ ሁሉ ሽማግሌዎቹም፦ እኛ ምስክሮች ነን፣ እግዚአብሔር ይህችን ወደ ቤትህ የምትገባውን ሴት የእስራኤልን ቤት እንደ ሠሩ እንደ ሁለቱ እንደ ራሔልና እንደ ልያ ያድርጋት፣ አንተም በኤፍራታ ባለ ጠጋ ሁን፥ ስምህም በቤተ ልሔም ይጠራ።'),
  ('2f9113a8-685d-56df-ab6d-2c5f506a3486', 'fb9f07d2-6197-5eca-a93c-08699db9bfd7', '20920397-2896-5349-acdb-300c09f001e9', 12, 12, 'ቤትህም እግዚአብሔር ከዚህች ቈንጆ ከሚስጥህ ዘር ትዕማር ለይሁዳ እንደ ወለደች እንደ ፋሬስ ቤት ይሁን አሉት።'),
  ('631f8014-344e-50fc-a2aa-c2a7686277d5', 'fb9f07d2-6197-5eca-a93c-08699db9bfd7', '20920397-2896-5349-acdb-300c09f001e9', 13, 13, 'ቦዔዝም ሩትን ወሰደ፥ ሚስትም ሆነችው፣ ደረሰባትም፥ እግዚአብሔርም ፅንስ ለጣት፥ ወንድ ልጅም ወለደች።'),
  ('e66c9e97-89ba-5d39-a7ae-88a499b18373', 'fb9f07d2-6197-5eca-a93c-08699db9bfd7', '20920397-2896-5349-acdb-300c09f001e9', 14, 14, 'ሴቶችም ኑኃሚንን፦ ዛሬ ዋርሳ ያላሳጣሽ እግዚአብሔር ይባረክ፣ ስሙም በእስራኤል ይጠራ።'),
  ('7d1d473c-88ac-5dbd-a64d-13f720aa26c1', 'fb9f07d2-6197-5eca-a93c-08699db9bfd7', '20920397-2896-5349-acdb-300c09f001e9', 15, 15, 'ከሰባትም ወንዶች ልጆች ይልቅ ለአንቺ ከምትሻል ከምትወድድሽ ምራት ተወልዶአልና ሰውነትሽን ያሳድሰዋል፥ በእርጅናሽም ይመግብሻል አሉአት።'),
  ('e5c1fd42-0ed7-5cfa-a160-f11e5fdee797', 'fb9f07d2-6197-5eca-a93c-08699db9bfd7', '20920397-2896-5349-acdb-300c09f001e9', 16, 16, 'ኑኃሚንም ሕፃኑን ወሰደች አቀፈችውም፥ ሞግዚትም ሆነችው።'),
  ('d6e7bab9-15f9-5af8-a3f2-630b844d5baa', 'fb9f07d2-6197-5eca-a93c-08699db9bfd7', '20920397-2896-5349-acdb-300c09f001e9', 17, 17, 'ሴቶችም ጎረቤቶችዋ፥ ለኑኃሚን ወንድ ልጅ ተወለደላት እያሉ ስም አወጡለት፣ ስሙንም ኢዮቤድ ብለው ጠሩት። እርሱም የዳዊት አባት የእሴይ አባት ነው።'),
  ('f6d220c5-25c2-5dc8-aebb-1f025d71e78e', 'fb9f07d2-6197-5eca-a93c-08699db9bfd7', '20920397-2896-5349-acdb-300c09f001e9', 18, 18, 'የፋሬስም ትውልድ ይህ ነው፣ ፋሬስ ኤስሮምን ወለደ፥'),
  ('4bbdab1a-cd87-5583-ad32-452dd14271e8', 'fb9f07d2-6197-5eca-a93c-08699db9bfd7', '20920397-2896-5349-acdb-300c09f001e9', 19, 19, 'ኤስሮምም አራምን ወለደ፥ አራምም አሚናዳብን ወለደ፥'),
  ('0343f427-e96e-535a-aafe-ec875557786e', 'fb9f07d2-6197-5eca-a93c-08699db9bfd7', '20920397-2896-5349-acdb-300c09f001e9', 20, 20, 'አሚናዳብም ነአሶንን ወለደ፥ ነአሶንም ሰልሞንን ወለደ፥'),
  ('5943ab24-d3c7-59f1-a769-46f6a6537be1', 'fb9f07d2-6197-5eca-a93c-08699db9bfd7', '20920397-2896-5349-acdb-300c09f001e9', 21, 21, 'ሰልሞንም ቦዔዝን ወለደ፥'),
  ('0effbc42-624e-57a4-a17f-cf62d2450c60', 'fb9f07d2-6197-5eca-a93c-08699db9bfd7', '20920397-2896-5349-acdb-300c09f001e9', 22, 22, 'ቦዔዝም ኢዮቤድን ወለደ፥ ኢዮቤድም እሴይን ወለደ፥ እሴይም ዳዊትን ወለደ።'),
  ('18eb9ef0-a00d-598a-a481-2a430b7f05b0', '1ead3289-89a6-5c89-a795-63647d36efd6', '95df1b85-d130-5cfb-a50e-9ca3469323e1', 1, 1, 'በተራራማው በኤፍሬም ሀገር ከአርማቴም መሴፋ የሆነ አንድ ሰው ነበረ። ስሙም፥ የናሲብ ልጅ የቴቆ ልጅ፥ የኤልዩ ልጅ ፥ የኢያርምያል ልጅ፥ ኤፍራታዊው ሕልቃና ነበረ።'),
  ('30bc4a3e-2292-5c15-ad81-11a2412db12e', '1ead3289-89a6-5c89-a795-63647d36efd6', '95df1b85-d130-5cfb-a50e-9ca3469323e1', 2, 2, 'ሁለትም ሚስቶች ነበሩት፤ የአንዲቱ ስም ሐና፥ የሁለተኛዪቱም ስም ፍናና ነበረ፤ ለፍናናም ልጆች ነበሩአት፤ ለሐና ግን ልጆች አልነበሩአትም።'),
  ('e1970646-a7b8-5e6c-a12e-7c378aae851a', '1ead3289-89a6-5c89-a795-63647d36efd6', '95df1b85-d130-5cfb-a50e-9ca3469323e1', 3, 3, 'ያም ሰው በሴሎ ይሰግድ ዘንድ፥ ለሠራዊት ጌታም ለእግዚአብሔር ይሠዋ ዘንድ ከከተማው ከአርማቴም በየዓመቱ ይወጣ ነበር። የእግዚአብሔርም ካህናት ሁለቱ የዔሊ ልጆች አፍኒንና ፊንሐስ በዚያ ነበሩ።'),
  ('b1a1f1d1-a55a-51a1-a95d-7977b938eb10', '1ead3289-89a6-5c89-a795-63647d36efd6', '95df1b85-d130-5cfb-a50e-9ca3469323e1', 4, 4, 'ሕልቃናም የሚሠዋበት ቀን በደረሰ ጊዜ ለሚስቱ ለፍናናና ለልጆችዋ ሁሉ ዕድል ፋንታቸውን ሰጣቸዉ።'),
  ('fa93a155-8b6a-5e39-abfb-43f19b75878b', '1ead3289-89a6-5c89-a795-63647d36efd6', '95df1b85-d130-5cfb-a50e-9ca3469323e1', 5, 5, 'ለሐናም ልጅ ስላልነበራት አንድ ዕድል ፋንታ ሰጣት፤ ሕልቃናም ከዚያችኛይቱ ይልቅ ሐናን ይወድድ ነበር። እግዚአብሔር ግን ማኅፀንዋን ዘግቶ ነበር።'),
  ('900993cc-71fa-5049-a03e-0c2ae1cc4285', '1ead3289-89a6-5c89-a795-63647d36efd6', '95df1b85-d130-5cfb-a50e-9ca3469323e1', 6, 6, 'እንደ መከራዋና እንደ ኀዘንዋም እግዚአብሔር ልጅ አልሰጣትም ነበር። ስለዚህም ታዝን ነበር። እግዚአብሔር ማኅፀንዋን ዘግትዋልና፥ ልጆችንም አልሰጣትምና።'),
  ('cb27a067-39fa-5f35-a2f9-a633a9cce0a0', '1ead3289-89a6-5c89-a795-63647d36efd6', '95df1b85-d130-5cfb-a50e-9ca3469323e1', 7, 7, 'በየዓመቱም ወደ እግዚአብሔር ቤት በሚወጣበት ጊዜ እንዲህ ያደርግ ነበር፤ እርስዋም ትበሳጭና ታለቅስ ነበር። እህልም አትበላም ነበር።'),
  ('b8ef6852-4dc0-54b0-a6b8-99d906746eaf', '1ead3289-89a6-5c89-a795-63647d36efd6', '95df1b85-d130-5cfb-a50e-9ca3469323e1', 8, 8, 'ባልዋ ሕልቃናም፥ “ሐና ሆይ!” አላት እርስዋም፥ “ጌታዬ እነሆኝ” አለችው። እርሱም፥ “ለምን ታለቅሻለሽ? ለምንስ አትበዪም? ለምንስ ልብሽ ያዝንብሻል? እኔስ ከዐሥር ልጆች አልሻልሽምን?” አላት።'),
  ('a4bed964-8c64-5b28-ae71-ecf217656e13', '1ead3289-89a6-5c89-a795-63647d36efd6', 'b94aa790-433d-598b-a4b1-ef7d165cba26', 1, 9, 'በሴሎም ከበሉ በኋላ ሐና ተነሣች። በሴሎም በእግዚአብሔር ፊት ቆመች። ካህኑም ዔሊ በእግዚአብሔር መቅደስ መቃን አጠገብ በወንበሩ ላይ ተቀምጦ ነበር።'),
  ('3edb257a-0072-5b84-a30a-8ecda97fa0ad', '1ead3289-89a6-5c89-a795-63647d36efd6', 'b94aa790-433d-598b-a4b1-ef7d165cba26', 2, 10, 'እርስዋም በልብዋ አዝና አለቀሰች፤ ወደ እግዚአብሔርም ጸለየች።'),
  ('e58e96d5-7b3f-5b25-a85c-81d72bad5675', '1ead3289-89a6-5c89-a795-63647d36efd6', 'b94aa790-433d-598b-a4b1-ef7d165cba26', 3, 11, 'እርስዋም፥ “አዶናይ፥ የሠራዊት አምላክ እግዚአብሔር ሆይ! የባርያህን መዋረድ ተመልክተህ ብታስበኝ፥ ለባርያህም ወንድ ልጅ ብትሰጥ ዕድሜውን ሁሉ ለአንተ እሰጠዋለሁ፤ የወይን ጠጅና የሚያሰክር መጠጥም አይጠጣም። ምላጭም በራሱ ላይ አይደርስም” ብላ ስእለት ተሳለች።'),
  ('5737dacf-985b-5e33-a89b-21460df8be4b', '1ead3289-89a6-5c89-a795-63647d36efd6', 'b94aa790-433d-598b-a4b1-ef7d165cba26', 4, 12, 'ጸሎቷንም በእግዚአብሔር ፊት ባበዛች ጊዜ፥ ካህኑ ዔሊ አፍዋን ይመለከት ነበር።'),
  ('8c70ae25-45e1-5148-a5ab-686113346d9d', '1ead3289-89a6-5c89-a795-63647d36efd6', 'b94aa790-433d-598b-a4b1-ef7d165cba26', 5, 13, 'ሐናም በልብዋ ትናገር ነበር፤ ድምፅዋም ሳይሰማ ከንፈርዋን ታንቀሳቅስ ነበር፤ ዔሊም እንደ ሰከረች ቈጠራት።'),
  ('bddd2e6c-cc72-548b-ac88-5671ea05711f', '1ead3289-89a6-5c89-a795-63647d36efd6', 'b94aa790-433d-598b-a4b1-ef7d165cba26', 6, 14, 'የዔሊም አገልጋይ፦ “ስካርሽ እስከ መቼ ነው? የወይን ጠጅሽን ከአንቺ አርቂው፤ ከእግዚአብሔርም ፊት ውጪ” አላት።'),
  ('4aa74c9e-dad0-5d1a-a52d-fb4ac6fa52be', '1ead3289-89a6-5c89-a795-63647d36efd6', 'b94aa790-433d-598b-a4b1-ef7d165cba26', 7, 15, 'ሐናም መልሳ እንዲህ አለችው፥ “ጌታዬ ሆይ፥ አይደለም፤ እኔስ ወራት የባሳት ሴት ነኝ፤ ጠጅና ሌላ የሚያሰክር ነገር አልጠጣሁም፤ ነገር ግን በእግዚአብሔር ፊት ነፍሴን አፈሰስሁ፤'),
  ('3f32134c-6be6-524f-aad3-4c5480b3d406', '1ead3289-89a6-5c89-a795-63647d36efd6', 'b94aa790-433d-598b-a4b1-ef7d165cba26', 8, 16, 'ኀዘኔና ጭንቀቴ ስለ በዛ እስከ አሁን ድረስ እደክማለሁና ባርያህን እንደ ኀጢአተኞች ሴቶች ልጆች አትቍጠራት።”'),
  ('033417ed-b73f-5842-ae1b-49cff97ec89f', '1ead3289-89a6-5c89-a795-63647d36efd6', 'b94aa790-433d-598b-a4b1-ef7d165cba26', 9, 17, 'ዔሊም፥ “በሰላም ሂጂ፤ የእስራኤልም አምላክ ከአንቺ ጋር ይሁን የለመንሽውንም ልመና ሁሉ ይስጥሽ” ብሎ መለሰላት።'),
  ('6d02085e-bbed-50f7-a4a5-9d99d2f651ec', '1ead3289-89a6-5c89-a795-63647d36efd6', 'b94aa790-433d-598b-a4b1-ef7d165cba26', 10, 18, 'እርስዋም፥ “ባርያህ በፊትህ ሞገስን አገኘች” አለችው። ሴቲቱም መንገድዋን ሄደች፤ ወደ ቤትዋም ገባች፤ ከባሏም ጋር በላች፤ ጠጣችም ፤ ፊቷም ከዚያ በኋላ አዘንተኛ መስሎ አልታየም።'),
  ('aac79acc-2c3f-5a48-abb7-58f09a51c6dd', '1ead3289-89a6-5c89-a795-63647d36efd6', 'd99fcb72-75ec-513c-a4dd-b8f2c165d9fc', 1, 19, 'ማልደውም ተነሥተው ለእግዚአብሔር ሰግደው ሄዱ፤ ወደ ቤታቸውም ወደ አርማቴም ደረሱ፤ ሕልቃናም ሚስቱን ሐናን ዐወቃት፤ እግዚአብሔርም አሰባት፤ ፀነሰችም።'),
  ('b6ba6571-c035-5ad0-ae35-4c821584ff59', '1ead3289-89a6-5c89-a795-63647d36efd6', 'd99fcb72-75ec-513c-a4dd-b8f2c165d9fc', 2, 20, 'የመውለጃዋም ወራት በደረሰ ጊዜ ሐና ወንድ ልጅ ወለደች፤ እርስዋም፥ “ከሠራዊት ጌታ ከእግዚአብሔር ለምኜዋለሁ” ስትል ስሙን “ሳሙኤል” ብላ ጠራችው።'),
  ('08560cb3-f41e-52cb-a74e-599b3d21d90d', '1ead3289-89a6-5c89-a795-63647d36efd6', 'd99fcb72-75ec-513c-a4dd-b8f2c165d9fc', 3, 21, 'ሰውዬውም ሕልቃና ከቤተ ሰቡ ሁሉ ጋር የዓመቱን መሥዋዕትና ስእለቱን፥ የምድሩንም ዐሥራት ሁሉ ለእግዚአብሔር ያቀርብ ዘንድ ወጣ።'),
  ('b9b9b2b3-b725-549e-ac3d-8f42d5ac5a21', '1ead3289-89a6-5c89-a795-63647d36efd6', 'd99fcb72-75ec-513c-a4dd-b8f2c165d9fc', 4, 22, 'ሐና ግን ከእርሱ ጋር አልወጣችም። ለባልዋም፥ “ሕፃኑን ጡት እስከ አስጥለው፥ ከእኔም ጋር እስኪወጣና በእግዚአብሔር ፊት እስኪታይ ድረስ አልወጣም፤ በዚያም ለዘለዓለም ይኖራል” ብላዋለችና።'),
  ('15093eae-71b0-5713-a545-eb972cce7084', '1ead3289-89a6-5c89-a795-63647d36efd6', 'd99fcb72-75ec-513c-a4dd-b8f2c165d9fc', 5, 23, 'ባልዋም ሕልቃና፥ “በዐይንሽ ደስ ያሰኘሽን አድርጊ፤ ጡትም እስኪተው ድረስ ተቀመጪ፤ ብቻ እግዚአብሔር ከአፍሽ የወጣውን ያጽና” አላት። ሴቲቱም ልጅዋን እያጠባች ጡት እስኪተው ድረስ ተቀመጠች።'),
  ('475f8a59-15f8-51aa-aaf9-b92c26cd9d1a', '1ead3289-89a6-5c89-a795-63647d36efd6', 'd99fcb72-75ec-513c-a4dd-b8f2c165d9fc', 6, 24, 'እርስዋም ከእርሱ ጋር አንድ የሦስት ዓመት ወይፈን፥ እንጀራ፥ አንድ የኢፍ መስፈሪያ ዱቄት፥ አንድ አቁማዳ የወይን ጠጅ ይዛ ወደ ሴሎ ወጣች። በሴሎም ወዳለው ወደ እግዚአብሔር ቤት ገባች። ልጃቸውም ከእነርሱ ጋር ነበረ።'),
  ('6e28cf23-d828-5b89-a168-98b59657d564', '1ead3289-89a6-5c89-a795-63647d36efd6', 'd99fcb72-75ec-513c-a4dd-b8f2c165d9fc', 7, 25, 'በእግዚአብሔርም ፊት አቀረቡት ፤ አባቱም በየዓመቱ ለእግዚአብሔር የሚሠዋውን መሥዋዕት ሠዋ። ሕፃኑንም አቀረበው፤ ወይፈኑንም አረደ፤ እናቱም ሐና ሕፃኑን ወደ ዔሊ አገባችው።'),
  ('35524566-2d81-5237-ab5a-062005b4c6f7', '1ead3289-89a6-5c89-a795-63647d36efd6', 'd99fcb72-75ec-513c-a4dd-b8f2c165d9fc', 8, 26, 'እርስዋም አለች፥ “ጌታዬ ሆይ! በሕያው ነፍስህ እምላለሁ፤ ወደ እግዚአብሔር ለመጸለይ በዚህ በፊትህ ቆማ የነበረች ሴት እኔ ነኝ።'),
  ('e16ebae5-c91d-589c-a9d3-020e6e7c0dac', '1ead3289-89a6-5c89-a795-63647d36efd6', 'd99fcb72-75ec-513c-a4dd-b8f2c165d9fc', 9, 27, 'ስለዚህ ልጅ ተሳልሁ፤ ጸለይሁም፤ እግዚአብሔርም የለመንሁትን ልመናዬን ሰጥቶኛል፤'),
  ('7f4f9098-f41b-59e8-a157-1a6e35351967', '1ead3289-89a6-5c89-a795-63647d36efd6', 'd99fcb72-75ec-513c-a4dd-b8f2c165d9fc', 10, 28, 'እኔም ደግሞ ዕድሜውን ሙሉ እግዚአብሔርን ያገለግል ዘንድ ለእግዚአብሔር ሰጥቼዋለሁ።”'),
  ('5cb8e120-a7d2-521e-a9f9-5545db566ac6', 'cd9234e7-cfa5-52c3-a03d-72b332206f75', 'df7e7f0a-3cec-562a-a5da-f52297f6b45e', 1, 11, 'በዚያም በእግዚአብሔር ፊት ተዉት። እነርሱም ወደ አርማቴም ወደ ቤታቸው ገቡ፤ ልጁም በካህኑ በዔሊ ፊት እግዚአብሔርን ያገለግል ነበር።'),
  ('49bb25e4-41bd-5fa1-a0ba-35a95c6d6c1f', 'cd9234e7-cfa5-52c3-a03d-72b332206f75', '2e1056b5-bd92-5ff1-acfe-0cd83342cb3a', 1, 12, 'የካህኑም የዔሊ ልጆች ክፉዎች ነበሩ፤ እግዚአብሔርንም አያውቁም ነበር።'),
  ('e6c30f77-68af-5d3c-abe9-ad6777144ba5', 'cd9234e7-cfa5-52c3-a03d-72b332206f75', '2e1056b5-bd92-5ff1-acfe-0cd83342cb3a', 2, 13, 'መሥዋዕት በሚሠዉ በሕዝቡ ሁሉ ዘንድ የነበረ የካህኑንም ሕግ አያውቁም ነበረ፤ ሕዝቡም ሁሉ መሥዋዕት በሠዉ ጊዜ የካህኑ ብላቴና ይመጣ ነበር፤ በእጁም ሦስት ጣት ያለው ሜንጦ ነበር፤'),
  ('abdb5f38-0bef-54ff-a79b-8eae7048487f', 'cd9234e7-cfa5-52c3-a03d-72b332206f75', '2e1056b5-bd92-5ff1-acfe-0cd83342cb3a', 3, 14, 'ወደ ድስቱም ወይም ወደ ምንቸቱ ወይም ወደ አፍላሉ ወይም ወደ ቶፋው ይሰድደው ነበር። ሜንጦውም ያወጣውን ሁሉ ካህኑ ለእርሱ ይወስደው ነበር፤ በሴሎም ለእግዚአብሔር ሊሠዉ በሚወጡ በእስራኤላውያን ሁሉ ላይ እንዲህ ያደርጉ ነበር።'),
  ('917d9a76-a5e1-5f9e-a77a-2cc74838d9e9', 'cd9234e7-cfa5-52c3-a03d-72b332206f75', '2e1056b5-bd92-5ff1-acfe-0cd83342cb3a', 4, 15, 'ደግሞም ስቡ ሳይጤስ የካህኑ ልጅ መጥቶ የሚሠዋውን ሰው፥ “ጥሬውን እንጂ የተቀቀለውን ሥጋ ከአንተ አይወስድምና እጠብስለት ዘንድ ለካህኑ ሥጋ ስጠኝ” ይለው ነበር።'),
  ('8e556561-61eb-559b-ab21-b9e4bb2ffe75', 'cd9234e7-cfa5-52c3-a03d-72b332206f75', '2e1056b5-bd92-5ff1-acfe-0cd83342cb3a', 5, 16, 'የሚሠዋውም ሰው፥ “አስቀድሞ እንደ ሕጉ ስቡ ይጢስ፤ ኋላም ሰውነትህን ደስ የሚያሰኛትን ትወስዳለህ” ቢለው፥ እርሱ፥ “አይሆንም፥ ነገር ግን አሁን ስጠኝ፤ ካልሆነም በግድ አወስደዋለሁ” ይለው ነበር።'),
  ('8d27d207-0a27-5f94-a909-5f99f4c531c3', 'cd9234e7-cfa5-52c3-a03d-72b332206f75', '2e1056b5-bd92-5ff1-acfe-0cd83342cb3a', 6, 17, 'የእግዚአብሔርን ቍርባን ይንቁ ነበርና የዔሊ ልጆች ኀጢአት በእግዚአብሔር ፊት እጅግ ታላቅ ነበረች።'),
  ('61e528b4-15e9-5d5b-aa08-5f52d32fd46b', 'cd9234e7-cfa5-52c3-a03d-72b332206f75', '464123dc-ed0c-51a1-aa92-e3832bb05c9f', 1, 18, 'ሳሙኤል ግን ገና ብላቴና ሳለ የበፍታ ኤፉድ ታጥቆ በእግዚአብሔር ፊት ያገለግል ነበር።'),
  ('521f19a3-5482-56e0-ab00-f4803b7b346d', 'cd9234e7-cfa5-52c3-a03d-72b332206f75', '464123dc-ed0c-51a1-aa92-e3832bb05c9f', 2, 19, 'እናቱም ታናሽ መደረቢያ ሠራችለት፤ በየዓመቱም መሥዋዕት ለመሠዋት ከባልዋ ጋር ስትወጣ ትወስድለት ነበር።'),
  ('130c5046-4246-50cf-a5f6-825478c9f61e', 'cd9234e7-cfa5-52c3-a03d-72b332206f75', '464123dc-ed0c-51a1-aa92-e3832bb05c9f', 3, 20, 'ዔሊም ሕልቃናንና ሚስቱን ባረካቸው፥ “ለእግዚአብሔር ስለ አገባኸው ስጦታ ፈንታ ከዚህች ሴት እግዚአብሔር ዘር ይስጥህ” አለው፤ እነርሱም ወደ ቤታቸው ገቡ።'),
  ('d2e2417f-39f2-5543-a2b7-f1499a770b0f', 'cd9234e7-cfa5-52c3-a03d-72b332206f75', '464123dc-ed0c-51a1-aa92-e3832bb05c9f', 4, 21, 'እግዚአብሔርም ሐናን ጐበኘ፤ ዳግመኛም ፀነሰች፥ ሦስት ወንዶችና ሁለት ሴቶች ልጆችን ወለደች። ብላቴናው ሳሙኤልም በእግዚአብሔር ፊት አደገ።'),
  ('65338238-489e-539a-a2cc-bd8ce83111c0', 'cd9234e7-cfa5-52c3-a03d-72b332206f75', '1c428cbc-1ecd-5172-a6b9-7a831be4a06d', 1, 22, 'ዔሊም እጅግ አረጀ፤ ልጆቹም የእስራኤልን ልጆች ያደረጓቸውን፥ በምስክሩ ድንኳን ደጃፍ ከሚያገለግሉት ሴቶችም ጋር እንደሚተኙ ሰማ።'),
  ('33c9fd36-e65c-5284-a88f-dde1079edb37', 'cd9234e7-cfa5-52c3-a03d-72b332206f75', '1c428cbc-1ecd-5172-a6b9-7a831be4a06d', 2, 23, 'እርሱም አላቸው፥ “ከእግዚአብሔር ሕዝብ ሁሉ አፍ የምሰማውን ይህን ነገር ለምን ታደርጋላችሁ?'),
  ('28639af7-243d-5f07-a9c7-591747a4e70f', 'cd9234e7-cfa5-52c3-a03d-72b332206f75', '1c428cbc-1ecd-5172-a6b9-7a831be4a06d', 3, 24, 'ልጆቼ ሆይ፥ ይህ አይሆንም፤ እኔ የምሰማው ይህ ነገር መልካም አይደለምና እንዲህ አታድርጉ። ሕዝቡንም እግዚአብሔርን ከማገልገል አትከልክሉአቸው።'),
  ('a02f0bc3-6e27-5bc9-a831-92649244cbab', 'cd9234e7-cfa5-52c3-a03d-72b332206f75', '1c428cbc-1ecd-5172-a6b9-7a831be4a06d', 4, 25, 'ሰውስ ሰውን ቢበድል ወደ እግዚአብሔር ይጸልዩለታል፤ ሰው ግን እግዚአብሔርን ቢበድል ስለ እርሱ ወደ ማን ይጸልዩለታል?” እነርሱ ግን እግዚአብሔር ሊያጠፋቸው ወድዶአልና የአባታቸውን ቃል አልሰሙም።'),
  ('400773eb-1db6-500a-a4a4-358f27b99490', 'cd9234e7-cfa5-52c3-a03d-72b332206f75', '1c428cbc-1ecd-5172-a6b9-7a831be4a06d', 5, 26, 'ብላቴናው ሳሙኤልም አደገ፤ በእግዚአብሔርም በሰውም ፊት ሞገስ እያገኘ ሄደ።'),
  ('22cca927-783c-5de5-abca-8ab15791a288', 'cd9234e7-cfa5-52c3-a03d-72b332206f75', 'ffbea2af-9e49-56ac-acca-169c96ee7f16', 1, 27, 'የእግዚአብሔርም ሰው ወደ ዔሊ መጥቶ እንዲህ አለው፥ “እግዚአብሔር እንዲህ ይላል፦ በግብፅ በፈርዖን ቤት ባሪያዎች ሳሉ ለአባትህ ቤት ተገለጥሁ፤'),
  ('4afc51b5-5018-57d1-abfd-228c4b8bb348', 'cd9234e7-cfa5-52c3-a03d-72b332206f75', 'ffbea2af-9e49-56ac-acca-169c96ee7f16', 2, 28, 'ከእስራኤልም ነገድ ሁሉ ካህን ይሆነኝ ዘንድ፥ በመሠዊያዬም ላይ ይሠዋ ዘንድ፥ ዕጣንንም ያጥን ዘንድ፥ ኤፉድንም በፊቴ ይለብስ ዘንድ፥ የአባትህን ቤት ለእኔ መረጥሁት፤ የእስራኤልንም ልጆች የእሳት ቍርባን ሁሉ ስለ ምግብ ለአባትህ ቤት ሰጠሁ።'),
  ('67666df7-e2d8-5179-aea5-b6ec0a7117d2', 'cd9234e7-cfa5-52c3-a03d-72b332206f75', 'ffbea2af-9e49-56ac-acca-169c96ee7f16', 3, 29, 'በመሥዋዕቴ ላይና በዕጣኔ ላይ ስለ ምን በክፉ ዐይን ተመለከትህ? የእስራኤል ልጆች በፊቴ ከሚያቀርቡት መሥዋዕት ሁሉ በቀዳምያቱ ስለ አከበርሁህ ከእኔ ይልቅ ልጆችህን ለምን መረጥህ?'),
  ('88b36e77-d130-542c-ac6e-2b6a1ccf664c', 'cd9234e7-cfa5-52c3-a03d-72b332206f75', 'ffbea2af-9e49-56ac-acca-169c96ee7f16', 4, 30, 'ስለዚህም የእስራኤል አምላክ እግዚአብሔር እንዲህ ይላል፦ በእውነት ቤትህ፥ የአባትህም ቤት፤ ለዘለዓለም በፊቴ እንዲኖር ተናግሬአለሁ፤ አሁን ግን እግዚአብሔር እንዲህ ይላል፦ ያከበሩኝን አከብራለሁና፥ የናቁኝም ይናቃሉና ይህ አይሆንልኝም።'),
  ('a616e694-d805-5361-a7a5-c7f615569cd4', 'cd9234e7-cfa5-52c3-a03d-72b332206f75', 'ffbea2af-9e49-56ac-acca-169c96ee7f16', 5, 31, 'እነሆ፥ ዘርህንም፥ የአባትህንም ቤት ዘር የማጠፋበት ዘመን ይመጣል፤'),
  ('1639ab8a-7a8a-5cf8-a785-4f52d5f8b65c', 'cd9234e7-cfa5-52c3-a03d-72b332206f75', 'ffbea2af-9e49-56ac-acca-169c96ee7f16', 6, 32, 'በቤትህም ለዘለዓለም ሽማግሌ አይገኝም።'),
  ('7d2eb7e4-9604-58e9-a3b1-6d1311b9b941', 'cd9234e7-cfa5-52c3-a03d-72b332206f75', 'ffbea2af-9e49-56ac-acca-169c96ee7f16', 7, 33, 'በዐይኖቹ የሚፈጽም በነፍሱም የሚተጋ ሰውን ከመሠዊያዬ አላጠፋም። ከቤትህ የሚቀሩት ሰዎች ሁሉ ግን በጐልማሶች ሰይፍ ይሞታሉ።'),
  ('7ddb5340-1db3-5e6a-a56d-154073ee736b', 'cd9234e7-cfa5-52c3-a03d-72b332206f75', 'ffbea2af-9e49-56ac-acca-169c96ee7f16', 8, 34, 'ይህ በሁለቱ ልጆችህ በአፍኒንና በፊንሐስ ላይ የሚመጣ ለአንተ ምልክት ነው፤ ሁለቱ በአንድ ቀን በጦር ይሞታሉ።'),
  ('868d709d-0570-5a8b-ac46-5b0414b60d0a', 'cd9234e7-cfa5-52c3-a03d-72b332206f75', 'ffbea2af-9e49-56ac-acca-169c96ee7f16', 9, 35, 'የታመነ ካህን ለእኔ አስነሣለሁ፤ በልቤም፥ በነፍሴም እንዳለ እንዲሁ ያደርጋል፤ እኔም የታመነ ቤት እሠራለታለሁ፤ ዘመኑን ሁሉ እኔ በቀባሁት ሰው ፊት ይሄዳል።'),
  ('bedd5428-56e8-50df-a1ef-4f86d1cd5585', 'cd9234e7-cfa5-52c3-a03d-72b332206f75', 'ffbea2af-9e49-56ac-acca-169c96ee7f16', 10, 36, 'ከቤትህም የቀረው ሁሉ ይመጣል፤ ከካህናትም ወደ አንዲቱ ዕጣ፥ እንጀራ ወደምበላበት እባክህ ላከኝ ብሎ ለአንድ ብር መሐልቅ ለቍራሽ እንጀራ በፊቱ ይሰግዳል።”'),
  ('c5eccda4-609e-53dd-a737-b83e40608d32', '8c4fbf22-19a9-5861-aba8-f90e3a31fb9d', '34e47fd5-dcd6-5b22-a609-2c348afed614', 1, 1, 'ብላቴናው ሳሙኤልም በዔሊ ፊት እግዚአብሔርን ያገለግል ነበር፤ በዚያም ዘመን የእግዚአብሔር ቃል ክቡር ነበረ፤ ራእይም አይገለጥም ነበር።'),
  ('b3cb2db5-3d54-5112-a1e4-60246b5f68aa', '8c4fbf22-19a9-5861-aba8-f90e3a31fb9d', '34e47fd5-dcd6-5b22-a609-2c348afed614', 2, 2, 'በዚያም ዘመን እንዲህ ሆነ፤ ዔሊም በስፍራው ተኝቶ ሳለ፥ ዐይኖቹ መፍዘዝ ጀምረው ነበር። ማየትም አይችልም ነበር።'),
  ('8c98cf00-186e-5fd6-a08e-9d1f2cd909c4', '8c4fbf22-19a9-5861-aba8-f90e3a31fb9d', '34e47fd5-dcd6-5b22-a609-2c348afed614', 3, 3, 'የእግዚአብሔርም መብራት ገና አልጠፋም ነበር፤ ሳሙኤልም የእግዚአብሔር ታቦት ባለበት በእግዚአብሔር መቅደስ ተኝቶ ነበር፤'),
  ('3018d65c-d576-5892-a3fd-8752f303dc74', '8c4fbf22-19a9-5861-aba8-f90e3a31fb9d', '34e47fd5-dcd6-5b22-a609-2c348afed614', 4, 4, 'እግዚአብሔርም ሳሙኤልን፥ “ሳሙኤል! ሳሙኤል” ብሎ ጠራው፤ እርሱም፥ “እነሆኝ” አለ።'),
  ('896d9e4e-0cce-559d-ab16-925ef2916dba', '8c4fbf22-19a9-5861-aba8-f90e3a31fb9d', '34e47fd5-dcd6-5b22-a609-2c348afed614', 5, 5, 'ወደ ዔሊም ሮጠ፥ “እነሆኝ ስለ ጠራኸኝ መጣሁ” አለው። እርሱም፥ “አልጠራሁህም፤ ተመልሰህ ተኛ” አለው። ሄዶም ተኛ።'),
  ('44389764-dd2f-5dcd-aaf6-37a3195edce0', '8c4fbf22-19a9-5861-aba8-f90e3a31fb9d', '34e47fd5-dcd6-5b22-a609-2c348afed614', 6, 6, 'እግዚአብሔርም ደግሞ፥ “ሳሙኤል! ሳሙኤል” ብሎ ጠራው። ሳሙኤልም ተነሥቶ ዳግመኛ ወደ ዔሊ ሄደና፥ “እነሆኝ ስለ ጠራኸኝ መጣሁ” አለ። እርሱም፥ “አልጠራሁህም ተመልሰህ ተኛ” አለው።'),
  ('8c0c53df-b626-5615-a033-c1c2bba7c8e1', '8c4fbf22-19a9-5861-aba8-f90e3a31fb9d', '34e47fd5-dcd6-5b22-a609-2c348afed614', 7, 7, 'ሳሙኤል ግን ከዚህ በፊት ገና እግዚአብሔርን አላወቀም ነበር፤ የእግዚአብሔርም ቃል ገና አልተገለጠለትም ነበር።'),
  ('79c5172e-190d-5f21-a914-dc7aec009e58', '8c4fbf22-19a9-5861-aba8-f90e3a31fb9d', '34e47fd5-dcd6-5b22-a609-2c348afed614', 8, 8, 'እግዚአብሔርም ሳሙኤልን እንደ ገና ሦስተኛ ጊዜ ጠራው። እርሱም ተነሥቶ ወደ ዔሊ ሄደና፥ “እነሆኝ ስለ ጠራኸኝ መጣሁ” አለ። ዔሊም እግዚአብሔር ልጁን እንደ ጠራው አስተዋለ።'),
  ('a0f5f4c6-cc57-596b-ad40-8154cfd9707b', '8c4fbf22-19a9-5861-aba8-f90e3a31fb9d', '34e47fd5-dcd6-5b22-a609-2c348afed614', 9, 9, 'ዔሊም ሳሙኤልን፥ “ልጄ፥ ሄደህ ተኛ፤ ቢጠራህም፦ አቤቱ፥ ባሪያህ ይሰማልና ተናገር በለው፥” አለው። ሳሙኤልም ሄዶ በስፍራው ተኛ።'),
  ('264852e0-6130-5d74-accc-a9845212db9a', '8c4fbf22-19a9-5861-aba8-f90e3a31fb9d', '34e47fd5-dcd6-5b22-a609-2c348afed614', 10, 10, 'እግዚአብሔርም መጥቶ ቆመ፤ እንደ ቀድሞውም ጠራው። ሳሙኤልም፥ “ባሪያህ ይሰማልና ተናገር” አለ።'),
  ('da66f077-3a48-5c40-a61b-f2fc850d6a4a', '8c4fbf22-19a9-5861-aba8-f90e3a31fb9d', '34e47fd5-dcd6-5b22-a609-2c348afed614', 11, 11, 'እግዚአብሔርም ሳሙኤልን አለው፥ “እነሆ የሰማውን ሁሉ ሁለቱን ጆሮዎቹን ጭው የሚያደርግ ነገሬን በእስራኤል ላይ አደርጋለሁ።'),
  ('b482fb9c-a5fb-5ca8-a2fc-eb7df1d80b37', '8c4fbf22-19a9-5861-aba8-f90e3a31fb9d', '34e47fd5-dcd6-5b22-a609-2c348afed614', 12, 12, 'በዚያም ቀን በቤቱ ላይ የተናገርሁትን ሁሉ በዔሊ ላይ አጸናለሁ፤ እኔም ጀምሬ እፈጽምበታለሁ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('4c11c0d2-9e00-5d16-a1ac-baa44ad70e79', '8c4fbf22-19a9-5861-aba8-f90e3a31fb9d', '34e47fd5-dcd6-5b22-a609-2c348afed614', 13, 13, 'ልጆቹ በእግዚአብሔር ላይ ክፉ እንዳደረጉ ዐውቆ አልገሠጻቸውምና ስለ ልጆቹ ኀጢአት ለዘለዓለም ቤቱን እንደምበቀል አስታውቄዋለሁ።'),
  ('941be9a7-ec4b-5408-a76c-de10006dd479', '8c4fbf22-19a9-5861-aba8-f90e3a31fb9d', '34e47fd5-dcd6-5b22-a609-2c348afed614', 14, 14, 'ስለዚህም የዔሊ ቤት ኀጢአት በዕጣንና በመሥዋዕት ለዘለዓለም እንዳይሰረይለት ለዔሊ ቤት ምያለሁ።”'),
  ('433ea9a4-11c6-55a4-aec8-ff40dd48dc1a', '8c4fbf22-19a9-5861-aba8-f90e3a31fb9d', '34e47fd5-dcd6-5b22-a609-2c348afed614', 15, 15, 'ሳሙኤልም እስኪነጋ ተኛ፥ ማልዶም ተነሥቶ የእግዚአብሔርን ቤት ደጅ ከፈተ። ሳሙኤልም ራእዩን ለዔሊ መንገር ፈራ።'),
  ('90dc36e0-34df-5245-ade2-11ca8a697c6c', '8c4fbf22-19a9-5861-aba8-f90e3a31fb9d', '34e47fd5-dcd6-5b22-a609-2c348afed614', 16, 16, 'ዔሊም ሳሙኤልን ጠርቶ፥ “ልጄ ሳሙኤል ሆይ፥” አለ፤ እርሱም፥ “እነሆኝ” አለ።'),
  ('e333e17f-a1f7-5d01-abf5-2dfe0ce8491f', '8c4fbf22-19a9-5861-aba8-f90e3a31fb9d', '34e47fd5-dcd6-5b22-a609-2c348afed614', 17, 17, 'እርሱም፥ “እግዚአብሔር የነገረህ ነገር ምንድን ነው? ከእኔ አትሸሽግ፤ ከነገረህና ከሰማኸው ነገር ሁሉ የሸሸግኸኝ እንደ ሆነ እግዚአብሔር እንዲህ ያድርግብህ፤ እንዲህም ይጨምርብህ” አለው።'),
  ('90c3056c-06a0-5eff-a7ef-de7ca5ce24f3', '8c4fbf22-19a9-5861-aba8-f90e3a31fb9d', '34e47fd5-dcd6-5b22-a609-2c348afed614', 18, 18, 'ሳሙኤልም ነገሩን ሁሉ ነገረው፤ አንዳችም አልሸሸገውም። ዔሊም፥ “እርሱ እግዚአብሔር ነው፤ ደስ ያሰኘውን ያድርግ” አለ።'),
  ('1566801b-6e69-5eb8-af41-8ef131ce6e28', '8c4fbf22-19a9-5861-aba8-f90e3a31fb9d', '34e47fd5-dcd6-5b22-a609-2c348afed614', 19, 19, 'ሳሙኤልም አደገ፤ እግዚአብሔርም ከእርሱ ጋር ነበረ፤ ከቃሉም አንዳች በምድር ላይ አይወድቅም ነበር።'),
  ('8cc089f5-a319-5d53-a155-82b4d4f8476f', '8c4fbf22-19a9-5861-aba8-f90e3a31fb9d', '34e47fd5-dcd6-5b22-a609-2c348afed614', 20, 20, 'እስራኤልም ሁሉ ከዳን እስከ ቤርሳቤህ ድረስ ሳሙኤል ለእግዚአብሔር ነቢይ ይሆን ዘንድ የታመነ እንደ ሆነ ዐወቀ።'),
  ('1eded06f-7356-541d-abe9-5d4a34e6c96a', '8c4fbf22-19a9-5861-aba8-f90e3a31fb9d', '34e47fd5-dcd6-5b22-a609-2c348afed614', 21, 21, 'እግዚአብሔርም ደግሞ በሴሎ ተገለጠ። እግዚአብሔር ለሳሙኤል ይገለጥለት ነበርና። ሳሙኤልም ከምድር ዳርቻ እስከ ምድር ዳርቻ ድረስ በእስራኤል ሁሉ የእግዚአብሔር ነቢይ እንደ ሆነ ታመነ። ዔሊም እጅግ አረጀ፥ ልጆቹ ግን በክፋት ጸንተው ኖሩ፤ መንገዳቸውም በእግዚአብሔር ፊት ክፉ ነበር።'),
  ('377469cf-6d67-5487-a3da-a70fbf4c3d6c', 'fe1131ad-58b4-5912-a00c-4d901e3171a7', 'f6ae0f48-a47a-5975-a8a4-1d3e173c0bf6', 1, 1, 'በእነዚያም ወራት እንዲህ ሆነ። ፍልስጥኤማውያን ለጦርነት በእስራኤላውያን ላይ ተሰበሰቡ። እስራኤልም ሊዋጉአቸው ወጡ፤ በአቤኔዜር አጠገብም ሰፈሩ፤ ፍልስጥኤማውያንም በአፌቅ ሰፈሩ።'),
  ('5737dfb1-4d58-5407-a464-beadd4e57f42', 'fe1131ad-58b4-5912-a00c-4d901e3171a7', 'f6ae0f48-a47a-5975-a8a4-1d3e173c0bf6', 2, 2, 'ፍልስጥኤማውያንም እስራኤልን ለመውጋት ተሰለፉ፤ እስራኤልም ሸሹ፤ በፍልስጥኤማውያንም ፊት ድል ሆኑ፤ ጦርነት በተደረገበትም ስፍራ ከእስራኤል አራት ሺህ ሰዎች ተገደሉ።'),
  ('b308499f-3ab6-5d0d-ab3d-63764d96f24b', 'fe1131ad-58b4-5912-a00c-4d901e3171a7', 'f6ae0f48-a47a-5975-a8a4-1d3e173c0bf6', 3, 3, 'ሕዝቡም ወደ ሰፈር በተመለሱ ጊዜ የእስራኤል ሽማግሌዎች፥ “ዛሬ እግዚአብሔር በፍልስጥኤማውያን ፊት ስለምን ጣለን? በፊታችን እንድትሄድ፥ ከጠላቶቻችንም እጅ እንድታድነን፥ የእግዚአብሔርን የቃል ኪዳኑን ታቦት ከሴሎ እናምጣ” አሉ።'),
  ('49850a8c-80cb-5386-a96d-c2649314a65d', 'fe1131ad-58b4-5912-a00c-4d901e3171a7', 'f6ae0f48-a47a-5975-a8a4-1d3e173c0bf6', 4, 4, 'ሕዝቡም ወደ ሴሎ ላኩ፤ በኪሩቤልም ላይ የሚቀመጠውን የሠራዊት ጌታ የእግዚአብሔርን የቃል ኪዳኑን ታቦት ከዚያ አመጡ፤ ሁለቱም የዔሊ ልጆች አፍኒንና ፊንሐስ ከእግዚአብሔር ቃል ኪዳን ታቦት ጋር በዚያ ነበሩ።'),
  ('c3a261c0-c7ea-5b27-a6a4-f4fabde81598', 'fe1131ad-58b4-5912-a00c-4d901e3171a7', 'f6ae0f48-a47a-5975-a8a4-1d3e173c0bf6', 5, 5, 'የእግዚአብሔር የቃል ኪዳን ታቦት ወደ ሰፈር በገባች ጊዜ እስራኤል ሁሉ ታላቅ እልልታ አደረጉ፤ ምድሪቱም አስተጋባች።'),
  ('2f61978e-8930-5853-a27a-9bccb65deba7', 'fe1131ad-58b4-5912-a00c-4d901e3171a7', 'f6ae0f48-a47a-5975-a8a4-1d3e173c0bf6', 6, 6, 'ፍልስጥኤማውያንም የእልልታውን ድምፅ በሰሙ ጊዜ፥ “በዕብራውያን ሰፈር ያለው ይህ ታላቅ የእልልታ ድምፅ ምንድን ነው?” አሉ። የእግዚአብሔርም ታቦት ወደ ሰፈሩ እንደ ደረሰች አስተዋሉ።'),
  ('24c0d34d-0848-5bc8-ad33-5a194ee34057', 'fe1131ad-58b4-5912-a00c-4d901e3171a7', 'f6ae0f48-a47a-5975-a8a4-1d3e173c0bf6', 7, 7, 'ፍልስጥኤማውያንም ፈርተው፥ “አማልክት ወደ እነርሱ ወደ ሰፈር መጥተዋል” አሉ። ደግሞም እንዲህ አሉ፥ “ወዮልን! አቤቱ፥ ዛሬ አድነን፤ ከዚህ አስቀድሞ እንዲህ ያለ ነገር አልሆነምና።'),
  ('217de93b-0a40-50c1-a269-6c6b25fc8b0a', 'fe1131ad-58b4-5912-a00c-4d901e3171a7', 'f6ae0f48-a47a-5975-a8a4-1d3e173c0bf6', 8, 8, 'ወዮልን! ከእነዚህ ኀያላን አማልክት እጅ ማን ያድነናል? እነዚህ አማልክት ግብፃውያንን በምድረ በዳ በልዩ ልዩ መቅሠፍት የመቱ ናቸው።'),
  ('e6b15f28-8aa1-54ea-a317-c4dac5303d4d', 'fe1131ad-58b4-5912-a00c-4d901e3171a7', 'f6ae0f48-a47a-5975-a8a4-1d3e173c0bf6', 9, 9, 'እናንተ ፍልስጥኤማውያን ሆይ! በርቱ፤ ጐብዙ፤ እናንተ ባሪያዎች እንዳደረጋችኋቸው ዕብራውያን ባሪያዎች እንዳያደርጓችሁ በርቱ፤ ተዋጉ።”'),
  ('fb1dd0b9-c89e-5fbd-a343-93de51bacb27', 'fe1131ad-58b4-5912-a00c-4d901e3171a7', 'f6ae0f48-a47a-5975-a8a4-1d3e173c0bf6', 10, 10, 'ከዚህም በኋላ ተዋጉአቸው፤ እስራኤልም በፍልስጥኤማውያን ፊት ወደቁ፤ ሁሉም እያንዳንዳቸው ወደ ድንኳናቸው ሸሹ፤ እጅግም ታላቅ ግድያ ሆነ፤ ከእስራኤልም ሠላሳ ሺህ እግረኞች ወደቁ።'),
  ('fef4c125-5a85-504a-a484-727b51eeb9a2', 'fe1131ad-58b4-5912-a00c-4d901e3171a7', 'f6ae0f48-a47a-5975-a8a4-1d3e173c0bf6', 11, 11, 'የእግዚአብሔርም ታቦት ተማረከች፤ ሁለቱም የዔሊ ልጆች አፍኒንና ፊንሐስ ሞቱ።'),
  ('b67c6df1-2f1e-5a0c-ac7c-6a6a3b515de6', 'fe1131ad-58b4-5912-a00c-4d901e3171a7', '5972a665-d0b8-5816-af9c-519afb9669a8', 1, 12, 'በዚያም ቀን አንድ የብንያም ሰው ከሰልፍ እየበረረ ወደ ሴሎ መጣ፤ ልብሱም ተቀድዶ ነበር፤ በራሱም ላይ ትቢያ ነስንሶ ነበር።'),
  ('24246d39-e0a3-57e6-aaea-732766847e47', 'fe1131ad-58b4-5912-a00c-4d901e3171a7', '5972a665-d0b8-5816-af9c-519afb9669a8', 2, 13, 'በመጣም ጊዜ ዔሊ ስለ እግዚአብሔር ታቦት ልቡ ተናውጦ ነበርና በመንገድ ዳር በወንበሩ ላይ ተቀምጦ ይጠባበቅ ነበር፤ ሰውዬውም ወደ ከተማዪቱ ገብቶ ባወራ ጊዜ ከተማዪቱ ሁሉ ተጭዋጭዋኸች።'),
  ('df09a8b1-10a0-5f68-aa78-fabbbbfe7345', 'fe1131ad-58b4-5912-a00c-4d901e3171a7', '5972a665-d0b8-5816-af9c-519afb9669a8', 3, 14, 'ዔሊም የጩኸቱን ድምፅ በሰማ ጊዜ፥ “ይህ ጩኸት ምንድን ነው?” አለ። ሰውዬውም ፈጥኖ መጣና ለዔሊ ነገረው።'),
  ('4e0c0037-5fd9-55cc-a744-21ac34b93d5e', 'fe1131ad-58b4-5912-a00c-4d901e3171a7', '5972a665-d0b8-5816-af9c-519afb9669a8', 4, 15, 'ዔሊም የዘጠና ስምንት ዓመት ሽማግሌ ነበረ፤ ዐይኖቹም ፈዝዘው አያይም ነበር።'),
  ('c8691a8c-4d62-5790-a040-1b2bc7d20e68', 'fe1131ad-58b4-5912-a00c-4d901e3171a7', '5972a665-d0b8-5816-af9c-519afb9669a8', 5, 16, 'ሰውዬውንም፥ “አንተ ከወዴት ነህ?” አለው። እርሱም፥ “ጦርነቱ ከአለበት ስፍራ የመጣሁ እኔ ነኝ፥ ዛሬም ከሰልፍ ሸሸሁ” አለ። እርሱም፥ “ልጄ ሆይ! ነገሩስ እንዴት ሆነ?” አለው።'),
  ('5cf645c7-7194-567a-a77b-a91f593dbcaa', 'fe1131ad-58b4-5912-a00c-4d901e3171a7', '5972a665-d0b8-5816-af9c-519afb9669a8', 6, 17, 'ያም ሰው መልሶ፥ “እስራኤል ከፍልስጥኤማውያን ፊት ሸሹ፤ ደግሞም በሕዝቡ ዘንድ ታላቅ ግድያ ሆኖአል፥ ሁለቱም ልጆችህ አፍኒንና ፊንሐስ ሞተዋል፤ የእግዚአብሔርም ታቦት ተማርካለች” አለው።'),
  ('1546628c-235d-5c87-ad20-0ced22c1fe10', 'fe1131ad-58b4-5912-a00c-4d901e3171a7', '5972a665-d0b8-5816-af9c-519afb9669a8', 7, 18, 'የእግዚአብሔርንም ታቦት ባሰባት ጊዜ በበሩ አጠገብ ካለው ከወንበሩ ወደቀ፤ እርሱ ሸምግሎ፥ ደንግዞም ነበርና ጀርባው ተሰብሮ ሞተ። እርሱም በእስራኤል ላይ አርባ ዓመት ፈራጅ ነበረ።'),
  ('7a0a5f2e-d3b1-546b-af68-f484b7c5de6a', 'fe1131ad-58b4-5912-a00c-4d901e3171a7', 'de5d73cd-c8ed-524f-ae7a-45fdd77a6615', 1, 19, 'ምራቱም የፊንሐስ ሚስት አርግዛ ልትወልድ ተቃርባ ነበር፤ የእግዚአብሔርም ታቦት እንደ ተማረከች፥ አማቷና ባልዋም እንደ ሞቱ በሰማች ጊዜ አለቀሰች፤ ከዚያም በኋላ ወለደች። ሕማምዋም ተመለሰባት።'),
  ('fb0cafe9-90db-5055-ad71-7f4bf01b0f07', 'fe1131ad-58b4-5912-a00c-4d901e3171a7', 'de5d73cd-c8ed-524f-ae7a-45fdd77a6615', 2, 20, 'ወደ ሞትም በቀረበች ጊዜ በዙሪያዋ ያሉት ሴቶች “ወንድ ልጅ ወልደሻልና አትፍሪ” አሉአት። እርስዋ ግን አልመለሰችላቸውም፤ ልብዋም አያስታውስም ነበር።'),
  ('dcf407dc-5299-5b92-a9c3-304e93dd0a62', 'fe1131ad-58b4-5912-a00c-4d901e3171a7', 'de5d73cd-c8ed-524f-ae7a-45fdd77a6615', 3, 21, 'እርስዋም የእግዚአብሔር ታቦት ስለ ተማረከች፥ ስለ አማቷና ስለ ባልዋም፦ የሕፃኑን ስም ዊቦርኮኢቦት ብላ ጠራችው።'),
  ('6f6aff5b-f248-54c9-ae58-c97670d01dc8', 'fe1131ad-58b4-5912-a00c-4d901e3171a7', 'de5d73cd-c8ed-524f-ae7a-45fdd77a6615', 4, 22, 'እነርሱም፥ “የእግዚአብሔር ታቦት ተማርካለችና ክብር ከእስራኤል ለቀቀ” አሉ።'),
  ('94e080d4-b651-5a00-aeaf-4d18b40db2da', 'ac06d228-1cd8-5ac7-a728-64798512fc37', '4c693de2-0afe-5d8d-a865-0f891c3c779b', 1, 1, 'ፍልስጥኤማውያንም የእግዚአብሔርን ታቦት ወሰዱአት፤ ከአቤኔዜርም ወደ አዛጦን ይዘዋት መጡ።'),
  ('6d2a0b06-75b9-5c8c-a09a-ebb38d096627', 'ac06d228-1cd8-5ac7-a728-64798512fc37', '4c693de2-0afe-5d8d-a865-0f891c3c779b', 2, 2, 'ፍልስጥኤማውያንም የእግዚአብሔርን ታቦት ወስደው ወደ ዳጎን ቤት አገቡአት፤ በዳጎንም አጠገብ አኖሩአት።'),
  ('e3664886-8725-5847-a3b5-ee19e56296f7', 'ac06d228-1cd8-5ac7-a728-64798512fc37', '4c693de2-0afe-5d8d-a865-0f891c3c779b', 3, 3, 'በነጋውም የአዛጦን ሰዎች ማለዱ፤ ወደ ዳጎንም ቤት ገቡ፤ እነሆም፥ ዳጎን በእግዚአብሔር ታቦት ፊት በምድር ላይ በግንባሩ ወድቆ አገኙት፤ ዳጎንንም አንሥተው በስፍራው አቆሙት።'),
  ('ab540b67-b415-524b-ac36-d240ddf97d0d', 'ac06d228-1cd8-5ac7-a728-64798512fc37', '4c693de2-0afe-5d8d-a865-0f891c3c779b', 4, 4, 'በነጋውም ማለዱ፤ እነሆም፥ ዳጎን በእግዚአብሔር የቃል ኪዳን ታቦት ፊት በምድር ላይ በግንባሩ ወድቆ ነበር፤ የዳጎንም ራስ፥ ሁለቱ እጆቹም ተቈርጠው እየራሳቸው በመድረኩ ላይ ወድቀው ነበር፤ ሁለቱ መሀል እጆቹም በወለሉ ላይ ወድቀው ነበር። የዳጎንም ደረት ብቻውን ቀርቶ ነበር።'),
  ('57680690-a06f-5c8c-a549-8e609a5982d6', 'ac06d228-1cd8-5ac7-a728-64798512fc37', '4c693de2-0afe-5d8d-a865-0f891c3c779b', 5, 5, 'ስለዚህም የዳጎን ካህናት፥ ወደ ዳጎን ቤት የሚገቡትም ሁሉ በአዛጦን ያለውን የዳጎንን መድረክ እስከ ዛሬ ድረስ አይረግጡም፤ ይራመዱት ነበር እንጂ።'),
  ('a0d0f277-8c23-544c-ac7d-ea23a045f717', 'ac06d228-1cd8-5ac7-a728-64798512fc37', '4c693de2-0afe-5d8d-a865-0f891c3c779b', 6, 6, 'የእግዚአብሔርም እጅ በአዛጦን ሰዎች ላይ ከበደች፤ ክፉም ነገር አመጣችባቸው፤ በእነርሱም ላይ በመርከቦች ውስጥ ወጣ፤ የአዛጦንንና የአውራጃዎችዋንም ሰዎች የውስጥ አካላቸውን በዕባጭ መታ፤ በከተሞቻቸውም መካከል አይጦች ወጡ፤ በከተማውም ታላቅ መቅሠፍት ሆነ።'),
  ('9fddfbbb-f763-534c-ab50-b5cc12dd9fd4', 'ac06d228-1cd8-5ac7-a728-64798512fc37', '4c693de2-0afe-5d8d-a865-0f891c3c779b', 7, 7, 'የአዛጦንም ሰዎች እንዲህ እንደ ሆነ ባዩ ጊዜ፥ “እጁ በእኛና በአምላካችን በዳጎን ላይ ጠንክራለችና የእስራኤል አምላክ ታቦት ከእኛ ዘንድ አትቀመጥ” አሉ።'),
  ('ecfd6a2f-e52d-5f87-a94c-6ade700e8e12', 'ac06d228-1cd8-5ac7-a728-64798512fc37', '4c693de2-0afe-5d8d-a865-0f891c3c779b', 8, 8, 'ልከውም የፍልስጥኤማውያንን አለቆች ወደ እነርሱ ሰበሰቡና፥ “በእስራኤል አምላክ ታቦት ምን እናድርግ?” አሉ፤ የጌት ሰዎችም፥ “የእስራኤል አምላክ ታቦት ወደ እኛ ትዙር” ብለው መለሱ። የእስራኤል አምላክ ታቦትም ወደ ጌት ሄደች።'),
  ('bb8e3b7b-109e-587f-ae0f-c30f7883184d', 'ac06d228-1cd8-5ac7-a728-64798512fc37', '4c693de2-0afe-5d8d-a865-0f891c3c779b', 9, 9, 'ከሄደችም በኋላ የእግዚአብሔር እጅ በከተማዪቱ ላይ መጣች፤ ታላቅ ሁከትም ሆነ፤ የከተማዪቱንም ሰዎች ታላቁንም ታናሹንም መታ፤ የውስጥ አካላቸውንም በእባጭ መታቸው፤ የጌት ሰዎችም የውስጥ አካላቸውን ምስል ሠሩ፥'),
  ('d2bb42c4-1f1c-531a-a443-854bb8147e54', 'ac06d228-1cd8-5ac7-a728-64798512fc37', '4c693de2-0afe-5d8d-a865-0f891c3c779b', 10, 10, 'የእግዚአብሔርንም ታቦት ወደ አስቀሎና ላኩአት። የእግዚአብሔር ታቦት ወደ አስቀሎና በመጣች ጊዜ አስቀሎናውያን፥ “እኛንና ሕዝባችንን ልታስገድሉን የእስራኤልን አምላክ ታቦት ለምን አመጣችሁብን?” ብለው ጮኹ።'),
  ('58dcbfcf-6a36-57bc-a96a-8aad91e58315', 'ac06d228-1cd8-5ac7-a728-64798512fc37', '4c693de2-0afe-5d8d-a865-0f891c3c779b', 11, 11, 'ልከውም የፍልስጥኤማውያንን አለቆች ሁሉ ሰብስበው፥ “የእስራኤልን አምላክ ታቦት ስደዱአት፤ እኛንና ሕዝባችንን እንዳትገድል በስፍራዋ ትቀመጥ” አሉ።'),
  ('90a101f5-72db-5ed6-ab3b-d6cf4736c8f8', 'ac06d228-1cd8-5ac7-a728-64798512fc37', '4c693de2-0afe-5d8d-a865-0f891c3c779b', 12, 12, 'የእግዚአብሔር ታቦት ወደዚያ በገባች ጊዜ በከተማው ሁሉ ታላቅ ሁከት ሆኖአልና። በሕይወትም ያሉ፥ ያልሞቱትም ሰዎች በእባጭ ተመቱ፤ የከተማዪቱም ዋይታ እስከ ሰማይ ወጣ።'),
  ('b977f494-55f0-5233-a6e9-4dbf15b79768', '46d08a13-a8a3-573d-a6b1-d6638b6f613d', '4130ce2a-08df-5cf6-a333-4e402589c51c', 1, 1, 'የእግዚአብሔርም ታቦት በፍልስጥኤማውያን ሀገር ሰባት ወር ተቀመጠች። ምድራቸውም አይጦችን አወጣች።'),
  ('cb8404c4-5dde-53ba-afaa-d57b4beb3f8b', '46d08a13-a8a3-573d-a6b1-d6638b6f613d', '4130ce2a-08df-5cf6-a333-4e402589c51c', 2, 2, 'ፍልስጥኤማውያንም ካህናትንና ምዋርተኞችን ጠንቋዮችንም ጠርተው፥ “በእግዚአብሔር ታቦት ላይ ምን እናድርግ? ወደ ስፍራዋስ በምን እንስደዳት? አስታውቁን” አሉ።'),
  ('7f30ffca-ea23-5d61-afff-482995cb78ac', '46d08a13-a8a3-573d-a6b1-d6638b6f613d', '4130ce2a-08df-5cf6-a333-4e402589c51c', 3, 3, 'እነርሱም፥ “የእስራኤልን አምላክ የቃል ኪዳኑን ታቦት ብትሰድዱአት ስለ አሳዘናችሁአት የበደል መባእ ስጡ እንጂ ባዶዋን አትስደዱአት፤ የዚያን ጊዜም ትፈወሳላችሁ፤ ስርየትም ይደረግላችኋል፤ አለዚያ ግን የእግዚአብሔር እጅ ከእናንተ አይርቅም” አሉ።'),
  ('71139974-5131-5cd7-afa7-7d18daa38429', '46d08a13-a8a3-573d-a6b1-d6638b6f613d', '4130ce2a-08df-5cf6-a333-4e402589c51c', 4, 4, 'እነርሱም፥ “ስለ መቅሠፍቱ የምንሰጠው የበደል መባእ ምንድን ነው?” አሉ። እነርሱም እንዲህ አሉ፥ “እናንተንና አለቆቻችሁን፥ ሕዝባችሁንም ያገኘች መቅሠፍት አንዲት ናትና እንደ ፍልስጥኤማውያን አለቆች ቍጥር አምስት የወርቅ እባጮች፥ አምስትም የወርቅ አይጦች አቅርቡ።'),
  ('fe24e0c9-9bde-5e3b-a960-e4af37d8120d', '46d08a13-a8a3-573d-a6b1-d6638b6f613d', '4130ce2a-08df-5cf6-a333-4e402589c51c', 5, 5, 'እጁ ከእናንተና ከአማልክቶቻችሁ፥ ከምድራችሁም ይቀልል ዘንድ፥ የእባጫችሁን ምሳሌ፥ ምድራችሁንም የሚያጠፉትን የአይጦችን ምሳሌ አድርጋችሁ ለእስራኤል አምላክ ክብርን ስጡ።'),
  ('8818f09d-c1ac-5299-a143-65dcfc2bf78e', '46d08a13-a8a3-573d-a6b1-d6638b6f613d', '4130ce2a-08df-5cf6-a333-4e402589c51c', 6, 6, 'ግብጻውያንና ፈርዖንም ልባቸውን እንዳጸኑ ልባችሁን ለምን ታጸናላችሁ? በተዘባበቱባቸው ጊዜ ያወጡአቸው አይደሉምን? እነርሱም አልሄዱምን?'),
  ('dffb6aae-971a-5752-afc4-f1291d0ddf5a', '46d08a13-a8a3-573d-a6b1-d6638b6f613d', '4130ce2a-08df-5cf6-a333-4e402589c51c', 7, 7, 'አሁንም ወስዳችሁ አንዲት አዲስ ሰረገላ ሥሩ፤ የሚያጠቡም፥ ቀንበር ያልተጫነባቸውን ሁለት ላሞች በሰረገላ ጥመዱአቸው፤ እንቦሶቻቸውንም ለይታችሁ ወደ ቤት መልሱአቸው።'),
  ('1b9db4f5-443a-517f-ac24-54cf0a998da9', '46d08a13-a8a3-573d-a6b1-d6638b6f613d', '4130ce2a-08df-5cf6-a333-4e402589c51c', 8, 8, 'የእግዚአብሔርንም ታቦት ወስዳችሁ በሰረገላው ላይ አኑሩአት፤ ስለበደል መባእ ካሳ አድርጋችሁ ያቀረባችሁትን የወርቁንም ዕቃ በሣጥን ውስጥ አድርጋችሁ በታቦቷ አጠገብ አኑሩት፤ ትሄድም ዘንድ ስደዱአት።'),
  ('c70a1b69-b9aa-5915-aeec-8679513f0f43', '46d08a13-a8a3-573d-a6b1-d6638b6f613d', '4130ce2a-08df-5cf6-a333-4e402589c51c', 9, 9, 'ወደምትሄድበትም ተመልከቱ፤ በድንበሩም መንገድ ላይ ወደ ቤትሳሚስ ብትወጣ ይህን እጅግ ክፉ ነገር ያደረገብን እርሱ ነው፤ አለዚያም እንዲያው መጥቶብናል እንጂ የመታን የእርሱ እጅ እንዳልሆነ እናውቃለን።”'),
  ('a45a6165-c0ea-57fb-ad8c-57b16a394e16', '46d08a13-a8a3-573d-a6b1-d6638b6f613d', '4130ce2a-08df-5cf6-a333-4e402589c51c', 10, 10, 'ፍልስጥኤማውያንም እንዲሁ አደረጉ፤ የሚያጠቡትን ሁለቱን ላሞች ወሰዱ፤ በሰረገላውም ጠመዱአቸው፤ እንቦሶቻቸውንም በቤት ዘጉባቸው፤'),
  ('18f14d4d-f138-565f-aa99-a23a35a03572', '46d08a13-a8a3-573d-a6b1-d6638b6f613d', '4130ce2a-08df-5cf6-a333-4e402589c51c', 11, 11, 'የእግዚአብሔርንም ታቦት፥ የወርቁ አይጦችና የአካላቸው እባጮች ምሳሌ ያሉበትንም ሣጥን በሰረገላው ላይ ጫኑ።'),
  ('1b72d427-8006-5a6d-ad2a-f48e5b925ade', '46d08a13-a8a3-573d-a6b1-d6638b6f613d', '4130ce2a-08df-5cf6-a333-4e402589c51c', 12, 12, 'ላሞችም ወደ ቤትሳሚስ ወደሚወስደው መንገድ አቅንተው “እምቧ” እያሉ በጎዳናው ላይ ሄዱ፤ ወደ ቀኝም ወደ ግራም አላሉም፤ የፍልስጥኤማውያን አለቆችም እስከ ቤትሳሚስ ዳርቻ ድረስ በኋላ በኋላ ይሄዱ ነበር።'),
  ('a5c49505-1530-5f74-ae8c-d6c52e92a036', '46d08a13-a8a3-573d-a6b1-d6638b6f613d', '4130ce2a-08df-5cf6-a333-4e402589c51c', 13, 13, 'የቤትሳሚስ ሰዎችም በእርሻ ውስጥ ስንዴ ያጭዱ ነበር፤ ዐይናቸውንም ከፍ አድርገው የእግዚአብሔርን ታቦት አዩ፤ ደስ ብሎአቸውም ተቀበሉአት።'),
  ('4b2c9574-112b-5193-a5c7-24006b643a1d', '46d08a13-a8a3-573d-a6b1-d6638b6f613d', '4130ce2a-08df-5cf6-a333-4e402589c51c', 14, 14, 'ሰረገላውም ወደ ቤትሳሚሳዊው ወደ ኦሴዕ እርሻ መጣ፤ ታላቅም ድንጋይ በነበረበት በዚያ ቆመ፤ የሰረገላውንም ዕንጨት ፈልጠው ላሞቹን ለእግዚአብሔር ለሚቃጠል መሥዋዕት አቀረቡ።'),
  ('7171d63a-fb51-5ebe-a31e-9ac37496577f', '46d08a13-a8a3-573d-a6b1-d6638b6f613d', '4130ce2a-08df-5cf6-a333-4e402589c51c', 15, 15, 'ሌዋውያንም የእግዚአብሔርን ታቦት፥ ከእርስዋም ጋር የነበረውን የወርቅ ዕቃ ያለበትን ሣጥን አወረዱ፤ በታላቁም ድንጋይ ላይ አኖሩት፤ በዚያም ቀን የቤትሳሚስ ሰዎች ለእግዚአብሔር የሚቃጠለውን መሥዋዕት፥ የእህሉንም ቍርባን አቀረቡ።'),
  ('615f7cf3-9562-5ae3-a83c-92076e995fda', '46d08a13-a8a3-573d-a6b1-d6638b6f613d', '4130ce2a-08df-5cf6-a333-4e402589c51c', 16, 16, 'እነዚያም የፍልስጥኤማውያን አምስቱ አለቆች አይተው በዚያው ቀን ወደ አስቀሎና ተመለሱ።'),
  ('789d34c2-1970-5698-a184-8904929c86cd', '46d08a13-a8a3-573d-a6b1-d6638b6f613d', '4130ce2a-08df-5cf6-a333-4e402589c51c', 17, 17, 'ፍልስጥኤማውያንም ስለ በደል መባእ ለእግዚአብሔር ያቀረቡአቸው የሰውነታቸው ምሳሌ የወርቅ እባጮች እነዚህ ናቸው፦ አንዲቱ ለአዛጦን፥ አንዲቱም ለጋዛ፥ አንዲቱም ለአስቀሎና፥ አንዲቱም ለጌት፥ አንዲቱም ለአቃሮን።'),
  ('1d76c9dd-db0a-5757-acee-d19e179db8e6', '46d08a13-a8a3-573d-a6b1-d6638b6f613d', '4130ce2a-08df-5cf6-a333-4e402589c51c', 18, 18, 'የወርቁም አይጦች ቍጥር ለአምስቱ የፍልስጥኤማውያን አለቆች እንደ ነበሩት ከተሞች ሁሉ ቍጥር እንዲሁ ነበረ፤ እነርሱም እስከ ታላቁ ድንጋይ የሚደርሱ ቅጥር ያላቸው ከተሞችና የፌርዜዎን መንደሮች ናቸው። በዚህም ድንጋይ ላይ የእግዚአብሔርን ታቦት አስቀመጡ፤ ድንጋዩም እስከ ዛሬ ድረስ በቤትሳሚሳዊው በኦሴዕ እርሻ አለ።'),
  ('59815056-3f97-5d03-aa5b-5638c9089568', '46d08a13-a8a3-573d-a6b1-d6638b6f613d', '4130ce2a-08df-5cf6-a333-4e402589c51c', 19, 19, 'የኢያኮንዩ ልጆችም የእግዚአብሔርን የቃል ኪዳን ታቦት ተመልክተው ከቤትሳሚስ ሰዎች ጋር አልተቀበሉአትም፤ እግዚአብሔርም ከሕዝቡ አምስት ሺህ ሰባ ሰዎችን መታ፤ እግዚአብሔርም ሕዝቡን በታላቅ ግዳይ ስለ መታ ሕዝቡ አለቀሱ።'),
  ('ca394e39-cae6-52c3-a91e-f41051daf397', '46d08a13-a8a3-573d-a6b1-d6638b6f613d', '4130ce2a-08df-5cf6-a333-4e402589c51c', 20, 20, 'የቤትሳሚስም ሰዎች፥ “በዚህ በቅዱሱ አምላክ በእግዚአብሔር ፊት ማለፍ ማን ይችላል? የእግዚአብሔር ታቦት ከእኛ ወጥታ ወደ ማን ትሄዳለች?” አሉ።'),
  ('c571e1d4-2f19-59a8-adf4-92651af1d218', '46d08a13-a8a3-573d-a6b1-d6638b6f613d', '4130ce2a-08df-5cf6-a333-4e402589c51c', 21, 21, 'በቂርያትይዓሪምም ወደ ተቀመጡት ሰዎች መልእክተኞችን ልከው፥ “ፍልስጥኤማውያን የእግዚአብሔርን ታቦት መልሰዋል፤ ወርዳችሁም ወደ እናንተ ውሰዱአት” አሉ።'),
  ('9f46da1c-e3e6-5dc5-a167-aab32047683e', '786ac41c-7231-57b5-adbf-f5925828b3d0', 'aa4490f9-1e94-54fb-ab6e-ce8df94d2568', 1, 1, 'የቂርያትይዓሪም ሰዎችም መጥተው የእግዚአብሔርን የቃል ኪዳን ታቦት አወጡ፤ በኮረብታውም ላይ ወዳለው ወደ አሚናዳብ ቤት አገቡአት፤ የእግዚአብሔርንም ታቦት እንዲጠብቅ ልጁን አልዓዛርን ቀደሱት።'),
  ('7a6852da-e87c-5c83-ab51-0cf9dff63d13', '786ac41c-7231-57b5-adbf-f5925828b3d0', 'aa4490f9-1e94-54fb-ab6e-ce8df94d2568', 2, 2, 'ታቦቲቱም በቂርያትይዓሪም ከተቀመጠችበት ቀን ጀምሮ ወራቱ ረዘመ፤ ሃያ ዓመትም ሆነ፤ የእስራኤልም ቤት ሁሉ አዝኖ እግዚአብሔርን ተከተለ።'),
  ('67017052-1c33-5777-a412-f9c19076ca03', '786ac41c-7231-57b5-adbf-f5925828b3d0', '49be7fd4-477c-5b9f-af18-88b6b2df7b36', 1, 3, 'ሳሙኤልም የእስራኤልን ቤት ሁሉ፥ “በሙሉ ልባችሁ ወደ እግዚአብሔር ከተመለሳችሁ እንግዶችን አማልክትና ምስሎቻቸውን ከመካከላችሁ አርቁ፤ ልባችሁንም ወደ እግዚአብሔር አቅኑ፤ እርሱንም ብቻ አምልኩ፤ እርሱም ከፍልስጥኤማውያን እጅ ያድናችኋል” ብሎ ተናገራቸው።'),
  ('dcbf6f76-65ad-59b4-a700-0811bb07a99a', '786ac41c-7231-57b5-adbf-f5925828b3d0', '49be7fd4-477c-5b9f-af18-88b6b2df7b36', 2, 4, 'የእስራኤልም ልጆች የበዓሊምን አማልክትና የአስጣሮትን ምስሎች አራቁ፤ እግዚአብሔርንም ብቻ አመለኩ።'),
  ('02295ea6-33f8-5ffe-ad12-765a4012e6cd', '786ac41c-7231-57b5-adbf-f5925828b3d0', '49be7fd4-477c-5b9f-af18-88b6b2df7b36', 3, 5, 'ሳሙኤልም፥ “እስራኤልን ሁሉ ወደ መሴፋ ሰብስቡ፤ ስለ እናንተም ወደ እግዚአብሔር እጸልያለሁ” አለ።'),
  ('d7df5665-fd14-5cc5-a39c-72edc5948144', '786ac41c-7231-57b5-adbf-f5925828b3d0', '49be7fd4-477c-5b9f-af18-88b6b2df7b36', 4, 6, 'እነርሱም ወደ መሴፋ ተሰበሰቡ፤ ውኃም ቀድተው በእግዚአብሔር ፊት በምድር ላይ አፈሰሱ፤ በዚያም ቀን ጾሙ፤ በዚያም፥ “በእግዚአብሔር ፊት በድለናል” አሉ። ሳሙኤልም በእስራኤል ልጆች ላይ በመሴፋ ፈረደ።'),
  ('972107a6-045b-596f-a0ec-e451c59118e5', '786ac41c-7231-57b5-adbf-f5925828b3d0', '49be7fd4-477c-5b9f-af18-88b6b2df7b36', 5, 7, 'ፍልስጥኤማውያንም የእስራኤል ልጆች ወደ መሴፋ እንደ ተሰበሰቡ በሰሙ ጊዜ የፍልስጥኤማውያን አለቆች በእስራኤል ላይ ዘመቱ፤ የእስራኤልም ልጆች ሰምተው ከፍልስጥኤማውያን ፊት ፈሩ።'),
  ('535ca0a6-8163-5612-ad70-03bc7cef205e', '786ac41c-7231-57b5-adbf-f5925828b3d0', '49be7fd4-477c-5b9f-af18-88b6b2df7b36', 6, 8, 'የእስራኤልም ልጆች ሳሙኤልን፥ “ወደ አምላክህ ወደ እግዚአብሔር ስለ እኛ ከመጮኽ ዝም አትበል። እርሱም ከፍልስጥኤማውያን እጅ ያድነናል” አሉት።'),
  ('912e7424-c5b9-5070-af4f-0fef7e16e306', '786ac41c-7231-57b5-adbf-f5925828b3d0', '49be7fd4-477c-5b9f-af18-88b6b2df7b36', 7, 9, 'ሳሙኤልም አንድ የበግ ጠቦት ወስዶ ለእግዚአብሔር ፈጽሞ የሚቃጠል መሥዋዕት አድርጎ ከሕዝቡ ጋር አቀረበው፤ ሳሙኤልም ስለ እስራኤል ወደ እግዚአብሔር ጮኸ፥ እግዚአብሔርም ሰማው።'),
  ('4570e0e3-d55f-5ed9-ab70-ce4cc0e9b6ba', '786ac41c-7231-57b5-adbf-f5925828b3d0', '49be7fd4-477c-5b9f-af18-88b6b2df7b36', 8, 10, 'ሳሙኤልም የሚቃጠለውን መሥዋዕት ሲያሣርግ ፍልስጥኤማውያን ከእስራኤል ጋር ሊዋጉ ቀረቡ፤ እግዚአብሔርም በዚያች ቀን በፍልስጥኤማውያን ላይ ታላቅ የነጐድጓድ ድምፅ አንጐደጐደ፤ ደነገጡም፤ በእስራኤልም ፊት ድል ተመቱ።'),
  ('408b3be5-e5d1-5911-adea-18a41392f5f1', '786ac41c-7231-57b5-adbf-f5925828b3d0', '49be7fd4-477c-5b9f-af18-88b6b2df7b36', 9, 11, 'የእስራኤልም ሰዎች ከመሴፋ ወጡ፤ ፍልስጥኤማውያንንም አሳደዱ፤ በቤኮር ታችም እስኪደርሱ ድረስ መቱአቸው።'),
  ('089bb030-9395-5f2d-a0a1-9e4322cc8d8f', '786ac41c-7231-57b5-adbf-f5925828b3d0', '49be7fd4-477c-5b9f-af18-88b6b2df7b36', 10, 12, 'ሳሙኤልም አንድ ድንጋይ ወስዶ በመሴፋና በአሮጌው ከተማ መካከል አኖረው፤ ስሙንም፥ “እስከ አሁን ድረስ እግዚአብሔር ረድቶናል” ሲል “አቤንኤዜር” ብሎ ጠራው። እብነ ረድኤት ማለት ነው።'),
  ('3a577f81-b471-5398-af62-e09a7d8b2933', '786ac41c-7231-57b5-adbf-f5925828b3d0', '49be7fd4-477c-5b9f-af18-88b6b2df7b36', 11, 13, 'እግዚአብሔርም ፍልስጥኤማውያንን አዋረዳቸው፤ ዳግመኛም ከዚያ ወዲያ ወደ እስራኤል ድንበር አልወጡም፤ በሳሙኤልም ዘመን ሁሉ የእግዚአብሔር እጅ በፍልስጥኤማውያን ላይ ነበረች።'),
  ('e06c15ff-abd0-5d8c-a5fa-717ca42902fb', '786ac41c-7231-57b5-adbf-f5925828b3d0', '49be7fd4-477c-5b9f-af18-88b6b2df7b36', 12, 14, 'ፍልስጥኤማውያንም ከአስቀሎና ጀምሮ እስከ፤ ጌት ድረስ ከእስራኤል ልጆች የወሰዱአቸው ከተሞች ለእስራኤል ተመለሱ፤ እስራኤልም ድንበሩን ከፍልስጥኤማውያን እጅ ወሰዱ። በእስራኤልና በአሞራውያን መካከልም ሰላም ሆነ።'),
  ('130caecf-2c23-5f03-ada1-c93d33dd8e4f', '786ac41c-7231-57b5-adbf-f5925828b3d0', '49be7fd4-477c-5b9f-af18-88b6b2df7b36', 13, 15, 'ሳሙኤልም በዘመኑ ሁሉ በእስራኤል ላይ ይፈርድ ነበር።'),
  ('fc39f8fa-0841-55e4-aee1-1e808717edfc', '786ac41c-7231-57b5-adbf-f5925828b3d0', '49be7fd4-477c-5b9f-af18-88b6b2df7b36', 14, 16, 'በየዓመቱም ወደ ቤቴል፥ ወደ ጌልጌላና ወደ መሴፋ ይዞር ነበር፤ በእነዚያም በተቀደሱ ስፍራዎች ሁሉ በእስራኤል ላይ ይፈርድ ነበር።'),
  ('c04c8ad1-53eb-5e51-a4d1-0def4df9b1f7', '786ac41c-7231-57b5-adbf-f5925828b3d0', '49be7fd4-477c-5b9f-af18-88b6b2df7b36', 15, 17, 'ቤቱም በዚያ ነበረና ወደ አርማቴም ይመለስ ነበር፤ በዚያም በእስራኤል ላይ ይፈርድ ነበር፤ በዚያም ለእግዚአብሔር መሠዊያ ሠራ።'),
  ('3d5a7823-db8f-54c7-a51c-07b94fbc0b03', '7255d03b-5750-5550-a21e-5093a5874ed6', 'dc561ab0-868e-567e-ac42-fd131fbe76da', 1, 1, 'እንዲህም ሆነ፤ ሳሙኤል በሸመገለ ጊዜ ልጆቹን በእስራኤል ላይ ፈራጆች አድርጎ ሾማቸው።'),
  ('b2d683dd-e55c-5395-aa8c-853553f80b18', '7255d03b-5750-5550-a21e-5093a5874ed6', 'dc561ab0-868e-567e-ac42-fd131fbe76da', 2, 2, 'የልጆቹም ስሞች እነዚህ ነበሩ። የበኵር ልጁ ስም ኢዩኤል፥ የሁለተኛውም ስም አብያ ነበረ። እነርሱም በቤርሳቤህ ፈራጆች ነበሩ።'),
  ('32c7d2fb-c49f-5c1a-a7b9-fbafcdb47a08', '7255d03b-5750-5550-a21e-5093a5874ed6', 'dc561ab0-868e-567e-ac42-fd131fbe76da', 3, 3, 'ልጆቹም በመንገዱ አልሄዱም፤ ነገር ግን ረብ ለማግኘት ፈቀቅ አሉ፤ መማለጃ በሉ፤ ፍርድ አደሉ።'),
  ('f5bc2598-6b91-50be-a021-e7c37f99430f', '7255d03b-5750-5550-a21e-5093a5874ed6', 'dc561ab0-868e-567e-ac42-fd131fbe76da', 4, 4, 'የእስራኤልም ሰዎች ሁሉ በአንድነት ተሰብስበው ወደ ሳሙኤል ወደ አርማቴም መጡ፤'),
  ('8cb08e61-f826-5303-a25b-cb0c6ad80ff0', '7255d03b-5750-5550-a21e-5093a5874ed6', 'dc561ab0-868e-567e-ac42-fd131fbe76da', 5, 5, 'እንዲህም አሉት፥ “እነሆ፥ አንተ ሸምግለሃል፤ ልጆችህም በመንገድህ አይሄዱም፤ አሁንም እንደ ሌሎች አሕዛብ ሁሉ የሚፈርድልን ንጉሥ አንግሥልን።”'),
  ('3f293bfd-2124-5efa-a713-3293e37bdbc6', '7255d03b-5750-5550-a21e-5093a5874ed6', 'dc561ab0-868e-567e-ac42-fd131fbe76da', 6, 6, '“የሚፈርድልን ንጉሥ ስጠን” ባሉት ጊዜም ነገሩ ሳሙኤልን አስከፋው፤ ሳሙኤልም ወደ እግዚአብሔር ጸለየ።'),
  ('e13a5d09-2e47-5a57-aa97-5cc366672a1f', '7255d03b-5750-5550-a21e-5093a5874ed6', 'dc561ab0-868e-567e-ac42-fd131fbe76da', 7, 7, 'እግዚአብሔርም ሳሙኤልን አለው፥ “በእነርሱ ላይ እንዳልነግሥ እኔን ናቁ እንጂ አንተን አልናቁምና በሚሉህ ነገር ሁሉ የሕዝቡን ቃል ስማ።'),
  ('c3d687a5-6e31-5537-aa4a-876523bdcff8', '7255d03b-5750-5550-a21e-5093a5874ed6', 'dc561ab0-868e-567e-ac42-fd131fbe76da', 8, 8, 'ከግብፅ ካወጣኋቸው ቀን ጀምሮ እስከ ዛሬ ድረስ እኔን ትተው እንግዶች አማልክትን በማምለካቸው እንደ ሠሩት ሥራ ሁሉ እንዲሁ በአንተ ደግሞ ያደርጉብሃል።'),
  ('ba2ae42c-3bac-5e1e-a1d8-8fdf1456502d', '7255d03b-5750-5550-a21e-5093a5874ed6', 'dc561ab0-868e-567e-ac42-fd131fbe76da', 9, 9, 'አሁንም ቃላቸውን ስማ፤ ነገር ግን ጽኑ ምስክር መስክርባቸው፤ በእነርሱም ላይ የሚነግሠውን የንጉሡን ሥርዐት ንገራቸው።”'),
  ('efe212c2-bc14-50a0-a0a8-c0fdd015d396', '7255d03b-5750-5550-a21e-5093a5874ed6', 'dc561ab0-868e-567e-ac42-fd131fbe76da', 10, 10, 'ሳሙኤልም የእግዚአብሔርን ቃል ሁሉ ንጉሥን ለፈለጉ ሕዝብ ነገራቸው።'),
  ('810a2250-9a85-5456-a7c2-ce7bd1dd8d08', '7255d03b-5750-5550-a21e-5093a5874ed6', 'dc561ab0-868e-567e-ac42-fd131fbe76da', 11, 11, 'እንዲህም አለ፥ “በእናንተ ላይ የሚነግሠው የንጉሡ ሥርዐት ይህ ነው፤ ወንዶች ልጆቻችሁን ወስዶ ሰረገላ ነጂዎችና ፈረሰኞች ያደርጋቸዋል፤ በሰረገሎችም ፊት ይሮጣሉ፤'),
  ('828279e5-9577-53b5-a4b2-5080fd87b6bc', '7255d03b-5750-5550-a21e-5093a5874ed6', 'dc561ab0-868e-567e-ac42-fd131fbe76da', 12, 12, 'ለራሱም የሻለቆችና የመቶ አለቆች የአምሳ አለቆችም ያደርጋቸዋል፤ እርሻውንም የሚያርሱ፥ እህሉንም የሚያጭዱ፥ ፍሬውንም የሚለቅሙ፥ የጦር መሣሪያውንና የሰረገሎቹንም ዕቃ የሚሠሩ ያደርጋቸዋል።'),
  ('beaf826a-639f-55dd-a003-bb89c5195f6b', '7255d03b-5750-5550-a21e-5093a5874ed6', 'dc561ab0-868e-567e-ac42-fd131fbe76da', 13, 13, 'ሴቶች ልጆቻችሁንም ወስዶ ሽቱ ቀማሚዎችና ወጥ ቤቶች፥ አበዛዎችም ያደርጋቸዋል።'),
  ('12dcc644-4f54-5515-a597-403ae0af2b81', '7255d03b-5750-5550-a21e-5093a5874ed6', 'dc561ab0-868e-567e-ac42-fd131fbe76da', 14, 14, 'እርሻችሁንና ወይናችሁንም፥ መልካም መልካሙንም የዘይት ቦታችሁን ወስዶ ለሎሌዎቹ ይሰጣቸዋል።'),
  ('31397444-5fb0-5395-afb4-67703898e444', '7255d03b-5750-5550-a21e-5093a5874ed6', 'dc561ab0-868e-567e-ac42-fd131fbe76da', 15, 15, 'ከዘራችሁና ከወይናችሁም ዐሥራት ወስዶ ለጃንደረቦቹና ለሎሌዎቹ ይሰጣቸዋል።'),
  ('110a59cf-0e59-5678-a27d-a9275966059f', '7255d03b-5750-5550-a21e-5093a5874ed6', 'dc561ab0-868e-567e-ac42-fd131fbe76da', 16, 16, 'ሎሌዎቻችሁንና ገረዶቻችሁን፥ ከከብቶቻችሁና ከአህዮቻችሁም መልካም መልካሙን ወስዶ ያሠራቸዋል።'),
  ('969d2b1b-3b52-5061-a68b-4a2be1385b77', '7255d03b-5750-5550-a21e-5093a5874ed6', 'dc561ab0-868e-567e-ac42-fd131fbe76da', 17, 17, 'ከላሞቻችሁ፥ ከበጎቻችሁና ከፍየሎችቻችሁም ዐሥራት ይወስዳል፤ እናንተም ባሪያዎች ትሆኑታላችሁ።'),
  ('a092f0ab-b0f6-5a44-a3bc-bc985275f609', '7255d03b-5750-5550-a21e-5093a5874ed6', 'dc561ab0-868e-567e-ac42-fd131fbe76da', 18, 18, 'በዚያም ቀን ለእናንተ ከመረጣችሁት ከንጉሣችሁ የተነሣ ትጮኻላችሁ፤ በእነዚያም ወራት እግዚአብሔር አይሰማችሁም። ለራሳችሁ ንጉሥ መርጣችኋልና።”'),
  ('16f7902f-ccdd-5491-a96f-42c3aff0b0cc', '7255d03b-5750-5550-a21e-5093a5874ed6', 'dc561ab0-868e-567e-ac42-fd131fbe76da', 19, 19, 'ሕዝቡ ግን የሳሙኤልን ነገር ይሰሙ ዘንድ እንቢ አሉ፥ “እንዲህ አይሁን፤ ነገር ግን ንጉሥ አንግሥልን፤'),
  ('6a95138d-5a90-535b-a8e1-24ca8389ec47', '7255d03b-5750-5550-a21e-5093a5874ed6', 'dc561ab0-868e-567e-ac42-fd131fbe76da', 20, 20, 'እኛም ደግሞ እንደ አሕዛብ ሁሉ እንሆናለን፤ ንጉሣችንም ይፈርድልናል፤ በፊታችንም ወጥቶ ስለ እኛ ጠላታችንን ይዋጋል” አሉት።'),
  ('f2c00669-219b-58b6-a246-601b765e3980', '7255d03b-5750-5550-a21e-5093a5874ed6', 'dc561ab0-868e-567e-ac42-fd131fbe76da', 21, 21, 'ሳሙኤልም የሕዝቡን ቃል ሁሉ ሰማ፤ ለእግዚአብሔርም ተናገረ።'),
  ('cbc9e360-dd25-5b06-ae68-aee79ef4a42b', '7255d03b-5750-5550-a21e-5093a5874ed6', 'dc561ab0-868e-567e-ac42-fd131fbe76da', 22, 22, 'እግዚአብሔርም ሳሙኤልን፥ “ቃላቸውን ስማ፤ ንጉሥም አንግሥላቸው” አለው። ሳሙኤልም የእስራኤልን ሰዎች፥ “እያንዳንዳችሁ ወደ ከተማችሁ ሂዱ” አላቸው።'),
  ('c8e0499f-68c9-5241-a5d2-7ddfe397a540', '0dd6793b-7a90-52d0-a90f-69afeaf5bd37', '3f279a08-c282-561c-a08f-df998711efa8', 1, 1, 'ከብንያም ልጆች ስሙ ቂስ የተባለ አንድ ሰው ነበረ፥ እርሱም የአብሔል ልጅ፥ የያሬድ ልጅ፥ የባሔር ልጅ፥ የብንያም ሰው፥ የአፌቅ ልጅ፥ ጽኑዕ ኀያል ሰው ነበረ።'),
  ('f0a9d7b5-5048-533f-ae8d-eed8764eb941', '0dd6793b-7a90-52d0-a90f-69afeaf5bd37', '3f279a08-c282-561c-a08f-df998711efa8', 2, 2, 'ለእርሱም ሳኦል የሚባል የተመረጠ መልካም ልጅ ነበረው፤ በምድር ሁሉ ላይ ከእስራኤል ልጆች ከእርሱ ይልቅ መልካም የሆነ ሰው አልነበረም፤ ከሕዝቡም ሁሉ ይልቅ ከትከሻውና ከዚያም በላይ ቁመቱ ዘለግ ያለ ነበረ።'),
  ('578dc045-4b9a-5526-ad4f-14d3fac6b8fe', '0dd6793b-7a90-52d0-a90f-69afeaf5bd37', '3f279a08-c282-561c-a08f-df998711efa8', 3, 3, 'የሳኦልም አባት የቂስ አህዮች ጠፍተው ነበር፤ ቂስም ልጁን ሳኦልን፥ “ከብላቴኖቹ አንዱን ወስደህ ተነሡና ሄዳችሁ አህዮችን ፈልጉ” አለው።'),
  ('133cc3bd-3e20-5899-a0cd-b223658cb854', '0dd6793b-7a90-52d0-a90f-69afeaf5bd37', '3f279a08-c282-561c-a08f-df998711efa8', 4, 4, 'ወደ ተራራማውም ወደ ኤፍሬም ሀገር ሄዱ፤ በሲልካ ምድርም አለፉ፤ አላገኙአቸውምም፤ በፋስቂም ምድር አለፉ፤ በዚያም አልነበሩም፤ በኢያሚንም ምድር አለፉ፤ አላገኙአቸውምም።'),
  ('8568ff0f-826d-5dfe-ac96-13f9b21a23fc', '0dd6793b-7a90-52d0-a90f-69afeaf5bd37', '3f279a08-c282-561c-a08f-df998711efa8', 5, 5, 'ወደ መሴፋ ምድርም በደረሱ ጊዜ ሳኦል ከእርሱ ጋር የነበረውን ብላቴና፥ “አባቴ ስለ አህዮች ማሰብን ትቶ ስለ እኛ እንዳይጨነቅ፥ ና፤ እንመለስ” አለው።'),
  ('d98ac266-0f72-5f40-a17e-62ab72d71a83', '0dd6793b-7a90-52d0-a90f-69afeaf5bd37', '3f279a08-c282-561c-a08f-df998711efa8', 6, 6, 'ብላቴናውም፥ “እነሆ፥ አንድ የእግዚአብሔር ሰው በዚህች ከተማ አለ፤ እርሱም የተከበረ ሰው ነው፤ የሚናገረው ሁሉ በእውነት ይፈጸማል፤ አሁንም ወደዚያ እንሂድ፤ ምናልባት የምንሄድበትን መንገድ ይነግረናልና” አለው።'),
  ('65842051-6fbf-5068-af2c-f13c7af75ab3', '0dd6793b-7a90-52d0-a90f-69afeaf5bd37', '3f279a08-c282-561c-a08f-df998711efa8', 7, 7, 'ሳኦልም አብሮት ያለውን ብላቴና፥ “እነሆ! እንሄዳለን፤ ነገር ግን ለእግዚአብሔር ሰው ምን እንወስድለታለን? እንጀራ ከከረጢታችን አልቆአልና፤ ለእግዚአብሔር ሰው የምንወስድለት ምንም የለንም” አለው።'),
  ('b2007e3e-21fa-5a74-a359-4c3a7048938c', '0dd6793b-7a90-52d0-a90f-69afeaf5bd37', '3f279a08-c282-561c-a08f-df998711efa8', 8, 8, 'ብላቴናው ደግሞ ለሳኦል መልሶ፥ “እነሆ፥ በእጄ የብር ሰቅል ሩብ አለኝ፤ እርሱንም ለእግዚአብሔር ሰው ትሰጠዋለህ፤ የምንሄድበትን መንገድም ይነግረናል።'),
  ('19d42c95-f214-5b94-a3d4-0a89f9c9f1d5', '0dd6793b-7a90-52d0-a90f-69afeaf5bd37', '3f279a08-c282-561c-a08f-df998711efa8', 9, 9, 'ቀድሞ ነቢዩን ባለ ራእይ ይሉት ነበርና አስቀድሞ በእስራኤል ዘንድ ሰው እግዚአብሔርን ለመጠየቅ ሲሄድ፦ ኑ፤ ወደ ባለ ራእይ እንሂድ ይል ነበር።”'),
  ('c0878701-17ad-5d4f-a4ab-85422a2a2ce3', '0dd6793b-7a90-52d0-a90f-69afeaf5bd37', '3f279a08-c282-561c-a08f-df998711efa8', 10, 10, 'ሳኦልም ብላቴናውን፥ “የተናገርኸው ነገር መልካም ነው፤ ና፤ እንሂድ” አለውና የእግዚአብሔር ሰው ወዳለበት ከተማ ሄዱ።'),
  ('2c201c14-f363-5d95-aad2-2f08d913cb55', '0dd6793b-7a90-52d0-a90f-69afeaf5bd37', '3f279a08-c282-561c-a08f-df998711efa8', 11, 11, 'በከተማዪቱም ዳገት በወጡ ጊዜ ቈነጃጅት ውኃ ሊቀዱ ሲወጡ አገኙና፥ “ባለ ራእይ በዚህ አለ ወይ?” አሉአቸው።'),
  ('963aa6b5-2f81-5307-a0cc-d933c41302d5', '0dd6793b-7a90-52d0-a90f-69afeaf5bd37', '3f279a08-c282-561c-a08f-df998711efa8', 12, 12, 'ቈነጃጅቱም፥ “አዎን እነሆ፥ በፊታችሁ ነው። ዛሬ ወደ ከተማዪቱ መጥቶአልና፥ ዛሬም ሕዝቡ በባማ ኮረብታ ላይ መሥዋዕት ማቅረብ አለባቸውና።'),
  ('a0c6accd-dbd4-5c61-a844-9b386640b091', '0dd6793b-7a90-52d0-a90f-69afeaf5bd37', '3f279a08-c282-561c-a08f-df998711efa8', 13, 13, 'ወደ ከተማዪቱም በገባችሁ ጊዜ ለመብላት ወደ ባማ ኮረብታ ሳይወጣ በከተማው ውስጥ ታገኙታላችሁ፤ መሥዋዕታቸውን እርሱ የሚባርክ ስለሆነ እርሱ ሳይወጣ ሕዝቡ ምንም አይቀምሱምና፥ ከዚያም በኋላ እንግዶች ይበላሉና፤ በዚህም ጊዜ ታገኙታላችሁና አሁን ውጡ” አሉአቸው።'),
  ('bb5b837b-3427-5634-a7d9-be09e8f5b30a', '0dd6793b-7a90-52d0-a90f-69afeaf5bd37', '3f279a08-c282-561c-a08f-df998711efa8', 14, 14, 'ወደ ከተማዪቱም ወጡ፤ በከተማዪቱም መካከል በገቡ ጊዜ እነሆ፥ ሳሙኤል ወደ ባማ ኮረብታ ለመውጣት ወደ እነርሱ መጣ።'),
  ('6c223eb9-0b4d-513a-a9f4-7028911f9feb', '0dd6793b-7a90-52d0-a90f-69afeaf5bd37', '3f279a08-c282-561c-a08f-df998711efa8', 15, 15, 'ገናም ሳኦል ሳይመጣ ከአንድ ቀን በፊት እግዚአብሔር ለሳሙኤል ጆሮውን ከፈተለት፥'),
  ('04541858-c70f-56e3-a87d-8677ba8afe88', '0dd6793b-7a90-52d0-a90f-69afeaf5bd37', '3f279a08-c282-561c-a08f-df998711efa8', 16, 16, 'እንዲህም አለው፥ “ነገ በዚህች ሰዓት ከብንያም ሀገር አንድ ሰው እልክልሃለሁ፤ ልቅሶአቸው ወደ እኔ ስለ ደረሰ የሕዝቤን ሥቃያቸውን ተመልክችአለሁና ለሕዝቤ ለእስራኤል አለቃ ይሆን ዘንድ ትቀባዋለህ፤ ከፍልስጥኤማውያንም እጅ ሕዝቤን ያድናል።”'),
  ('357b9781-3e01-5e78-a2a7-beef499f6dbd', '0dd6793b-7a90-52d0-a90f-69afeaf5bd37', '3f279a08-c282-561c-a08f-df998711efa8', 17, 17, 'ሳሙኤልም ሳኦልን ባየ ጊዜ እግዚአብሔር፥ “ያ የነገርሁህ ሰው እነሆ፤ እርሱም በሕዝቤ ላይ ይነግሣል” አለው።'),
  ('90e9d0fe-5ccd-56de-a113-fb8c1c5823cd', '0dd6793b-7a90-52d0-a90f-69afeaf5bd37', '3f279a08-c282-561c-a08f-df998711efa8', 18, 18, 'ሳኦልም በበሩ ወደ ሳሙኤል ቀርቦ፥ “የባለ ራእዩ ቤት ወዴት እንደ ሆነ፥ እባክህ፥ ንገረኝ” አለው።'),
  ('80a2a616-f466-5141-aece-a0c25a124f4a', '0dd6793b-7a90-52d0-a90f-69afeaf5bd37', '3f279a08-c282-561c-a08f-df998711efa8', 19, 19, 'ሳሙኤልም መልሶ ሳኦልን፥ “ባለ ራእዩ እኔ ነኝ፤ ዛሬም ከእኔ ጋር ወደ ባማ ኮረብታ በፊቴ ውጣና ምሳ ብላ፤ ነገም በጥዋት አሰናብትሃለሁ፤ በልብህም ያለውን ነገር ሁሉ እነግርሃለሁ፤'),
  ('a330034d-7a9f-555c-a5d4-31e332fde9e9', '0dd6793b-7a90-52d0-a90f-69afeaf5bd37', '3f279a08-c282-561c-a08f-df998711efa8', 20, 20, 'ከሦስት ቀንም በፊት የጠፉ አህዮችህ ተገኝተዋልና ልብህን አታስጨንቀው። የእስራኤል መልካም ምኞት ለማን ነው? ለአንተና ለአባትህ ቤት አይደለምን?” አለው።'),
  ('9af4b0e3-e2a6-513f-a391-64522503e326', '0dd6793b-7a90-52d0-a90f-69afeaf5bd37', '3f279a08-c282-561c-a08f-df998711efa8', 21, 21, 'ሳኦልም መልሶ፥ “እኔ ከእስራኤል ነገዶች ከሚያንስ ወገን የሆንሁ ብንያማዊ ሰው አይደለሁምን? ወገኔስ ከብንያም ነገድ ወገኖች ሁሉ የሚያንስ አይደለምን? እንዲህስ ያለውን ነገር ለምን ነገርኸኝ?” አለ።'),
  ('31a74c04-bc70-522e-ae91-f8dac1f1e1ae', '0dd6793b-7a90-52d0-a90f-69afeaf5bd37', '3f279a08-c282-561c-a08f-df998711efa8', 22, 22, 'ሳሙኤልም ሳኦልንና ብላቴናውን ወስዶ ወደ አዳራሽ አገባቸው፥ ሰባ ሰዎችም ምሳ በሚበሉበት በምርፋቁ ራስ አስቀመጣቸው፤'),
  ('d92e5ee0-1335-54b2-a020-15a1a7ee04db', '0dd6793b-7a90-52d0-a90f-69afeaf5bd37', '3f279a08-c282-561c-a08f-df998711efa8', 23, 23, 'ሳሙኤልም ወጥ ቤቱን፥ “በአንተ ዘንድ አኑረው ብዬ የሰጠሁህን እድል ፋንታ አምጣ” አለው።'),
  ('745e0728-c6ee-5d07-a64d-b61b6e73ddfc', '0dd6793b-7a90-52d0-a90f-69afeaf5bd37', '3f279a08-c282-561c-a08f-df998711efa8', 24, 24, 'ወጥቤቱም ወርቹን አምጥቶ በሳኦል ፊት አኖረው። ሳሙኤልም፥ “ሳኦልን ለምስክር ከባልንጀራህ ተለይቶ ቀርቦልሃልና እነሆ፥ በልተህ የተረፈህን በፊትህ አኑር” አለው። በዚያም ቀን ሳኦል ከሳሙኤል ጋር በላ።'),
  ('07d0f45d-6c52-5f26-a1ca-e7dc096c380f', '0dd6793b-7a90-52d0-a90f-69afeaf5bd37', '3f279a08-c282-561c-a08f-df998711efa8', 25, 25, 'ከባማ ኮረብታም ወደ ከተማዪቱ ወረዱ፤ ሳሙኤልም ለሳኦል በሰገነቱ ላይ መኝታ አዘጋጀለት፤ እርሱም ተኛ።'),
  ('7a4d62dd-3f67-59d7-ad7c-44d12f215e1e', '0dd6793b-7a90-52d0-a90f-69afeaf5bd37', '3f279a08-c282-561c-a08f-df998711efa8', 26, 26, 'ማልደውም ተነሡ፤ በነጋም ጊዜ ሳሙኤል ሳኦልን፥ “ከሰገነቱ ላይ ጠርቶ፦ ተነሣና ላሰናብትህ” አለው። ሳኦልም ተነሣ፤ እርሱና ሳሙኤልም ሁለቱ ወደ ሜዳ ወጡ።'),
  ('b2a15902-de80-5d26-a2af-90985a2e4aed', '0dd6793b-7a90-52d0-a90f-69afeaf5bd37', '3f279a08-c282-561c-a08f-df998711efa8', 27, 27, 'እነርሱም በከተማዪቱ ዳር ሲወርዱ ሳሙኤል ሳኦልን፥ “ብላቴናው ወደ ፊታችን እንዲያልፍ እዘዘው፤ አንተ ግን ከእኔ ጋር ከዚህ ቁምና የእግዚአብሔርን ቃል ስማ” አለው። ብላቴናውም አለፈ።'),
  ('56d64d5e-1b77-585b-a8d6-a12acbb472fa', 'a0dd5282-5902-5084-a524-fd875046627f', 'e18e6dd0-f194-5aac-a2be-d3816ab2fad7', 1, 1, 'ሳሙኤልም የዘይቱን ቀንድ ወስዶ በራሱ ላይ አፈሰሰው፤ ሳመውም፤ እንዲህም አለው፥ “በሕዝቡ በእስራኤል ላይ ትነግሥ ዘንድ እግዚአብሔር ቀብቶሃል፤ የእግዚአብሔርንም ሕዝብ ትገዛለህ፤ በዙሪያውም ካሉ ጠላቶቻቸው እጅ ታድናቸዋለህ። እግዚአብሔርም በርስቱ ላይ ትነግሥ ዘንድ እንደ ቀባህ ምልክቱ ይህ ነው።'),
  ('7a10692f-28de-5255-af0e-cd134cc8e5ff', 'a0dd5282-5902-5084-a524-fd875046627f', 'e18e6dd0-f194-5aac-a2be-d3816ab2fad7', 2, 2, 'ዛሬ ከእኔ በተለየህ ጊዜ በብንያም ግዛት በቤቴል አውራጃ በራሔል መቃብር አጠገብ ሁለት ሰዎች እየቸኰሉ ሲሄዱ ታገኛለህ፤ እነርሱም፦ ልትፈልጉአቸው ሂዳችሁ የነበራችሁላቸው አህዮች ተገኝተዋል፤ እነሆም፥ አባትህ ስለ አህዮቹ ማሰብ ትቶ፦ የልጄን ነገር እንዴት አደርጋለሁ? እያለ ስለ እናንተ ይጨነቃል ይሉሃል።'),
  ('986d7eb7-7102-5f88-a357-7ef5de27b0a8', 'a0dd5282-5902-5084-a524-fd875046627f', 'e18e6dd0-f194-5aac-a2be-d3816ab2fad7', 3, 3, 'ከዚያም ደግሞ አልፈህ፥ ወደ ትልቁ የታቦር ዛፍ ትደርሳለህ፤ በዚያም ሦስት ሰዎች፥ አንዱ ሦስት የፍየል ጠቦቶች ሲነዳ፥ ሁለተኛው ሦስት የዳቦ ስልቻ፥ ሦስተኛውም የወይን ጠጅ አቁማዳ ይዘው ወደ እግዚአብሔር ወደ ቤቴል ሲወጡ ታገኛለህ፤'),
  ('0c11e858-603b-5958-a674-06b373602c9e', 'a0dd5282-5902-5084-a524-fd875046627f', 'e18e6dd0-f194-5aac-a2be-d3816ab2fad7', 4, 4, 'ሰላምታም ይሰጡሃል፤ የመጀመሪያዎቹን ሁለት ዳቦዎችም ይሰጡሃል፤ ከእጃቸውም ትቀበላለህ።'),
  ('ea0e83e9-fd54-5887-a32d-e095830eb2cc', 'a0dd5282-5902-5084-a524-fd875046627f', 'e18e6dd0-f194-5aac-a2be-d3816ab2fad7', 5, 5, 'ከዚያም በኋላ የፍልስጥኤማውያን ጭፍራ ወዳለበት ወደ እግዚአብሔር ኮረብታ ትመጣለህ፤ በዚያም ፍልስጥኤማዊው ናሴብ አለ፤ ወደዚያም ወደ ከተማዪቱ በደረስህ ጊዜ በገናና ከበሮ፥ እምቢልታና መሰንቆ ይዘው ትንቢት እየተናገሩ ከኰረብታው መስገጃ የሚወርዱ የነቢያትን ጉባኤ ታገኛለህ።'),
  ('62a7bbe0-82b5-5883-a0e6-34985d9067fa', 'a0dd5282-5902-5084-a524-fd875046627f', 'e18e6dd0-f194-5aac-a2be-d3816ab2fad7', 6, 6, 'የእግዚአብሔርም መንፈስ በአንተ ይወርዳል፤ ከእነርሱም ጋር ትንቢት ትናገራለህ፤ እንደ ሌላም ሰው ሆነህ ትለወጣለህ።'),
  ('75c32209-212a-5041-a09c-ff89cf6fcfe3', 'a0dd5282-5902-5084-a524-fd875046627f', 'e18e6dd0-f194-5aac-a2be-d3816ab2fad7', 7, 7, 'እነዚህም ምልክቶች በደረሱህ ጊዜ እግዚአብሔር ከአንተ ጋር ነውና እጅህ የምትችለውን ሁሉ አድርግ።'),
  ('03e796d8-821f-5331-acec-a6531bd4051a', 'a0dd5282-5902-5084-a524-fd875046627f', 'e18e6dd0-f194-5aac-a2be-d3816ab2fad7', 8, 8, 'በፊቴም ወደ ጌልገላ ትወርዳለህ፤ እኔም እነሆ፥ የሚቃጠለውን መሥዋዕት አቀርብ ዘንድ፥ የደኅንነትንም መሥዋዕት እሠዋ ዘንድ ወደ አንተ እወርዳለሁ፤ እኔ ወደ አንተ እስክመጣና የምታደርገውን እስከምነግርህ ድረስ ሰባት ቀን ትቈያለህ።”'),
  ('d1c78808-c63b-5c74-a559-1634a06bb335', 'a0dd5282-5902-5084-a524-fd875046627f', 'e18e6dd0-f194-5aac-a2be-d3816ab2fad7', 9, 9, 'ከሳሙኤልም ዘንድ ለመሄድ ፊቱን በመለሰ ጊዜ እግዚአብሔር ሌላ ልብ ለወጠለት፤ በዚያም ቀን እነዚህ ምልክቶች ሁሉ ደረሱለት።'),
  ('e0f1f39d-a467-54c4-a388-32e4cb8f5195', 'a0dd5282-5902-5084-a524-fd875046627f', 'e18e6dd0-f194-5aac-a2be-d3816ab2fad7', 10, 10, 'ወደዚያም ኮረብታ በደረሰ ጊዜ፥ እነሆ፥ የነቢያት ጉባኤ አገኙት፤ የእግዚአብሔርም መንፈስ በእርሱ ላይ ወረደ፤ በመካከላቸውም ትንቢት ተናገረ።'),
  ('86ec26d8-ceea-5e3f-a46f-709633f527a0', 'a0dd5282-5902-5084-a524-fd875046627f', 'e18e6dd0-f194-5aac-a2be-d3816ab2fad7', 11, 11, 'ቀድሞም የሚያውቁት ሁሉ በነቢያት መካከል ባዩት ጊዜ ሕዝቡ እርስ በርሳቸው፥ “በቂስ ልጅ ላይ የሆነው ምንድን ነው? በውኑ ሳኦል ከነቢያት ወገን ነውን?” ተባባሉ።'),
  ('d37d6c65-1802-5501-a5d8-911e915f8233', 'a0dd5282-5902-5084-a524-fd875046627f', 'e18e6dd0-f194-5aac-a2be-d3816ab2fad7', 12, 12, 'ከዚያም ስፍራ ያለ አንድ ሰው፥ “አባቱስ ማን ነው?” ብሎ መለሰ። ስለዚህም “ሳኦል ደግሞ ከነቢያት ወገን ነውን?” የሚል ምሳሌ ሆነ።'),
  ('d4875ef2-1462-58ce-a4dd-5838b53078c5', 'a0dd5282-5902-5084-a524-fd875046627f', 'e18e6dd0-f194-5aac-a2be-d3816ab2fad7', 13, 13, 'ትንቢት መናገሩንም በፈጸመ ጊዜ ወደ ኮረብታው ወጣ።'),
  ('e792ac5d-7c76-599b-ac73-c3062c0d966f', 'a0dd5282-5902-5084-a524-fd875046627f', 'e18e6dd0-f194-5aac-a2be-d3816ab2fad7', 14, 14, 'ከቤተ ሰቡም አንዱ እርሱንና ብላቴናውን፥ “ወዴት ሄዳችሁ ኖሮአል?” አላቸው። እነርሱም፥ “አህዮችን ልንፈልግ ሄደን ነበር፤ ባጣናቸውም ጊዜ ወደ ሳሙኤል መጣን” አሉት።'),
  ('6db73404-7830-5fdc-a757-5ec00da84365', 'a0dd5282-5902-5084-a524-fd875046627f', 'e18e6dd0-f194-5aac-a2be-d3816ab2fad7', 15, 15, 'ያም ቤተ ሰብ፥ “ሳሙኤል ምን አለ? እባክህ! ንገረኝ” አለው፤'),
  ('fb7f92d2-a818-5759-aebd-86d65aafd8f1', 'a0dd5282-5902-5084-a524-fd875046627f', 'e18e6dd0-f194-5aac-a2be-d3816ab2fad7', 16, 16, 'ሳኦልም ለቤተ ሰቡ፥ “አህዮች እንደ ተገኙ ገለጠልን” አለው፤ ነገር ግን የመንግሥትን ነገር አላወራለትም።'),
  ('d3ddaafb-0bd2-5c26-aec2-59301b8f20bf', 'a0dd5282-5902-5084-a524-fd875046627f', '3bdeffbe-0bba-50cc-a5b7-edfc18f923f5', 1, 17, 'ሳሙኤልም ሕዝቡን ሁሉ ወደ እግዚአብሔር ወደ መሴፋ እንዲሄዱ አዘዛቸው።'),
  ('83a25f6a-ca01-5e90-a260-a3294a035b71', 'a0dd5282-5902-5084-a524-fd875046627f', '3bdeffbe-0bba-50cc-a5b7-edfc18f923f5', 2, 18, 'የእስራኤልንም ልጆች፥ “የእስራኤል አምላክ እግዚአብሔር እንዲህ ይላል፦ ‘እስራኤልን ከግብፅ አወጣሁ፤ ከግብፅ ንጉሥ ከፈርዖንም እጅ፥ ከሚያስጨንቁአችሁም ነገሥታት ሁሉ እጅ አዳንኋችሁ’ አላቸው።'),
  ('bfa6c292-dc94-54a2-a02b-18a36eaf2682', 'a0dd5282-5902-5084-a524-fd875046627f', '3bdeffbe-0bba-50cc-a5b7-edfc18f923f5', 3, 19, 'ዛሬ ግን ከመከራችሁና ከጭንቃችሁ ሁሉ ያዳናችሁን እግዚአብሔርን ንቃችሁ፦ ‘እንዲህ አይሁን፤ ነገር ግን ንጉሥ አንግሥልን’ አላችሁት። አሁንም በየነገዳችሁና በየወገናችሁ በእግዚአብሔር ፊት ቁሙ” አላቸው።'),
  ('7440257c-e21f-5746-a01e-30f4ddfb4de2', 'a0dd5282-5902-5084-a524-fd875046627f', '3bdeffbe-0bba-50cc-a5b7-edfc18f923f5', 4, 20, 'ሳሙኤልም የእስራኤልን ነገዶች ሁሉ አቀረበ፤ ዕጣውም በብንያም ወገን ላይ ወደቀ።'),
  ('838ac9e3-f002-5d6b-a863-1d97d85f72ae', 'a0dd5282-5902-5084-a524-fd875046627f', '3bdeffbe-0bba-50cc-a5b7-edfc18f923f5', 5, 21, 'የብንያምንም ነገድ በየወገናቸው አቀረበ፤ ዕጣውም በማጥር ወገን ላይ ወደቀ፤ የማጥርንም ወገን በየሰዉ አቀረበ፤ ዕጣውም በቂስ ልጅ በሳኦል ላይ ወደቀ፤ ፈለገውም፤ አላገኘውምም።'),
  ('e4c37161-5410-5a0c-a9ff-b03f67c57de7', 'a0dd5282-5902-5084-a524-fd875046627f', '3bdeffbe-0bba-50cc-a5b7-edfc18f923f5', 6, 22, 'ሳሙኤልም፦ ያ ሰው እዚህ ይመጣ እንደ ሆነ እግዚአብሔርን ጠየቀ፤ እግዚአብሔርም፥ “እነሆ፥ በዕቃ መካከል ተሸሽጎአል” ብሎ መለሰ።'),
  ('642833e6-623a-55bd-a71b-6b8c6e4a0a11', 'a0dd5282-5902-5084-a524-fd875046627f', '3bdeffbe-0bba-50cc-a5b7-edfc18f923f5', 7, 23, 'እርሱም ሮጦ ከዚያ አመጣው፤ እርሱም በሕዝቡ መካከል አቆመው፤ ከሕዝቡም ሁሉ ይልቅ ረዥም ነበረ፤ ሕዝቡም ከትከሻው በታች ሆኑ።'),
  ('b71a7edb-4eb6-59a0-a05e-dcb2bea7cb2a', 'a0dd5282-5902-5084-a524-fd875046627f', '3bdeffbe-0bba-50cc-a5b7-edfc18f923f5', 8, 24, 'ሳሙኤልም ለሕዝቡ ሁሉ፥ “ከሕዝቡ ሁሉ እርሱን የሚመስል እንደ ሌለ እግዚአብሔር የመረጠውን ታያላችሁን?” አላቸው፤ ሕዝቡም ሁሉ፥ “ንጉሥ ሕያው ይሁን” እያሉ እልልታ አደረጉ።'),
  ('4a67cab5-a744-52e4-a20d-757f3cf4a998', 'a0dd5282-5902-5084-a524-fd875046627f', '3bdeffbe-0bba-50cc-a5b7-edfc18f923f5', 9, 25, 'ሳሙኤልም የንጉሡን ሥርዐት ነገራቸው፤ በመጽሐፍም ጻፈው፤ በእግዚአብሔርም ፊት አኖረው። ሳሙኤልም ሕዝቡን ሁሉ ወደ እየቤታቸው አሰናበታቸው። ሕዝቡም ሁሉ ወደ እየቤታቸው ሄዱ።'),
  ('36dbf368-8e1c-5be8-a0e1-0f3ef88fcece', 'a0dd5282-5902-5084-a524-fd875046627f', '3bdeffbe-0bba-50cc-a5b7-edfc18f923f5', 10, 26, 'ሳኦልም ወደ ቤቱ ወደ ገባዖን ሄደ፤ እግዚአብሔር ልባቸውን የነካው ኀያላንም ከሳኦል ጋር ሄዱ።'),
  ('6ba72ccc-e3f2-56e6-aea7-d161bc6ae4be', 'a0dd5282-5902-5084-a524-fd875046627f', '3bdeffbe-0bba-50cc-a5b7-edfc18f923f5', 11, 27, 'ክፉዎች ሰዎች ግን፥ “ያድነን ዘንድ ይህ ሰው ማን ነው?” ብለው ናቁት፤ እጅ መንሻም አላመጡለትም።'),
  ('250fea7d-3783-525c-afbb-f5b883d78697', 'f267a93c-fa24-596c-a21e-40d2ba092d51', '3a74a55f-4f70-5f6a-a5fd-d517a163ab38', 1, 1, 'እንዲህም ሆነ፤ ከአንድ ወር በኋላ አሞናዊው ናዖስ መጣ፤ በኢያቢስ ገለዓድም ሰፈረ፤ የኢያቢስም ሰዎች ሁሉ፥ “አሞናዊውን ናዖስን ቃል ኪዳን አድርግልን፤ እኛም እንገዛልሃለን” አሉት።'),
  ('3fa90192-a9f7-51d8-ab34-679f9e7b81f4', 'f267a93c-fa24-596c-a21e-40d2ba092d51', '3a74a55f-4f70-5f6a-a5fd-d517a163ab38', 2, 2, 'አሞናዊው ናዖስም፦“ ቀኝ ዐይናችሁን ብታወጡ ከእናንተ ጋር ቃል ኪዳን አደርጋለሁ፤ በእስራኤልም ሁሉ ላይ ስድብን አደርጋለሁ” አላቸው።'),
  ('47c726ee-533a-5d82-abf7-d03f202ea55f', 'f267a93c-fa24-596c-a21e-40d2ba092d51', '3a74a55f-4f70-5f6a-a5fd-d517a163ab38', 3, 3, 'የኢያቢስም ሰዎች፥ “ወደ እስራኤል ሀገር ሁሉ መልእክተኞችን እንድንልክ ሰባት ቀን ቈይልን፤ ከዚያም በኋላ የሚያድነን ባይኖር ወደ አንተ እንመጣለን” አሉት።'),
  ('2955882b-cba9-512b-a3aa-b5c74882a671', 'f267a93c-fa24-596c-a21e-40d2ba092d51', '3a74a55f-4f70-5f6a-a5fd-d517a163ab38', 4, 4, 'መልእክተኞቹም ሳኦል ወዳለበት ወደ ገባዖን መጥተው ይህን ነገር በሕዝቡ ጆሮ ተናገሩ፤ ሕዝቡም ሁሉ ድምፃቸውን ከፍ አድርገው አለቀሱ።'),
  ('390d6ae6-a81b-59a6-ab97-5d15a257abd6', 'f267a93c-fa24-596c-a21e-40d2ba092d51', '3a74a55f-4f70-5f6a-a5fd-d517a163ab38', 5, 5, 'እነሆም፥ ሳኦል ከእርሻው አርፍዶ መጣ፤ ሳኦልም፥ “ሕዝቡ የሚያለቅስ ምን ሆኖ ነው?” አለ። የኢያቢስንም ሰዎች ነገር ነገሩት።'),
  ('3ee96b08-62ff-5f45-a7b3-dc8d1eda7024', 'f267a93c-fa24-596c-a21e-40d2ba092d51', '3a74a55f-4f70-5f6a-a5fd-d517a163ab38', 6, 6, 'ይህንም ነገር በሰማ ጊዜ በሳኦል ላይ የእግዚአብሔር መንፈስ መጣ፤ በእነርሱም ላይ ተቈጣ።'),
  ('b185dfc4-5d3c-5ee2-ab17-83f12873c519', 'f267a93c-fa24-596c-a21e-40d2ba092d51', '3a74a55f-4f70-5f6a-a5fd-d517a163ab38', 7, 7, 'ጥምዱንም በሬዎች ወስዶ በየብልታቸው ቈራረጣቸው፤ ወደ እስራኤልም ዳርቻ ሁሉ በመልእክተኞቹ እጅ ላከና፥ “ሳኦልንና ሳሙኤልን ተከትሎ የማይወጣ ሁሉ፥ በበሬዎቹ እንዲሁ ይደረግበታል” አለ። ድንጋጤም በሕዝቡ ላይ ከእግዚአብሔር ዘንድ ወደቀ፤ እንደ አንድ ሰውም ሆነው ጮኹ።'),
  ('3a57b5bd-1861-5dc1-af99-3ebfa129a9a2', 'f267a93c-fa24-596c-a21e-40d2ba092d51', '3a74a55f-4f70-5f6a-a5fd-d517a163ab38', 8, 8, 'በባማ ባለው በቤዜቅም ቈጠራቸው፤ የእስራኤልም ልጆች ሦስት መቶ ሺህ፥ የይሁዳም ሰዎች ሠላሳ ሺህ ነበሩ።'),
  ('3a55fbff-8ed6-5810-a896-7ab791a2650d', 'f267a93c-fa24-596c-a21e-40d2ba092d51', '3a74a55f-4f70-5f6a-a5fd-d517a163ab38', 9, 9, 'የመጡትንም መልእክተኞች፥ “የኢያቢስ ገለዓድን ሰዎች፦ ነገ ፀሐይ በተኰሰ ጊዜ ድኅነት ይሆንላችኋል በሉአቸው” አሉአቸው። መልእክተኞችም ወደ ከተማዪቱ መጥተው ለኢያቢስ ሰዎች ነገሩ፤ ደስም አላቸው።'),
  ('f8fd40cb-5b16-50a1-af15-9165341ad81e', 'f267a93c-fa24-596c-a21e-40d2ba092d51', '3a74a55f-4f70-5f6a-a5fd-d517a163ab38', 10, 10, 'የኢያቢስም ሰዎች፦ ለአሞናዊው ናዖስ “ነገ እንወጣላችኋለን፤ ደስ የሚያሰኛችሁንም አድርጉብን” አሉት።'),
  ('6636207b-05d5-5f5a-ad9c-1c275e4b671c', 'f267a93c-fa24-596c-a21e-40d2ba092d51', '3a74a55f-4f70-5f6a-a5fd-d517a163ab38', 11, 11, 'በነጋውም ሳኦል ሕዝቡን በሦስት ወገን አደረጋቸው፤ወገግም ባለ ጊዜ ወደ ሰፈሩ መካከል ገቡ፤ ቀትርም እስኪሆን ድረስ አሞናውያንን መቱ፤ የቀሩትም ተበተኑ፤ ከውስጣቸውም ሁለት በአንድ ላይ ሆነው አልተገኙም።'),
  ('72ede488-50df-5800-aa5b-811efb6094aa', 'f267a93c-fa24-596c-a21e-40d2ba092d51', '9d29a1e5-3ced-562b-a6b7-0af1a73921b5', 1, 12, 'ሕዝቡም ሳሙኤልን፥ “ሳኦል አይንገሥብን ያሉ እነማን ናቸው? እነዚያን ሰዎች አውጡአቸውና እንግደላቸው” አሉት።'),
  ('6a219365-4574-5aec-a641-4ce57db03130', 'f267a93c-fa24-596c-a21e-40d2ba092d51', '9d29a1e5-3ced-562b-a6b7-0af1a73921b5', 2, 13, 'ሳኦልም፦“በዚያች ቀን እግዚአብሔር ለእስራኤል ድኅነትን አድርጎአልና ዛሬ አንድ ሰው አይሞትም” አለ።'),
  ('e87ceab3-a25c-53d4-a229-0d04b1604180', 'f267a93c-fa24-596c-a21e-40d2ba092d51', '9d29a1e5-3ced-562b-a6b7-0af1a73921b5', 3, 14, 'ሳሙኤልም ሕዝቡን፥ “ኑ፤ ወደ ጌልገላ እንሂድ፤ በዚያም መንግሥቱን እናጽና” አላቸው።'),
  ('cfcc6e74-7edc-5035-aeec-ca395bdba30c', 'f267a93c-fa24-596c-a21e-40d2ba092d51', '9d29a1e5-3ced-562b-a6b7-0af1a73921b5', 4, 15, 'ሕዝቡም ሁሉ ወደ ጌልገላ ሄዱ፤ ሳሙኤልም ሳኦልን ቀብቶ በእግዚአብሔር ፊት በጌልጌላ አነገሠው፤ በዚያም በእግዚአብሔር ፊት የእህል ቍርባንና የሰላም መሥዋዕት አቀረበ፤ በዚያም ሳኦልና የእስራኤል ሰዎች ሁሉ ታላቅ ደስታ አደረጉ።'),
  ('102a21bb-287f-5dcd-abf4-94b6e6b04aee', '206264f4-fe9b-5980-a7a2-c2a9bf76939d', '0f9ced76-ff44-5d73-a845-38162484123f', 1, 1, 'ሳሙኤልም ለእስራኤል ሕዝብ ሁሉ አለ፥ “የነገራችሁኝን ሁሉ ሰምቼ ንጉሥ አንግሼላችኋለሁ።'),
  ('73dd2c32-806b-5485-ad8c-161bfe50e682', '206264f4-fe9b-5980-a7a2-c2a9bf76939d', '0f9ced76-ff44-5d73-a845-38162484123f', 2, 2, 'አሁንም እነሆ፥ ንጉሡ በፊታችሁ ይሄዳል፤ እኔም አርጅቻለሁ፤ እንግዲህም አርፋለሁ፤ እነሆም፥ ልጆቼ ከእናንተ ጋር ናቸው፤ እኔም ከሕፃንነቴ ጀምሮ እስከ ዛሬ ድረስ በፊታችሁ ሄድሁ።'),
  ('7bf63cc6-7582-5873-a6f0-b6971e6041cb', '206264f4-fe9b-5980-a7a2-c2a9bf76939d', '0f9ced76-ff44-5d73-a845-38162484123f', 3, 3, 'እነሆኝ፥ በእግዚአብሔርና እርሱ በቀባው ፊት መስክሩብኝ፤ የማንን በሬ ወሰድሁ? የማንንስ አህያ ወሰድሁ? ማንንስ ሸነገልሁ? በማንስ ላይ ግፍ አደረግሁ? ነጠላ ጫማ እንኳን ቢሆን ከማን እጅ መማለጃ ተቀበልሁ? መስክሩብኝ፤ እኔ እመልስላችኋለሁ።”'),
  ('a45b88bf-d930-5eb2-a995-f82db49474c3', '206264f4-fe9b-5980-a7a2-c2a9bf76939d', '0f9ced76-ff44-5d73-a845-38162484123f', 4, 4, 'እነርሱም ሳሙኤልን፥ “ግፍም አላደረግህብንም፤ የቀማኸን የለም፤ አላሠቃየኸንም፤ ከእኛም ከማንም እጅ ምንም አልወሰድህም” አሉት።'),
  ('19a618c4-a507-5b6c-ab3f-51337fb939ca', '206264f4-fe9b-5980-a7a2-c2a9bf76939d', '0f9ced76-ff44-5d73-a845-38162484123f', 5, 5, 'ሳሙኤልም፥ “በእጄ ምንም እንዳላገኛችሁ ዛሬ በዚህች ቀን እግዚአብሔር ምስክር ነው፤ እርሱ የቀባውም ምስክር ነው” አላቸው፤ እነርሱም፥ “አዎ ምስክር ነው” አሉ።'),
  ('a76ed938-76c0-58e4-a6bf-64f93c1a2c92', '206264f4-fe9b-5980-a7a2-c2a9bf76939d', '0f9ced76-ff44-5d73-a845-38162484123f', 6, 6, 'ሳሙኤልም ሕዝቡን አለ፥ “ሙሴንና አሮንን ያላቀ፥ አባቶቻችሁንም ከግብጽ ምድር ያወጣ እግዚአብሔር ምስክር ነው።'),
  ('57bed3ee-c187-5492-a1ad-6443c6832481', '206264f4-fe9b-5980-a7a2-c2a9bf76939d', '0f9ced76-ff44-5d73-a845-38162484123f', 7, 7, 'አሁንም ቁሙ፤ በእግዚአብሔርም ፊት እፋረዳችኋለሁ፤ ለእናንተና ለአባቶቻችሁ ያደረገውን የእግዚአብሔርን ጽድቅ ሁሉ እነግራችኋለሁ።'),
  ('661017aa-0e13-5118-a915-c199e6484c62', '206264f4-fe9b-5980-a7a2-c2a9bf76939d', '0f9ced76-ff44-5d73-a845-38162484123f', 8, 8, 'ያዕቆብና ልጆቹ ወደ ግብጽ በገቡ ጊዜ ግብጻውያን አስጨነቁአቸው፤ አባቶቻችሁም ወደ እግዚአብሔር ጮኹ፤ እግዚአብሔርም ሙሴንና አሮንን ላከ፤ አባቶቻችሁንም ከግብጽ አውጥተው በዚህ ቦታ አኖሩአቸው።'),
  ('f7027e8a-74ea-57b1-a7b3-6d714b9c9c50', '206264f4-fe9b-5980-a7a2-c2a9bf76939d', '0f9ced76-ff44-5d73-a845-38162484123f', 9, 9, 'አምላካቸውንም እግዚአብሔርን ረሱ፤ ለአሶር ሠራዊትም አለቃ ለሲሣራ እጅ፥ ለፍልስጥኤማውያንም እጅ፥ ለሞዓብም ንጉሥ እጅ አሳልፎ ሰጣቸው፤ እነርሱም ወጉአቸው፤'),
  ('06b13a63-1e29-56e3-a87e-b1b89c35cb4d', '206264f4-fe9b-5980-a7a2-c2a9bf76939d', '0f9ced76-ff44-5d73-a845-38162484123f', 10, 10, 'እነርሱም፦ እግዚአብሔርን ትተን በዓሊምንና ምስሎቹን በማምለካችን በድለናል፤ አሁንም ከጠላቶቻችን እጅ አድነን፤ እናመልክሃለንም” ብለው ወደ እግዚአብሔር ጮኹ ።'),
  ('b05573e2-dcf6-5d60-ae57-47610133982b', '206264f4-fe9b-5980-a7a2-c2a9bf76939d', '0f9ced76-ff44-5d73-a845-38162484123f', 11, 11, 'እግዚአብሔርም ይሩበኣልን፥ ባርቅንም፥ ዮፍታሔንም፥ ሳሙኤልንም ላከ፤ በዙሪያችሁም ካሉት ከጠላቶቻችሁ እጅ አዳኑአችሁ፤ ተዘልላችሁም ተቀመጣችሁ።'),
  ('53e6c07b-5171-5e2e-ab5b-d3882c2c220a', '206264f4-fe9b-5980-a7a2-c2a9bf76939d', '0f9ced76-ff44-5d73-a845-38162484123f', 12, 12, 'የአሞንም ልጆች ንጉሥ ናዖስ እንደ መጣባችሁ ባያችሁ ጊዜ፥ አምላካችሁ እግዚአብሔር ንጉሣችሁ ሳለ፦ እንዲህ አይሁን፤ ነገር ግን ንጉሥ አንግሥልን አላችሁኝ።'),
  ('a12ee8da-0d3b-5b75-aaf5-0859e25f4ede', '206264f4-fe9b-5980-a7a2-c2a9bf76939d', '0f9ced76-ff44-5d73-a845-38162484123f', 13, 13, 'አሁንም የመረጣችሁትን ንጉሥ እዩ፤ እነሆም፥ እግዚአብሔር ንጉሥ ሰጣችሁ።'),
  ('7586a6fe-4207-56cf-a17c-f10e934ca8d8', '206264f4-fe9b-5980-a7a2-c2a9bf76939d', '0f9ced76-ff44-5d73-a845-38162484123f', 14, 14, 'እግዚአብሔርን ብትፈሩ፥ ብታመልኩትም፥ ቃሉንም ብትሰሙ፥ በእግዚአብሔርም ትእዛዝ ላይ ባታምፁ፥ እናንተና በእናንተ ላይ የነገሠው ንጉሥ አምላካችሁን እግዚአብሔርን ብትከተሉ፥ መልካም ይሆንላችኋል።'),
  ('c6c783d5-2eb0-5dbe-adbc-1b1244bf69f8', '206264f4-fe9b-5980-a7a2-c2a9bf76939d', '0f9ced76-ff44-5d73-a845-38162484123f', 15, 15, 'ነገር ግን የእግዚአብሔርን ቃል ባትሰሙ፥ በእግዚአብሔርም ትእዛዝ ላይ ብታምፁ፥ በእናንተና በንጉሣችሁ ላይ የእግዚአብሔር እጅ ትመጣለች።'),
  ('230041bc-9da2-59cc-a810-804066104786', '206264f4-fe9b-5980-a7a2-c2a9bf76939d', '0f9ced76-ff44-5d73-a845-38162484123f', 16, 16, 'አሁንም ቁሙ፤ እግዚአብሔርም በዐይናችሁ ፊት የሚያደርገውን ይህን ታላቅ ነገር ተመልከቱ።'),
  ('34d3cba2-80bc-5fd3-a2a2-1d23b018cfe2', '206264f4-fe9b-5980-a7a2-c2a9bf76939d', '0f9ced76-ff44-5d73-a845-38162484123f', 17, 17, 'የስንዴ መከር ዛሬ አይደለምን? ወደ እግዚአብሔር እጮኻለሁ፤ እርሱም ነጐድጓድንና ዝናብን ይልካል፤ እናንተም ንጉሥ በመለመናችሁ በእግዚአብሔር ፊት ያደረጋችሁት ክፋት ታላቅ እንደ ሆነ ታውቃላችሁ፤ ታያላችሁም።”'),
  ('d0ed858d-222b-5c5f-a2e6-8c7edd2a69ab', '206264f4-fe9b-5980-a7a2-c2a9bf76939d', '0f9ced76-ff44-5d73-a845-38162484123f', 18, 18, 'ሳሙኤልም ወደ እግዚአብሔር ጮኸ፥ እግዚአብሔርም በዚያ ቀን ነጐድጓድንና ዝናብን ላከ፤ ያንጊዜም ሕዝቡ ሁሉ እግዚአብሔርንና ሳሙኤልን እጅግ ፈሩአቸው።'),
  ('0aa26659-ed6b-56ea-a23b-29745b1c6f8d', '206264f4-fe9b-5980-a7a2-c2a9bf76939d', '0f9ced76-ff44-5d73-a845-38162484123f', 19, 19, 'ሕዝቡም ሁሉ ሳሙኤልን፥ “ንጉሥ በመለመናችን በኀጢአታችን ሁሉ ላይ ይህን ክፋት ጨምረናልና እንዳንሞት ስለ ባሪያዎችህ ወደ አምላክህ ወደ እግዚአብሔር ጸልይልን” አሉት።'),
  ('511bbfb4-a60d-5c91-a1c5-9352df0f36ee', '206264f4-fe9b-5980-a7a2-c2a9bf76939d', '0f9ced76-ff44-5d73-a845-38162484123f', 20, 20, 'ሳሙኤልም ሕዝቡን ሁሉ አላቸው፥ “አትፍሩ፤ በእውነት ይህን ክፋት ሁሉ አደረጋችሁ፤ ነገር ግን እግዚአብሔርን በፍጹም ልባችሁ አምልኩት እንጂ እግዚአብሔርን ከመከተል ፈቀቅ አትበሉ።'),
  ('542a7c87-c9f2-5152-a0ed-e58648569154', '206264f4-fe9b-5980-a7a2-c2a9bf76939d', '0f9ced76-ff44-5d73-a845-38162484123f', 21, 21, 'ምንም አይደሉምና የማይረቡትንና የማያድኑአችሁን ለመከተል ከእርሱ ፈቀቅ አትበሉ።'),
  ('d8b51456-1928-539d-accd-0043944a5641', '206264f4-fe9b-5980-a7a2-c2a9bf76939d', '0f9ced76-ff44-5d73-a845-38162484123f', 22, 22, 'እግዚአብሔር ለእርሱ ሕዝብ ያደርጋችሁ ዘንድ ተቀብሎአችኋልና፥ እግዚአብሔር ስለ ታላቅ ስሙ ሕዝቡን አይተውም።'),
  ('4233caa2-feff-5bdc-a570-fef0fd1a5dbd', '206264f4-fe9b-5980-a7a2-c2a9bf76939d', '0f9ced76-ff44-5d73-a845-38162484123f', 23, 23, 'ደግሞ መልካሙንና ቅኑን መንገድ አሳያችኋለሁ እንጂ ስለ እናንተ መጸለይንና እግዚአብሔርን ማገልገልን በመተው እርሱን እበድል ዘንድ እግዚአብሔር ይህን አያድርግብኝ።'),
  ('40b34669-ba9d-5ae9-accc-21d90a30f8b5', '206264f4-fe9b-5980-a7a2-c2a9bf76939d', '0f9ced76-ff44-5d73-a845-38162484123f', 24, 24, 'ብቻ እግዚአብሔርን ፍሩ፤ ያደረገላችሁንም ታላቅ ነገር አይታችኋልና በፍጹም ልባችሁ በእውነት አምልኩት፤'),
  ('6c4a8122-63d1-55ce-a5c6-5347a4b67d87', '206264f4-fe9b-5980-a7a2-c2a9bf76939d', '0f9ced76-ff44-5d73-a845-38162484123f', 25, 25, 'ነገር ግን ክፉ ብትሠሩ እናንተም፥ ንጉሣችሁም ትጠፋላችሁ።”'),
  ('87d2c78c-9004-5f28-a524-4dbf3738a814', '8e15bcc1-5b0b-5284-ada5-ba40933265a9', '06394f8c-cf3f-5413-ab5e-bf11b3eb3600', 1, 1, 'ሳኦልም በእስራኤል ላይ ከነገሠ ሁለት ዓመት ሆነው፥'),
  ('4b41f822-fe69-5c21-a684-162661aecd8c', '8e15bcc1-5b0b-5284-ada5-ba40933265a9', '06394f8c-cf3f-5413-ab5e-bf11b3eb3600', 2, 2, 'ያንጊዜም ሳኦል ሦስት ሺህ ሰዎችን ከእስራኤል መረጠ፤ ሁለቱም ሺህ በማኪማስና በቤቴል ተራራ ከሳኦል ጋር ነበሩ፤ አንዱም ሺህ በብንያም ገባዖን ከልጁ ከዮናታን ጋር ነበሩ፤ የቀረውንም ሕዝብ እያንዳንዱን ወደ ድንኳኑ አሰናበተ።'),
  ('56839b8e-4555-5ab7-a1d4-09a0fd36b447', '8e15bcc1-5b0b-5284-ada5-ba40933265a9', '06394f8c-cf3f-5413-ab5e-bf11b3eb3600', 3, 3, 'ዮናታንም በኮረብታው የነበሩትን የፍልስጥኤማውያንን ጭፍራ መታ፤ ፍልስጥኤማውያንም ያን ሰሙ፤ ሳኦልም፦ እስራኤል ይስሙ ብሎ በሀገሩ ሁሉ ቀንደ መለከት ነፋ።'),
  ('8675a94e-6bdd-5dac-a806-f5cbfad6d3be', '8e15bcc1-5b0b-5284-ada5-ba40933265a9', '06394f8c-cf3f-5413-ab5e-bf11b3eb3600', 4, 4, 'እስራኤልም ሁሉ ሳኦል የፍልስጥኤማውያንን ጭፍራ እንደ መታ፥ ደግሞም እስራኤል በፍልስጥኤማውያን ዘንድ እንደ በረቱ ሰሙ፤ ሕዝቡም ደንፍተው ሳኦልን ለመከተል ወደ ጌልጌላ ተሰበሰቡ።'),
  ('06e26a92-b380-5d28-a60d-51a42120d408', '8e15bcc1-5b0b-5284-ada5-ba40933265a9', '06394f8c-cf3f-5413-ab5e-bf11b3eb3600', 5, 5, 'ፍልስጥኤማውያንም ከእስራኤል ጋር ለመዋጋት ተሰበሰቡ፤ ሠላሳ ሺህ ሰረገሎች፥ ስድስት ሺህም ፈረሰኞች፥ በባሕርም ዳር እንዳለ አሸዋ ብዙ ሕዝብ ነበሩ፤ ወጥተውም ከቤቶሮን በአዜብ በኩል በማኪማስ ሰፈሩ።'),
  ('6fe568d6-1072-5b5b-aea1-70c95a5b4d84', '8e15bcc1-5b0b-5284-ada5-ba40933265a9', '06394f8c-cf3f-5413-ab5e-bf11b3eb3600', 6, 6, 'የእስራኤልም ሰዎች ወደ እነርሱ መሄድ እንደሚያስጨንቃቸው ባዩ ጊዜ ሕዝቡ በዋሻና በግንብ፥ በገደልና በቋጥኝ፥ በጕድጓድም ውስጥ ተሸሸጉ።'),
  ('38183bf9-6003-5c23-a5c6-588d6bb4ecb3', '8e15bcc1-5b0b-5284-ada5-ba40933265a9', '06394f8c-cf3f-5413-ab5e-bf11b3eb3600', 7, 7, 'ዮርዳኖስንም ተሻግረው ወደ ጋድና ወደ ገለዓድ ምድር የሄዱ አሉ፤ ሳኦል ግን ገና በጌልጌላ ነበረ፤ ሕዝቡም ሁሉ ፈርተው እርሱን መከተልን ትተው ተበተኑ።'),
  ('0f6d118f-916c-5ea5-a238-8ed66fa23a6a', '8e15bcc1-5b0b-5284-ada5-ba40933265a9', '8ffe0cd4-31eb-56b3-a137-d0d5b5824712', 1, 8, 'ሳኦልም ሳሙኤል እንደ ቀጠረው ጊዜ ሰባት ቀን ቈየ፤ ሳሙኤል ግን ወደ ጌልጌላ አልመጣም፤ ሕዝቡም ከእርሱ ተለይተው ተበታተኑ።'),
  ('2351d6f6-caae-5827-acb1-8b5758905927', '8e15bcc1-5b0b-5284-ada5-ba40933265a9', '8ffe0cd4-31eb-56b3-a137-d0d5b5824712', 2, 9, 'ሳኦልም፥ “የሚቃጠል መሥዋዕትና የደኅንነት መሥዋዕት አምጡልኝ” አለ። የሚቃጠለውንም መሥዋዕት አሳረገ።'),
  ('60563a63-47af-5907-aa01-a84a8d151082', '8e15bcc1-5b0b-5284-ada5-ba40933265a9', '8ffe0cd4-31eb-56b3-a137-d0d5b5824712', 3, 10, 'የሚቃጠለውንም መሥዋዕት ማሳረግ በፈጸመ ጊዜ፥ እነሆ፥ ሳሙኤል መጣ፤ ሳኦልም እንዲባርከው ሊገናኘው ወጣ።'),
  ('16747b18-9f50-5679-a932-7e0b4b8d65c8', '8e15bcc1-5b0b-5284-ada5-ba40933265a9', '8ffe0cd4-31eb-56b3-a137-d0d5b5824712', 4, 11, 'ሳሙኤልም፥ “ያደረግኸው ምንድን ነው?” አለ። ሳኦልም፥ “ሕዝቡ ከእኔ ተለይተው እንደ ተበታተኑ፥ አንተም በነገርኸኝ መሠረት በቀጠሮው ቀን እንዳልመጣህ፥ ፍልስጥኤማውያንም ወደ ማኪማስ እንደ ተሰበሰቡ አየሁ፤'),
  ('587314df-33e9-532b-ad99-e0df5730b8a4', '8e15bcc1-5b0b-5284-ada5-ba40933265a9', '8ffe0cd4-31eb-56b3-a137-d0d5b5824712', 5, 12, 'ስለዚህ፦ ፍልስጥኤማውያን አሁን ወደ እኔ ወደ ጌልጌላ ይወርዱብኛል፤ እኔም የእግዚአብሔርን ፊት አልለመንሁም አልሁ፤ ስለዚህም ደፍሬ የሚቃጠል መሥዋዕትን አሳረግሁ” አለ።'),
  ('077f64eb-35eb-5c94-aafd-05016b299be3', '8e15bcc1-5b0b-5284-ada5-ba40933265a9', '8ffe0cd4-31eb-56b3-a137-d0d5b5824712', 6, 13, 'ሳሙኤልም ሳኦልን፥ “በድለኻል፤ አምላክህ እግዚአብሔር ያዘዘህን ትእዛዙን አልጠበቅህምና፤ ዛሬ እግዚአብሔር መንግሥትህን በእስራኤል ላይ ለዘለዓለም አጽንቶልህ ነበር።'),
  ('622936d5-b573-59ba-a4e9-f5adca1c9176', '8e15bcc1-5b0b-5284-ada5-ba40933265a9', '8ffe0cd4-31eb-56b3-a137-d0d5b5824712', 7, 14, 'ከእንግዲህ ወዲያ ግን መንግሥትህ አይጸናም፤ እግዚአብሔር እንደ ልቡ የሆነ ሰው መርጦአል፤ እግዚአብሔርም ያዘዘህን አልጠበቅህምና እግዚአብሔር በሕዝቡ ላይ ንጉሥን ያነግሣል” አለው።'),
  ('55551bd6-9a9f-5d15-a967-ed491f40f9fa', '8e15bcc1-5b0b-5284-ada5-ba40933265a9', '8ffe0cd4-31eb-56b3-a137-d0d5b5824712', 8, 15, 'ሳሙኤልም ከጌልጌላ ተነሥቶ መንገዱን ሄደ፤ የቀሩትም ሕዝብ ሳኦልን ተከትለው ሰልፈኞቹን ሊገናኙ ሄዱ። ከጌልጌላም ተነሥተው ወደ ብንያም ገባዖን መጡ፤ ሳኦልም ከእርሱ ጋር የነበሩትን ሕዝብ ቈጠረ፤ ስድስት መቶም የሚያህሉ ሰዎች ነበሩ።'),
  ('8e222eec-481c-5940-a99d-b86197860b5b', '8e15bcc1-5b0b-5284-ada5-ba40933265a9', '8ffe0cd4-31eb-56b3-a137-d0d5b5824712', 9, 16, 'ሳኦልና ልጁ ዮናታንም፥ ከእነርሱም ጋር የነበሩ ሕዝብ በብንያም ገባዖን ተቀምጠው አለቀሱ፤ ፍልስጥኤማውያንም በማኪማስ ሰፈሩ።'),
  ('93a33691-e175-519f-a2a6-cc5cd30a3c01', '8e15bcc1-5b0b-5284-ada5-ba40933265a9', '8ffe0cd4-31eb-56b3-a137-d0d5b5824712', 10, 17, 'ከፍልስጥኤማውያንም ሰፈር ማራኪዎች በሦስት ክፍል ሆነው ወጡ፤ አንዱም ክፍል በጎፌር መንገድ ወደ ሦጋክ ምድር ሄደ።'),
  ('7f8d1c79-da51-55f8-a6da-a397038a41db', '8e15bcc1-5b0b-5284-ada5-ba40933265a9', '8ffe0cd4-31eb-56b3-a137-d0d5b5824712', 11, 18, 'ሁለተኛው ክፍል ወደ ቤቶሮን መንገድ ዞረ፤ ሦስተኛውም ክፍል በገባዖን መንገድ ባለው ወደ ሴቤሮም ሸለቆ በሚመለከተው በዳርቻው መንገድ ዞረ።'),
  ('2f0ab6d6-e383-5b14-a8d1-d9177f0e0694', '8e15bcc1-5b0b-5284-ada5-ba40933265a9', '8ffe0cd4-31eb-56b3-a137-d0d5b5824712', 12, 19, 'ፍልስጥኤማውያንም፥ “ዕብራውያን ሰይፍና ጦር እንዳይሠሩ” ብለው ነበርና በእስራኤል ምድር ሁሉ ብረት ሠሪ አልተገኘም።'),
  ('add6f485-6a73-594b-a98a-eb3917be02ba', '8e15bcc1-5b0b-5284-ada5-ba40933265a9', '8ffe0cd4-31eb-56b3-a137-d0d5b5824712', 13, 20, 'እስራኤልም ሁሉ ማረሻውንና ማጭዱን፥ መጥረቢያውንና መቈፈሪያውን ይስሉ ዘንድ ወደ ፍልስጥኤማውያን ይወርዱ ነበር።'),
  ('701e4865-a528-51c1-af13-4f109c38ad34', '8e15bcc1-5b0b-5284-ada5-ba40933265a9', '8ffe0cd4-31eb-56b3-a137-d0d5b5824712', 14, 21, 'አዝመራውም ለአጨዳ ደርሶ ነበር። ለማረሻውና ለመቈፈሪያው ዋጋው ሦስት ሰቅል ነበር። መጥረቢያውንም ለማሳል፥ መውጊያውንም ለማበጀት ዋጋው ተመሳሳይ ነበር።'),
  ('1b1b63dd-7921-5850-aab3-1a4d67661ba7', '8e15bcc1-5b0b-5284-ada5-ba40933265a9', '8ffe0cd4-31eb-56b3-a137-d0d5b5824712', 15, 22, 'ስለዚህም በማኪማስ ጦርነት ጊዜ ሰይፍና ጦር ከሳኦልና ከዮናታን ጋር በነበሩ ሕዝብ ሁሉ እጅ አልተገኘም፤ ብቻ በሳኦልና በልጁ በዮናታን ዘንድ ተገኘ።'),
  ('64134e59-20e0-5869-a9c6-665068f446f1', '8e15bcc1-5b0b-5284-ada5-ba40933265a9', '8ffe0cd4-31eb-56b3-a137-d0d5b5824712', 16, 23, 'ከዚያም ጥቂቶች ከፍልስጥኤማውያን ሰፈር ወደ ማኪማስ መተላለፊያ ወጡ።'),
  ('a97fc849-232d-5092-a918-daf99e4f14e3', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', '72c91126-70c9-5578-aa1b-857659105cae', 1, 1, 'በነጋም ጊዜ፥ የሳኦል ልጅ ዮናታን ጋሻ ጃግሬውን፥ “ና፤ በዚያ በኩል ወዳለው ወደ ፍልስጥኤማውያን ሰፈር እንለፍ” አለው፤ ለአባቱም አልነገረውም።'),
  ('e1e5b967-0cba-5c52-ac37-29a3b634ca24', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', '72c91126-70c9-5578-aa1b-857659105cae', 2, 2, 'ሳኦልም በመጌዶን ባለው በሮማኑ ዛፍ በታች በኮረብታው ላይ ተቀምጦ ነበር፤ ከእርሱም ጋር የነበረው ሕዝብ ስድስት መቶ የሚያህል ሰው ነበረ።'),
  ('6162e78f-e061-5744-a159-9553e92c0d14', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', '72c91126-70c9-5578-aa1b-857659105cae', 3, 3, 'የዔሊ ልጅ፥ የፊንሐስ ልጅ፥ የዮካብድ ወንድም፥ የአኪጦብ ልጅ በሴሎ ለእግዚአብሔር ካህን የሆነ፥ ኤፉድም የለበሰ አኪያ አብሮ ነበር፤ ሕዝቡም ዮናታን እንደ ሄደ አላወቁም ነበር።'),
  ('1a678549-b765-5fea-a74a-f708c45770e1', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', '72c91126-70c9-5578-aa1b-857659105cae', 4, 4, 'ዮናታንም ወደ ፍልስጥኤማውያን ሰፈር ሊሻገርበት በወደደው መተላለፊያ መካከል በወዲህ አንድ ሾጣጣ፥ በወዲህም አንድ ሾጣጣ ድንጋዮች ነበሩ፤ የአንዱም ስም ባዚስ፥ የሁለተኛውም ስም ሴና ነበረ።'),
  ('e7fe0fc5-b66d-5f74-a6be-2b393274eeca', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', '72c91126-70c9-5578-aa1b-857659105cae', 5, 5, 'አንደኛዋ መንገድ በማኪማስ አንጻር በመስዕ በኩል የምትመጣ ናት፤ ሁለተኛዋም መንገድ በገባዖን አንጻር በአዜብ በኩል የምትመጣ ነበረች።'),
  ('9ea3048d-fb2d-5b87-af9b-05e58bacbb46', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', '72c91126-70c9-5578-aa1b-857659105cae', 6, 6, 'ዮናታንም ጋሻ ጃግሬውን፥ “ና፥ ወደ እነዚህ ቈላፋን ሰፈር እንለፍ፤ በብዙ ወይም በጥቂት ማዳን እግዚአብሔርን አያስቸግረውምና ምናልባት እግዚአብሔር ይረዳን ይሆናል” አለው።'),
  ('265b630c-c9d1-596c-acc2-125ee2da6d67', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', '72c91126-70c9-5578-aa1b-857659105cae', 7, 7, 'ጋሻ ጃግሬውም፥ “ልብህ ያሰኘህን ሁሉ አድርግ እነሆ፥ ከአንተ ጋር ነኝ፤ እንደ አንተ ልብ የእኔም ልብ እንዲሁ ነው” አለው።'),
  ('0faf84a7-437a-5c85-a2f5-0980f5f5b781', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', '72c91126-70c9-5578-aa1b-857659105cae', 8, 8, 'ዮናታንም አለው፥ “እነሆ፥ ወደ ሰዎቹ እናልፋለን፤ ወደ እነርሱም እንቀርባለን፤'),
  ('bf529e60-8f4b-557c-add2-8b35f1bff9e3', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', '72c91126-70c9-5578-aa1b-857659105cae', 9, 9, 'እነርሱም፦ እስክንነግራችሁ ድረስ ርቃችሁ ቈዩ ቢሉን ርቀን እንቆማለን፤ ወደ እነርሱም አንወጣም።'),
  ('6efcff2c-acd4-5c77-a8f6-50e1c151a918', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', '72c91126-70c9-5578-aa1b-857659105cae', 10, 10, 'ነገር ግን ወደ እኛ ውጡ ቢሉን እግዚአብሔር በእጃችን አሳልፎ ሰጥቶአቸዋልና እንወጣለን፤ ምልክታችንም ይህ ይሆናል።”'),
  ('3a3f8aa9-7359-5ff0-a79b-96601c2243db', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', '72c91126-70c9-5578-aa1b-857659105cae', 11, 11, 'ሁለታቸውም ወደ ፍልስጥኤማውያን ሰፈር ገቡ፤ ፍልስጥኤማውያንም “እነሆ፥ ዕብራውያን ከተሸሸጉበት ጕድጓድ ይወጣሉ” አሉ።'),
  ('74f0318f-b5ee-509d-ac4e-cfeab9102bd6', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', '72c91126-70c9-5578-aa1b-857659105cae', 12, 12, 'የሰፈሩም ሰዎች፦ ዮናታንንና ጋሻ ጃግሬውን “ወደ እኛ ውጡ፤ አንድ ነገርንም እንነግራችኋለን” አሉ። ዮናታንም ጋሻ ጃግሬውን “እግዚአብሔር በእስራኤል እጅ አሳልፎ ሰጥቶአቸዋልና ተከተለኝ” አለው።'),
  ('b92e1307-348b-53e5-ab42-612c62faf955', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', '72c91126-70c9-5578-aa1b-857659105cae', 13, 13, 'ዮናታንም በእጁና በእግሩ ወጣ፤ ጋሻ ጃግሬውም ከእርሱ ጋር ነበረ፤ ዮናታንም ፊቱን መልሶ ገደላቸው፤ ጋሻ ጃግሬውም ተከትሎ ገደላቸው።'),
  ('09f01f4c-2e90-5f6c-a97a-43667e508644', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', '72c91126-70c9-5578-aa1b-857659105cae', 14, 14, 'የዮናታንና የጋሻ ጃግሬውም በወንጭፍና በዱላ የመጀመሪያ ግድያቸው በአንድ ትልም እርሻ መካከል ሃያ ያህል ሰው ነበረ።'),
  ('1c5c1ec3-f84d-5ff2-a64c-52a40fce4f47', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', '72c91126-70c9-5578-aa1b-857659105cae', 15, 15, 'በሰፈሩና በእርሻውም ድንጋጤ ሆነ፤ በሰፈሩ የተቀመጡ ሕዝብና የሚዋጉትም ሁሉ ተሸበሩ፤ መዋጋትም አልቻሉም፤ ምድሪቱም ተናወጠች፤ ከእግዚአብሔርም ዘንድ ታላቅ ድንጋጤ መጣ።'),
  ('292deaf7-6912-5927-a8ee-86bf306047fa', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', '64880f46-d962-545e-af26-b29fe5faed6f', 1, 16, 'በብንያም ገባዖን ያሉ የሳኦል ዘበኞችም ተመለከቱ፤ እነሆም፥ ሠራዊቱ ወዲህና ወዲያ እየተራወጡ ተበታተኑ።'),
  ('a7443c90-c198-568f-a6fb-92a1897265b0', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', '64880f46-d962-545e-af26-b29fe5faed6f', 2, 17, 'ሳኦልም ከእርሱ ጋር የነበሩትን ሕዝብ፥ “እስኪ ተቋጠሩ፤ ከእኛ ዘንድ የሄደ ማን እንደ ሆነ ተመልከቱ” አላቸው። በተቋጠሩም ጊዜ እነሆ፥ ዮናታንና ጋሻ ጃግሬው በዚያ አልተገኙም።'),
  ('fe5bb208-b8fd-5e90-a6ee-710dd2348e08', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', '64880f46-d962-545e-af26-b29fe5faed6f', 3, 18, 'በዚያም ቀን አኪያ በእስራኤል ልጆች ፊት ኤፉድ ይለብስ ነበርና ሳኦል፥ “ኤፉድን አምጣ” አለው።'),
  ('a70876b5-0416-57fc-adb2-c159c9384135', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', '64880f46-d962-545e-af26-b29fe5faed6f', 4, 19, 'ሳኦልም ከካህኑ ጋር ሲነጋገር በፍልስጥኤማውያን መንደር ግርግርታ እየበዛ ሄደ፤ ሳኦልም ካህኑን፥ “እጅህን መልስ” አለው።'),
  ('c7bc541d-ed04-5767-a266-134123f98edf', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', '64880f46-d962-545e-af26-b29fe5faed6f', 5, 20, 'ሳኦልና ከእርሱም ጋር የነበሩት ሕዝብ ሁሉ ተሰብስበው ወደ ውጊያው መጡ፤ እነሆም፥ የእያንዳንዱ ሰው ሰይፍ በባልንጀራው ላይ ነበረ፤ እጅግም ታላቅ ሽብር ሆነ።'),
  ('065d9222-2ec0-53db-af9c-6106f6a2db59', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', '64880f46-d962-545e-af26-b29fe5faed6f', 6, 21, 'ቀድሞ ከፍልስጥኤማውያን ጋር የነበሩና ወደ ሠራዊቱ የወጡ አገልጋዮችም ከሳኦልና ከዮናታን ጋር ወደ ነበሩ እስራኤላውያን ለመሆን ተመለሱ።'),
  ('ce8d91ec-d728-506b-a59d-8dc3658f7650', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', '64880f46-d962-545e-af26-b29fe5faed6f', 7, 22, 'በተራራማውም በኤፍሬም ሀገር የተሸሸጉት እስራኤል ሁሉ ፍልስጥኤማውያን እንደ ሸሹ በሰሙ ጊዜ እነርሱ ደግሞ ሊዋጉአቸው ተከተሉአቸው።'),
  ('abc7e435-145b-550e-a782-b0651afc8b94', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', '64880f46-d962-545e-af26-b29fe5faed6f', 8, 23, 'እግዚአብሔርም በዚያ ቀን እስራኤልን አዳነ፤ ውጊያውም በባሞት በኩል አለፈ። ከሳኦልም ጋር የነበሩ ሕዝብ ሁሉ ዐሥር ሺህ የሚያህሉ ሰዎች ነበሩ፤ ውጊያውም በተራራማው በኤፍሬም ከተማ ሁሉ ተበታትኖ ነበር።'),
  ('8c859a34-7884-5763-ac4e-739d532e34ab', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', 'b98b6c8e-d183-5906-ac1a-e72ba6717e34', 1, 24, 'ሳኦልም በዚያ ቀን ትልቅ በደል ፈጸመ፤ “ጠላቶቼን እስክበቀል እስከ ማታ ድረስ መብል የሚበላ ሰው ርጉም ይሁን” ብሎ ሕዝቡን አምሎአቸው ነበርና። ሕዝቡም ሁሉ እህል አልቀመሱም። ሀገሩም ሁሉ ምሳ አልበላም።'),
  ('aa98d7d0-71c7-5c73-a1c4-b2a582129fd2', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', 'b98b6c8e-d183-5906-ac1a-e72ba6717e34', 2, 25, 'ብዙ ንብ ያለበት የማር ቀፎም በዱሩ ይታይ ነበር።'),
  ('8e16ffbc-7fb3-5397-a85c-5b54266d2c68', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', 'b98b6c8e-d183-5906-ac1a-e72ba6717e34', 3, 26, 'ሕዝቡም ማር ወደ አለበት ቀፎ ሄዱ፤ እርስ በርሳቸውም ይነጋገሩ ነበር። እነሆም፥ ሕዝቡ መሐላውን ፈርቶ ነበርና ማንም እጁን አንሥቶ ወደ አፉ አላደረገም።'),
  ('6ecc02dc-1981-55c1-ad4f-95a0d6cc5a4f', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', 'b98b6c8e-d183-5906-ac1a-e72ba6717e34', 4, 27, 'ዮናታን ግን አባቱ ሕዝቡን ባማለ ጊዜ አልሰማም ነበር፤ እርሱም በእጁ ያለችውን በትር አንሥቶ ጫፍዋን ወደ ወለላው ነከረ፤ እጁንም ወደ አፉ አደረገ፤ ዐይኑም በራ።'),
  ('318c5500-191d-5c08-ae89-762fe241fa5c', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', 'b98b6c8e-d183-5906-ac1a-e72ba6717e34', 5, 28, 'ከሕዝቡም አንድ ሰው መልሶ፥ “አባትህ፦ ዛሬ መብል የሚበላ ሰው ርጉም ይሁን ብሎ ሕዝቡን መሐላ አምሎአቸዋል” አለው፤ ሕዝቡም ደከሙ።'),
  ('34f0c260-f478-55a4-aa6e-298bf1ae6d21', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', 'b98b6c8e-d183-5906-ac1a-e72ba6717e34', 6, 29, 'ዮናታንም “አባቴ ምድሪቱን አስቸገረ፤ ከዚህ ማር ጥቂት ብቀምስ ዐይኔ እንደ በራ እዩ፤'),
  ('6dd506a0-1f02-5079-a744-9ff90379101b', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', 'b98b6c8e-d183-5906-ac1a-e72ba6717e34', 7, 30, 'ይልቅስ ሕዝቡ ካገኙት ከጠላቶቻቸው ምርኮ በልተው ቢሆን ኑሮ የፍልስጥኤማውያን መመታት ይበልጥ አልነበረምን?” አለ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('adb16c08-d8fc-58b4-a676-2f158a0f51c7', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', 'b98b6c8e-d183-5906-ac1a-e72ba6717e34', 8, 31, 'በዚያም ቀን ፍልስጥኤማውያንን በማኪማስ መቱአቸው፤ ሕዝቡም እጅግ ደከሙ።'),
  ('89f97fb0-5c93-5cd5-aa2b-8c88b9223685', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', 'b98b6c8e-d183-5906-ac1a-e72ba6717e34', 9, 32, 'ሕዝቡም ወደ ምርኮ ሄዱ፤ በጎችን፥ በሬዎችንም፥ ጥጆችንም ወስደው እንዳገኙ በምድር ላይ አረዱ፤ ሕዝቡም ከደሙ ጋር በሉ።'),
  ('2d172c60-0811-564f-a0ba-765ccd75a578', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', 'b98b6c8e-d183-5906-ac1a-e72ba6717e34', 10, 33, 'ለሳኦልም፥ “እነሆ፥ ሕዝቡ ከደሙ ጋር በመብላታቸው እግዚአብሔርን በደሉ” ብለው ነገሩት። ሳኦልም በጌቴም “ትልቅ ድንጋይ አንከባልላችሁ አቅርቡልኝ” አላቸው።'),
  ('242b3d4f-b6e9-5f3d-ab4a-63d0d019c41e', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', 'b98b6c8e-d183-5906-ac1a-e72ba6717e34', 11, 34, 'ሳኦልም፥ “በሕዝቡ መካከል እየዞራችሁ፦ እያንዳንዱ ሰው በሬውንና በጉን ወደ እኔ ያቅርብ፥ በዚህም እረዱና ብሉ፤ ከደሙም ጋር በመብላታችሁ እግዚአብሔርን አትበድሉ” በሉአቸው አለ። እያንዳንዱም ሰው ሁሉ በእጁ ያለውን በዚያች ሌሊት አቀረበ፤ በዚያም አረደው።'),
  ('af8ea0af-9afb-55b1-a73d-becfb565ecd5', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', 'b98b6c8e-d183-5906-ac1a-e72ba6717e34', 12, 35, 'ሳኦልም በዚያ ለእግዚአብሔር መሠዊያን ሠራ፤ ይኸውም ሳኦል ለእግዚአብሔር የሠራው የመጀመሪያ መሠዊያ ነው።'),
  ('b89cfe9e-7144-55d7-adf2-105fff21ee8b', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', 'b98b6c8e-d183-5906-ac1a-e72ba6717e34', 13, 36, 'ሳኦልም፥ “ፍልስጥኤማውያንን በሌሊት ተከትለን እንውረድ፤ እስኪነጋም ድረስ እንበዝብዛቸው፤ አንድ ሰው እንኳ አናስቀርላቸው” አለ። እነርሱም፥ “ደስ የሚያሰኝህን ሁሉ አድርግ” አሉት። ካህኑም፥ “ወደ እግዚአብሔር እንቅረብ” አለ።'),
  ('8a7b407b-d34f-58f0-a7da-92ef4759b1b1', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', 'b98b6c8e-d183-5906-ac1a-e72ba6717e34', 14, 37, 'ሳኦልም፥ “ልውረድና ፍልስጥኤማውያንን ልከተልን? በእስራኤልስ እጅ አሳልፈህ ትሰጣቸዋለህን?” ብሎ እግዚአብሔርን ጠየቀው። በዚያ ቀን ግን እግዚአብሔር አልመለሰለትም።'),
  ('6e6e2b63-e1fa-5b27-adb0-c8708a878db0', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', 'b98b6c8e-d183-5906-ac1a-e72ba6717e34', 15, 38, 'ሳኦልም፥ “እናንተ የእስራኤል አለቆችን ሁሉ ወደዚህ አቅርቡ፤ ዛሬ ይህ ኀጢኣት በማን እንደ ሆነ ዕወቁ፤ ተመልከቱም፤'),
  ('12a210ce-9b11-53b2-a3de-e33fa16f6b28', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', 'b98b6c8e-d183-5906-ac1a-e72ba6717e34', 16, 39, 'እስራኤልን የሚያድን ሕያው እግዚአብሔርን! ኀጢኣቱ በልጄ በዮናታን ቢሆን ፈጽሞ ይሞታል” አለ። ከሕዝቡም ሁሉ አንድ የመለሰለት ሰው አልነበረም።'),
  ('a04358b4-c074-5178-a5ca-e14996da7e28', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', 'b98b6c8e-d183-5906-ac1a-e72ba6717e34', 17, 40, 'እስራኤልንም ሁሉ፥ “እናንተ አንድ ወገን ትሆናላችሁ፤ እኔና ልጄ ዮናታንም አንድ ወገን እንሆናለን” አለ። ሕዝቡም ሳኦልን፥ “ደስ የሚያሰኝህን አድርግ” አሉት።'),
  ('32e99180-5867-54b8-a057-737762c2f3b1', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', 'b98b6c8e-d183-5906-ac1a-e72ba6717e34', 18, 41, 'ሳኦልም እግዚአብሔርን፥ “የእስራኤል አምላክ ሆይ፥ ለእኔ ለባሪያህ ዛሬ ያልመለስህልኝ ስለ ምንድን ነው? ይህች በደል በእኔ፥ በልጄ በዮናታንም እንደ ሆነች አቤቱ የእስራኤል አምላክ ሆይ፥ ተናገር። ዕጣው ይህን የሚገልጥ ከሆነ ለሕዝብህ ለእስራኤል እውነትን ግለጥ፥” አለ። ዕጣም በዮናታንና በሳኦል ላይ ወጣ፤ ሕዝቡም ነፃ ወጣ።'),
  ('0e041953-0de5-5d0c-a4f6-5c7df6e87b02', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', 'b98b6c8e-d183-5906-ac1a-e72ba6717e34', 19, 42, 'ሳኦልም፥ “በእኔና በዮናታን መካከል ዕጣ አጣጥሉን፤ እግዚአብሔር ዕጣ ያወጣበትም ይሞታል” አላቸው። ሕዝቡም ሳኦልን፥ “እንዲህ ያለ ነገር አይሆንም” አሉት፤ ሳኦልም ሕዝቡን እንቢ አላቸው። በእርሱና በልጁ በዮናታን መካከልም ዕጣ አጣጣሉ። ዕጣውም በልጁ በዮናታን ላይ ወጣ።'),
  ('2a77ae5c-4739-557f-a145-9f18f62ad858', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', 'b98b6c8e-d183-5906-ac1a-e72ba6717e34', 20, 43, 'ሳኦልም ዮናታንን፥ “ያደረግኸውን ንገረኝ” አለው፤ ዮናታንም፥ “በእጄ ባለው በበትሬ ጫፍ ጥቂት ማር በርግጥ ቀምሻለሁ፤ እነሆኝ፥ እሞታለሁ” ብሎ ነገረው።'),
  ('847a8900-bc9a-5d0a-aa8c-70761617197b', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', 'b98b6c8e-d183-5906-ac1a-e72ba6717e34', 21, 44, 'ሳኦልም፥ “እግዚአብሔር እንዲህ ያድርግብኝ፤ እንዲህም ይጨምርብኝ፤ ዛሬ ፈጽመህ ትሞታለህ” አለ።'),
  ('a6faef1f-8ba6-566c-a18f-b60671ba3c14', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', 'b98b6c8e-d183-5906-ac1a-e72ba6717e34', 22, 45, 'ሕዝቡም ሳኦልን፥ “በውኑ በእስራኤል ዘንድ ታላቅ መድኀኒት ያደረገ ዮናታን ዛሬ ይሞታልን? ይህ አይሁን፤ ዛሬ ለሕዝቡ ከእግዚአብሔር ጋር አድርጎአልና ሕያው እግዚአብሔርን! ከራሱ ጠጕር አንዲት በምድር ላይ አትወድቅም” አሉት። ሕዝቡም ያን ጊዜ ስለ ዮናታን ጸለዩ፤ እርሱም አልተገደለም።'),
  ('e96b2c09-6942-563a-a1fd-d2fb03a24230', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', 'b98b6c8e-d183-5906-ac1a-e72ba6717e34', 23, 46, 'ሳኦልም ፍልስጥኤማውያንን ከመከተል ተመለሰ፤ ፍልስጥኤማውያንም ወደ ስፍራቸው ሄዱ።'),
  ('c1cc6179-caf7-5a2c-a74b-600193bf4721', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', '065dc63e-050c-5b26-a5bb-b775da52cb7a', 1, 47, 'ሳኦልም መንግሥቱን በእስራኤል ላይ አጸና፤ በዙሪያውም ካሉት ከጠላቶቹ ሁሉ ጋር፥ ከሞዓብም፥ ከአሞንም ልጆች፥ ከኤዶምያስም፥ ከቢዖርም፥ ከሱባም ነገሥታት፥ ከፍልስጥኤማውያንም ሁሉ ጋር ይዋጋ ነበር፤ በየሄደበትም ሁሉ ድል ይነሣ ነበር።'),
  ('56892055-55c7-5c03-a47f-a90e98aac777', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', '065dc63e-050c-5b26-a5bb-b775da52cb7a', 2, 48, 'እርሱም ጀግና ነበረ፤ አማሌቃውያንንም መታ፤ እስራኤልንም ከዘራፊዎቹ እጅ አዳነ።'),
  ('7b1f34c0-fe79-51fe-ac57-b01f8428906e', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', '065dc63e-050c-5b26-a5bb-b775da52cb7a', 3, 49, 'የሳኦልም ወንዶች ልጆች ዮናታን፥ የሱዊ፥ ሚልኪሳ ነበሩ፤ የሁለቱም ሴቶች ልጆቹ ስም ይህ ነበረ፤ የታላቂቱ ስም ሜሮብ፥ የታናሺቱም ስም ሜልኮል ነበረ።'),
  ('5182aeb3-cc34-5d89-aaa7-c41af628b84d', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', '065dc63e-050c-5b26-a5bb-b775da52cb7a', 4, 50, 'የሳኦልም ሚስት ስም የአኪማኦስ ልጅ አኪናሆም ነበረች፤ የሠራዊቱም አለቃ ስም የሳኦል አጎት የኔር ልጅ አቤኔር ነበረ።'),
  ('17e608f5-5641-55d3-aadd-1bdf4373be38', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', '065dc63e-050c-5b26-a5bb-b775da52cb7a', 5, 51, 'የሳኦልም አባት ቂስ ነበረ፤ የአቤኔርም አባት የአብኤል ልጅ የያሚን ልጅ ኔር ነበረ።'),
  ('19116eda-0724-5bae-a379-70ff134e7174', '446ade46-1dd1-5c7c-a7ef-d6ff333504b8', '065dc63e-050c-5b26-a5bb-b775da52cb7a', 6, 52, 'በሳኦልም ዘመን ሁሉ ከፍልስጥኤማውያን ጋር ጽኑ ውጊያ ነበረ፤ ሳኦልም ጽኑ ወይም ኀያል ሰው ባየ ጊዜ ወደ እርሱ ይሰበስብ ነበር።'),
  ('9a1ac2fb-2b16-507c-af69-88bde502b62a', '0eed681a-dcd4-5df1-a90c-b9a0bea5bf22', '45e0b0a1-309e-5289-a0bb-2bb0bd373fc3', 1, 1, 'ሳሙኤልም ሳኦልን አለው፥ “በእስራኤል ላይ ንጉሥ እንድትሆን እቀባህ ዘንድ እግዚአብሔር ላከኝ፤ አሁንም የእግዚአብሔርን ቃል ስማ።'),
  ('914f9f71-acf3-5694-a88f-ef3d76d8a346', '0eed681a-dcd4-5df1-a90c-b9a0bea5bf22', '45e0b0a1-309e-5289-a0bb-2bb0bd373fc3', 2, 2, 'የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ እስራኤል ከግብፅ በወጡ ጊዜ በመንገድ እንደ ተዋጉ በእስራኤል ላይ ክፉ ያደረጉትን አማሌቃውያንን ዛሬ እበቀላለሁ።'),
  ('c388a838-83df-5250-ae0a-f8eb629ba497', '0eed681a-dcd4-5df1-a90c-b9a0bea5bf22', '45e0b0a1-309e-5289-a0bb-2bb0bd373fc3', 3, 3, 'አሁንም ሄደህ አማሌቅንና ኢያሬምን ምታ፤ ያላቸውንም ሁሉ ፈጽመህ አጥፋ፤ ከእነርሱም የምታድነው የለም። አጥፋቸው፤ መከራም አጽናባቸው፤ የእነርሱ የሆነውን ሁሉ አጥፋ፤ ለያቸውም፤ አትማራቸውም፤ ወንዱንና ሴቱን፥ ብላቴናውንና ሕፃኑን፥ በሬውንና በጉን፥ ግመሉንና አህያውን ግደል።”'),
  ('4a0ffce3-7df6-58d5-a7c2-e3d56c230b44', '0eed681a-dcd4-5df1-a90c-b9a0bea5bf22', '45e0b0a1-309e-5289-a0bb-2bb0bd373fc3', 4, 4, 'ሳኦልም ሕዝቡን ጠርቶ በጌልጌላ ቈጠራቸው፤ አራት መቶ ሺህ እግረኞች፥ ከይሁዳም ሠላሳ ሺህ ሰዎች ነበሩ።'),
  ('b9c581bb-20da-574f-af4a-35664309afa9', '0eed681a-dcd4-5df1-a90c-b9a0bea5bf22', '45e0b0a1-309e-5289-a0bb-2bb0bd373fc3', 5, 5, 'ሳኦልም ወደ አማሌቅ ከተማ ወጣ፤ በሸለቆውም ውስጥ ተደበቀ።'),
  ('6013422d-be63-5612-a8e1-ddb13adff7ae', '0eed681a-dcd4-5df1-a90c-b9a0bea5bf22', '45e0b0a1-309e-5289-a0bb-2bb0bd373fc3', 6, 6, 'ሳኦልም ቄኔዎናውያንን፥ “ከእነርሱ ጋር እንዳላጠፋችሁ ከአማሌቃውያን መካከል ተነሥታችሁ ሂዱ፤ ከግብፅ በወጡ ጊዜ ለእስራኤል ልጆች ቸርነት አድርጋችኋልና” አላቸው። ቄኔዎናውያንም ከአማሌቃውያን መካከል ወጡ።'),
  ('adeaad2a-5fff-593a-a64d-d559c475e342', '0eed681a-dcd4-5df1-a90c-b9a0bea5bf22', '45e0b0a1-309e-5289-a0bb-2bb0bd373fc3', 7, 7, 'ሳኦልም አማሌቃውያንን ከኤውላጥ ጀምሮ በግብፅ ፊት እስካለችው እስከ ሱር ድረስ መታቸው።'),
  ('4ef04066-e85b-572d-a8b1-39cc6414786a', '0eed681a-dcd4-5df1-a90c-b9a0bea5bf22', '45e0b0a1-309e-5289-a0bb-2bb0bd373fc3', 8, 8, 'የአማሌቅንም ንጉሥ አጋግን በሕይወቱ ማረከው፤ የኢያሬምንም ሕዝብ ሁሉ በሰይፍ ስለት ፈጽሞ አጠፋቸው።'),
  ('17ea94e5-36f3-5ba9-ada5-f871ff3f0b8d', '0eed681a-dcd4-5df1-a90c-b9a0bea5bf22', '45e0b0a1-309e-5289-a0bb-2bb0bd373fc3', 9, 9, 'ነገር ግን ሳኦልና ሕዝቡ ሁሉ አጋግን፥ ከከብቱና ከበጉ መንጋ መልካም መልካሙን፥ እህሉንም፥ ወይኑንም፥ መልካም የሆነውን ሁሉ አዳኑ። ፈጽመው ሊያጠፉአቸውም አልወደዱም፤ ነገር ግን የተናቀውን ሁሉ ፈጽመው አጠፉት።'),
  ('cb49ee23-1e9d-5da3-a30d-8adae8ef2c6f', '0eed681a-dcd4-5df1-a90c-b9a0bea5bf22', 'e0deb981-8e79-5a30-a5fa-3d91c0cdd779', 1, 10, 'የእግዚአብሔርም ቃል ወደ ሳሙኤል መጣ፤ እንዲህም አለው፦'),
  ('7ac766ef-0d7f-543f-a492-f3ef8b2cc265', '0eed681a-dcd4-5df1-a90c-b9a0bea5bf22', 'e0deb981-8e79-5a30-a5fa-3d91c0cdd779', 2, 11, '“ሳኦል እኔን ከመከተል ተመልሶአልና፥ ትእዛዜንም አልፈጸመምና ስላነገሥሁት ተጸጸትሁ።” ሳሙኤልም አዘነ። ሌሊቱንም ሁሉ ወደ እግዚአብሔር ጮኸ።'),
  ('06030cc5-9e13-539d-a177-b6c7508f2bfd', '0eed681a-dcd4-5df1-a90c-b9a0bea5bf22', 'e0deb981-8e79-5a30-a5fa-3d91c0cdd779', 3, 12, 'ሳሙኤልም እስራኤልን ለመገናኘት በጥዋት ገሥግሦ ሄደ። ለሳሙኤልም፥ “ሳኦል ወደ ቀርሜሎስ መጣ፤ እነሆም፥ ለራሱ የመታሰቢያ ዐምድ አቆመ” ብለው ነገሩት። ሳሙኤልም ሰረገላውን መልሶ ወደ ጌልጌላ ወደ ሳኦል ወረደ፤ ከአማሌቅ ዘንድ ከአመጣውም ከአማረው ከምርኮው መንጋ ለእግዚአብሔር የሚቃጠል መሥዋዕት ሲሠዋ አገኘው፤'),
  ('675852e7-0cbe-5af2-a01b-a6fa54309888', '0eed681a-dcd4-5df1-a90c-b9a0bea5bf22', 'e0deb981-8e79-5a30-a5fa-3d91c0cdd779', 4, 13, 'ሳሙኤልም ወደ ሳኦል መጣ፤ ሳኦልም፥ “አንተ ለእግዚአብሔር የተባረክህ ሁን፤ እግዚአብሔር ያዘዘውን ሁሉ ፈጽሜአለሁ” አለው።'),
  ('6154f27b-513a-5354-af0c-8811a4509257', '0eed681a-dcd4-5df1-a90c-b9a0bea5bf22', 'e0deb981-8e79-5a30-a5fa-3d91c0cdd779', 5, 14, 'ሳሙኤልም፥ “ይህ በጆሮዬ የምሰማው የበጎች ጩኸትና የበሬዎች ግሣት ምንድር ነው?” አለ።'),
  ('b412fa33-66f0-530c-a73c-eec1cdffaec0', '0eed681a-dcd4-5df1-a90c-b9a0bea5bf22', 'e0deb981-8e79-5a30-a5fa-3d91c0cdd779', 6, 15, 'ሳኦልም፦“ሕዝቡ ለአምላክህ ለእግዚአብሔር ይሠዉአቸው ዘንድ ከበጎችና ከላሞች መንጋዎች መልካም መልካሙን አድነዋቸዋልና ከአማሌቃውያን አመጣን፤ የቀሩትንም ፈጽሜ አጠፋሁ” አለው።'),
  ('b97072e7-cf98-547c-a4f4-38ca45c750ea', '0eed681a-dcd4-5df1-a90c-b9a0bea5bf22', 'e0deb981-8e79-5a30-a5fa-3d91c0cdd779', 7, 16, 'ሳሙኤልም ሳኦልን፥ “ስማ፤ እግዚአብሔር ዛሬ ሌሊት የነገረኝን ልንገርህ” አለው፤ እርሱም፥ “ተናገር” አለው።'),
  ('2219f489-57ed-52f3-a6ef-564de9ad5eda', '0eed681a-dcd4-5df1-a90c-b9a0bea5bf22', 'e0deb981-8e79-5a30-a5fa-3d91c0cdd779', 8, 17, 'ሳሙኤልም ሳኦልን አለው፥ “በፊቱ ምንም ታናሽ ብትሆን ለእስራኤል ነገዶች አለቃ አልሆንህምን? እግዚአብሔርም በእስራኤል ላይ ንጉሥ ትሆን ዘንድ ቀባህ።'),
  ('e3a96cab-e862-53ad-a6ef-7823e0f878a2', '0eed681a-dcd4-5df1-a90c-b9a0bea5bf22', 'e0deb981-8e79-5a30-a5fa-3d91c0cdd779', 9, 18, 'እግዚአብሔርም፦ ሄደህ ኀጢኣተኞቹን አማሌቃውያንን ፈጽመህ አጥፋቸው፤ እስኪጠፉም ድረስ ውጋቸው ብሎ በመንገድ ላከህ።'),
  ('dc51b5d8-5dd7-5082-aef7-5b178bb05400', '0eed681a-dcd4-5df1-a90c-b9a0bea5bf22', 'e0deb981-8e79-5a30-a5fa-3d91c0cdd779', 10, 19, 'ለምርኮ ሳስተህ ለምን የእግዚአብሔርን ቃል አልሰማህም? ለምንስ በእግዚአብሔር ፊት ክፉ አደረግህ?”'),
  ('2e1b0126-5b77-58dc-ac15-add76a0adb32', '0eed681a-dcd4-5df1-a90c-b9a0bea5bf22', 'e0deb981-8e79-5a30-a5fa-3d91c0cdd779', 11, 20, 'ሳኦልም ሳሙኤልን፥ “የእግዚአብሔርን ቃል ስለሰማሁ፥ እግዚአብሔር በላከኝ መንገድ ሄጃለሁ፤ የአማሌቅን ንጉሥ አጋግንም አምጥቻለሁ፤ አማሌቃውያንንም ፈጽሜ አጥፍቻለሁ።'),
  ('c167ea43-2cf7-5378-a207-694703dcdc5e', '0eed681a-dcd4-5df1-a90c-b9a0bea5bf22', 'e0deb981-8e79-5a30-a5fa-3d91c0cdd779', 12, 21, 'ሕዝቡ ግን ለአምላካችን ለእግዚአብሔር በጌልጌላ ይሠዉ ዘንድ ከእርሙ የተመረጡትን በጎችና በሬዎች ከምርኮው ወሰዱ” አለው።'),
  ('7ce52bbe-5fe9-5ba9-a8b6-a4196caf5c9f', '0eed681a-dcd4-5df1-a90c-b9a0bea5bf22', 'e0deb981-8e79-5a30-a5fa-3d91c0cdd779', 13, 22, 'ሳሙኤልም ሳኦልን፥ “በውኑ የእግዚአብሔርን ቃል በመስማት ደስ እንደሚለው እግዚአብሔር በሚቃጠልና በሚታረድ መሥዋዕት ደስ ይለዋልን? እነሆ፥ መታዘዝ ከመሥዋዕት፥ ማዳመጥም የአውራ በግ ስብ ከማቅረብ ይበልጣል።'),
  ('d1fdd42d-42e3-5cbd-a913-b98dd3ecdace', '0eed681a-dcd4-5df1-a90c-b9a0bea5bf22', 'e0deb981-8e79-5a30-a5fa-3d91c0cdd779', 14, 23, 'ኀጢኣት እንደ ምዋርተኝነት ናትና አምልኮተ ጣዖትም ደዌንና ኀዘንን ያመጣል። የእግዚአብሔርን ቃል ንቀሃልና እግዚአብሔር ንጉሥ እንዳትሆን ናቀህ” አለው።'),
  ('3f0bf652-1286-5163-ac39-313acda8576b', '0eed681a-dcd4-5df1-a90c-b9a0bea5bf22', 'e0deb981-8e79-5a30-a5fa-3d91c0cdd779', 15, 24, 'ሳኦልም ሳሙኤልን፥ “ሕዝቡን ስለ ፈራሁ፥ ቃላቸውንም ስለ ሰማሁ የእግዚአብሔርን ትእዛዝና የአንተን ቃል በመተላለፍ በድያለሁ።'),
  ('8c36abd1-7857-59bb-ac2e-a27f6927277d', '0eed681a-dcd4-5df1-a90c-b9a0bea5bf22', 'e0deb981-8e79-5a30-a5fa-3d91c0cdd779', 16, 25, 'አሁንም እባክህ ኀጢኣቴን ይቅር በለኝ፤ ለእግዚአብሔርም እሰግድ ዘንድ ከእኔ ጋር ተመለስ” አለው።'),
  ('6214633e-4899-5a1f-ad06-eaf21ee1671c', '0eed681a-dcd4-5df1-a90c-b9a0bea5bf22', 'e0deb981-8e79-5a30-a5fa-3d91c0cdd779', 17, 26, 'ሳሙኤልም ሳኦልን፥ “የእግዚአብሔርን ቃል ንቀሃልና፥ እግዚአብሔርም በእስራኤል ላይ ንጉሥ እንዳትሆን ንቆሃልና ከአንተ ጋር አልመለስም” አለው።'),
  ('f7c09b6f-2b42-54e9-a577-c60bbcc0376e', '0eed681a-dcd4-5df1-a90c-b9a0bea5bf22', 'e0deb981-8e79-5a30-a5fa-3d91c0cdd779', 18, 27, 'ሳሙኤልም ሊሄድ ዘወር ባለ ጊዜ ሳኦል የልብሱን ጫፍ ያዘ፤ ተቀደደም።'),
  ('6348822c-0841-5ea8-ac27-e1888be8ff34', '0eed681a-dcd4-5df1-a90c-b9a0bea5bf22', 'e0deb981-8e79-5a30-a5fa-3d91c0cdd779', 19, 28, 'ሳሙኤልም፥ “እግዚአብሔር ከእስራኤል መንግሥትህን ዛሬ ከእጅህ ቀደዳት፤ ከአንተም ለሚሻል ለባልንጀራህ አሳልፎ ሰጣት፤'),
  ('b8a05240-1a44-5dbb-a6eb-c463c964d49c', '0eed681a-dcd4-5df1-a90c-b9a0bea5bf22', 'e0deb981-8e79-5a30-a5fa-3d91c0cdd779', 20, 29, 'እስራኤል ለሁለት ይከፈላል፤ ከእንግዲህም አይሰበሰብም፤ እግዚአብሔርም እንደ ሰው የሚጸጸት አይደለምና አይጸጸትም” አለው።'),
  ('2c22966a-ab6d-5413-aeaa-252b9274acee', '0eed681a-dcd4-5df1-a90c-b9a0bea5bf22', 'e0deb981-8e79-5a30-a5fa-3d91c0cdd779', 21, 30, 'ሳኦልም፥ “በድያለሁ፤ አሁንም በሕዝቤ ሽማግሌዎች ፊትና በእስራኤል ፊት እባክህ አክብረኝ፤ ለአምላክህም ለእግዚአብሔር እሰግድ ዘንድ ከእኔ ጋር ተመለስ” አለው።'),
  ('5b1721ed-acfd-5965-a181-29ca42fdb1b6', '0eed681a-dcd4-5df1-a90c-b9a0bea5bf22', 'e0deb981-8e79-5a30-a5fa-3d91c0cdd779', 22, 31, 'ሳሙኤልም ከሳኦል በኋላ ተመለሰ፤ ሳኦልም ለእግዚአብሔር ሰገደ።'),
  ('16cc4f8a-52b2-5d3d-aee5-79bc597d14fc', '0eed681a-dcd4-5df1-a90c-b9a0bea5bf22', 'e0deb981-8e79-5a30-a5fa-3d91c0cdd779', 23, 32, 'ሳሙኤልም፥ “የአማሌቅን ንጉሥ አጋግን አምጡልኝ” አለ። አጋግም እየተንቀጠቀጠ ወደ እርሱ መጣ። አጋግም፥ “በውኑ ሞት እንደዚህ መራራ ነውን?” አለ።'),
  ('1d76f74c-ffc7-508e-a5b4-1a1735063806', '0eed681a-dcd4-5df1-a90c-b9a0bea5bf22', 'e0deb981-8e79-5a30-a5fa-3d91c0cdd779', 24, 33, 'ሳሙኤልም አጋግን፥ “ሰይፍህ ሴቶችን ልጆች አልባ እንዳደረገቻቸው እንዲሁ እናትህ በሴቶች መካከል ልጅ አልባ ትሆናለች” አለ፥ ሳሙኤልም አጋግን በእግዚአብሔር ፊት በጌልጌላ ወጋው።'),
  ('4fba5a35-95e6-5fac-a471-4608cc0fcb91', '0eed681a-dcd4-5df1-a90c-b9a0bea5bf22', 'e0deb981-8e79-5a30-a5fa-3d91c0cdd779', 25, 34, 'ሳሙኤልም ወደ አርማቴም ሄደ፤ ሳኦልም ወደ ቤቱ ወደ ገባዖን ወጣ።'),
  ('cfc958e0-d5c4-53a4-a95c-3a3a0236b786', '0eed681a-dcd4-5df1-a90c-b9a0bea5bf22', 'e0deb981-8e79-5a30-a5fa-3d91c0cdd779', 26, 35, 'ሳሙኤልም እስከ ሞተበት ቀን ድረስ ሳኦልን ለማየት ዳግመኛ አልሄደም፤ ሳሙኤልም ለሳኦል አለቀሰ፤ እግዚአብሔርም በእስራኤል ላይ ሳኦልን ስላነገሠ ተጸጸተ።'),
  ('a79bac0d-35ea-5d67-a335-ac9118e8f2af', '7ededb23-c05b-50d9-ac1c-784ced8e94ab', '3b44a2fa-5212-53af-ab34-0ae52a2512bd', 1, 1, 'እግዚአብሔርም ሳሙኤልን፥ “በእስራኤል ላይ እንዳይነግሥ ለናቅሁት ለሳኦል የምታለቅስለት እስከ መቼ ነው? የዘይቱን ቀንድ ሞልተህ ና፤ በልጆቹ መካከል ለእኔ ንጉሥ አዘጋጅቼአለሁና ወደ እሴይ ወደ ቤተ ልሔም እልክሃለሁ” አለው።'),
  ('e66caa82-fd72-5e03-a9b4-c3a96517630b', '7ededb23-c05b-50d9-ac1c-784ced8e94ab', '3b44a2fa-5212-53af-ab34-0ae52a2512bd', 2, 2, 'ሳሙኤልም፥ “እንዴት እሄዳለሁ? ሳኦል ቢሰማ ይገድለኛል” አለ። እግዚአብሔርም፥ “አንዲት ጊደር ይዘህ ሂድና፦ ‘ለእግዚአብሔር እሠዋ ዘንድ መጣሁ’ በል።'),
  ('1246906b-e24c-5440-afd2-67619ee073ed', '7ededb23-c05b-50d9-ac1c-784ced8e94ab', '3b44a2fa-5212-53af-ab34-0ae52a2512bd', 3, 3, 'እሴይንም ወደ መሥዋዕቱ ጥራው፥ የምታደርገውንም አስታውቅሃለሁ፤ የምነግርህንም ቅባው” አለው።'),
  ('5d910a69-e6ff-5689-aca1-e1ea63a7a251', '7ededb23-c05b-50d9-ac1c-784ced8e94ab', '3b44a2fa-5212-53af-ab34-0ae52a2512bd', 4, 4, 'ሳሙኤልም እግዚአብሔር የተናገረውን አደረገ፤ ወደ ቤተ ልሔምም መጣ። የከተማውም ሽማግሌዎች በተገናኙት ጊዜ ደነገጡ፥ “ነቢይ! የመጣኸው ለሰላም ነውን?” አሉት።'),
  ('8a90ebe2-63d2-5751-a235-152ff5441dfd', '7ededb23-c05b-50d9-ac1c-784ced8e94ab', '3b44a2fa-5212-53af-ab34-0ae52a2512bd', 5, 5, 'እርሱም፥ “ለሰላም ነው፤ ለእግዚአብሔር እሠዋ ዘንድ መጣሁ፤ ቅዱሳን ሁኑ፤ ከእኔም ጋር ዛሬ ደስ ይበላችሁ፤ ከእኔም ጋር ወደ መሥዋዕቱ ኑ” አለ። እሴይንና ልጆቹንም ቀደሳቸው፤ ወደ መሥዋዕቱም ጠራቸው።'),
  ('621ea976-feb9-5c54-ad80-f298cafa594a', '7ededb23-c05b-50d9-ac1c-784ced8e94ab', '3b44a2fa-5212-53af-ab34-0ae52a2512bd', 6, 6, 'እንዲህም ሆነ፤ በመጡ ጊዜ ወደ ኤልያብ ተመልክቶ፥ “በእውነት እግዚአብሔር የሚቀባው በፊቱ ነው” አለ።'),
  ('1877e9e6-4151-5396-ac8b-2661620b3b92', '7ededb23-c05b-50d9-ac1c-784ced8e94ab', '3b44a2fa-5212-53af-ab34-0ae52a2512bd', 7, 7, 'እግዚአብሔር ግን ሳሙኤልን፥ “ፊቱን፥ የቁመቱንም ዘለግታ አትይ፤ ሰው እንደሚያይ እግዚአብሔር አያይምና ናቅሁት፤ ሰው ፊትን ያያል፤ እግዚአብሔር ግን ልብን ያያል” አለው።'),
  ('6282f4f9-f23e-5fbe-a788-1182ea3da0a5', '7ededb23-c05b-50d9-ac1c-784ced8e94ab', '3b44a2fa-5212-53af-ab34-0ae52a2512bd', 8, 8, 'እሴይም አሚናዳብን ጠርቶ በሳሙኤል ፊት አሳለፈው፤ እርሱም፥ “ይህን ደግሞ እግዚአብሔር አልመረጠውም” አለ።'),
  ('7e1fd967-6240-5508-a671-48c56690932d', '7ededb23-c05b-50d9-ac1c-784ced8e94ab', '3b44a2fa-5212-53af-ab34-0ae52a2512bd', 9, 9, 'እሴይም ሣማዕን አሳለፈው፤ እርሱም፥ “ይህን ደግሞ እግዚአብሔር አልመረጠውም” አለ።'),
  ('67b31ff8-88ab-54cb-a164-82c4d3be4b03', '7ededb23-c05b-50d9-ac1c-784ced8e94ab', '3b44a2fa-5212-53af-ab34-0ae52a2512bd', 10, 10, 'እሴይም ከልጆቹ ሰባቱን በሳሙኤል ፊት አሳለፋቸው። ሳሙኤልም እሴይን፥ “እግዚአብሔር እነዚህን አልመረጠም” አለው።'),
  ('f1ebedae-9529-5969-a6d0-695ebee43cbe', '7ededb23-c05b-50d9-ac1c-784ced8e94ab', '3b44a2fa-5212-53af-ab34-0ae52a2512bd', 11, 11, 'ሳሙኤልም እሴይን፥ “ልጆችህ እኒህ ብቻ ናቸው?” አለው። እርሱም፥ “ታናሹ ገና ቀርቶአል፤ እነሆም፥ በጎችን ይጠብቃል” አለ። ሳሙኤልም እሴይን፥ “እርሱ እስኪመጣ ድረስ ለማዕድ አንቀመጥምና ልከህ አስመጣው” አለው።'),
  ('d2d8f24e-e2ec-5805-ad41-150b55cb32c2', '7ededb23-c05b-50d9-ac1c-784ced8e94ab', '3b44a2fa-5212-53af-ab34-0ae52a2512bd', 12, 12, 'ልኮም አስመጣው፤ እርሱም ቀይ፥ ዐይኑም የተዋበ፥ መልኩም ያማረ ነበረ። እግዚአብሔርም ሳሙኤልን፥ “ይህ መልካም ነውና ተነሥተህ ዳዊትን ቅባው” አለው።'),
  ('2a0505cc-5a9d-50d7-a67f-cfb7d6d78d98', '7ededb23-c05b-50d9-ac1c-784ced8e94ab', '3b44a2fa-5212-53af-ab34-0ae52a2512bd', 13, 13, 'ሳሙኤልም የዘይቱን ቀንድ ወስዶ በወንድሞቹ መካከል ቀባው። የእግዚአብሔርም መንፈስ ከዚያ ቀን ጀምሮ በዳዊት ላይ መጣ። ሳሙኤልም ተነሥቶ ወደ አርማቴም ሄደ።'),
  ('1547b58c-3c3d-540a-ab0f-8c2e40323963', '7ededb23-c05b-50d9-ac1c-784ced8e94ab', '3b44a2fa-5212-53af-ab34-0ae52a2512bd', 14, 14, 'የእግዚአብሔርም መንፈስ ከሳኦል ራቀ፤ ክፉም መንፈስ ከእግዚአብሔር ዘንድ አስጨነቀው።'),
  ('8d05f085-3aef-5207-a1aa-74e19a50ab0e', '7ededb23-c05b-50d9-ac1c-784ced8e94ab', '3b44a2fa-5212-53af-ab34-0ae52a2512bd', 15, 15, 'የሳኦልም ብላቴኖች፥ “እነሆ፥ ክፉ መንፈስ ከእግዚአብሔር ዘንድ ያስጨንቅሃል፤'),
  ('7a25aeee-34f7-5376-a5a3-b6e60be0fee7', '7ededb23-c05b-50d9-ac1c-784ced8e94ab', '3b44a2fa-5212-53af-ab34-0ae52a2512bd', 16, 16, 'አገልጋዮችህ በፊትህ ይናገሩ፤ በበገና የሚዘምር ሰውም ለጌታቸው ይፈልጉለት፤ ክፉ መንፈስም በመጣብህ ጊዜ በገናውን ሲመታ አንተ ደኅና ትሆናለህ፤ እርሱም ያሳርፍሃል” አሉት።'),
  ('efb8f5dd-4deb-54f4-af89-6a5f3e498f9a', '7ededb23-c05b-50d9-ac1c-784ced8e94ab', '3b44a2fa-5212-53af-ab34-0ae52a2512bd', 17, 17, 'ሳኦልም ብላቴኖቹን፥ “መልካም አድርጎ በገና መምታት የሚችል ሰው ፈልጋችሁ አምጡልኝ” አላቸው።'),
  ('9d63a5aa-0da5-5af8-a9b1-6523a7bdcce0', '7ededb23-c05b-50d9-ac1c-784ced8e94ab', '3b44a2fa-5212-53af-ab34-0ae52a2512bd', 18, 18, 'ከብላቴኖቹም አንዱ መልሶ፥ “እነሆ፥ መልካም አድርጎ በገና ሲመታ የቤተ ልሔሙን የእሴይን ልጅ አይቻለሁ፤ ሰውየውም ጠቢብ፥ ተዋጊም ነው፤ በነገርም ብልህ፥ መልኩም ያማረ ነው፤ እግዚአብሔርም ከእርሱ ጋር ነው” አለ።'),
  ('cd305b96-8ce2-5153-af77-2589b27ac252', '7ededb23-c05b-50d9-ac1c-784ced8e94ab', '3b44a2fa-5212-53af-ab34-0ae52a2512bd', 19, 19, 'ሳኦልም ወደ እሴይ መልእክተኞችን ልኮ፥ “ከመንጋዎችህ ጋር ያለውን ልጅህን ዳዊትን ላክልኝ” አለ።'),
  ('15e9e523-8cfb-58d9-a0b3-d8084abb628d', '7ededb23-c05b-50d9-ac1c-784ced8e94ab', '3b44a2fa-5212-53af-ab34-0ae52a2512bd', 20, 20, 'እሴይም እንጀራና የወይን ጠጅ አቁማዳ የተጫነ አህያ፥ አንድም የፍየል ጠቦት ወስዶ በልጁ በዳዊት እጅ ወደ ሳኦል ላከ።'),
  ('38a68506-94f3-594f-a474-09da6d02f619', '7ededb23-c05b-50d9-ac1c-784ced8e94ab', '3b44a2fa-5212-53af-ab34-0ae52a2512bd', 21, 21, 'ዳዊትም ወደ ሳኦል መጣ፤ በፊቱም ቆመ፤ እጅግም ወደደው፤ ለእርሱም ጋሻ ጃግሬው ሆነ።'),
  ('b6244c74-c6c8-5fdd-a99c-883bb81d67e9', '7ededb23-c05b-50d9-ac1c-784ced8e94ab', '3b44a2fa-5212-53af-ab34-0ae52a2512bd', 22, 22, 'ሳኦልም ወደ እሴይ፥ “በዐይኔ ሞገስ አግኝቶአልና ዳዊት በፊቴ እባክህ ይቁም፥” ብሎ ላከ።'),
  ('f20629f2-6361-588f-ad34-3e1bf74ea21a', '7ededb23-c05b-50d9-ac1c-784ced8e94ab', '3b44a2fa-5212-53af-ab34-0ae52a2512bd', 23, 23, 'እንዲህም ሆነ፤ ያ ክፉ መንፈስ በሳኦል ላይ በሆነ ጊዜ ዳዊት በገና ይዞ በእጁ ይመታ ነበር፤ ሳኦልንም ደስ ያሰኘው፥ ያሳርፈውም ነበር፥ ክፉው መንፈስም ከእርሱ ይርቅ ነበር።'),
  ('460be7f5-bc46-5e44-a3b2-0d1640ea0b8c', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 1, 1, 'ፍልስጥኤማውያንም ጭፍሮቻቸውን ለጦርነት ሰበሰቡ፤ ራሳቸውም በይሁዳ በሰኮት ተሰበሰቡ፤ በሰኮትና በዓዜቃ መካከል በኤፌርሜም ሰፈሩ።'),
  ('8f2364ec-f379-5e55-ac01-7081bc37d14e', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 2, 2, 'ሳኦልና የእስራኤል ሰዎችም ተሰበሰቡ፤ በኤላ ሸለቆም ሰፈሩ፤ ከፍልስጥኤማውያንም ጋር ሊዋጉ ተሰለፉ።'),
  ('a59ddc66-670d-5e3f-a0d0-62f4188297f4', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 3, 3, 'ፍልስጥኤማውያንም በአንድ ወገን በተራራ ላይ ቆመው ነበር፥ እስራኤልም በሌላው ወገን በተራራ ላይ ቆመው ነበር፤ በመካከላቸውም ሸለቆ ነበረ።'),
  ('62ccdc7f-bba5-5482-a2ec-a4613fca084f', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 4, 4, 'ከፍልስጥኤማውያንም ሰፈር የጌት ሰው ጎልያድ፥ ቁመቱም ስድስት ክንድ ከስንዝር የሆነ፥ ኀይለኛ ሰው መጣ።'),
  ('6dc6b79b-6568-563f-a35d-c5157dd6b0ec', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 5, 5, 'በራሱም የናስ ቍር ደፍቶ ነበር፤ ጥሩርም ለብሶ ነበር፤ የጥሩሩም ሚዛን አምስት ሺህ ሰቅል ናስና ብረት ነበረ።'),
  ('e04b666f-c495-593d-a40e-00ed4bba91c0', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 6, 6, 'በእግሮቹም ላይ የናስ ገምባሌ ነበረ፤ የናስም ጭሬ በትከሻው ላይ ነበረ።'),
  ('d48a2dbf-5e98-502d-afc3-4818dfa4d4e1', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 7, 7, 'የጦሩም የቦ እንደ ሸማኔ መጠቅለያ ነበረ፤ የጦሩም ሚዛን ስድስት መቶ ሰቅል ብረት ነበረ፤ ጋሻ ጃግሬውም በፊቱ ይሄድ ነበር።'),
  ('78e98ae0-108f-5c41-a4d0-ea8f69c4067e', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 8, 8, 'እርሱም ቆሞ ወደ እስራኤል ጭፍሮች ጮኸ፥ “ከእኛ ጋር ትዋጉ ዘንድ ለምን ወጣችሁ? እኔ ፍልስጥኤማዊ አይደለሁምን? እናንተስ የሳኦል አገልጋዮች ዕብራውያን አይደላችሁምን? ከእናንተ አንድ ሰው ምረጡ፤ ወደ እኔም ይውረድ፤'),
  ('2357ea85-bc58-554a-aabd-09d30b2d1aa3', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 9, 9, 'ከእኔም ጋር ሊዋጋ ቢችል ቢገድለኝም፥ ባሪያዎች እንሆናችኋለን፤ እኔ ግን ባሸንፈው፥ ብገድለውም፥ እናንተ ባሪያዎች ትሆኑናላችሁ፤ ለእኛም ትገዛላችሁ” አለ።'),
  ('0a109543-a39c-573e-a887-a537baef7a38', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 10, 10, 'ፍልስጥኤማዊውም፥ “ዛሬ የእስራኤልን ጭፍሮች ተገዳደርኋቸው፤ አንድ ሰው ስጡኝ ሁለታችንም ለብቻችን እንዋጋ አልኋቸው” አለ።'),
  ('bdc72a34-19b3-5e6b-adf5-5ff0f1b683d3', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 11, 11, 'ሳኦልና እስራኤልም ሁሉ ይህን የፍልስጥኤማዊውን ቃል በሰሙ ጊዜ እጅግ ፈሩ፤ ደነገጡም።'),
  ('a60260b2-e6c8-537c-a245-4978830b3edb', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 12, 12, 'ዳዊትም የዚያ የኤፍራታዊው ሰው ልጅ ነበረ፤ ያም ሰው ከቤተ ልሔም ይሁዳ ስሙም እሴይ ነበረ፤ ስምንት ልጆችም ነበሩት፤ እሴይም በሳኦል ዘመን በዕድሜ አርጅቶ ሸምግሎም ነበር።'),
  ('6b105a63-4e91-5ea5-ac9d-6e128a5d3621', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 13, 13, 'የእሴይም ሦስቱ ታላላቆች ልጆቹ ሳኦልን ተከትለው ወደ ሰልፉ ሄደው ነበር፤ ወደ ሰልፉም የሄዱት የሦስቱ ልጆች ስም ይህ ነበረ፤ ታላቁ ኤልያብ፥ ሁለተኛውም አሚናዳብ፥ ሦስተኛውም ሣማዕ ነበረ።'),
  ('9581e224-7076-5ba3-a755-095e88f2d2ea', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 14, 14, 'ዳዊትም የሁሉ ታናሽ ነበረ፤ ሦስቱም ታላላቆቹ ሳኦልን ተከትለው ነበር።'),
  ('355f6054-1f21-5163-a703-4fe14e768ad5', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 15, 15, 'ዳዊትም የአባቱን በጎች ለመጠበቅ ከሳኦል ዘንድ ወደ ቤተ ልሔም ይመላለስ ነበር።'),
  ('215176ee-b805-5cda-ac4a-1cb12e42ce38', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 16, 16, 'ፍልስጥኤማዊውም ጥዋትና ማታ እየመጣ አርባ ቀን ይቆም ነበር።'),
  ('4a8190bf-33d6-5cc3-a966-59b6b050febf', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 17, 17, 'እሴይም ልጁን ዳዊትን እንዲህ አለው፥ “ከዚህ በሶ አንድ የኢፍ መስፈሪያ እነዚህንም ዐሥር እንጀራዎች ለወንድሞችህ ውሰድ፤ ወደ ሰፈሩም ፈጥነህ ሂድና ለወንድሞችህ ስጣቸው፤'),
  ('c5ebefec-0781-5b08-a039-6fefbad27578', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 18, 18, 'ይህንም ዐሥሩን አይብ ወደ ሻለቃው ውሰደው፤ የወንድሞችህንም ደኅንነት ጠይቅ፤ ወሬአቸውንም አምጣልኝ።”'),
  ('1f061fcd-7abe-5968-a0bd-eed410440fcf', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 19, 19, 'ሳኦልና የእስራኤልም ሰዎች ሁሉ ከፍልስጥኤማውያን ጋር እየተዋጉ በኤላ ሸለቆ ነበሩ።'),
  ('d38deaa3-4eab-5241-ac9a-ad394a412571', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 20, 20, 'ዳዊትም ማልዶ ተነሣ፤ በጎቹንም ለጠባቂ ተወ፤ እሴይም ያዘዘውን ይዞ ሄደ፤ ጭፍራውም ተሰልፎ ሲወጣ፥ ለሰልፍም ሲጮኽ በሰረገሎች ወደ ተከበበው ሰፈር መጣ።'),
  ('c72ea3a6-32b3-5b96-a425-250f73231684', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 21, 21, 'የእስራኤልና የፍልስጥኤማውያን ሠራዊትም ፊት ለፊት ተሰላልፈው ነበር።'),
  ('fa85e5ce-a13d-5dd5-ac32-dbe8d9844a8e', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 22, 22, 'ዳዊትም ዕቃውን በዕቃ ጠባቂው እጅ አኖረው፤ ወደሚዋጉበትም ሮጦ ሄደ፤ የወንድሞቹንም ደኅንነት ጠየቀ።'),
  ('0791df4c-4d71-50b3-ad4a-72679d343aa5', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 23, 23, 'እርሱም ሲነጋገራቸው፥ እነሆ፥ ጎልያድ የተባለ ያ አርበኛ ፍልስጥኤማዊ የጌት ሰው ከፍልስጥኤማውያን ጭፍራ መካከል ወጣ፤ ቀድሞ የተናገረውንም ቃል ተናገረ፤ ዳዊትም ሰማ።'),
  ('d1114108-362d-55f0-a9da-53785a08c786', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 24, 24, 'የእስራኤልም ሰዎች ሁሉ ሰውዬውን ባዩ ጊዜ እጅግ ፈርተው ከፊቱ ሸሹ።'),
  ('a075a629-d917-5b4f-a0bb-b5d790d83a12', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 25, 25, 'የእስራኤልም ሰዎች፥ “ይህን የወጣውን ሰው አያችሁትን? በእውነት እስራኤልን ሊገዳደር ወጣ፤ የሚገድለውንም ሰው ንጉሡ እጅግ ባለጠጋ ያደርገዋል፤ ልጁንም ይድርለታል፤ ያባቱንም ቤተ ሰብ በእስራኤል ዘንድ ከግብር ነጻ ያወጣቸዋል” አሉ።'),
  ('ca3b9804-2ce4-5a8b-a249-f77c207089a0', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 26, 26, 'ዳዊትም በአጠገቡ ለቆሙት ሰዎች፦ ይህን ፍልስጥኤማዊ ለሚገድል፥ ከእስራኤልም ተግዳሮትን ለሚያርቅ ሰው በውኑ ይህ ይደረግለታል? የሕያው አምላክን ጭፍሮች የሚገዳደር ይህ ያልተገረዘ ፍልስጥኤማዊ ማን ነው?” ብሎ ተናገራቸው።'),
  ('5c7aeb2e-dc5f-5edf-a553-48b436916a86', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 27, 27, 'ሕዝቡም፥ “ለሚገድለው ሰው እንዲህ ይደረግለታል” ብለው እንደ ቀድሞው መለሱለት።'),
  ('0598e4b5-1d5a-51e7-a0bc-e51e21c1a640', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 28, 28, 'ታላቅ ወንድሙም ኤልያብ ከሰዎች ጋር ሲነጋገር ሰማ፤ ኤልያብም በዳዊት ላይ እጅግ ተቈጣ፥ “ለምን ወደዚህ ወረድህ? እነዚያንስ ጥቂቶች በጎች በምድረ በዳ ለማን ተውሃቸው? እኔ ኵራትህንና የልብህን ክፋት አውቃለሁና ሰልፉን ለማየት መጥተሃል” አለው።'),
  ('3138361c-1c64-5161-aea2-d82ea7ed1988', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 29, 29, 'ዳዊትም፥ “እኔ ምን አደረግሁ? ይህ ታላቅ ነገር አይደለምን?” አለ።'),
  ('a42a0d79-4962-5149-a78f-4cf8876ef557', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 30, 30, 'ዳዊትም ከእርሱ ወደ ሌላ ሰው ዘወር አለ፤ እንደዚህም ያለ ነገር ተናገረ፤ ሕዝቡም እንደ ቀድሞው ያለ ነገር መለሱለት።'),
  ('256fdfb6-bd4c-5733-a20f-332a3ba2b1b7', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 31, 31, 'ዳዊትም የተናገረው ቃል ተሰማ፤ ለሳኦልም ነገሩት፤ ወደ እርሱም ወሰደው።'),
  ('2a7d0c8a-9808-5a1d-a9ef-1dcf772d45f6', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 32, 32, 'ዳዊትም ሳኦልን፥ “ስለ እርሱ የማንም ልብ አይውደቅ፤ እኔ ባሪያህ ሄጄ ያን ፍልስጥኤማዊ እወጋዋለሁ” አለው።'),
  ('4487d3ee-3640-5472-adcc-9a77b95807f4', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 33, 33, 'ሳኦልም ዳዊትን፥ “አንተ ገና ብላቴና ነህና፥ እርሱም ከብላቴንነቱ ጀምሮ ጦረኛ ነውና ይህን ፍልስጥኤማዊ ለመውጋት ትሄድ ዘንድ አትችልም” አለው።'),
  ('b44e29ca-8ef7-592e-abac-0eb72a65752e', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 34, 34, 'ዳዊትም ሳኦልን አለው፥ “እኔ ባሪያህ የአባቴን በጎች ስጠብቅ አንበሳ ወይም ድብ ይመጣ ነበር፤ ከመንጋውም ጠቦት ይወስድ ነበር።'),
  ('02da5c4c-5e1a-53bb-ac4e-52daeecb2a9e', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 35, 35, 'በኋላውም እከተለውና እመታው ነበር። ከአፉም አስጥለው ነበር፤ በተነሣብኝም ጊዜ ጕሮሮውን አንቄ እመታውና እገድለው ነበር።'),
  ('8a2ef193-c5ee-52e7-a907-29ce5518432e', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 36, 36, 'እኔ ባሪያህ አንበሳና ድብ ገደልሁ፤ ይህም ያልተገረዘው ፍልስጥኤማዊ ከእነርሱ እንደ አንዱ ይሆናል። እንግዲህ እገድለው ዘንድ፥ ከእስራኤልም ተግዳሮትን አስወግድ ዘንድ ዛሬ አልሄድምን? የሕያው አምላክ ጭፍሮችን ይገዳደር ዘንድ ይህ ቈላፍ ምንድን ነው?”'),
  ('cbd272da-1323-56a8-a784-f82ae8b2edb2', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 37, 37, 'ዳዊትም፥ “ከአንበሳና ከድብ እጅ ያስጣለኝ እግዚአብሔር ከዚህ ያልተገረዘ ፍልስጥኤማዊ እጅ ያስጥለኛል” አለ። ሳኦልም ዳዊትን፥ “ሂድ፤ እግዚአብሔርም ከአንተ ጋር ይሁን” አለው።'),
  ('a3fe724b-3caf-57de-aae6-fd1ab8422f18', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 38, 38, 'ሳኦልም ለዳዊት ጥሩር አለበሰው፤ በራሱም ላይ የናስ ቍር ደፋለት።'),
  ('f90874c2-fb23-55dd-ac93-afac36ee1307', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 39, 39, 'ዳዊትንም ሰይፉን በልብሱ ላይ አስታጠቀው፤ ዳዊትም አንድና ሁለት ጊዜ ሲራመድ ደከመ። ዳዊትም ሳኦልን፥ “አለመድሁምና በዚህ መሄድ አልችልም” አለው። ከላዩም አወለቁለት።'),
  ('8c81d699-5d83-5742-ae71-a3bf2448b57d', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 40, 40, 'ዳዊትም በትሩን በእጁ ያዘ፤ ከወንዝም አምስት ድብልብል ድንጋዮችን መረጠ፤ በእረኛ ኮሮጆውም በኪሱ ከተታቸው፤ ወንጭፍም በእጁ ነበረ፤ ወደ ፍልስጥኤማዊውም ቀረበ።'),
  ('2b345e09-d2bc-5767-ad2c-09861fb49f32', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 41, 41, 'ፍልስጥኤማዊውም መጥቶ ወደ ዳዊት ቀረበ፤ ጋሻ ጃግሬውም በፊቱ ይሄድ ነበር።'),
  ('3f005fd9-f19d-519e-aa9d-1035fb2fec04', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 42, 42, 'ጎልያድም ዳዊትን ትኩር ብሎ አየው፤ ቀይ ብላቴና፥ መልኩም ያማረ ነበረና ናቀው።'),
  ('e04d6ef3-81b4-5a70-afea-0e7e04c5ba5e', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 43, 43, 'ፍልስጥኤማዊውም ዳዊትን፥ “በትርና ድንጋይ ይዘህ የምትመጣብኝ እኔ ውሻ ነኝን?” አለው። ዳዊትም፥ “የለም ከውሻ ትከፋለህ” አለው። ፍልስጥኤማዊውም ዳዊትን በአምላኮቹ ረገመው።'),
  ('9295eb3d-76f7-5790-a39f-4be9eab343ae', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 44, 44, 'ፍልስጥኤማዊውም ዳዊትን፥ “ወደ እኔ ና፤ ሥጋህንም ለሰማይ ወፎችና ለምድር አራዊት እሰጣቸዋለሁ” አለው።'),
  ('0c97be60-f386-535b-a298-d6210acae587', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 45, 45, 'ዳዊትም ፍልስጥኤማዊዉን አለው፥ “አንተ ሰይፍና ጦር፥ ጋሻም ይዘህ ትመጣብኛለህ፤ እኔ ግን ዛሬ በተገዳደርኸው በእስራኤል ጭፍሮች አምላክ ስም በሰራዊት ጌታ በእግዚአብሔር ስም እመጣብሃለሁ።'),
  ('1e2ebe94-91d7-5e67-ae29-38a8746fedfb', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 46, 46, 'እግዚአብሔር ዛሬ አንተን በእጄ አሳልፎ ይሰጣል፤ እመታህማለሁ፤ ራስህንም ከአንተ እቈርጠዋለሁ፤ ሬሳህንና የፍልስጥኤማውያንንም ሠራዊት ሬሶች ለሰማይ ወፎችና ለምድር አራዊት ዛሬ እሰጣለሁ። ምድር ሁሉ እግዚአብሔር ከእስራኤል ጋር እንዳለ ያውቃሉ፤'),
  ('275c6226-0d2f-503d-a1e6-7546954b3761', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 47, 47, 'ይህም ጉባኤ ሁሉ እግዚአብሔር በሰይፍና በጦር የሚያድን እንዳይደለ ያውቃል። ሰልፉ ለእግዚአብሔር ነውና፤ እግዚአብሔርም እናንተን በእጃችን አሳልፎ ይሰጣል።”'),
  ('c3785b5a-d52d-5bdb-a69e-8e7b79b82a53', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 48, 48, 'ፍልስጥኤማዊውም ተነሥቶ ዳዊትን ሊገናኘው በቀረበ ጊዜ ዳዊት ፍልስጥኤማዊዉን ሊገናኘው ወደ ሰልፉ ሮጠ።'),
  ('609505d2-3c2f-5a4c-a22f-fd47b783752a', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 49, 49, 'ዳዊትም እጁን ወደ ኮሮጆው አግብቶ አንድ ድንጋይ ወሰደ፤ ወነጨፈውም፤ ፍልስጥኤማዊውንም ግንባሩን መታው፤ ድንጋዩም ጥሩሩን ዘልቆ በግንባሩ ተቀረቀረ፤ እርሱም በምድር ላይ በፊቱ ተደፋ።'),
  ('636c3dcf-3b4e-5cc8-a5a3-42541cd40007', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 50, 50, 'ዳዊትም ፍልስጥኤማዊውን በወንጭፍና በድንጋይ አሸነፈው፤ ፍልስጥኤማዊውንም መትቶ ገደለ ፤ በዳዊትም እጅ ሰይፍ አልነበረም።'),
  ('a91fdf20-3d40-5fe1-ad32-b0aaf0f48bc5', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 51, 51, 'ዳዊትም ሮጦ በፍልስጥኤማዊው ላይ ቆመ፤ ሰይፉንም ይዞ ከሰገባው መዘዘው፤ ገደለውም፤ ራሱንም ቈረጠው። ፍልስጥኤማውያንም ዋናቸው እንደ ሞተ ባዩ ጊዜ ሸሹ።'),
  ('d4391cac-be03-5ffa-a53e-851f639a6f04', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 52, 52, 'የእስራኤልና የይሁዳ ሰዎችም ተነሥተው እልል አሉ፤ ፍልስጥኤማውያንንም እስከ ጌትና እስከ አስቀሎና በር ድረስ አሳደዱአቸው። የፍልስጥኤማውያንም በድኖቻቸው እስከ ጌትና እስከ አቃሮን በሮች ድረስ በመንገድ ላይ ወደቁ።'),
  ('b3c623f6-82c6-5874-a143-932073464b73', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 53, 53, 'የእስራኤልም ሰዎች ፍልስጥኤማውያንን ከማሳደድ ተመልሰው ሰፈራቸውን በዘበዙ።'),
  ('4d5e47a1-63e8-5082-a388-e7b98f846f9a', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 54, 54, 'ዳዊትም የፍልስጥኤማዊውን ራስ ይዞ ወደ ኢየሩሳሌም አመጣው፤ ጋሻና ጦሩን ግን በድንኳኑ ውስጥ አኖረው።'),
  ('dde38fb6-55fe-522a-a5a9-96ea82487e42', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 55, 55, 'ሳኦልም ዳዊትን ፍልስጥኤማዊውን ሊዋጋ ሲወጣ ባየ ጊዜ ለሠራዊቱ አለቃ ለአቤኔር፥ “አቤኔር ሆይ፥ ይህ ብላቴና የማን ልጅ ነው?” አለው። አቤኔርም፥ “ንጉሥ ሆይ፥ በሕያው ነፍስህ እምላለሁ አላውቅም” አለ።'),
  ('16afd896-b0f2-555a-a554-d1e8ffe14253', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 56, 56, 'ንጉሡም፥ “ይህ ብላቴና የማን ልጅ እንደ ሆነ አንተ ጠይቅና ዕወቅ” አለው።'),
  ('c16ce32d-ba37-5adc-a65c-be500ea41ec3', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 57, 57, 'ዳዊትም ፍልስጥኤማዊውን ገድሎ በተመለሰ ጊዜ አቤኔር ወሰደው፤ ወደ ሳኦልም ፊት አመጣው፤ የፍልስጥኤማዊውንም ራስ በእጁ ይዞ ነበር።'),
  ('7c9e7ce5-8115-5452-adae-c18872e84fa1', '1ec0b488-58f3-5257-a153-05c4c72e49d6', '32354b8d-e40e-58e6-add1-ba6fc6fef226', 58, 58, 'ሳኦልም፥ “አንተ ብላቴና የማን ልጅ ነህ?” አለው ዳዊትም፥ “እኔ የቤተ ልሔሙ የባሪያህ የእሴይ ልጅ ነኝ” ብሎ መለሰ።'),
  ('33197ca3-e246-5213-a83d-3925acc6b86d', '5f11fb53-7cfc-5160-abb0-abce36eae3da', '675abd21-54ec-5ec2-a2f3-7f707a7e8924', 1, 1, 'እንዲህም ሆነ፤ ዳዊት ለሳኦል መንገሩን በፈጸመ ጊዜ የዮናታን ነፍስ በዳዊት ነፍስ ታሰረች፤ ዮናታንም እንደ ነፍሱ ወደደው።'),
  ('a0771b52-7d3d-5b8c-ad89-d65d4c8a9413', '5f11fb53-7cfc-5160-abb0-abce36eae3da', '675abd21-54ec-5ec2-a2f3-7f707a7e8924', 2, 2, 'በዚያም ቀን ሳኦል ወሰደው፤ ወደ አባቱም ቤት ይመልሰው ዘንድ አልፈቀደለትም።'),
  ('d0a516cc-212e-56fb-a4c9-71e680102775', '5f11fb53-7cfc-5160-abb0-abce36eae3da', '675abd21-54ec-5ec2-a2f3-7f707a7e8924', 3, 3, 'ዮናታንም እንደ ነፍሱ ስለ ወደደው ዮናታንና ዳዊት ቃል ኪዳን አደረጉ።'),
  ('2c7279ef-c2ac-521b-a7bd-33cfa5167fdd', '5f11fb53-7cfc-5160-abb0-abce36eae3da', '675abd21-54ec-5ec2-a2f3-7f707a7e8924', 4, 4, 'ዮናታንም የለበሰውን ካባ አውልቆ እርሱንና ልብሱን፥ ሰይፉንም፥ ቀስቱንም፥ ዝናሩንም ለዳዊት ሸለመው።'),
  ('2910000b-19b6-59af-aceb-bc87beee35fd', '5f11fb53-7cfc-5160-abb0-abce36eae3da', '675abd21-54ec-5ec2-a2f3-7f707a7e8924', 5, 5, 'ዳዊትም ሳኦል ወደ ላከው ሁሉ ይሄድ ነበር፤ አስተውሎም ያደርግ ነበር፤ ሳኦልም በጦረኞች ላይ ሾመው፤ ይህም በሕዝብ ሁሉ ዐይንና በሳኦል ባሪያዎች ዐይን መልካም ነበረ።'),
  ('848e62eb-430a-57d5-a3dc-c0047f6340ed', '5f11fb53-7cfc-5160-abb0-abce36eae3da', '675abd21-54ec-5ec2-a2f3-7f707a7e8924', 6, 6, 'እንዲህም ሆነ፤ ዳዊት ፍልስጥኤማዊውን ገድሎ በተመለሰ ጊዜ፥ እየዘመሩና እየዘፈኑ፥ እልልም እያሉ ከበሮና አታሞ ይዘው ዳዊትን ሊቀበሉ ሴቶች ከእስራኤል ከተሞች ሁሉ ወጡ።'),
  ('956aefde-ffdb-55be-a789-313bd28f49e6', '5f11fb53-7cfc-5160-abb0-abce36eae3da', '675abd21-54ec-5ec2-a2f3-7f707a7e8924', 7, 7, 'ሴቶችም፥ “ሳኦል ሺህ ገደለ፤ ዳዊትም ዐሥር ሺህ ገደለ” እያሉ እየተቀባበሉ ይዘፍኑ ነበር።'),
  ('76ebd546-e66e-5be1-a3aa-11cea38999b8', '5f11fb53-7cfc-5160-abb0-abce36eae3da', '675abd21-54ec-5ec2-a2f3-7f707a7e8924', 8, 8, 'ሳኦልም እጅግ ተቈጣ፤ ይህም ነገር ሳኦልን አስከፋው፤ እርሱም፥ “ለዳዊት ዐሥር ሺህ ሰጡት፤ ለእኔ ግን ሺህ ብቻ ሰጡኝ፤ ከመንግሥት በቀር ምን ቀረበት?” አለ።'),
  ('898c9049-a6c9-5b31-a0dc-07fde0ce8a8f', '5f11fb53-7cfc-5160-abb0-abce36eae3da', '675abd21-54ec-5ec2-a2f3-7f707a7e8924', 9, 9, 'ከዚያም ቀን ጀምሮ ሳኦል ዳዊትን ሁልጊዜ ይጠባበቀው ነበር።'),
  ('707b501e-ed90-56e7-a9fe-816861f7acba', '5f11fb53-7cfc-5160-abb0-abce36eae3da', '675abd21-54ec-5ec2-a2f3-7f707a7e8924', 10, 10, 'እንዲህም ሆነ፤ በነጋው ሳኦልን ክፉ መንፈስ ከእግዚአብሔር ዘንድ ያዘው፤ በቤቱም ውስጥ ትንቢት ተናገረ። ዳዊትም በየቀኑ ያደርግ እንደ ነበረ በእጁ በገና ይመታ ነበር። ሳኦልም ጦሩን በእጁ ይዞ ነበር።'),
  ('d74c5c44-2e2f-5855-a471-194bdeddd4d6', '5f11fb53-7cfc-5160-abb0-abce36eae3da', '675abd21-54ec-5ec2-a2f3-7f707a7e8924', 11, 11, 'ሳኦልም፥ “ዳዊትን ከግንቡ ጋር አጣብቄ እመታዋለሁ” ብሎ ጦሩን ወረወረ። ዳዊትም ሁለት ጊዜ ከፊቱ ዘወር አለ።'),
  ('61dee554-4026-524f-aeb1-bbaefff2f2cd', '5f11fb53-7cfc-5160-abb0-abce36eae3da', '675abd21-54ec-5ec2-a2f3-7f707a7e8924', 12, 12, 'እግዚአብሔርም ከእርሱ ጋር ስለ ነበረ፥ ከሳኦልም ስለ ተለየ ሳኦል ከዳዊት ፊት የተነሣ ፈራ።'),
  ('786a944c-b713-5cc6-a074-a4782a582482', '5f11fb53-7cfc-5160-abb0-abce36eae3da', '675abd21-54ec-5ec2-a2f3-7f707a7e8924', 13, 13, 'ስለዚህም ሳኦል ከእርሱ አራቀው፤ የሺህ አለቃም አድርጎ ሾመው፤ በሕዝቡም ፊት ይወጣና ይገባ ነበር።'),
  ('3584ca95-9f30-56a2-a6c8-42445762aa0d', '5f11fb53-7cfc-5160-abb0-abce36eae3da', '675abd21-54ec-5ec2-a2f3-7f707a7e8924', 14, 14, 'ዳዊትም በአካሄዱ ሁሉ ብልህና ዐዋቂ ነበር፤ እግዚአብሔርም ከእርሱ ጋር ነበረ።'),
  ('a48cd5fa-230f-5009-a14e-9ef5a44254fe', '5f11fb53-7cfc-5160-abb0-abce36eae3da', '675abd21-54ec-5ec2-a2f3-7f707a7e8924', 15, 15, 'ሳኦልም እጅግ ብልህ እንደ ሆነ አይቶ እጅግ ፈራው።'),
  ('03392bb0-ff18-5d40-a87d-e7622682e2a1', '5f11fb53-7cfc-5160-abb0-abce36eae3da', '675abd21-54ec-5ec2-a2f3-7f707a7e8924', 16, 16, 'ነገር ግን በፊታቸው ይወጣና ይገባ ስለነበረ እስራኤልና ይሁዳ ሁሉ ዳዊትን ወደዱ።'),
  ('ca8a7754-6ccf-5bce-a8b6-f3d9765cafb1', '5f11fb53-7cfc-5160-abb0-abce36eae3da', 'f235aff0-7447-5193-ad69-9670817252cb', 1, 17, 'ሳኦልም ዳዊትን፥ “ታላቂቱ ልጄ ሜሮብ እነኋት፤ እርስዋን እድርልሃለሁ፤ ብቻ ጀግና ልጅ ሁንልኝ፤ ስለ እግዚአብሔርም ጦርነት ተጋደል” አለው። ሳኦልም፥ “የፍልስጥኤማውያን እጅ በእርሱ ላይ ትሁን እንጂ የእኔ እጅ በእርሱ ላይ አትሁን” ይል ነበር።'),
  ('9e470cf3-0ab2-5f73-a3c1-e2dc0fc63de4', '5f11fb53-7cfc-5160-abb0-abce36eae3da', 'f235aff0-7447-5193-ad69-9670817252cb', 2, 18, 'ዳዊትም ሳኦልን፥ “ለንጉሥ አማች እሆን ዘንድ እኔ ማን ነኝ? ሰውነቴስ ምንድን ናት? የአባቴስ ወገን በእስራኤል ዘንድ ምንድን ነው?” አለው።'),
  ('67ab7009-e67c-5cd1-af4f-7cd35d6c42a6', '5f11fb53-7cfc-5160-abb0-abce36eae3da', 'f235aff0-7447-5193-ad69-9670817252cb', 3, 19, 'ነገር ግን የሳኦል ልጅ ሜሮብ ዳዊትን የምታገባበት ጊዜ ሲደርስ ለሚሆላዊው ለአድርኤል ተዳረች።'),
  ('1b66edb6-aea8-50bf-aa1b-f40867597fa8', '5f11fb53-7cfc-5160-abb0-abce36eae3da', 'f235aff0-7447-5193-ad69-9670817252cb', 4, 20, 'የሳኦልም ልጅ ሜልኮል ዳዊትን ወደደች፤ ይህም ወሬ ለሳኦል ደረሰለት፤ ነገሩም ደስ አሰኘው።'),
  ('fb70eb77-dd92-56c7-a2d3-c9f44c353a9a', '5f11fb53-7cfc-5160-abb0-abce36eae3da', 'f235aff0-7447-5193-ad69-9670817252cb', 5, 21, 'ሳኦልም፥ “እርስዋን እሰጠዋለሁ፤ እርስዋም እንቅፋት ትሆንበታለች” አለ። እነሆም፥ የፍልስጥኤማውያን እጅ በሳኦል ላይ ነበረች።'),
  ('053eae6f-db10-5554-a14a-a3b13abfe551', '5f11fb53-7cfc-5160-abb0-abce36eae3da', 'f235aff0-7447-5193-ad69-9670817252cb', 6, 22, 'ሳኦልም ብላቴኖቹን፥ “እነሆ፥ ንጉሥ እጅግ ወድዶሃል፤ ቤተ ሰቡም ሁሉ ወድደውሃል፤ አሁንም ለንጉሥ አማች ሁን ብላችሁ በስውር ለዳዊት ንገሩት” ብሎ አዘዛቸው።'),
  ('5301c3cc-ff5c-5fa2-aa46-1d4b6e327222', '5f11fb53-7cfc-5160-abb0-abce36eae3da', 'f235aff0-7447-5193-ad69-9670817252cb', 7, 23, 'የሳኦልም ብላቴኖች ይህን ቃል በዳዊት ጆሮ ተናገሩ፤ ዳዊትም፥ “እኔ የተዋረድሁና ክብር የሌለኝ ሰው ስሆን ለንጉሥ አማች እሆን ዘንድ ለእናንተ ትንሽ ነገር ይመስላችኋልን?” አለ።'),
  ('3d5dcf34-1ede-5125-a653-f1eb5c293524', '5f11fb53-7cfc-5160-abb0-abce36eae3da', 'f235aff0-7447-5193-ad69-9670817252cb', 8, 24, 'የሳኦልም ብላቴኖች፦ ዳዊት እንዲህ ብሎ ተናገረ ብለው ነገሩት።'),
  ('cd7813cf-994c-59ce-a968-e14d33f5fdb5', '5f11fb53-7cfc-5160-abb0-abce36eae3da', 'f235aff0-7447-5193-ad69-9670817252cb', 9, 25, 'ሳኦልም አላቸው፥ “የንጉሥን ጠላቶች ይበቀል ዘንድ ከመቶ ፍልስጥኤማውያን ሸለፈት በቀር ንጉሥ ማጫ አይሻም ብላችሁ ለዳዊት ንገሩት” አላቸው። ሳኦል ግን ይህን ማለቱ በፍልስጥኤማውያን እጅ ይጥለው ዘንድ አስቦ ነው።'),
  ('bd11d1f7-9b35-57c5-a2d3-b8121d85924f', '5f11fb53-7cfc-5160-abb0-abce36eae3da', 'f235aff0-7447-5193-ad69-9670817252cb', 10, 26, 'የሳኦልም ብላቴኖች ይህን ቃል ለዳዊት ነገሩት፤ ለንጉሥም አማች ይሆን ዘንድ ዳዊትን ደስ አሰኘው።'),
  ('9c3253aa-bf59-5a8c-a657-03b1ec675320', '5f11fb53-7cfc-5160-abb0-abce36eae3da', 'f235aff0-7447-5193-ad69-9670817252cb', 11, 27, 'ዳዊትና ሰዎቹም ተነሥተው ሄዱ፤ ከፍልስጥኤማውያንም ሁለት መቶ ሰዎችን ገደሉ፤ ዳዊትም ለንጉሥ አማች ይሆን ዘንድ ሰለባቸውን አምጥቶ በቍጥራቸው ልክ ለንጉሡ ሰጠ። ሳኦልም ልጁን ሜልኮልን ዳረለት።'),
  ('4a25ea51-0c06-541d-ae0f-57c024087a84', '5f11fb53-7cfc-5160-abb0-abce36eae3da', 'f235aff0-7447-5193-ad69-9670817252cb', 12, 28, 'ሳኦልም እግዚአብሔር ከዳዊት ጋር እንደ ሆነ አየ፤ እስራኤልም ሁሉ ወደዱት።'),
  ('0a0c9552-2537-5095-a24c-76614e4c2818', '5f11fb53-7cfc-5160-abb0-abce36eae3da', 'f235aff0-7447-5193-ad69-9670817252cb', 13, 29, 'ሳኦልም ዳዊትን አጥብቆ ፈራው፤ ሳኦልም ዕድሜውን ሁሉ ለዳዊት ጠላት ሆነ።'),
  ('edb53dba-de08-5209-a0be-6f95fc426f8f', '5f11fb53-7cfc-5160-abb0-abce36eae3da', 'f235aff0-7447-5193-ad69-9670817252cb', 14, 30, 'የፍልስጥኤማውያንም አለቆች ይወጡ ነበር፤ በወጡም ጊዜ ሁሉ ከሳኦል አገልጋዮች ሁሉ ይልቅ ዳዊት አስተውሎ ያደርግ ነበርና ስሙ እጅግ ተጠርቶ ነበር።'),
  ('fcb55f94-e8a5-59f4-a837-3a13c11f18fe', 'aa402ee0-90aa-50d6-a9c7-fd8d658c67ee', '301e4192-063c-571b-ae46-b2188f7208d6', 1, 1, 'ሳኦልም ለልጁ ለዮናታንና ለብላቴኖቹ ሁሉ ዳዊትን ይገድሉ ዘንድ ነገራቸው። የሳኦል ልጅ ዮናታን ግን ዳዊትን እጅግ ይወድደው ነበር።'),
  ('01e868ee-fa9c-5895-a304-947cbdb363bf', 'aa402ee0-90aa-50d6-a9c7-fd8d658c67ee', '301e4192-063c-571b-ae46-b2188f7208d6', 2, 2, 'ዮናታንም፥ “አባቴ ሳኦል ሊገድልህ ፈልጎአል፤ አሁን እንግዲህ ለነገው ተጠንቅቀህ ተሸሸግ፤ በስውርም ተቀመጥ።'),
  ('976ebd13-0e65-5dc9-a471-e2e7f6342fcf', 'aa402ee0-90aa-50d6-a9c7-fd8d658c67ee', '301e4192-063c-571b-ae46-b2188f7208d6', 3, 3, 'እኔም እወጣለሁ፤ አንተም ባለህበት እርሻ በአባቴ አጠገብ እቆማለሁ፤ ስለ አንተም ለአባቴ እነግረዋለሁ፤ የሆነውንም አይቼ እነግርሃለሁ” ብሎ ለዳዊት ነገረው።'),
  ('bd440c31-bc8b-5d88-af19-6a672d65214f', 'aa402ee0-90aa-50d6-a9c7-fd8d658c67ee', '301e4192-063c-571b-ae46-b2188f7208d6', 4, 4, 'ዮናታንም ለአባቱ ለሳኦል ስለ ዳዊት መልካም ተናገረ እንዲህም አለው፥ “እርሱ አልበደለህምና፥ ሥራውም ለአንተ እጅግ መልካም ሆኖአልና ንጉሡ ባሪያውን ዳዊትን አይበድለው፤'),
  ('2487d919-e055-5911-abcb-58386b952e91', 'aa402ee0-90aa-50d6-a9c7-fd8d658c67ee', '301e4192-063c-571b-ae46-b2188f7208d6', 5, 5, 'ነፍሱንም በእጁ ጥሎ ፍልስጥኤማዊዉን ገደለ፤ እግዚአብሔርም በእርሱ ታላቅ መድኀኒት አደረገ፤ እስራኤልም ሁሉ አይተው ደስ አላቸው፤ በከንቱ ዳዊትን ትገድለው ዘንድ ስለምን በንጹሕ ደም ላይ ትበድላለህ?”'),
  ('d1589c08-d2a6-5c72-a15a-26360db4308b', 'aa402ee0-90aa-50d6-a9c7-fd8d658c67ee', '301e4192-063c-571b-ae46-b2188f7208d6', 6, 6, 'ሳኦልም የዮናታንን ቃል ሰማ፤ ሳኦልም፥ “ሕያው እግዚአብሔርን! ዳዊት አይገደልም” ብሎ ማለ።'),
  ('49259ef3-8530-5c58-a82c-3aeb175d4fe9', 'aa402ee0-90aa-50d6-a9c7-fd8d658c67ee', '301e4192-063c-571b-ae46-b2188f7208d6', 7, 7, 'ዮናታንም ዳዊትን ጠርቶ ይህን ነገር ሁሉ ነገረው፤ ዮናታንም ዳዊትን ወደ ሳኦል አመጣው፤ እንደ ቀድሞውም በፊቱ ነበረ።'),
  ('1281c70f-92e9-5144-afd2-18e9a82c1f7b', 'aa402ee0-90aa-50d6-a9c7-fd8d658c67ee', '301e4192-063c-571b-ae46-b2188f7208d6', 8, 8, 'ደግሞም ጦርነት ሆነ፤ ዳዊትም ወጥቶ ከፍልስጥኤማውያን ጋር ተዋጋ፤ ታላቅ ግዳይም ገደላቸው፤ ከፊቱም ሸሹ።'),
  ('2000c0db-a987-53e2-a6c0-003499936af1', 'aa402ee0-90aa-50d6-a9c7-fd8d658c67ee', '301e4192-063c-571b-ae46-b2188f7208d6', 9, 9, 'ሳኦልም ጦሩን ይዞ በቤቱ ተቀምጦ ሳለ ክፉ መንፈስ ከእግዚአብሔር ዘንድ ያዘው። ዳዊትም በእጁ በገና ይመታ ነበር።'),
  ('9b8b82ee-bd50-53e2-a83f-b06f4c0eb2c9', 'aa402ee0-90aa-50d6-a9c7-fd8d658c67ee', '301e4192-063c-571b-ae46-b2188f7208d6', 10, 10, 'ሳኦልም ዳዊትን ከግንብ ጋር ያጣብቀው ዘንድ ጦሩን ወረወረ፤ ዳዊትም ከሳኦል ፊት ዘወር አለ፤ ጦሩም በግንቡ ውስጥ ተተከለ፤ በዚያም ሌሊት ዳዊት ሸሸቶ አመለጠ።'),
  ('0a3207f2-d87a-5ffb-a62f-33bf7218b728', 'aa402ee0-90aa-50d6-a9c7-fd8d658c67ee', '301e4192-063c-571b-ae46-b2188f7208d6', 11, 11, 'ሳኦልም ዳዊትን ጠበቀው፤ በነጋው እንዲገድሉት መልእክተኞቹን ወደ ዳዊት ቤት ላከ፤ ሚስቱም ሜልኮል፥ “በዚህች ሌሊት ነፍስህን ካላዳንህ ነገ ትገደላለህ” ብላ ነገረችው።'),
  ('dc48429f-9109-50d2-aae8-c566a0d8bf4c', 'aa402ee0-90aa-50d6-a9c7-fd8d658c67ee', '301e4192-063c-571b-ae46-b2188f7208d6', 12, 12, 'ሜልኮልም ዳዊትን በመስኮት አወረደችው፤ ሄደም፤ ሸሽቶም አመለጠ።'),
  ('c6f000cc-9377-54e2-ab5e-7423c47a8808', 'aa402ee0-90aa-50d6-a9c7-fd8d658c67ee', '301e4192-063c-571b-ae46-b2188f7208d6', 13, 13, 'ሜልኮልም ተራፊምን ወስዳ በአልጋ ላይ አኖረችው፤ በራስጌውም ጕንጕን የፍየል ጠጕር አደረገች፤ በልብስም ከደነችው።'),
  ('1ed06c5b-0c53-54b3-a78e-ff9c70017fc8', 'aa402ee0-90aa-50d6-a9c7-fd8d658c67ee', '301e4192-063c-571b-ae46-b2188f7208d6', 14, 14, 'ሳኦልም ዳዊትን ይዘው እንዲያመጡት መልእክተኞችን ላከ፤ እርስዋም ታሞአል አለቻቸው።'),
  ('a736c661-ab95-53f9-a575-eaf38148fefd', 'aa402ee0-90aa-50d6-a9c7-fd8d658c67ee', '301e4192-063c-571b-ae46-b2188f7208d6', 15, 15, 'ሳኦልም፥ “እገድለው ዘንድ ዳዊትን ከነአልጋው” አምጡልኝ ብሎ መልእክተኞቹን ወደ ዳዊት ላከ።'),
  ('3ad15111-d466-5eba-ae94-b6014144d3ba', 'aa402ee0-90aa-50d6-a9c7-fd8d658c67ee', '301e4192-063c-571b-ae46-b2188f7208d6', 16, 16, 'መልእክተኞቹም በገቡ ጊዜ እነሆ፥ ተራፊሙን በአልጋው ላይ አገኙ፤ በራስጌውም ጕንጕን የፍየል ጠጕር ነበረ።'),
  ('fdafd3a3-4301-550a-a2c7-76a374c751a9', 'aa402ee0-90aa-50d6-a9c7-fd8d658c67ee', '301e4192-063c-571b-ae46-b2188f7208d6', 17, 17, 'ሳኦልም ሜልኮልን አላት፥ “ስለምን እንዲህ አታለልሽኝ? ጠላቴን አስኰበለልሽ፤ እንዲያመልጥም አደረግሽው?” ሜልኮልም ለሳኦል፥ “እርሱ፦ አውጥተሽ ስደጂኝ፤ አለዚያ እገድልሻለሁ አለኝ” አለችው።'),
  ('1ded764e-de8c-526a-afe7-c42d9bbf77f0', 'aa402ee0-90aa-50d6-a9c7-fd8d658c67ee', '301e4192-063c-571b-ae46-b2188f7208d6', 18, 18, 'ዳዊትም ሸሽቶ አመለጠ፤ ወደ አርማቴምም ወደ ሳሙኤል መጣ፤ ሳኦልም ያደረገበትን ሁሉ ነገረው፤ እርሱና ሳሙኤልም ሄዱ፤ በአውቴዘራማም ተቀመጡ።'),
  ('4086e421-fe96-5957-aacc-0421ab138e40', 'aa402ee0-90aa-50d6-a9c7-fd8d658c67ee', '301e4192-063c-571b-ae46-b2188f7208d6', 19, 19, 'ለሳኦልም፥ “ዳዊት እነሆ፥ በአውቴዘራማ ተቀምጦአል” ብለው ነገሩት።'),
  ('28807515-01a9-5f53-a059-a272d603b925', 'aa402ee0-90aa-50d6-a9c7-fd8d658c67ee', '301e4192-063c-571b-ae46-b2188f7208d6', 20, 20, 'ሳኦልም ዳዊትን ያመጡት ዘንድ መልእክተኞችን ላከ፤ የነቢያትንም ጉባኤ አገኙ፤ ሳሙኤልም አለቃቸው ሆኖ በመካከላቸው ቆሞ ነበረ፤ የእግዚአብሔርም መንፈስ በሳኦል መልእክተኞች ላይ ወረደ፤ እነርሱም ትንቢት ይናገሩ ጀመር።'),
  ('044321af-4f5c-5365-a535-9c1c593ba69c', 'aa402ee0-90aa-50d6-a9c7-fd8d658c67ee', '301e4192-063c-571b-ae46-b2188f7208d6', 21, 21, 'ለሳኦልም ይህን በነገሩት ጊዜ ሌሎች መልእክተኞችን ላከ፤ እነርሱም ደግሞ ትንቢት ተናገሩ። ሳኦልም እንደ ገና ሦስተኛ ጊዜ መልእክተኞችን ላከ፤ እነርሱም ደግሞ ትንቢት ተናገሩ።'),
  ('af0366fd-fb76-54b2-a0e0-8839fd7075ac', 'aa402ee0-90aa-50d6-a9c7-fd8d658c67ee', '301e4192-063c-571b-ae46-b2188f7208d6', 22, 22, 'ሳኦልም እጅግ ተቈጣ፤ እርሱም ደግሞ ወደ አርማቴም መጣ፤ በመሴፋም አውድማ ወዳለው ወደ ታላቁ የውኃ ጕድጓድ ደረሰ። “ሳሙኤልና ዳዊት የት ናቸው?” ብሎ ጠየቀ፤ “እነሆ፥ በአውቴዘራማ ናቸው” አሉት።'),
  ('0638e26e-5262-5bae-ab84-ed5681628c08', 'aa402ee0-90aa-50d6-a9c7-fd8d658c67ee', '301e4192-063c-571b-ae46-b2188f7208d6', 23, 23, 'ወደ አውቴዘራማም ሄደ፤ የእግዚአብሔርም መንፈስ በእርሱ ደግሞ ወረደ፤ እርሱም ሄደ፤ ወደ አውቴዘራማም እስኪመጣ ድረስ ትንቢት ይናገር ነበር።'),
  ('2385b273-faf6-586e-a321-09aaf8a1921c', 'aa402ee0-90aa-50d6-a9c7-fd8d658c67ee', '301e4192-063c-571b-ae46-b2188f7208d6', 24, 24, 'ልብሱንም አወለቀ፤ በፊታቸውም ትንቢት ተናገረ፤ ራቁቱንም ወድቆ በዚያ ቀን ሁሉ በዚያም ሌሊት ሁሉ ተጋደመ። ስለዚህ፥ “ሳኦል ደግሞ ከነቢያት መካከል ነውን?” ይባባሉ ነበር።'),
  ('f78499f2-dc3f-5f02-aaad-7f77ecba8261', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 1, 1, 'ዳዊትም ከአውቴዘራማ ሸሸ፤ ወደ ዮናታንም መጣ፤ እንዲህም አለው፥ “ምን አደረግሁ? ምንስ በደልሁ? ነፍሴንም ይሻት ዘንድ በአባትህ ፊት ጥፋቴና ኀጢአቴ ምንድን ነው?”'),
  ('07d590f9-df2b-532a-a9dd-79be2af0da9f', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 2, 2, 'ዮናታንም፥ “ይህንስ ያርቀው፤ አትሞትም፤ እነሆ፥ አባቴ አስቀድሞ ለእኔ ሳይገልጥ ትልቅም ሆነ ትንሽ ነገር ቢሆን አያደርግም፤ አባቴስ ይህን ነገር ለምን ይሰውረኛል? እንዲህ አይደለም” አለው።'),
  ('c30ee5a2-e9df-5381-a34b-6dd7187764af', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 3, 3, 'ዳዊትም፥ “እኔ በፊትህ ሞገስን እንዳገኘሁ አባትህ በእውነት ያውቃል፤ እርሱም፦ ዮናታን እንዳይቃወም አይወቅ ይላል፤ ነገር ግን ሕያው እግዚአብሔርን! በሕያው ነፍስህም እምላለሁ፤ እኔ እንዳልሁት በእኔና በሞት መካከል አንድ ርምጃ ያህል ቀርቶአል” ብሎ ማለ።'),
  ('8b9acae0-5c62-58c1-a41d-6fcbd972e46d', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 4, 4, 'ዮናታንም ዳዊትን፥ “ነፍስህ ምን ትፈልጋለች? እኔስ ምን ላድርግልህ?” አለው።'),
  ('9c0851c6-8b52-51e8-a856-a08e05fb25e7', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 5, 5, 'ዳዊትም ዮናታንን አለው፥ “እነሆ ነገ መባቻ ነው፤ በንጉሥም አጠገብ ለምሳ አልቀመጥም፤ እስከ ማታ ድረስ በውጭ በሜዳ እንድሸሸግ አሰናብተኝ ።'),
  ('7fdd296c-036b-582e-a160-45048aed6eba', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 6, 6, 'አባትህም ቢፈልገኝ፦ ለዘመዶቹ ሁሉ በዚያ በቤተ ልሔም የዓመት መሥዋዕት አላቸውና ዳዊት ወደ ከተማው ፈጥኖ ይሄድ ዘንድ አጽንቶ ለምኖኛል በለው።'),
  ('57185b0d-2a40-5099-a67d-9690dcb61b38', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 7, 7, 'እርሱም፦ መልካም ነው ቢል ለእኔ ለባሪያህ ሰላም ይሆናል፤ ቢቈጣ ግን ክፋት ከእርሱ ዘንድ በእኔ ላይ እንደ ተቈረጠች ዕወቅ።'),
  ('b0797a5f-5cdb-5a2c-a42a-4e163a5d5297', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 8, 8, 'እንግዲህ የእግዚአብሔርን ቃል ኪዳን ከባሪያህ ጋር አድርገሃልና ለባሪያህ ቸርነትን አድርግ፤ በደል ግን ቢገኝብኝ አንተ ግደለኝ፤ ለምን ወደ አባትህ ታደርሰኛለህ?”'),
  ('bd8aaf1d-cf8a-5d15-a9bd-6130da825f09', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 9, 9, 'ዮናታንም፥ “ይህ ከአንተ ይራቅ፤ ከአባቴ ዘንድ ክፋት በላይህ እንደ ተቈረጠች ያወቅሁ እንደ ሆነ በከተማ ባትኖርም እንኳን ወደ አንተ መጥቼ እነግርሃለሁ” አለው።'),
  ('a2d4f227-dcda-5845-a6ef-5cb7e325b4c7', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 10, 10, 'ዳዊትም ዮናታንን፥ “አባትህ ስለ እኔ ክፉ ነገር የነገረህ እንደ ሆነ ማን ይነግረኛል?” አለው።'),
  ('fd05faa8-1787-5c19-aa79-a6abb8eb70bd', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 11, 11, 'ዮናታንም ዳዊትን፥ “ና፤ ወደ ሜዳ እንውጣ” አለው። ሁለቱም ወደ ሜዳ ወጡ።'),
  ('0e580338-48a3-553a-a2a4-2a80440c79c6', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 12, 12, 'ዮናታንም ዳዊትን አለው፥ “የእስራኤል አምላክ እግዚአብሔር ያውቃል፤ እስከ ሦስት ቀን ድረስ በዚህ ጊዜ አባቴን መርምሬ እነሆ፥ በዳዊት ላይ መልካም ቢያስብ፥ እነሆ፥ ወደ ሜዳ ወደ አንተ አልልክም፤ ይህም ምልክት ይሁንህ፤'),
  ('42b6fa24-138e-5d41-a4cb-2c937718a212', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 13, 13, 'አባቴም በአንተ ላይ ክፋት ማድረግ ቢወድድ፥ እኔም ባላስታውቅህ፥ በሰላምም ትሄድ ዘንድ ባላሰናብትህ፥ እግዚአብሔር በዮናታን ይህን ያድርግ፤ ይህንም ይጨምር፤ እግዚአብሔርም ከአባቴ ጋር እንደ ነበረ ከአንተ ጋር ይሁን።'),
  ('a98b1c32-e27a-59b2-a840-84cd7b81fc26', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 14, 14, 'እኔም በሕይወት ሳለሁ ቸርነትን ታደርግልኛለህ፤'),
  ('a59ec683-bf4f-5d38-aae6-56c2a8bcd4ac', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 15, 15, 'ብሞትም ቸርነትህን እስከ ዘለዓለም ከቤቴ አትተው፤ ደግሞም እግዚአብሔር የዳዊትን ጠላቶች ሁሉ እያንዳንዱን ከምድር ፊት ባጠፋቸው ጊዜ የዮናታን ስም በዳዊት ቤት ይገኛል።”'),
  ('eb5f8b7f-85f7-5ac0-ab35-d727373b6197', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 16, 16, 'ዮናታንም፥ “እግዚአብሔር ከዳዊት ጠላቶች እጅ ይፈልገው” ብሎ ከዳዊት ቤት ጋር ቃል ኪዳን አደረገ።'),
  ('2f33fdaa-85a3-5140-ac21-314c3769f712', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 17, 17, 'ዮናታንም ዳዊትን እንደ ነፍሱ ይወድድ ነበርና እንደ ገና ማለለት።'),
  ('fe1c3812-15a1-5707-a262-e97188a23bb2', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 18, 18, 'ዮናታንም አለው፥ “ነገ መባቻ ነው፤ መቀመጫህም ባዶ ሆኖ ይገኛልና ትታሰባለህ።'),
  ('720b2434-5c3f-5466-adf6-e6f1da71a4be', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 19, 19, 'ሦስት ቀንም ያህል ቈይ፤ ከዚህም በኋላ በፈለገህ ጊዜ ትመጣና ነገሩ በተደረገበት ቀን በተሸሸግህበት ስፍራ ትቀመጣለህ፤ በኤርገብ ድንጋይም አጠገብ ቈይ።'),
  ('5e04fc66-65cf-5d3e-a87d-0b33b76e5a3a', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 20, 20, 'እኔም በዓላማ ላይ እወረውራለሁ ብዬ ሦስት ፍላጻዎችን ወደ ዓላማው እወረውራለሁ።'),
  ('1fa6a6ca-3601-53f3-a85d-f01e4128fde5', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 21, 21, 'እነሆም፦ ሂድ ፍላጻዎቹን ፈልግ ብዬ ብላቴናውን እልካለሁ፤ ብላቴናውንም፦ እነሆ፥ ፍላጻው ከአንተ ወደዚህ ነው፤ ይዘኸው ወደ እኔ ና ያልሁት እንደ ሆነ፥ ሕያው እግዚአብሔርን! ለአንተ ሰላም ነውና ምንም ክፉ ነገር የለብህም።'),
  ('f7067421-a0ef-50e2-ace4-9e81341f74c2', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 22, 22, 'ብላቴናውን ግን፦ እነሆ፥ ፍላጻው ከአንተ ወዲያ ነው ያልሁት እንደ ሆነ፥ እግዚአብሔር አሰናብቶሃልና መንገድህን ሂድ።'),
  ('e4061a31-2b10-5ca1-a7c3-427d16af43b5', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 23, 23, 'አንተና እኔም ስለ ተነጋገርነው፥ እነሆ፥ እግዚአብሔር ለዘለዓለም በመካከላችን ምስክር ነው።”'),
  ('6716aa13-46a1-5065-a6eb-56f51f01a692', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 24, 24, 'ዳዊትም በሜዳው ተሸሸገ፤ መባቻም በሆነ ጊዜ ንጉሡ ግብር ለመብላት ተቀመጠ።'),
  ('0ac076fa-0eb2-55f0-ac9b-01e0fa1ead74', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 25, 25, 'ንጉሡም እንደ ቀድሞው በግንቡ አጠገብ በዙፋኑ ላይ ተቀመጠ፤ ዮናታንም ቆመ፤ አቤኔርም በሳኦል አጠገብ ተቀመጠ፤ የዳዊትም ስፍራ ባዶውን ነበረ።'),
  ('53ed4321-091d-5b40-af2a-c21da1d9bad6', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 26, 26, 'ሳኦልም፥ “አንድ ነገር ሆኖ ይሆናል፤ ምንአልባትም ንጹሕ አይደለም ይሆናል፤ በእውነትም ንጹሕ አይደለም” ብሎ አስቦአልና በዚያ ቀን ምንም አልተናገረም።'),
  ('c870bd48-99a1-5e7d-a4ee-97cc23609e53', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 27, 27, 'ከመባቻም በኋላ በማግሥቱ በሁለተኛው ቀን የዳዊት ስፍራ ባዶውን ነበረ፤ ሳኦልም ልጁን ዮናታንን፥ “የእሴይ ልጅ ትናትና ዛሬ ወደ ግብር ያልመጣ ስለምን ነው?” አለው።'),
  ('ade6e6cd-08c7-5d5d-a9f8-06e04b010092', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 28, 28, 'ዮናታንም ለሳኦል፥ “ዳዊት ወደ ከተማው ወደ ቤተ ልሔም ይሄድ ዘንድ ነግሮኝ ተሰናብቶኛል።'),
  ('ad01e7ce-fa4c-5302-a91d-ae68175df5c5', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 29, 29, 'እርሱም፥ “ዘመዶቼ በከተማ ውስጥ መሥዋዕት አላቸውና፥ ወንድሞቼም ጠርተውኛልና እባክህ! አሰናብተኝ፤ አሁንም በዐይኖችህ ሞገስ አግኝቼ እንደ ሆነ ልሂድና ወንድሞቼን ልይ አለ፤ ስለዚህ ወደ ንጉሥ ማዕድ አልመጣም” ብሎ መለሰለት።'),
  ('9b253856-da99-57c5-ae36-2d241fc61c10', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 30, 30, 'ሳኦልም በዮናታን ላይ እጅግ ተቈጣ፥ “አንተ የከዳተኞች ሴቶች ልጅ! የእሴይን ልጅ ለአንተ ማፈርያ፥ ለእናትህም ኀፍረተ ሥጋ ማፈርያ እንደ መረጥህ እኔ አላውቅምን?'),
  ('0ced1ef8-742a-55a2-a3a6-a33e3d5c2cb4', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 31, 31, 'የእሴይ ልጅ በምድር ላይ በሕይወት በሚኖርበት ዘመን ሁሉ መንግሥትህ አትጸናም፤ አሁንም ሞት የሚገባው ነውና ያን ብላቴና ያመጡት ዘንድ ላክ” አለው።'),
  ('98d599e2-b88a-5d0e-ac3f-12535a7b483a', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 32, 32, 'ዮናታንም ለአባቱ ለሳኦል፥ “ስለ ምን ይሞታል? ምንስ አደረገ?” ብሎ መለሰለት።'),
  ('dda9b433-40d1-557c-ad63-4055e4af26c1', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 33, 33, 'ሳኦልም ሊገድለው በዮናታን ላይ ጦሩን አነሣ፤ ዮናታንም አባቱ ዳዊትን ይገድለው ዘንድ ያች ክፉ ነገር እንደ ተቈረጠች ዐወቀ።'),
  ('c4ed9f2b-02b4-508a-aca9-eb303ebb1827', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 34, 34, 'አባቱ በእርሱ ላይ ክፉ ነገርን ሊያደርግ ስለ ቈረጠ ዮናታን ስለ ዳዊት አዝኖአልና እጅግ ተቈጥቶ ከማዕዱ ተነሣ፤ በመባቻውም በሁለተኛው ቀን ግብር አልበላም።'),
  ('1020f7ef-802b-5f3d-a3be-65a82c2719b6', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 35, 35, 'እንዲህም ሆነ በነጋው ዮናታን ከዳዊት ጋር ምልክት ለማድረግ ወደ ተቃጠረበት ቦታ ወደ ሜዳ ወጣ፤ ከእርሱም ጋር ታናሽ ብላቴና ነበረ።'),
  ('4125f87e-3ead-5475-a17d-7551db5a29a5', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 36, 36, 'ብላቴናውንም፥ “ሮጠህ የምወረውራቸውን ፍላጻዎች ፈልግልኝ” አለው። ብላቴናውም በሮጠ ጊዜ ዮናታን ፍላጻውን ወደ ማዶ አሳልፎ ወረወረው።'),
  ('0da57faa-6f5c-5589-a1f9-69e72a9338a4', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 37, 37, 'ብላቴናውም ዮናታን ፍላጻውን ወደ ወረወረበት ስፍራ በመጣ ጊዜ ዮናታን፥ “ፍላጻው ከአንተ ወዲያ ነው” ብሎ ወደ ብላቴናው ጮኸ።'),
  ('5b392073-a9ec-57ac-a2f0-ca343053ee5a', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 38, 38, 'ዮናታንም ደግሞ፥ “ቶሎ ፍጠን፤ አትቈይ” ብሎ ወደ ብላቴናው ጮኸ፤ የዮናታንም ብላቴና ፍላጻዎቹን ሰብስቦ ወደ ጌታው መጣ።'),
  ('961431f9-3f3a-5720-accd-83a48d65b317', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 39, 39, 'ዮናታንና ዳዊት ብቻ ነገሩን ያውቁ ነበር እንጂ ብላቴናው ምንም አያውቅም ነበር።'),
  ('04fe7e32-cec1-551f-a42c-6ce05d74a8b8', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 40, 40, 'ዮናታንም መሣሪያውን ለብላቴናው ሰጥቶ፥ “ሂድ ወደ ከተማ ግባ” አለው።'),
  ('28c2ea36-de27-5d24-a3cf-b5b2ad0c207c', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 41, 41, 'ብላቴናውም በሄደ ጊዜ ዳዊት ከኤርገብ ተነሣ፤ በምድርም ላይ በግንባሩ ተደፋ፤ ሦስት ጊዜም ሰገደ፤ እርስ በእርሳቸውም ተሳሳሙ፤ ለረዥም ሰዓትም ተላቀሱ።'),
  ('97248305-748a-5998-a649-d2423d52d7f6', '517ca8ac-4bf7-527c-ad6c-67a062447d0c', 'c61bc620-3757-57c4-ae7c-dd99df6d122f', 42, 42, 'ዮናታንም ዳዊትን፥ “በሰላም ሂድ፤ እነሆ፥ እኛ ሁለታችን በእኔና በአንተ፥ በዘሬና በዘርህ መካከል እግዚአብሔር ለዘለዓለም ምስክር ይሁን ብለን በእግዚአብሔር ስም ተማምለናል” አለው። ዳዊትም ተነሥቶ ሄደ፤ ዮናታንም ወደ ከተማ ገባ።'),
  ('3d67494a-82af-595f-a5db-c2282e1d5720', 'ba2a2a25-78f0-576e-a4e1-efe3a611370f', 'bda887a7-f765-5c18-a1ee-ba3f5f8d6a32', 1, 1, 'ዳዊትም ወደ ካህኑ ወደ አቤሜሌክ ወደ ኖብ መጣ፤ አቤሜሌክም እርሱን በተገናኘው ጊዜ ደነገጠ፥ “ስለምን አንተ ብቻህን ነህ? ከአንተስ ጋር ስለምን ማንም የለም?” አለው።'),
  ('11f47d9f-d7cc-543e-a949-ed4d2a72c5c6', 'ba2a2a25-78f0-576e-a4e1-efe3a611370f', 'bda887a7-f765-5c18-a1ee-ba3f5f8d6a32', 2, 2, 'ዳዊትም ካህኑን አቤሜሌክን፥ “የተላክህበትን ነገርና የሰጠሁህን ትእዛዝ ማንም አይወቅ ብሎ ንጉሡ አንድ ነገር አዝዞኛል፤ ስለዚህም ‘ብላቴኖቼን በእግዚአብሔር መታመን’ በሚባለው እንዲህ ባለው ስፍራ እንዲሆኑ አዝዣቸዋለሁ።'),
  ('24f10e1b-1da3-592c-a9da-8f0bbd40f815', 'ba2a2a25-78f0-576e-a4e1-efe3a611370f', 'bda887a7-f765-5c18-a1ee-ba3f5f8d6a32', 3, 3, 'አሁንም አምስት እንጀራ በእጅህ ካለ፥ ወይም በእጅህ ያለውን ስጠኝ” አለው።'),
  ('3b55d678-bd34-5779-a4de-509d7d6fcaa3', 'ba2a2a25-78f0-576e-a4e1-efe3a611370f', 'bda887a7-f765-5c18-a1ee-ba3f5f8d6a32', 4, 4, 'ካህኑም ለዳዊት መልሶ፥ “ሁሉ የሚበላው እንጀራ የለኝም፤ ነገር ግን የተቀደሰ እንጀራ አለ፤ ብላቴኖቹ ከሴቶች ንጹሓን እንደ ሆኑ መብላት ይችላሉ” አለው።'),
  ('d4c93fd5-0d6e-57fe-ac83-214d151c78bd', 'ba2a2a25-78f0-576e-a4e1-efe3a611370f', 'bda887a7-f765-5c18-a1ee-ba3f5f8d6a32', 5, 5, 'ዳዊትም ለካህኑ መልሶ፥ “ከሴቶች ተለይተን ወደ መንገድ ከወጣን ዛሬ ሦስተኛ ቀናችን ነው። እኔም ብላቴኖቼም ንጹሓን ነን። ነገር ግን ዛሬ ሰውነቴ ንጽሕት ስለ ሆነች ነው እንጂ ይህች መንገድ የነጻች አይደለችም” አለው።'),
  ('02c1b5cb-8872-59a0-a503-7f6fa77d7448', 'ba2a2a25-78f0-576e-a4e1-efe3a611370f', 'bda887a7-f765-5c18-a1ee-ba3f5f8d6a32', 6, 6, 'ካህኑ አቤሜሌክም በእርሱ ፋንታ ትኩስ እንጀራ ይደረግ ዘንድ በእግዚአብሔር ፊት ከአለው ኅብስት በቀር ሌላ እንጀራ አልነበረምና የቍርባኑን ኅብስት ሰጠው።'),
  ('7a49ae39-078c-5a3c-a790-2a134f98c7ca', 'ba2a2a25-78f0-576e-a4e1-efe3a611370f', 'bda887a7-f765-5c18-a1ee-ba3f5f8d6a32', 7, 7, 'በዚያም ቀን ከሳኦል አገልጋዮች አንድ ሰው በኔሴራ አቅራቢያ በዚያ በእግዚአብሔር ፊት ነበር፤ ስሙም ሶርያዊው ዶይቅ ነበረ፤ የሳኦልም በቅሎዎች ጠባቂ ነበረ።'),
  ('e9bf741b-1d49-5986-aa4c-0170383da08b', 'ba2a2a25-78f0-576e-a4e1-efe3a611370f', 'bda887a7-f765-5c18-a1ee-ba3f5f8d6a32', 8, 8, 'ዳዊትም አቤሜሌክን፥ “የንጉሥ ጉዳይ ስላስቸኰለኝ ሰይፌንና መሣሪያዬን አላመጣሁምና በአንተ ዘንድ ጦር ወይም ሰይፍ እንዳለ እይልኝ” አለው።'),
  ('6b73f5be-2880-539b-aeea-af78f80b2f59', 'ba2a2a25-78f0-576e-a4e1-efe3a611370f', 'bda887a7-f765-5c18-a1ee-ba3f5f8d6a32', 9, 9, 'ካህኑም፥ “በኤላ ሸለቆ የገደልኸው የፍልስጥኤማዊው የጎልያድ ሰይፍ እነሆ፥ በመጐናጸፊያ ተጠቅልላ አለች፤ የምትወስዳት ከሆነ ውሰዳት፤ ከእርስዋ በቀር ሌላ ከዚህ የለምና” አለው። ዳዊትም፥ “ከእርስዋ በቀር ሌላ ከሌለ እርስዋን ስጠኝ” አለው። እርሱም ሰጠው።'),
  ('64ffe48d-de9a-5434-acc4-a7ac7105c8bd', 'ba2a2a25-78f0-576e-a4e1-efe3a611370f', 'bda887a7-f765-5c18-a1ee-ba3f5f8d6a32', 10, 10, 'ዳዊትም ተነሣ በዚያም ቀን ከሳኦል ፊት ሸሸ፤ ወደ ጌትም ንጉሥ ወደ አንኩስ መጣ።'),
  ('efac8e84-faff-57bc-a718-77451775b289', 'ba2a2a25-78f0-576e-a4e1-efe3a611370f', 'bda887a7-f765-5c18-a1ee-ba3f5f8d6a32', 11, 11, 'የአንኩስ ብላቴኖችም፥ “ይህ ዳዊት የሀገሩ ንጉሥ አይደለምን? ሳኦል ሺህ፥ ዳዊትም ዐሥር ሺህ ገደለ ብለው ሴቶች በዘፈን የዘመሩለት እርሱ አይደለምን?” አሉት።'),
  ('cb77a2cb-a82e-51a5-a1b1-021bfc606d1d', 'ba2a2a25-78f0-576e-a4e1-efe3a611370f', 'bda887a7-f765-5c18-a1ee-ba3f5f8d6a32', 12, 12, 'ዳዊትም ይህን ቃል በልቡ አኖረ፤ የጌትንም ንጉሥ አንኩስን እጅግ ፈራ።'),
  ('0d0fc16f-1d85-5230-a5bb-7f921d07be3a', 'ba2a2a25-78f0-576e-a4e1-efe3a611370f', 'bda887a7-f765-5c18-a1ee-ba3f5f8d6a32', 13, 13, 'በፊቱም መልኩን ለወጠ፤ በዚያችም ቀን አመለጠ። በከተማውም በር ከበሮ ይዞ በእጁ መታ፤ በበሩም መድረክ ላይ ተንፈራፈረ፤ ልጋጉም በጢሙ ላይ ይወርድ ነበር።'),
  ('1cd240d9-bfac-5b50-a849-a2f41b8c2953', 'ba2a2a25-78f0-576e-a4e1-efe3a611370f', 'bda887a7-f765-5c18-a1ee-ba3f5f8d6a32', 14, 14, 'አንኩስም ብላቴኖቹን፥ “እነሆ፥ ይህ ሰው እብድ እንደ ሆነ አይታችኋል፤ ለምን ወደ እኔ አመጣችሁት?'),
  ('20bfd710-c6bc-5d54-ae4c-eea75a59ab85', 'ba2a2a25-78f0-576e-a4e1-efe3a611370f', 'bda887a7-f765-5c18-a1ee-ba3f5f8d6a32', 15, 15, 'በፊቴ ያብድ ዘንድ ይህን ያመጣችሁት እኔ የእብዶች አለቃ ነኝን? እንዲህ ያለውስ ወደ ቤቴ ይገባልን?” አላቸው።'),
  ('a31e972c-45ad-594b-a8fa-8f838df158e9', '96015e59-e0d6-56db-a38e-2d4f18aaa048', '93cc199e-e410-5f40-a758-05fc958eb116', 1, 1, 'ዳዊትም ከዚያ ተነሥቶ አመለጠ፤ ወደ ዔዶላም ዋሻም መጣ፤ ወንድሞቹና የአባቱ ቤተ ሰብ ሁሉ ይህን በሰሙ ጊዜ ወደ እርሱ ወደዚያ ወረዱ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('d416e6af-89fb-50d5-ab42-aa7b85c32115', '96015e59-e0d6-56db-a38e-2d4f18aaa048', '93cc199e-e410-5f40-a758-05fc958eb116', 2, 2, 'የተጨነቀም ሁሉ፥ ዕዳም ያለበት ሁሉ፥ የተከፋም ሁሉ ወደ እርሱ ተሰባሰበ፤ እርሱም በላያቸው አለቃ ሆነ፤ ከእርሱም ጋር አራት መቶ የሚያህሉ ሰዎች ነበሩ።'),
  ('8da9fb66-bdd4-50ca-af29-e31c2081b4ff', '96015e59-e0d6-56db-a38e-2d4f18aaa048', '93cc199e-e410-5f40-a758-05fc958eb116', 3, 3, 'ዳዊትም ከዚያ በሞዓብ ምድር ወዳለችው ወደ መሴፋ ሄደ፤ የሞዓብንም ንጉሥ፥ “እግዚአብሔር የሚያደርግልኝን እስካውቅ ድረስ አባቴና እናቴ ከአንተ ጋር ይቀመጡ ዘንድ እለምንሃለሁ” አለው።'),
  ('24075131-5675-5e14-a346-bafab9849be1', '96015e59-e0d6-56db-a38e-2d4f18aaa048', '93cc199e-e410-5f40-a758-05fc958eb116', 4, 4, 'የሞዓብንም ንጉሥ ማለደው፤ ዳዊትም በአንባ ውስጥ በነበረበት ወራት ሁሉ በእርሱ ዘንድ ተቀመጡ።'),
  ('948a995e-58f1-57b0-a6e6-6bb24e4e7d99', '96015e59-e0d6-56db-a38e-2d4f18aaa048', '93cc199e-e410-5f40-a758-05fc958eb116', 5, 5, 'ነቢዩ ጋድም ዳዊትን፥ “ተነሥተህ ወደ ይሁዳ ምድር ሂድ እንጂ በአንባው ውስጥ አትቀመጥ” አለው፤ ዳዊትም ሄደ፤ ወደ ሳሬቅ ከተማም መጥቶ ተቀመጠ፤'),
  ('fc4647db-d5cd-5e27-a3fd-38d6f8e90baa', '96015e59-e0d6-56db-a38e-2d4f18aaa048', '93cc199e-e410-5f40-a758-05fc958eb116', 6, 6, 'ሳኦልም ዳዊትና ከእርሱ ጋር የነበሩት ሰዎች ያሉበት ቦታ እንደ ታወቀ ሰማ። ሳኦልም በራማ በሚገኘው በመሰማርያው ቦታ በኮረብታው ላይ ተቀምጦ በእጁም ጦር ይዞ ነበር፤ ብላቴኖቹም ሁሉ በአጠገቡ ቆመው ነበር።'),
  ('c4a4696f-84a2-59ad-a10f-5460f05f81e7', '96015e59-e0d6-56db-a38e-2d4f18aaa048', '93cc199e-e410-5f40-a758-05fc958eb116', 7, 7, 'ሳኦልም በአጠገቡ የቆሙትን ብላቴኖች፥ “ብንያማውያን ሆይ! እንግዲህ ስሙ በእውነት የእሴይ ልጅ እርሻና የወይን ቦታ ለሁላችሁ ይሰጣችኋልን? ሁላችሁንስ መቶ አለቆችና ሻለቆች ያደርጋችኋልን?'),
  ('c7088dc4-13aa-591f-a52c-87782cb64016', '96015e59-e0d6-56db-a38e-2d4f18aaa048', '93cc199e-e410-5f40-a758-05fc958eb116', 8, 8, 'ሁላችሁ በላዬ ዶልታችሁ ተነሣችሁብኝ፤ ልጄ ከእሴይ ልጅ ጋር ሲማማል ማንም አልገለጠልኝም፤ ከእናንተም አንድ ለእኔ የሚያዝን የለም፤ ዛሬም እንደ ሆነው ሁሉ ልጄ አገልጋዬን እንዲዶልት ሲያስነሣብኝ ማንም አላስታወቀኝም” አላቸው።'),
  ('37a7b9d4-56bb-51ba-a896-cb922bb6d5ce', '96015e59-e0d6-56db-a38e-2d4f18aaa048', '93cc199e-e410-5f40-a758-05fc958eb116', 9, 9, 'የሳኦልም በቅሎዎች ጠባቂ ሶርያዊው ዶይቅ መልሶ፥ “የእሴይ ልጅ ወደ ኖብ ወደ አኪጦብ ልጅ ወደ ካህኑ አቤሜሌክ ሲመጣ አይቼዋለሁ።'),
  ('d77cc439-7f77-5f34-aae2-c1e159d264c3', '96015e59-e0d6-56db-a38e-2d4f18aaa048', '93cc199e-e410-5f40-a758-05fc958eb116', 10, 10, 'እግዚአብሔርንም ጠየቀለት፤ ስንቅንም ሰጠው፤ የፍልስጥኤማዊውንም የጎልያድን ሰይፍ ሰጠው” አለው።'),
  ('5ec2ead5-bc49-5091-aaa6-930446c33c96', '96015e59-e0d6-56db-a38e-2d4f18aaa048', '93cc199e-e410-5f40-a758-05fc958eb116', 11, 11, 'ንጉሡም የአኪጦብን ልጅ ካህኑን አቤሜሌክን፥ በኖብም ያሉትን ካህናት፥ የአባቱን ልጆች ሁሉ ልኮ አስጠራቸው፤ ሁላቸውም ወደ ንጉሡ መጡ።'),
  ('b3135dca-4c84-5d9f-a7da-d088b1c31975', '96015e59-e0d6-56db-a38e-2d4f18aaa048', '93cc199e-e410-5f40-a758-05fc958eb116', 12, 12, 'ሳኦልም፥ “የአኪጦብ ልጅ ሆይ! እንግዲህ ስማ” አለ፤ እርሱም፥ “እነሆኝ ጌታዬ ሆይ” ብሎ መለሰ።'),
  ('22bea3ee-e00e-54a1-aae3-6bffef7e0f16', '96015e59-e0d6-56db-a38e-2d4f18aaa048', '93cc199e-e410-5f40-a758-05fc958eb116', 13, 13, 'ሳኦልም፥ “አንተ ከእሴይ ልጅ ጋር ለምን ዶለትህብኝ? እንጀራና ሰይፍ ሰጠኸው፤ ዛሬም እንደ ተደረገው ጠላት ሆኖ ይነሣብኝ ዘንድ እግዚአብሔርን ስለ እርሱ ጠየቅህለት” አለው።'),
  ('96569242-b8df-554e-a89c-db6eaaec61ef', '96015e59-e0d6-56db-a38e-2d4f18aaa048', '93cc199e-e410-5f40-a758-05fc958eb116', 14, 14, 'አቤሜሌክም መልሶ ንጉሡን፥ “ከባሪያዎቹ ሁሉ የታመነ፥ ለንጉሥም አማች የሆነ፥ የትእዛዝህ ሁሉ አለቃ፥ በቤትህም የከበረ እንደ ዳዊት ያለ ማን ነው?'),
  ('c829417e-e9b2-5360-a111-63283c989b8f', '96015e59-e0d6-56db-a38e-2d4f18aaa048', '93cc199e-e410-5f40-a758-05fc958eb116', 15, 15, 'በውኑ ስለ እርሱ እግዚአብሔርን እጠይቅ ዘንድ ዛሬ ጀመርሁን? ይህ ከእኔ ይራቅ፤ እኔ ባሪያህ ይህን ሁሉ ትልቅ ወይም ጥቂት ቢሆን አላውቅምና ንጉሡ እንደዚህ ያለውን ነገር በእኔ በባሪያውና በአባቴ ቤት ሁሉ ላይ አያኑር” አለ።'),
  ('5f66adf0-7d57-5146-a195-cca324c86800', '96015e59-e0d6-56db-a38e-2d4f18aaa048', '93cc199e-e410-5f40-a758-05fc958eb116', 16, 16, 'ንጉሡም፥ “አቤሜሌክ ሆይ! አንተና የአባትህ ቤት ሁሉ ፈጽማችሁ ትሞታላችሁ” አለ።'),
  ('936eb820-99bf-5807-aa16-dc66458ebb8c', '96015e59-e0d6-56db-a38e-2d4f18aaa048', '93cc199e-e410-5f40-a758-05fc958eb116', 17, 17, 'ንጉሡም በዙሪያው የቆሙትን እግረኞች፥ “የእግዚአብሔር ካህናት እጅ ከዳዊት ጋር ነውና፥ ኵብለላውንም ሲያውቁ አልነገሩኝምና፥ ዞራችሁ ግደሉአቸው” አላቸው። የንጉሡ አገልጋዮች ግን እጃቸውን በእግዚአብሔር ካህናት ላይ ይዘረጉ ዘንድ እንቢ አሉ።'),
  ('56faff4a-27a3-5d8b-a843-fc00f88bcd58', '96015e59-e0d6-56db-a38e-2d4f18aaa048', '93cc199e-e410-5f40-a758-05fc958eb116', 18, 18, 'ንጉሡም ዶይቅን፥ “አንተ ዞረህ ካህናቱን ግደላቸው” አለው። ሶርያዊው ዶይቅም ዞሮ ካህናቱን ገደላቸው፤ በዚያም ቀን የበፍታ ኤፉድ የለበሱትን ሦስት መቶ ሰማንያ አምስት ሰዎችን ገደለ።'),
  ('584cf51c-8581-58b4-a613-6c0df9f8cfee', '96015e59-e0d6-56db-a38e-2d4f18aaa048', '93cc199e-e410-5f40-a758-05fc958eb116', 19, 19, 'የካህናቱንም ከተማ ኖብን በሰይፍ ስለት መታ፤ ወንዶችንና ሴቶችንም፥ ብላቴኖችንና ጡት የሚጠቡትን፥ በሬዎችንና አህዮችንም፥ በጎችንም በሰይፍ ስለት ገደለ።'),
  ('d992200c-244b-5ef6-aa2a-0d8bd04c497c', '96015e59-e0d6-56db-a38e-2d4f18aaa048', '93cc199e-e410-5f40-a758-05fc958eb116', 20, 20, 'ከአኪጦብም ልጅ ከአቤሜሌክ ልጆች ስሙ አብያታር የሚባል አንዱ ልጅ አምልጦ ሸሸ፤ ዳዊትንም ተከተለ።'),
  ('92eeff6e-4442-588e-ade2-5167174b6573', '96015e59-e0d6-56db-a38e-2d4f18aaa048', '93cc199e-e410-5f40-a758-05fc958eb116', 21, 21, 'አብያታርም ሳኦል የእግዚአብሔርን ካህናት እንደ ፈጀ ለዳዊት ነገረው።'),
  ('d1777a36-2e21-57a3-aaf8-7456ef5d1d29', '96015e59-e0d6-56db-a38e-2d4f18aaa048', '93cc199e-e410-5f40-a758-05fc958eb116', 22, 22, 'ዳዊት አብያታርን፦ ሶርያዊው ዶይቅ በዚያ መኖሩን ባየሁ ጊዜ፥ “ለሳኦል በርግጥ ይነግራል ብዬ በዚያ ቀን አውቄዋለሁ፤ ለአባትህ ቤት ነፍስ ሁሉ ጥፋት በደለኛው እኔ ነኝ።'),
  ('25fd8a68-6335-5881-aa13-837e305d6ab6', '96015e59-e0d6-56db-a38e-2d4f18aaa048', '93cc199e-e410-5f40-a758-05fc958eb116', 23, 23, 'እንግዲህ ወዲህ ከእኔ ጋር ተቀመጥ፤ አትፍራ፤ ለእኔ ነፍስ የደኅንነት ቦታን እንደምፈልግ ለአንተም ነፍስ የደኅንነት ቦታን እፈልጋለሁና፥ ከእኔም ጋር ተጠብቀህ ትኖራለህ” አለው።'),
  ('dcba83f0-4c8e-57ad-a36f-3715f20ea891', '5dff6806-0103-5490-af20-4a386b23d190', 'f19f3c33-81e7-505b-a7f4-7af9433fc65e', 1, 1, 'ለዳዊትም፥ “እነሆ፥ ፍልስጥኤማውያን ቂአላን ይወጋሉ፤ አውድማውንም ይዘርፋሉ” ብለው ነገሩት።'),
  ('6948ebfa-d312-5816-a9ef-99c7ac0ab101', '5dff6806-0103-5490-af20-4a386b23d190', 'f19f3c33-81e7-505b-a7f4-7af9433fc65e', 2, 2, 'ዳዊትም፥ “ልሂድን? እነዚህንስ ፍልስጥኤማውያንን ልምታን?” ብሎ እግዚአብሔርን ጠየቀ፤ እግዚአብሔርም፥ “ሂድ፤ ፍልስጥኤማውያንን ምታ፤ ቂአላንም አድን” አለው።'),
  ('6f51734a-f85a-5b6d-a3ed-c7426dfd4bcd', '5dff6806-0103-5490-af20-4a386b23d190', 'f19f3c33-81e7-505b-a7f4-7af9433fc65e', 3, 3, 'የዳዊትም ሰዎች፥ “እነሆ፥ በዚህ በይሁዳ መቀመጥ እንፈራለን፤ ይልቁንስ ፍልስጥኤማውያንን ለመዝረፍ ወደ ቂአላ ብንሄድ እንዴት እንሆናለን?” አሉት።'),
  ('2cab2a41-7931-5878-a020-94feb73cebc0', '5dff6806-0103-5490-af20-4a386b23d190', 'f19f3c33-81e7-505b-a7f4-7af9433fc65e', 4, 4, 'ዳዊትም ደግሞ እግዚአብሔርን ጠየቀ፤ እግዚአብሔርም መልሶ፥ “ፍልስጥኤማውያንን በእጅህ አሳልፌ እሰጣለሁና ተነሥተህ ወደ ቂአላ ውረድ” አለው።'),
  ('25cab88d-afdd-5655-aa34-32032f080717', '5dff6806-0103-5490-af20-4a386b23d190', 'f19f3c33-81e7-505b-a7f4-7af9433fc65e', 5, 5, 'ዳዊትና ሰዎቹም ወደ ቂአላ ሄዱ፤ ከፍልስጥኤማውያንም ጋር ተዋጉ፤ እነርሱም ከፊቱ ሸሹ፤ እንስሶቻቸውንም ማረኩ፤ በታላቅም አገዳደል ገደሉአቸው። ዳዊትም በቂአላ የሚኖሩትን አዳነ።'),
  ('d61348a0-84c7-5dc2-a426-f9e4b4c0e2f9', '5dff6806-0103-5490-af20-4a386b23d190', 'f19f3c33-81e7-505b-a7f4-7af9433fc65e', 6, 6, 'እንዲህም ሆነ፤ የአቤሜሌክ ልጅ አብያታር ወደ ዳዊት ወደ ቂአላ በኰበለለ ጊዜ ኤፉዱን ይዞ ወርዶ ነበር።'),
  ('84919e9a-b31e-57cf-a61b-ceef8cfa2136', '5dff6806-0103-5490-af20-4a386b23d190', 'f19f3c33-81e7-505b-a7f4-7af9433fc65e', 7, 7, 'ለሳኦልም ዳዊት ወደ ቂአላ እንደ መጣ ተነገረው፤ ሳኦልም፥ “መዝጊያና መወርወሪያ ወዳለባት ከተማ ገብቶ ተገኝቶአልና እግዚአብሔር በእጄ አሳልፎ ሰጥቶታል” አለ።'),
  ('8d35b936-9898-53b9-a661-522222b8e707', '5dff6806-0103-5490-af20-4a386b23d190', 'f19f3c33-81e7-505b-a7f4-7af9433fc65e', 8, 8, 'ሳኦልም ወደ ቂአላ ወርደው ይዋጉ ዘንድ፥ ዳዊትንና ሰዎቹንም ይከብቡ ዘንድ ሕዝቡን ሁሉ አዘዘ።'),
  ('d9b95832-b6cd-5a97-ae1e-9b0a394cb4ad', '5dff6806-0103-5490-af20-4a386b23d190', 'f19f3c33-81e7-505b-a7f4-7af9433fc65e', 9, 9, 'ዳዊትም ሳኦል በእርሱ ለክፋት ዝም እንደማይል ዐወቀ፤ ዳዊትም ካህኑን አብያታርን፥ “የእግዚአብሔርን ኤፉድ ወደዚህ አምጣ” አለው።'),
  ('eb4659c3-6234-51d0-a5e3-f1dee5ca79b0', '5dff6806-0103-5490-af20-4a386b23d190', 'f19f3c33-81e7-505b-a7f4-7af9433fc65e', 10, 10, 'ዳዊትም፥ “የእስራኤል አምላክ አቤቱ! በእኔ ምክንያት ከተማዪቱን ያጠፋ ዘንድ ሳኦል ወደ ቂአላ ሊመጣ እንደሚፈልግ እኔ ባሪያህ ፈጽሜ ሰምቻለሁ።'),
  ('ee668059-c680-5c29-a4fd-188f05f49db4', '5dff6806-0103-5490-af20-4a386b23d190', 'f19f3c33-81e7-505b-a7f4-7af9433fc65e', 11, 11, 'የቂአላ ሰዎችስ ይከበባሉን? ባሪያህስ እንደ ሰማ ሳኦል በውኑ ይወርዳልን? የእስራኤል አምላክ አቤቱ! ለባርያህ ንገረው” አለ። እግዚአብሔርም፥ “ይወርዳል” አለ።'),
  ('030c95c5-46d1-553e-a31a-30c2fb05f4ba', '5dff6806-0103-5490-af20-4a386b23d190', 'f19f3c33-81e7-505b-a7f4-7af9433fc65e', 12, 12, 'ዳዊትም፥ “የቂአላ ሰዎች እኔንና ሰዎቼን በሳኦል እጅ አሳልፈው ይሰጡናልን?” አለ። እግዚአብሔርም፥ “አሳልፈው ይሰጡአችኋል” ብሎ ተናገረ።'),
  ('59ea958f-ac8d-59bc-a0a5-e29f0f5315c1', '5dff6806-0103-5490-af20-4a386b23d190', 'f19f3c33-81e7-505b-a7f4-7af9433fc65e', 13, 13, 'ዳዊትና ስድስት መቶ የሚሆኑ ሰዎችም ተነሥተው ከቂአላ ወጡ፤ ወደሚሄድበትም ይከተሉት ነበር። ሳኦልም ዳዊት ከቂአላ እንደ ሸሸ ሰማ፤ ስለዚህም ከመውጣት ቀረ።'),
  ('fc35622c-0b41-506c-a65b-a10086fef213', '5dff6806-0103-5490-af20-4a386b23d190', 'f19f3c33-81e7-505b-a7f4-7af9433fc65e', 14, 14, 'ዳዊትም በምድረ በዳ በጠባቡ በማሴሬም ይኖር ነበር፥ በአውክሞዲስ ውስጥም በዚፍ ተራራ ምድረ በዳ ተቀመጠ፤ ሳኦልም ሁልጊዜ ይፈልገው ነበር፤ እግዚአብሔር ግን በእጁ አሳልፎ አልሰጠውም።'),
  ('2ebb3537-a571-57a4-a4cc-5ad527e86dbd', '5dff6806-0103-5490-af20-4a386b23d190', 'f19f3c33-81e7-505b-a7f4-7af9433fc65e', 15, 15, 'ዳዊትም ሳኦል ሊፈልገው እንደ ወጣ አየ፤ ዳዊትም በቄኒ ዚፍ ምድረ በዳ በአውክሞዲስ ውስጥ ይኖር ነበር።'),
  ('9a3de3ba-3f8f-552b-a32e-c9cb9738929e', '5dff6806-0103-5490-af20-4a386b23d190', 'f19f3c33-81e7-505b-a7f4-7af9433fc65e', 16, 16, 'የሳኦልም ልጅ ዮናታን ተነሥቶ ወደ ዳዊት ወደ ቄኒ ሄደ። እጁንም በእግዚአብሔር አጸና።'),
  ('34024c7f-e02a-59c8-afff-6ebc929ef3a3', '5dff6806-0103-5490-af20-4a386b23d190', 'f19f3c33-81e7-505b-a7f4-7af9433fc65e', 17, 17, 'ለእርሱም “የአባቴ የሳኦል እጅ አታገኝህምና አትፍራ፤ አንተም በእስራኤል ላይ ንጉሥ ትሆናለህ፤ እኔም ከአንተ በታች እሆናለሁ፤ ይህን ደግሞ አባቴ ሳኦል ያውቃል” አለው።'),
  ('8a721587-11ab-5a6f-ad4a-5e5482792a51', '5dff6806-0103-5490-af20-4a386b23d190', 'f19f3c33-81e7-505b-a7f4-7af9433fc65e', 18, 18, 'ሁለቱም በእግዚአብሔር ፊት ቃል ኪዳን አደረጉ፤ ዳዊትም በቄኒ ውስጥ ተቀመጠ፤ ዮናታንም ወደ ቤቱ ሄደ።'),
  ('fdfc25c0-6439-52e8-ae3a-1ad28f6ec046', '5dff6806-0103-5490-af20-4a386b23d190', 'f19f3c33-81e7-505b-a7f4-7af9433fc65e', 19, 19, 'የዚፍ ሰዎችም ከአውክሞዲስ ወደ ሳኦል ወደ ኮረብታው ወጥተው እንዲህ አሉት፥ “እነሆ፥ ዳዊት በየሴሞን ቀኝ በጠባቡ በኩል በኤኬላ ኮረብታ ላይ በቄኒ ውስጥ በማሴሬት በእኛ ዘንድ ተሸሽጎ የለምን?'),
  ('631eb86e-369e-5394-a2de-09e87306b793', '5dff6806-0103-5490-af20-4a386b23d190', 'f19f3c33-81e7-505b-a7f4-7af9433fc65e', 20, 20, 'አሁንም፦ ንጉሥ ሆይ! ለመውረድ ፈቃድህ ከሆነ ወደ እኛ ውረድ፤ በንጉሡ እጅ ጥሎታልና።”'),
  ('c87dc0c7-333c-5e1b-acbd-9bb1f8e3fafb', '5dff6806-0103-5490-af20-4a386b23d190', 'f19f3c33-81e7-505b-a7f4-7af9433fc65e', 21, 21, 'ሳኦልም አለ፥ “እናንተ ስለ እኔ አዝናችኋልና በእግዚአብሔር ዘንድ የተባረካችሁ ሁኑ፤'),
  ('b0ee9bd3-871f-5b62-a7da-f0096b510e80', '5dff6806-0103-5490-af20-4a386b23d190', 'f19f3c33-81e7-505b-a7f4-7af9433fc65e', 22, 22, 'አሁንም ደግሞ ሂዱና አዘጋጁ፤ የተናገራችሁትንም፥ ያለበትንም ቦታ ሁሉ እንዳያታልላችሁ ፈጥናችሁ ዕወቁ።'),
  ('261cf51b-45e5-58d8-a365-cf7d3d1d1b1a', '5dff6806-0103-5490-af20-4a386b23d190', 'f19f3c33-81e7-505b-a7f4-7af9433fc65e', 23, 23, 'እንግዲህ ዕወቁ፤ ከአያችሁ በኋላ ከእናንተ ጋር እንሄዳለን፤ በዚያችም ምድር ካለ በይሁዳ አእላፍ ሁሉ እፈትሻታለሁ።”'),
  ('75b25b24-2d0b-506f-a67a-d7da00e956a6', '5dff6806-0103-5490-af20-4a386b23d190', 'f19f3c33-81e7-505b-a7f4-7af9433fc65e', 24, 24, 'የዚፍ ሰዎችም ተነሥተው ከሳኦል በፊት ሄዱ፤ ዳዊትና ሰዎቹ ግን በየሴሞን ቀኝ በኩል በዓረባ በማዖን ምድረ በዳ ነበሩ።'),
  ('8199e9f3-5b8a-5a51-ad80-91213db54048', '5dff6806-0103-5490-af20-4a386b23d190', 'f19f3c33-81e7-505b-a7f4-7af9433fc65e', 25, 25, 'ሳኦልና ሰዎቹም ሊፈልጉት ሄዱ፤ ለዳዊትም ነገሩት፤ እርሱም በማዖን ምድረ በዳ ወዳለው ዓለት ወረደ፤ ሳኦልም ያን በሰማ ጊዜ ዳዊትን በማዖን ምድረ በዳ ተከትሎ አሳደደው።'),
  ('9a9a9614-ce4a-5fa6-a213-903025fddb29', '5dff6806-0103-5490-af20-4a386b23d190', 'f19f3c33-81e7-505b-a7f4-7af9433fc65e', 26, 26, 'ሳኦልና ሰዎቹም በተራራው በአንድ ወገን ሄዱ፤ ዳዊትና ሰዎቹም በተራራው በሌላው ወገን ሄዱ። ዳዊትም ከሳኦል ፊት ያመልጥ ዘንድ ተሰውሮ ነበር። ሳኦልና ሰዎቹ ዳዊትንና ሰዎቹን ለመያዝ ከብበዋቸው ነበርና።'),
  ('b3b0b15b-0bd4-568d-a689-9d386614477b', '5dff6806-0103-5490-af20-4a386b23d190', 'f19f3c33-81e7-505b-a7f4-7af9433fc65e', 27, 27, 'ወደ ሳኦልም መልእክተኛ መጥቶ፥ “ፍልስጥኤማውያን ሀገሩን ወርረውታልና ፈጥነህ ና” አለው።'),
  ('5beb1d02-b70e-5556-ad7b-45a9d91f5c1e', '5dff6806-0103-5490-af20-4a386b23d190', 'f19f3c33-81e7-505b-a7f4-7af9433fc65e', 28, 28, 'ሳኦልም ዳዊትን ማሳደድን ትቶ ተመለሰ። ከፍልስጥኤማውያንም ጋር ሊዋጋ ሄደ። ስለዚህ የዚያ ስፍራ ስም የመለያየት ዓለት ተባለ።'),
  ('6ece979f-4237-5733-ae3e-aea3904a3f84', '9333aa72-e1dd-5a5a-a166-5368702cc0eb', 'c6380d10-7484-591d-a872-ce3143cf0a27', 1, 1, 'ዳዊትም ከዚያ መጥቶ በዓይን ጋዲ በጠባብ ቦታ ተቀመጠ፤'),
  ('591cb2f5-d397-5724-a75e-56a3a3db9679', '9333aa72-e1dd-5a5a-a166-5368702cc0eb', 'c6380d10-7484-591d-a872-ce3143cf0a27', 2, 2, 'ሳኦልም ፍልስጥኤማውያንን ከማሳደድ ከተመለሰ በኋላ፥ “እነሆ! ዳዊት በዓይን ጋዲ ምድረ በዳ አለ” ብለው ነገሩት።'),
  ('2d34a942-a2c9-570a-a103-73c329d319fc', '9333aa72-e1dd-5a5a-a166-5368702cc0eb', 'c6380d10-7484-591d-a872-ce3143cf0a27', 3, 3, 'ሳኦልም ከእስራኤል ሁሉ የተመረጡትን ሦስት ሺህ ሰዎች ወሰደ፤ ዳዊትንና ሰዎቹንም ለመፈለግ ዋሊያዎች ወደሚታደኑባቸው ዓለቶች ሄደ።'),
  ('25a26f0a-be07-55f8-a861-4df291c019cf', '9333aa72-e1dd-5a5a-a166-5368702cc0eb', 'c6380d10-7484-591d-a872-ce3143cf0a27', 4, 4, 'በመንገድም አጠገብ ወዳሉት የበጎች ማደሪያዎች ወጣ፤ በዚያም ዋሻ ነበረ፤ ሳኦልም ወገቡን ይሞክር ዘንድ ወደዚያ ዋሻ ገባ፤ ዳዊትና ሰዎቹም ከዋሻው በውስጠኛው ቦታ ተቀምጠው ነበር።'),
  ('9adb41ca-ac36-5a56-a9f1-1ed52cac32a6', '9333aa72-e1dd-5a5a-a166-5368702cc0eb', 'c6380d10-7484-591d-a872-ce3143cf0a27', 5, 5, 'የዳዊትም ሰዎች፥ “እነሆ፥ ጠላትህን በእጅህ አሳልፌ እሰጠዋለሁ፤ በዐይንህም ደስ የሚያሰኝህን ታደርግበታለህ ብሎ እግዚአብሔር የነገረህ ቀን እነሆ ዛሬ ነው” አሉት። ዳዊትም ተነሥቶ የሳኦልን መጐናጸፊያ ዘርፍ በቀስታ ቈረጠ።'),
  ('309d5ccd-67f4-53c6-a91b-d9c4783591a5', '9333aa72-e1dd-5a5a-a166-5368702cc0eb', 'c6380d10-7484-591d-a872-ce3143cf0a27', 6, 6, 'ከዚያም በኋላ እንዲህ ሆነ፤ የሳኦልን የልብሱን ዘርፍ ስለ ቈረጠ የዳዊት ልብ በኀዘን ተመታ።'),
  ('4b1c3988-8c5c-5449-a9bc-06e2d44148e7', '9333aa72-e1dd-5a5a-a166-5368702cc0eb', 'c6380d10-7484-591d-a872-ce3143cf0a27', 7, 7, 'ዳዊትም ሰዎቹን፥ “እግዚአብሔር የቀባው ነውና እግዚአብሔር በቀባው በጌታዬ ላይ እንዲህ ያለውን ነገር አደርግ ዘንድ፥ እጄንም እጥልበት ዘንድ እግዚአብሔር ከእኔ ያርቀው” አላቸው።'),
  ('3482df38-10b2-59b9-ae20-0d9ef5b618e8', '9333aa72-e1dd-5a5a-a166-5368702cc0eb', 'c6380d10-7484-591d-a872-ce3143cf0a27', 8, 8, 'ዳዊትም በዚህ ቃል ሰዎቹን ከለከላቸው። በሳኦልም ላይ ተነሥተው ይገድሉት ዘንድ አልፈቀደላቸውም፤ ሳኦልም ከዋሻው ተነሥቶ መንገዱን ሄደ።'),
  ('99bc9400-35e8-5904-ab1f-fd8dcdd9d0f9', '9333aa72-e1dd-5a5a-a166-5368702cc0eb', 'c6380d10-7484-591d-a872-ce3143cf0a27', 9, 9, 'ከእርሱም በኋላ ዳዊት ደግሞ ተነሣ፤ ከዋሻውም ወጣ፤ ከሳኦልም በኋላ፦“ ጌታዬ ንጉሥ ሆይ!” ብሎ ጮኸ፤ ሳኦልም ወደ ኋላው ተመለከተ፤ ዳዊትም ወደ ምድር ተጐንብሶ እጅ ነሣ።'),
  ('2f7715be-bd24-5637-aed6-7b9f6eaeff5b', '9333aa72-e1dd-5a5a-a166-5368702cc0eb', 'c6380d10-7484-591d-a872-ce3143cf0a27', 10, 10, 'ዳዊትም ሳኦልን አለው፥ “እነሆ፥ ዳዊት ክፉ ነገር ይሻብሃል የሚሉህን ሰዎች ቃል ለምን ትሰማለህ?'),
  ('c5908919-9a51-5593-aeb4-522cac3b8233', '9333aa72-e1dd-5a5a-a166-5368702cc0eb', 'c6380d10-7484-591d-a872-ce3143cf0a27', 11, 11, 'እነሆ፥ ዛሬ በዋሻው ውስጥ እግዚአብሔር በእጄ አሳልፎ እንደ ሰጠህ ዐይንህ አይታለች፤ አንተንም እንድገድልህ ሰዎች ተናገሩኝ፤ እኔ ግን፦ በእግዚአብሔር የተቀባ ነውና እጄን በጌታዬ ላይ አልዘረጋም ብዬ ራራሁልህ።'),
  ('8ee20622-d9a9-56ef-a0c4-899d696745a8', '9333aa72-e1dd-5a5a-a166-5368702cc0eb', 'c6380d10-7484-591d-a872-ce3143cf0a27', 12, 12, 'እነሆ፥ የልብስህ ዘርፍ በእጄ እንዳለ ተመልክተህ ዕወቅ፤ የልብስህንም ዘርፍ በቈረጥሁ ጊዜ አልገደልሁህም፤ ስለዚህም በእጄ ክፋት፥ በደልና ክዳት እንደሌለ፥ አንተንም እንዳልበደልሁህ ዕወቅ፤ አንተ ግን ነፍሴን ልታጠፋ ታጠምዳለህ።'),
  ('c5398233-a5cb-57de-ada0-464c9f93f57f', '9333aa72-e1dd-5a5a-a166-5368702cc0eb', 'c6380d10-7484-591d-a872-ce3143cf0a27', 13, 13, 'እግዚእብሔር በእኔና በአንተ መካከል ይፍረድ፤ እግዚአብሔርም አንተን ይበቀልልኝ፤ እጄ ግን በአንተ ላይ አትሆንም።'),
  ('6ea38fd6-f196-5f3a-a736-2a525fff97ab', '9333aa72-e1dd-5a5a-a166-5368702cc0eb', 'c6380d10-7484-591d-a872-ce3143cf0a27', 14, 14, 'የጥንት ምሳሌ፦ ‘ከኀጢአተኞች ኀጢአት ይወጣል’ እንደሚል፥ እጄ ግን በአንተ ላይ አትሆንም።'),
  ('cf6b0840-5ee2-5312-a14c-dbcee926221f', '9333aa72-e1dd-5a5a-a166-5368702cc0eb', 'c6380d10-7484-591d-a872-ce3143cf0a27', 15, 15, 'አሁንም የእስራኤል ንጉሥ ማንን ለማሳደድ ወጥተሀል? አንተስ ማንን ታሳድዳለህ? የሞተ ውሻን ታሳድዳለህን? ወይስ ቍንጫን ታሳድዳለህ?'),
  ('becd66c6-f865-53d0-a222-824a767011b4', '9333aa72-e1dd-5a5a-a166-5368702cc0eb', 'c6380d10-7484-591d-a872-ce3143cf0a27', 16, 16, 'እንግዲህ እግዚአብሔር ዳኛ ይሁን፤ በእኔና በአንተም መካከል ይፍረድ፤ አይቶም ለእኔ ይፍረድ፤ ከእጅህም ያድነኝ።”'),
  ('6c7791ec-b740-5d79-aece-b456cb52af36', '9333aa72-e1dd-5a5a-a166-5368702cc0eb', 'c6380d10-7484-591d-a872-ce3143cf0a27', 17, 17, 'እንዲህም ሆነ፤ ዳዊት ይህን ቃል ለሳኦል መንገር በፈጸመ ጊዜ፥ ሳኦል፥ “ልጄ ዳዊት ሆይ! ይህ ድምፅህ ነውን?” አለ፤ ሳኦልም ድምፁን ከፍ አድርጎ አለቀሰ።'),
  ('479e8d93-f896-5197-a11b-0318099e510f', '9333aa72-e1dd-5a5a-a166-5368702cc0eb', 'c6380d10-7484-591d-a872-ce3143cf0a27', 18, 18, 'ሳኦልም ዳዊትን አለው፥ “እኔ ክፉ በመለስሁልህ ፋንታ በጎ መልሰህልኛልና አንተ ከእኔ ይልቅ ጻድቅ ነህ።'),
  ('d78dab70-271b-5ad9-a899-11b32e316a69', '9333aa72-e1dd-5a5a-a166-5368702cc0eb', 'c6380d10-7484-591d-a872-ce3143cf0a27', 19, 19, 'እግዚአብሔርም ዛሬ በእጅህ አሳልፎ ሰጥቶኝ ሳለ አልገደልኸኝምና ለእኔ መልካም እንዳደረግኽልኝ ለእኔ ነገርኸኝ።'),
  ('55ccd495-7248-547e-aecc-4a83f398aef9', '9333aa72-e1dd-5a5a-a166-5368702cc0eb', 'c6380d10-7484-591d-a872-ce3143cf0a27', 20, 20, 'ጠላቱን ተቸግሮ አግኝቶ በመልካም መንገድ ሸኝቶ የሚሰድድ ማን ነው? ስለዚህ ለእኔ ስላደረግኸው ቸርነት እግዚአብሔር መልካሙን ይመልስልህ።'),
  ('7bb6159e-b6d9-5f4f-a0bb-8b8f637cfb97', '9333aa72-e1dd-5a5a-a166-5368702cc0eb', 'c6380d10-7484-591d-a872-ce3143cf0a27', 21, 21, 'አሁንም እነሆ፥ አንተ በርግጥ ንጉሥ እንድትሆን የእስራኤልም መንግሥት በእጅህ እንድትጸና እኔ አውቃለሁ።'),
  ('ab8aeaf7-8452-534e-a2b2-ef7094e882fb', '9333aa72-e1dd-5a5a-a166-5368702cc0eb', 'c6380d10-7484-591d-a872-ce3143cf0a27', 22, 22, 'አሁን እንግዲህ ከእኔ በኋላ ዘሬን እንዳትነቅል ከአባቴም ቤት ስሜን እንዳታጠፋው በእግዚአብሔር ማልልኝ።”'),
  ('be329be7-e014-5458-a746-646954276060', '9333aa72-e1dd-5a5a-a166-5368702cc0eb', 'c6380d10-7484-591d-a872-ce3143cf0a27', 23, 23, 'ዳዊትም ለሳኦል ማለለት፤ ሳኦልም ወደ ቤቱ ሄደ፤ ዳዊትና ሰዎቹም ወደ ጠባቡ ወደ ሜሴራ ወጡ።'),
  ('8a070739-da5e-50cf-af93-89bd011d4b20', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'a5f96de2-8524-52f6-a725-13be686debcc', 1, 1, 'ሳሙኤልም ሞተ፤ እስራኤልም ሁሉ ተሰብስበው አለቀሱለት፤ በአርማቴምም በቤቱ ቀበሩት። ዳዊትም ተነሥቶ ወደ ማዖን ምድረ በዳ ወረደ።'),
  ('dae8c77f-70cd-539e-a65f-a2d204964978', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 1, 2, 'በማዖንም የተቀመጠ አንድ ሰው ነበረ፤ ከብቱም በቀርሜሎስ ነበረ፤ እጅግም ታላቅ ሰው ነበረ፤ ለእርሱም ሦስት ሺህ በጎችና አንድ ሺህ ፍየሎች ነበሩት፤ በቀርሜሎስም በጎቹን ሊሸልት ሄደ።'),
  ('04025e37-e166-5398-aa70-1070b462a57d', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 2, 3, 'የሰውዬውም ስም ናባል፥ የሚስቱም ስም አቤግያ ነበረ፤ ሴቲቱም ደግና ብልህ፥ መልክዋም እጅግ የተዋበ ነበረ፤ ሰውዬው ግን ጨካኝና ንፉግ ነበረ፤ ግብሩም ክፉ ነበረ።'),
  ('e035747b-7b53-5400-ad77-e09459fe4df9', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 3, 4, 'ዳዊትም በምድረ በዳ ሳለ፥ “ናባል በቀርሜሎስ በጎቹን ይሸልታል” የሚል ወሬ ሰማ።'),
  ('a50d3832-3641-55a5-a8f4-3862054909bd', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 4, 5, 'ዳዊትም ዐሥር ብላቴኖችን ላከ፤ ለብላቴኖቹም አለ፥ “ወደ ቀርሜሎስ ወጥታችሁ ወደ ናባል ሂዱ፤ በስሜም ሰላም በሉት፤'),
  ('89c07fcc-c4e4-5bf0-aeaf-7015f1e2693f', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 5, 6, 'እንዲህም በሉት፥ “ደኅንነትና ሰላም ለአንተና ለቤትህ፥ ለአንተም ለሆኑት ሁሉ ይሁን።'),
  ('aa05fa00-1221-5f73-aacb-0e028df0380f', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 6, 7, 'አሁንም በጎችህ እንደሚሸለቱ ከእኛ ጋር በምድረ በዳ ያሉ ሰዎች ነገሩን፤ እኛም አልከለከልናቸውም፤ በቀርሜሎስም በነበሩበት ዘመን ሁሉ ከመንጋቸው ይሰጡን ዘንድ አላዘዝናቸውም።'),
  ('4d63e653-e538-50fd-a290-da3146de6daa', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 7, 8, 'ብላቴኖችህን ጠይቃቸው፤ እነርሱም ይነግሩሃል፤ አሁንም እንግዲህ በመልካም ቀን መጥተናልና ብላቴኖች በፊትህ ሞገስ ያግኙ፤ በእጅህም ከተገኘው ለልጅህ ለዳዊት እባክህ፥ ላክ።”'),
  ('9911538f-7f44-5038-a19f-3270b96a05e8', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 8, 9, 'የዳዊትም ብላቴኖች መጡ፤ ይህንም የላካቸውን ቃል ሁሉ በዳዊት ስም ለናባል ነገሩት፤'),
  ('cc5ac43e-7c50-5988-a6b5-13ac53188d1e', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 9, 10, 'ናባልም ተነሥቶ ለዳዊት ብላቴኖች መለሰላቸው እንዲህም አላቸው፥ “ዳዊት ማን ነው? የእሴይስ ልጅ ማን ነው? እያንዳንዳቸው ከጌቶቻቸው የኰበለሉ አገልጋዮች ዛሬ ብዙ ናቸው።'),
  ('ea39b3fe-a25b-5565-a87f-bb5f0bacfc6b', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 10, 11, 'እንጀራዬንና የወይን ጠጄን፥ ለሸላቾቼም ያረድሁትን ሥጋ ወስጄ ከወዴት እንደ ሆኑ ለማላውቃቸው ሰዎች እሰጣለሁን?”'),
  ('ee399c90-f2b2-57de-a803-c3049be90371', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 11, 12, 'የዳዊትም ብላቴኖች ዞረው በመጡበት መንገድ ተመለሱ፤ መጥተውም ይህን ነገር ሁሉ ለዳዊት ነገሩት።'),
  ('a914c1dc-7188-5c99-a32c-8d3cb8d5b947', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 12, 13, 'ዳዊትም ሰዎቹን፥ “ሁላችሁ ሰይፋችሁን ታጠቁ” አላቸው። ሁሉም ሰይፋቸውን ታጠቁ፤ ዳዊትም ሰይፉን ታጠቀ፤ አራት መቶ ሰዎችም ዳዊትን ተከትለው ወጡ፤ ሁለት መቶውም በጓዛቸው ዘንድ ተቀመጡ።'),
  ('efa33f05-2b13-59e6-a0b6-304d4c7ee715', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 13, 14, 'ከብላቴኖቹም አንዱ ለናባል ሚስት ለአቤግያ እንዲህ ብሎ ነገራት፥ “እነሆ፥ ዳዊት በምድረ በዳ ሳለ ጌታችንን ሰላም ሊሉት መልእክተኞችን ላከ፤ እርሱ ግን ፊቱን አዞረባቸው።'),
  ('1c536151-b804-53cd-ab72-6606e12dd529', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 14, 15, 'እነዚህ ሰዎች ግን በእኛ ዘንድ እጅግ ደጎች ነበሩ፤ የከለከሉንም የለም፤ ከእነርሱም ጋር በኖርንበት ዘመን ሁሉ በምድረ በዳ ሳለን ከመንጋው እንሰጣቸው ዘንድ ያዘዙን አንዳች ነገር የለም።'),
  ('eb335d80-03be-5ad9-ac84-6e32d233e639', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 15, 16, 'ከእነርሱም ጋር ሆነን መንጋውን በጠበቅንበት ዘመን ሁሉ በምድረ በዳ ሌሊትና ቀን አጥር ሆነውን ነበር።'),
  ('45d87d5d-6813-554e-affd-281d4542de0c', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 16, 17, 'ስለዚህም በጌታችንና በቤቱ ሁላ ክፉ ነገር እንዲመጣ ተቈርጦአልና፥ እርሱ ክፉ ሰው ስለ ሆነ ማንም ሊናገረው አይችልምና የምታደርጊውን ተመልከቺና ዕወቂ።”'),
  ('00c0b706-0d45-5131-a780-5faabf2b84ae', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 17, 18, 'አቤግያም ፈጥና፦ ሁለት መቶ እንጀራ፥ ሁለት አቁማዳ የወይን ጠጅ፥ አምስት የተዘጋጁ በጎች፥ አምስትም መስፈሪያ በሶ፥ አንድ ጎሞር ዘቢብ፥ ሁለት መቶም የበለስ ጥፍጥፍ ወሰደች፥ በአህዮችም ላይ አስጫነች።'),
  ('0ec30128-1488-54be-ac00-603137b2020f', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 18, 19, 'ለአገልጋዮችዋም፥ “አስቀድማችሁ በፊቴ ሂዱ፤ እነሆም እከተላችኋለሁ” አለች። ይህንም ለባልዋ ለናባል አልነገረችውም።'),
  ('e93647f5-089f-5220-a5e1-2bf9675f20f5', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 19, 20, 'እርስዋም በአህያዋ ላይ ተቀምጣ በተራራው ላይ በተሰወረ ስፍራ በወረደች ጊዜ፥ እነሆ፥ ዳዊትና ሰዎቹ ወደ እርስዋ ወርደው ተቀበሏት፤ እርስዋም ተገናኘቻቸው።'),
  ('bed3e7a6-73c9-5208-ae95-edf968b9896a', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 20, 21, 'ዳዊትም አለ፥ “ለዚህ ሰው ከሆነው ሁሉ አንድ ነገር እንዳይጠፋበት በእውነት ከብቱን ሁሉ በምድረ በዳ በከንቱ ጠበቅሁ፤ ከገንዘቡ ሁሉ አንዳች ይወስዱበት ዘንድ ያዘዝነው የለም፤ እርሱም በበጎ ፋንታ ክፉ መለሰልኝ።'),
  ('2685d801-89cb-5368-a40e-331759f27221', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 21, 22, 'ለናባልም ከሆነው ሁሉ እስከ ነገ ጥዋት ድረስ አጥር ተጠግቶ የሚሸን አንድ ስንኳ ብንተው፥ እግዚአብሔር በዳዊት ላይ እንዲህ ያድርግ፤ እንዲህም ይጨምር” ብሎ ነበር።'),
  ('294aa8fa-989e-50f6-a75e-dd9b9f58cfcc', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 22, 23, 'አቤግያም ዳዊትን ባየች ጊዜ ከአህያዋ ላይ ፈጥና ወረደች፤ በዳዊትም ፊት በግንባርዋ ወደቀች፤ ምድርም ነክታ ሰገደችለት።'),
  ('e8e49baa-52e9-5e01-afdf-8193b14f1690', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 23, 24, 'በእግሩም ላይ ወደቀች፤ እንዲህም አለች፥ “ጌታዬ ሆይ! ይህ ኀጢኣት በእኔ ላይ ይሁን፤ እኔ ባሪያህ በጆሮህ ልናገር፥ የባሪያህንም ቃል አድምጥ።'),
  ('1d23113e-50e9-51f1-a826-268f6b1c0063', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 24, 25, 'በዚህ ክፉ ሰው በናባል ላይ ጌታዬ ልቡን እንዳይጥል እለምናለሁ፤ እንደ ስሙ እንዲሁ እርሱ ነው፤ ስሙ ናባል ነው፤ ስንፍናም አድሮበታል፤ እኔ ባሪያህ ግን አንተ የላክሃቸውን ብላቴኖችህን አላየሁም።'),
  ('2a6110dc-4ea7-586c-af64-96c7dd4997bf', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 25, 26, 'አሁንም ጌታዬ ሆይ! ሕያው እግዚአብሔርን! በሕያው ነፍስህ እምላለሁ! ወደ ንጹሕ ደም እንዳትገባና፥ እጅህን እንድታድን የከለከለህ እግዚአብሔር ነው፤ አሁንም ጠላቶችህና በጌታዬ ላይ ክፉ የሚሹ ሁሉ እንደ ናባል ይሁኑ።'),
  ('68aaf904-e741-5130-ac60-178916f3712f', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 26, 27, 'አሁንም ባሪያህ ወደ ጌታዬ ያመጣችውን ይህን መተያያ ተቀበል፤ በጌታዬም ዘንድ ለሚቆሙ ሰዎች ስጣቸው።'),
  ('2687897d-0c29-5b4b-af9b-a2a2dc16fa4f', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 27, 28, 'እግዚአብሔር ለጌታዬ የታመነ ቤትን ይሠራለታልና፥ የጌታዬንም ጦርነት እግዚአብሔር ይዋጋለታልና የእኔን የባሪያህን ኀጢኣት፥ እባክህ፥ ይቅር በል፤ በዘመንህም ሁሉ ክፋት አይገኝብህም።'),
  ('23278849-a437-537e-a756-d8841aea80bf', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 28, 29, 'የሚያሳድድህና ነፍስህን የሚሻ ሰው ቢነሣ፥ የጌታዬ ነፍስ በአምላክህ በእግዚአብሔር ዘንድ በሕይወት ማሰሪያ የታሰረች ትሆናለች፤ የጠላቶችህ ነፍስ ግን በወንጭፍ እንደሚወነጨፍ ትሁን።'),
  ('bbbe9b23-33c0-5de3-a595-416e2b99f6c4', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 29, 30, 'እንዲህም ይሆናል፤ እግዚአብሔር ለጌታዬ የተናገረውን ቸርነት ሁሉ ያደርግልሃል፤ በእስራኤልም ላይ አለቃ አድርጎ ይሾምሃል፤'),
  ('b6b5bc33-6af5-5b3b-a8e7-953dd5f9ee93', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 30, 31, 'ይህ ርኵሰትና የልብ በደል፥ በከንቱ ንጹሕ ደም ማፍሰስም ለጌታዬ አይሁኑበት፤ የጌታዬም እጁ ትዳን፤ እግዚአብሔርም ለጌታዬ በጎ ያድርግለት፤ በጎም ታደርግላት ዘንድ ባሪያህን አስብ።”'),
  ('c0e1670b-b41d-5152-a166-86cdcfef55fe', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 31, 32, 'ዳዊትም አቤግያን አላት፥ “ዛሬ እኔን ለመገናኘት አንቺን የላከ የእስራኤል አምላክ እግዚአብሔር ይመስገን።'),
  ('df5a468c-4e03-52ab-a2e2-0f607b3446d7', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 32, 33, 'ጠባይሽ የተባረከ ነው። ወደ ደም እንዳልገባ፥ እጄንም እንዳድን ዛሬ የከለከልሽኝ አንቺም የተባረክሽ ነሽ።'),
  ('f09bc482-59ac-5ef9-a4cf-6172dd756701', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 33, 34, 'ነገር ግን ክፉ እንዳላደርግብሽ የከለከለኝ የእስራኤል አምላክ ሕያው እግዚአብሔርን! እኔን ለመገናኘት ፈጥነሽ ባልመጣሽ ኖሮ፥ እስኪነጋ ድረስ ለናባል አጥር ተጠግቶ የሚሸን አንድ ስንኳ ባልቀረውም ብዬ ነበር።”'),
  ('826b5847-3ca1-59e0-aae5-8ad04115a6b3', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 34, 35, 'ዳዊትም ያመጣችውን ከእጅዋ ተቀብሎ፥ “በሰላም ወደ ቤትሽ ሂጂ፤ እነሆ፥ ቃልሽን እንደ ሰማሁ፥ ፊትሽንም እንዳከበርሁ ተመልከቺ” አላት።'),
  ('cb104cb0-e805-5746-af5f-4948cb436458', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 35, 36, 'አቤግያም ወደ ናባል መጣች፤ እነሆም፥ በቤቱ እንደ ንጉሥ ግብዣ ያለ ግብዣ ያደርግ ነበር፤ ናባልም እጅግ ሰክሮ ነበርና ልቡ ደስ ብሎት ነበር፤ ስለዚህም እስኪነጋ ድረስ ታናሽ ነገር ወይም ታላቅ ነገር አልነገረችውም ነበር።'),
  ('9a2e099a-0f89-5104-a72a-3344a0c801e6', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 36, 37, 'በነጋውም የወይኑ ስካር ከናባል ባለፈ ጊዜ ሚስቱ ይህን ነገር ነገረችው፤ ልቡም በውስጡ ሞተ፤ እንደ ድንጋይም ሆነ፤'),
  ('c00aa3ca-98b5-5234-ac06-b3df373f72e9', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 37, 38, 'ከዐሥር ቀንም በኋላ እግዚአብሔር ናባልን ቀሠፈው፤ እርሱም ሞተ።'),
  ('05c29440-3872-57f8-a8ca-f3c142113c53', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 38, 39, 'ዳዊትም ናባል እንደ ሞተ በሰማ ጊዜ፥ “ከናባል እጅ የስድቤን ፍርድ የፈረደልኝ፥ ባሪያውንም ከክፉዎች እጅ የጠበቀ እግዚአብሔር ይመስገን፤ እግዚአብሔርም የናባልን ክፋት በራሱ ላይ መለሰ” አለ። ዳዊትም ያገባት ዘንድ አቤግያን እንዲያነጋግሩለት ላከ።'),
  ('59f11fd8-7e7f-5f2b-a879-f0d12a20b96b', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 39, 40, 'የዳዊትም ብላቴኖች ወደ ቀርሜሎስ ወደ አቤግያ መጡ፥ “ዳዊትም ሚስት ትሆኚው ዘንድ ወደ አንቺ ልኮናል” ብለው ነገሩአት።'),
  ('c21487dd-cb3d-592c-a9b3-f97fbf9a821e', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 40, 41, 'ተነሥታም በግንባርዋ በምድር ወድቃ ሰገደችና፥ “እነሆ፥ እኔ ገረድህ የጌታዬን ሎሌዎች እግር አጥብ ዘንድ አገልጋይ ነኝ” አለች።'),
  ('e740ee1d-ee2e-5949-a580-3b6879e066ea', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 41, 42, 'አቤግያም ፈጥና ተነሣች፤ በአህያም ላይ ተቀመጠች፤ አምስቱም ገረዶችዋ ተከተሉአት፤ የዳዊትንም መልእክተኞች ተከትላ ሄደች፤ ሚስትም ሆነችው።'),
  ('b2829f62-6d49-56d2-ab9e-a26b78c5835a', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 42, 43, 'ዳዊትም ደግሞ ከኢይዝራኤል አኪናሆምን ወሰደ፤ ሁለቱም ሚስቶቹ ሆኑለት።'),
  ('363de3d3-4351-59a1-afac-1ac8662e44ea', 'c50912dd-8951-5fbc-ac4a-5504acc2d695', 'bdf0eb87-b4b3-5c09-a7b5-9c5d8d65150e', 43, 44, 'ሳኦል ግን የዳዊትን ሚስት ልጁን ሜልኮልን ሀገሩ ሮማ ለነበረው ለያሚስ ልጅ ለፈልጢ ሰጣት።'),
  ('674db2cb-6a42-505d-a5c7-d2f6fafc6011', 'bf570083-9960-5236-ab88-f455d73d9d77', 'a8897d5a-c6f1-5b0a-abc1-bf57a69c4b57', 1, 1, 'የዚፍ ሰዎችም ከአውክሞዲስ ወደ ኮረብታው ወደ ሳኦል መጥተው፥ “እነሆ፥ ዳዊት በየሴሞን ፊት ለፊት ባለው በኤኬላ ኮረብታ ላይ ከእኛ ጋር ተሸሽጎ አለ” አሉት።'),
  ('5f8ce7a4-5abc-5a95-a012-b0076d0c57fa', 'bf570083-9960-5236-ab88-f455d73d9d77', 'a8897d5a-c6f1-5b0a-abc1-bf57a69c4b57', 2, 2, 'ሳኦልም ተነሥቶ ዳዊትን በዚፍ ምድረ በዳ ይሻ ዘንድ ከእስራኤል የተመረጡ ሦስት ሺህ ሰዎችን ይዞ ወደ ዚፍ ምድረ በዳ ወረደ።'),
  ('6cdd7023-3405-54a2-ae20-58823a3d218b', 'bf570083-9960-5236-ab88-f455d73d9d77', 'a8897d5a-c6f1-5b0a-abc1-bf57a69c4b57', 3, 3, 'ሳኦልም በየሴሞን ፊት ለፊት ባለው በኤኬላ ኮረብታ ላይ በመንገዱ አጠገብ ሰፈረ። ዳዊትም በምድረ በዳ ውስጥ ተቀምጦ ነበር፥ ዳዊትም ሳኦል ሊፈልገው ወደ ምድረ በዳ እንደ መጣ ዐወቀ።'),
  ('a8c5edec-5023-5b12-a8b2-5f2542191e62', 'bf570083-9960-5236-ab88-f455d73d9d77', 'a8897d5a-c6f1-5b0a-abc1-bf57a69c4b57', 4, 4, 'ዳዊትም ሰላዮችን ላከ፤ ሳኦልም ተዘጋጅቶ ወደ ቂአላ እንደ መጣ በርግጥ ዐወቀ።'),
  ('08d3d106-99f3-50e7-ae88-80dc8b9a94c6', 'bf570083-9960-5236-ab88-f455d73d9d77', 'a8897d5a-c6f1-5b0a-abc1-bf57a69c4b57', 5, 5, 'ዳዊትም በቀስታ ተነሥቶ ሳኦል ወደ ሰፈረበት ቦታ መጣ፤ ሳኦልና የሠራዊቱ አለቃ የኔር ልጅ አቤኔርም የተኙበትን ስፍራ አየ፤ ሳኦልም በድንኳን ውስጥ ተኝቶ ነበር፤ ሕዝቡም በዙሪያው ሰፍሮ ነበር።'),
  ('e9ed11fc-1a6b-5f5f-a988-35f049eb733b', 'bf570083-9960-5236-ab88-f455d73d9d77', 'a8897d5a-c6f1-5b0a-abc1-bf57a69c4b57', 6, 6, 'ዳዊትም ኬጤያዊዉን አቤሜሌክንና የሶርህያን ልጅ የኢዮአብን ወንድም አቢሳን፥ “ወደ ሳኦል ወደ ሰፈሩ ከእኔ ጋር የሚገባ ማን ነው?” ብሎ ጠየቃቸው፤ አቢሳም፥ “እኔ ከአንተ ጋር እገባለሁ” አለ።'),
  ('630a6365-056d-5f48-ae9d-fde3033fc0ba', 'bf570083-9960-5236-ab88-f455d73d9d77', 'a8897d5a-c6f1-5b0a-abc1-bf57a69c4b57', 7, 7, 'ዳዊትና አቢሳም ወደ ሕዝቡ በሌሊት መጡ፤ እነሆም፥ ሳኦል በድንኳን ውስጥ ተኝቶ ነበር፤ ጦሩም በራስጌው አጠገብ በምድር ተተክሎ ነበር፤ አቤኔርና ሕዝቡም በዙሪያው ተኝተው ነበር።'),
  ('a5f83bdd-f109-5504-aca3-fd461baee1de', 'bf570083-9960-5236-ab88-f455d73d9d77', 'a8897d5a-c6f1-5b0a-abc1-bf57a69c4b57', 8, 8, 'አቢሳም ዳዊትን፥ “ዛሬ እግዚአብሔር ጠላትህን በእጅህ አሳልፎ ሰጥቶታል፤ አሁንም እኔ በጦር አንድ ጊዜ ከምድር ጋር ላጣብቀው፤ ሁለተኛም አልደግመውም” አለው።'),
  ('aea72fa3-b0c0-5506-afaf-d92c9618a0a8', 'bf570083-9960-5236-ab88-f455d73d9d77', 'a8897d5a-c6f1-5b0a-abc1-bf57a69c4b57', 9, 9, 'ዳዊትም አቢሳን፥ “እግዚአብሔር በቀባው ላይ እጁን የሚዘረጋ ንጹሕ አይሆንምና አትግደለው” አለው።'),
  ('426a43bc-d57e-5593-aec6-1b768dd01b1d', 'bf570083-9960-5236-ab88-f455d73d9d77', 'a8897d5a-c6f1-5b0a-abc1-bf57a69c4b57', 10, 10, 'ደግሞም ዳዊት አለው፥ “ሕያው እግዚአብሔርን! እግዚአብሔር ካልገደለው፥ ወይም ቀኑ ደርሶ ካልሞተ፥ ወይም ወደ ጦርነት ወርዶ ካልሞተ እኔ አልገድለውም።'),
  ('8f75ee19-5a7c-5bc9-aa47-8ae034e821d0', 'bf570083-9960-5236-ab88-f455d73d9d77', 'a8897d5a-c6f1-5b0a-abc1-bf57a69c4b57', 11, 11, 'እግዚአብሔርም በቀባው ላይ እጄን እዘረጋ ዘንድ እግዚአብሔር ከእኔ ያርቀው፤ አሁንም በራሱ አጠገብ ያለውን ጦርና የውኃውን መንቀል ይዘህ እንሂድ፤” አለው።'),
  ('e67ffc0c-53a9-5d21-acfa-f858a0593d88', 'bf570083-9960-5236-ab88-f455d73d9d77', 'a8897d5a-c6f1-5b0a-abc1-bf57a69c4b57', 12, 12, 'ዳዊትም በሳኦል ራስጌ የነበረውን ጦርና የውኃውን መንቀል ወሰደ፤ ወደ ቤታቸውም ተመለሱ። ማንም ያየ አልነበረም፤ ያወቃቸውም ማንም አልነበረም፤ የነቃም ማንም አልነበረም፤ ከእግዚአብሔር ዘንድ ከባድ እንቅልፍ ወድቆባቸው ነበርና ሁሉ ተኝተው ነበር።'),
  ('25fa4086-5ea7-58f9-a057-0981fecdb4b0', 'bf570083-9960-5236-ab88-f455d73d9d77', 'a8897d5a-c6f1-5b0a-abc1-bf57a69c4b57', 13, 13, 'ዳዊትም ወደ ማዶ ተሻገረ፤ በተራራውም ራስ ላይ ርቆ ቆመ፤ በመካከላቸውም ሰፊ ርቀት ነበረ።'),
  ('ccc884a8-ae2a-5b1a-ab82-5d012f3f62db', 'bf570083-9960-5236-ab88-f455d73d9d77', 'a8897d5a-c6f1-5b0a-abc1-bf57a69c4b57', 14, 14, 'ዳዊትም ሕዝቡንና የኔር ልጅ አቤኔርን ጠራቸው፥ “አቤኔር ሆይ፥ አትመልስምን?” አለው። አቤኔርም መልሶ፥ “አንተ የምትጠራኝ ማን ነህ?” አለ።'),
  ('ad262377-5e26-5779-a54a-b4ff019e9b12', 'bf570083-9960-5236-ab88-f455d73d9d77', 'a8897d5a-c6f1-5b0a-abc1-bf57a69c4b57', 15, 15, 'ዳዊትም አቤኔርን፥ “አንተ ጐልማሳ አይደለህምን? በእስራኤል ዘንድ አንተን የሚመስል ማን ነው? ጌታህን ንጉሡን ለመግደል አንድ ሰው ገብቶ ነበርና ጌታህን ንጉሡን የማትጠብቅ ስለምን ነው?'),
  ('37a5b281-50f7-58a7-ab75-c256174a6ecb', 'bf570083-9960-5236-ab88-f455d73d9d77', 'a8897d5a-c6f1-5b0a-abc1-bf57a69c4b57', 16, 16, 'ይህ ያደረግኸው ነገር መልካም አይደለም፤ ሕያው እግዚአብሔርን! እናንተ እግዚአብሔር የቀባውን ጌታችሁን አልጠበቃችሁምና ሞት ይገባችኋል፤ አሁንም የንጉሡ ጦርና በራሱ አጠገብ የነበረው የውኃ መንቀል የት እንደ ሆነ ተመልከት” አለው።'),
  ('b9d259ac-67b4-59af-a4e2-408adb13764f', 'bf570083-9960-5236-ab88-f455d73d9d77', 'a8897d5a-c6f1-5b0a-abc1-bf57a69c4b57', 17, 17, 'ሳኦልም የዳዊት ድምፅ እንደ ሆነ ዐውቆ፥ “ልጄ ዳዊት ሆይ! ይህ ድምፅህ ነውን?” አለው። ዳዊትም፥ “ጌታዬ ንጉሥ ሆይ! አዎ እኔ ባሪያህ ነኝ” አለው።'),
  ('8ff673eb-d6b4-502e-a430-8fce8ce9593b', 'bf570083-9960-5236-ab88-f455d73d9d77', 'a8897d5a-c6f1-5b0a-abc1-bf57a69c4b57', 18, 18, 'ደግሞም አለ፥ “ጌታዬ አገልጋዩን ስለምን ያሳድዳል? ምን አደረግሁ? ምንስ ክፋት በእጄ ላይ ተገኘብኝ?'),
  ('6488867e-ec41-5d3f-a3b5-3c02acb170ee', 'bf570083-9960-5236-ab88-f455d73d9d77', 'a8897d5a-c6f1-5b0a-abc1-bf57a69c4b57', 19, 19, 'አሁንም ጌታዬ ንጉሥ ሆይ! የእኔን የአገልጋይህን ቃል ስማ፤ እግዚአብሔር በእኔ ላይ አስነሥቶህ እንደሆነ፥ ቍርባንህን ይቀበል፤ የሰው ልጆች ግን ቢሆኑ፦ ሂድ ሌሎችን አማልክት አምልክ ብለው በእግዚአብሔር ርስት ላይ እንዳልቀመጥ ዛሬ ጥለውኛልና በእግዚአብሔር ፊት ርጉማን ይሁኑ።'),
  ('18f36415-e57d-5b4b-a63f-7b33fd9937be', 'bf570083-9960-5236-ab88-f455d73d9d77', 'a8897d5a-c6f1-5b0a-abc1-bf57a69c4b57', 20, 20, 'አሁንም በተራራው ላይ ሰው ቆቅን እንደሚሻ የእስራኤል ንጉሥ ነፍሴን ለመሻት ወጥቶአልና ደሜ በእግዚአብሔር ፊት በምድር ላይ አይፍሰስ።”'),
  ('ecb6d861-9df1-58fd-a0c7-7a6a91ed59cf', 'bf570083-9960-5236-ab88-f455d73d9d77', 'a8897d5a-c6f1-5b0a-abc1-bf57a69c4b57', 21, 21, 'ሳኦልም፥ “በድያለሁ፤ ልጄ ዳዊት ሆይ! ተመለስ፤ ዛሬ ነፍሴ በዐይንህ ፊት ከብራለችና ከዚህ በኋላ ክፉ አላደርግብህም፤ እነሆ፥ ስንፍና እንደ አደረግሁና፥ እጅግ ብዙም እንደ ሳትሁ ዐወቅሁ” አለ።'),
  ('27b3b00f-5fcc-5343-a185-5373d276be8f', 'bf570083-9960-5236-ab88-f455d73d9d77', 'a8897d5a-c6f1-5b0a-abc1-bf57a69c4b57', 22, 22, 'ዳዊትም መልሶ አለ፥ “የንጉሥ ጦር እነሆ፤ ከብላቴኖችም አንድ ይምጣና ይውሰዳት።'),
  ('75a7c726-8f76-5854-ae03-27e1c6e7ff80', 'bf570083-9960-5236-ab88-f455d73d9d77', 'a8897d5a-c6f1-5b0a-abc1-bf57a69c4b57', 23, 23, 'ዛሬም እግዚአብሔር በእጄ አሳልፎ ሰጥቶህ ሳለ እግዚአብሔር በቀባው ላይ እጄን እዘረጋ ዘንድ አልወደድሁምና ለሁሉ እያንዳንዱ እግዚአብሔር እንደ ጽድቁና እንደ እምነቱ ፍዳውን ይክፈለው።'),
  ('792eed01-1a3b-5000-a495-79d1278e270d', 'bf570083-9960-5236-ab88-f455d73d9d77', 'a8897d5a-c6f1-5b0a-abc1-bf57a69c4b57', 24, 24, 'ነፍስህም ዛሬ በዐይኔ ፊት እንደ ከበረች እንዲሁ ነፍሴ በእግዚአብሔር ፊት ትክበር፤ ከመከራም ሁሉ ይሰውረኝ፤ ያድነኝም።”'),
  ('e48e1560-b3b5-589d-abde-f267c7ac76fd', 'bf570083-9960-5236-ab88-f455d73d9d77', 'a8897d5a-c6f1-5b0a-abc1-bf57a69c4b57', 25, 25, 'ሳኦልም ዳዊትን፥ “ልጄ ዳዊት ሆይ! ቡሩክ ሁን፤ ማድረግን ታደርጋለህ፤ መቻልንም ትችላለህ” አለው። ዳዊትም መንገዱን ሄደ፤ ሳኦልም ወደ ስፍራው ተመለሰ።'),
  ('6dd7712f-a859-5dec-a906-d390cfc7965b', 'cacb2a40-a856-53fc-a805-beb850207c41', '7b4941b9-e3d9-5a85-a137-9a9df1da25ee', 1, 1, 'ዳዊትም በልቡ፥ “አንድ ቀን በሳኦል እጅ እሞታለሁ፤ ወደ ፍልስጥኤማውያንም ምድር ከመሸሸ በቀር የሚሻለኝ የለም፤ ሳኦልም በእስራኤል አውራጃ ሁሉ እኔን መሻት ይተዋል፤ እንዲሁም ከእጁ እድናለሁ” አለ።'),
  ('db649bed-aba3-507b-ad24-930756ef49de', 'cacb2a40-a856-53fc-a805-beb850207c41', '7b4941b9-e3d9-5a85-a137-9a9df1da25ee', 2, 2, 'ዳዊትም ከእርሱም ጋር የነበሩት ስድስቱ መቶ ሰዎች ተነሥተው ወደ ጌት ንጉሥ ወደ አሜህ ልጅ ወደ አንኩስ አለፉ።'),
  ('c5eba0b6-1b6c-5c84-a162-c5e4343dcf10', 'cacb2a40-a856-53fc-a805-beb850207c41', '7b4941b9-e3d9-5a85-a137-9a9df1da25ee', 3, 3, 'ዳዊትና ሰዎቹም እያንዳንዳቸው ከነቤተሰቡ ከአንኩስ ጋር በጌት ተቀመጡ፤ ከዳዊትም ጋር ኢይዝራኤላዊቱ አኪናሆምና የቀርሜሎሳዊው የናባል ሚስት አቤግያ ሁለቱ ሚስቶቹ ነበሩ።'),
  ('27e76f13-8bd9-5dae-a40f-92e41ef394a4', 'cacb2a40-a856-53fc-a805-beb850207c41', '7b4941b9-e3d9-5a85-a137-9a9df1da25ee', 4, 4, 'ለሳኦልም ዳዊት ወደ ጌት እንደ ኰበለለ ነገሩት፤ ከዚያም በኋላ ደግሞ አልፈለገውም።'),
  ('6d378cce-a131-5944-a281-5d8bca8b5c1c', 'cacb2a40-a856-53fc-a805-beb850207c41', '7b4941b9-e3d9-5a85-a137-9a9df1da25ee', 5, 5, 'ዳዊትም አንኩስን፥ “አገልጋይህ በዐይንህ ፊት ሞገስ አግኝቼ እንደ ሆነ በዚህ ሀገር ከከተሞችህ በአንዲቱ የምቀመጥበት ስፍራ ስጠኝ፤ ስለ ምን እኔ አገልጋይህ ከአንተ ጋር በንጉሥ ከተማ እቀመጣለሁ?” አለው።።'),
  ('c37a427f-7105-505b-ab1c-86af34fa48b3', 'cacb2a40-a856-53fc-a805-beb850207c41', '7b4941b9-e3d9-5a85-a137-9a9df1da25ee', 6, 6, 'በዚያም ቀን አንኩስ ሴቄላቅን ሰጠው፤ ስለዚህም ሴቄላቅ እስከ ዛሬ ድረስ ለይሁዳ ንጉሥ ሆነች።'),
  ('c8d2d0b6-0291-5ee7-a6a9-b2f8d7be8504', 'cacb2a40-a856-53fc-a805-beb850207c41', '7b4941b9-e3d9-5a85-a137-9a9df1da25ee', 7, 7, 'ዳዊትም በፍልስጥኤማውያን ሀገር የተቀመጠበት የዘመን ቍጥር አራት ወር ነበረ።'),
  ('0ba27afd-3ac7-57ad-aa51-1b0bb2516761', 'cacb2a40-a856-53fc-a805-beb850207c41', '7b4941b9-e3d9-5a85-a137-9a9df1da25ee', 8, 8, 'ዳዊትና ሰዎቹም ወጥተው በጌሴራውያንና በአማሌቃውያን ላይ አደጋ ጣሉ፤ እነዚህንም ቅጽር ባላቸው በጌላምሱርና በአኔቆንጦን እስከ ግብፅ ምድር ድረስ ተቀምጠው አገኙአቸው።'),
  ('050592f4-ce9f-5f64-a93d-a9fea8646fc8', 'cacb2a40-a856-53fc-a805-beb850207c41', '7b4941b9-e3d9-5a85-a137-9a9df1da25ee', 9, 9, 'ዳዊትም ሀገሪቱን መታ፤ ወንድም ሆነ፥ ሴትም ሆነ፥ ማንንም በሕይወት አልተወም፤ በጎችንና ላሞችን፥ አህያዎችንና ግመሎችን፥ ልብስንም ማረከ፤ ተመልሶም ወደ አንኩስ መጣ።'),
  ('c255cfee-44ef-5814-ae68-bbe14a0196c1', 'cacb2a40-a856-53fc-a805-beb850207c41', '7b4941b9-e3d9-5a85-a137-9a9df1da25ee', 10, 10, 'አንኩስም ዳዊትን፥ “ዛሬ በማን ላይ ዘመታችሁ?” አለው፤ ዳዊትም፥ “በይሁዳ ደቡብ፥ በያሴሜጋ ደቡብ፥ በቄኔዛውያን ደቡብ ላይ ዘመትን” አለው።'),
  ('f6333638-f0d0-561b-ae7e-de9778a8285f', 'cacb2a40-a856-53fc-a805-beb850207c41', '7b4941b9-e3d9-5a85-a137-9a9df1da25ee', 11, 11, 'ዳዊት እንዲህ አደረገ፤ በፍልስጥኤማውያንም ሀገር በሚቀመጥበት ዘመን ሁሉ ልማዱ ይህ ነበረ ብለው እንዳይናገሩብን ብሎ ዳዊት ወደ ጌት ያመጣቸው ዘንድ ወንድም ሆነ ሴትም ሆነ ማንንም በሕይወት አልተወም።'),
  ('b9809c58-c41b-5ab4-a50d-5c43664ff571', 'cacb2a40-a856-53fc-a805-beb850207c41', '7b4941b9-e3d9-5a85-a137-9a9df1da25ee', 12, 12, 'አንኩስም፥ “በሕዝቡ በእስራኤል ዘንድ እጅግ የተጠላ ሆኖአል፤ ስለዚህም ለዘለዓለም ባሪያ ይሆነኛል” ብሎ ዳዊትን አመነው።'),
  ('9db51dfc-01e8-50d5-a325-522a7c2f8765', 'b5dad0c7-4385-59c4-a2f9-9e4cdb73e740', '80afd0fd-1362-5058-a1c7-fac42a1b2953', 1, 1, 'እንዲህም ሆነ፤ በዚያ ወራት ከእስራኤል ጋር ይዋጉ ዘንድ ፍልስጥኤማውያን ጭፍሮቻቸውን ለሰልፍ ሰበሰቡ፤ አንኩስም ዳዊትን፥ “አንተና ሰዎችህ ከእኔ ጋር ወደ ሰልፍ እንድትወጡ በርግጥ ዕወቅ” አለው።'),
  ('af99c348-4c5f-543c-af3d-8a449425a79e', 'b5dad0c7-4385-59c4-a2f9-9e4cdb73e740', '80afd0fd-1362-5058-a1c7-fac42a1b2953', 2, 2, 'ዳዊትም አንኩስን፥ “አሁን አገልጋይህ የሚያደርገውን ንገረው” አለው። አንኩስም ዳዊትን፥ “እንግዲህ በዘመኑ ሁሉ ራሴን ጠባቂ አደርግሃለሁ” አለው።'),
  ('b17da76d-9eaa-5640-a5c7-b545f48e3862', 'b5dad0c7-4385-59c4-a2f9-9e4cdb73e740', '220dc160-cff8-59f6-a43f-56cafc4ad2ce', 1, 3, 'ሳሙኤል ግን ሞቶ ነበር፤ እስራኤልም ሁሉ አልቅሰውለት ነበር፤ በከተማውም በአርማቴም ቀብረውት ነበር። ሳኦልም መናፍስት ጠሪዎችንና ጠንቋዮችን ከምድር አጥፍቶ ነበር።'),
  ('4bdbf2e2-f641-50d9-a11c-b27b9003e5c1', 'b5dad0c7-4385-59c4-a2f9-9e4cdb73e740', '220dc160-cff8-59f6-a43f-56cafc4ad2ce', 2, 4, 'ፍልስጥኤማውያንም ተሰብስበው መጡ፤ በሱነምም ሰፈሩ፤ ሳኦልም እስራኤልን ሁሉ ሰበሰበ፤ በጌላቡሄም ሰፈሩ።'),
  ('fbf2e7ff-523b-58ad-a7d9-0bdf15a8ec23', 'b5dad0c7-4385-59c4-a2f9-9e4cdb73e740', '220dc160-cff8-59f6-a43f-56cafc4ad2ce', 3, 5, 'ሳኦልም የፍልስጥኤማውያንን ጭፍራ ባየ ጊዜ ፈራ፤ ልቡም እጅግ ተንቀጠቀጠ።'),
  ('919b60b2-7821-584c-a796-85cc0575b517', 'b5dad0c7-4385-59c4-a2f9-9e4cdb73e740', '220dc160-cff8-59f6-a43f-56cafc4ad2ce', 4, 6, 'ሳኦልም የእግዚአብሔርን ቃል ጠየቀ፤ እግዚአብሔርም በሕልም አላሚዎች፥ ወይም በነጋሪዎች፥ ወይም በነቢያት አልመለሰለትም።'),
  ('df100060-59c1-53c6-a23a-7dc9c9275a61', 'b5dad0c7-4385-59c4-a2f9-9e4cdb73e740', '220dc160-cff8-59f6-a43f-56cafc4ad2ce', 5, 7, 'ሳኦልም ብላቴኖቹን፥ “ወደ እርስዋ ሄጄ እጠይቅ ዘንድ መናፍስትን የምትጠራ ሴት ፈልጉልኝ” አላቸው፤ ብላቴኖቹም፥ “እነሆ፥ መናፍስትን የምትጠራ አንዲት ሴት በዓይንዶር አለች” አሉት።'),
  ('59edf69b-359a-5d14-aec5-d113faa2b5ff', 'b5dad0c7-4385-59c4-a2f9-9e4cdb73e740', '220dc160-cff8-59f6-a43f-56cafc4ad2ce', 6, 8, 'ሳኦልም መልኩን ለውጦ፥ ሌላ ልብስም ለብሶ ሄደ፤ ሁለትም ሰዎች ከእርሱ ጋር ነበሩ፤ በሌሊትም ወደ ሴቲቱ መጡ። ሳኦልም፥ “እባክሽ በመናፍስት አምዋርቺልኝ፤ የምልሽንም አስነሽልኝ” አላት።'),
  ('1ded0ea0-cdb0-5388-af87-0900f8c7f174', 'b5dad0c7-4385-59c4-a2f9-9e4cdb73e740', '220dc160-cff8-59f6-a43f-56cafc4ad2ce', 7, 9, 'ሴቲቱም፥ “እነሆ፥ መናፍስት ጠሪዎችንና ጠንቋዮችን ከምድር እንዳጠፋ ሳኦል ያደረገውን ታውቃለህ፤ ስለምን እኔን ለማስገደል ለነፍሴ ወጥመድ ታደርጋለህ?” አለችው።'),
  ('9994a362-ab67-50c5-a32d-0b4593ee079f', 'b5dad0c7-4385-59c4-a2f9-9e4cdb73e740', '220dc160-cff8-59f6-a43f-56cafc4ad2ce', 8, 10, 'ሳኦልም ሕያው እግዚአብሔርን! በዚህ ነገር ክፉ አያገኝሽም ብሎ በእግዚአብሔር ማለላት።'),
  ('527a508f-cb0e-59d8-aa26-5fc805ecb327', 'b5dad0c7-4385-59c4-a2f9-9e4cdb73e740', '220dc160-cff8-59f6-a43f-56cafc4ad2ce', 9, 11, 'ሴቲቱም፥ “ማንን ላስነሣልህ?” አለችው፤ እርሱም፥ “ሳሙኤልን አስነሽልኝ” አላት።'),
  ('13876ee3-5d8e-5ef6-aa30-ead289dda433', 'b5dad0c7-4385-59c4-a2f9-9e4cdb73e740', '220dc160-cff8-59f6-a43f-56cafc4ad2ce', 10, 12, 'ሴቲቱም ሳሙኤልን ባየች ጊዜ በታላቅ ድምፅ ጮኸች፤ ሴቲቱም ሳኦልን፥ “አንተ ሳኦል ስትሆን ለምን አታለልኸኝ?” ብላ ተናገረችው።'),
  ('8b78f488-e442-5532-a4e5-2712a7cc487f', 'b5dad0c7-4385-59c4-a2f9-9e4cdb73e740', '220dc160-cff8-59f6-a43f-56cafc4ad2ce', 11, 13, 'ንጉሡም፥ “አትፍሪ ፤ ንገሪኝ፤ ማንን አየሽ?” አላት። ሴቲቱም፥ “አማልክት ከምድር ሲወጡ አየሁ” አለችው።'),
  ('3e99c500-7bd1-54ca-a902-88e2e1db12bc', 'b5dad0c7-4385-59c4-a2f9-9e4cdb73e740', '220dc160-cff8-59f6-a43f-56cafc4ad2ce', 12, 14, 'እርሱም፥ “ምን አየሽ?” አላት። እርስዋም፥ “ቀጥ ያለ ሽማግሌ ሰው ከምድር ወጣ፤ መጐናጸፊያም ተጐናጽፎአል” አለች። ሳኦልም ሳሙኤል እንደ ሆነ ዐወቀ፤ በፊቱም ወደ ምድር ጐንበስ ብሎ ሰገደለት።'),
  ('537cd8ad-2ad9-5305-a0de-adcc175a7429', 'b5dad0c7-4385-59c4-a2f9-9e4cdb73e740', '220dc160-cff8-59f6-a43f-56cafc4ad2ce', 13, 15, 'ሳሙኤልም ሳኦልን፥ “ለምን አወክኸኝ? ለምንስ አስነሣኸኝ?” አለው። ሳኦልም መልሶ፥ “ፍልስጥኤማውያን ይወጉኛልና እጅግ ተጨንቄአለሁ፤ እግዚአብሔርም ከእኔ ርቆአል፤ በነቢያት ወይም በሕልም አላሚዎች አልመለሰልኝም፤ ስለዚህም የማደርገውን ታስታውቀኝ ዘንድ ጠራሁህ” አለው።'),
  ('ebb561dd-9c6f-5bdb-a804-fad6009d901e', 'b5dad0c7-4385-59c4-a2f9-9e4cdb73e740', '220dc160-cff8-59f6-a43f-56cafc4ad2ce', 14, 16, 'ሳሙኤልም አለ፥ “እግዚአብሔር ከራቀህ፥ ወደ ባልንጀራህም ከተመለሰ ለምን ትጠይቀኛለህ?'),
  ('e778010e-8c7c-5b7e-a02c-05be28610d9c', 'b5dad0c7-4385-59c4-a2f9-9e4cdb73e740', '220dc160-cff8-59f6-a43f-56cafc4ad2ce', 15, 17, 'እግዚአብሔርም በቃሌ እንደ ተናገረ አድርጎአል፤ እግዚአብሔርም መንግሥትህን ከእጅህ ነጥቆ ለባልንጀራህ ለዳዊት ሰጥቶታል።'),
  ('c6bf225f-8f68-534b-aba5-e6e9328edf31', 'b5dad0c7-4385-59c4-a2f9-9e4cdb73e740', '220dc160-cff8-59f6-a43f-56cafc4ad2ce', 16, 18, 'የእግዚአብሔርን ቃል አልሰማህምና፥ በአማሌቅም ላይ ታላቅ የሆነ ቍጣውን አላደረግህምና ስለዚህ ዛሬ እግዚአብሔር ይህን ነገር አድርጎብሃል።'),
  ('fbb65bb1-892b-5cb6-a1c7-1c96cc61fd24', 'b5dad0c7-4385-59c4-a2f9-9e4cdb73e740', '220dc160-cff8-59f6-a43f-56cafc4ad2ce', 17, 19, 'እግዚአብሔርም እስራኤልን ከአንተ ጋር በፍልስጥኤማውያን እጅ አሳልፎ ይሰጣል፤ ነገም አንተና ከአንተ ጋር ያሉ ልጆችህ ትወድቃላችሁ፥ እግዚአብሔርም የእስራኤልን ጭፍራ ደግሞ በፍልስጥኤማውያን እጅ አሳልፎ ይሰጣል።'),
  ('a9135978-4bff-5b68-a42b-729940b8f56b', 'b5dad0c7-4385-59c4-a2f9-9e4cdb73e740', '220dc160-cff8-59f6-a43f-56cafc4ad2ce', 18, 20, 'ሳኦልም በዚያ ጊዜ በቁመቱ ሙሉ በምድር ላይ ወደቀ፤ ከሳሙኤልም ቃል የተነሣ እጅግ ፈራ። በዚያም ቀን ሁሉ፥ በዚያም ሌሊት ሁሉ እንጀራ አልበላምና ኀይል አልቀረለትም።'),
  ('882676b9-5d34-5f6e-a7b2-02a2aab38f74', 'b5dad0c7-4385-59c4-a2f9-9e4cdb73e740', '220dc160-cff8-59f6-a43f-56cafc4ad2ce', 19, 21, 'ሴቲቱም ወደ ሳኦል መጣች፤ እጅግም ደንግጦ እንደ ነበር አይታ፥ “እነሆ፥ እኔ አገልጋይህ ቃልህን ሰማሁ፤ ነፍሴንም በእጄ ጣልሁ፤ የነገርኸኝንም ቃል ሰማሁ።'),
  ('8e275407-79e0-5f15-ae96-3875b912bb7d', 'b5dad0c7-4385-59c4-a2f9-9e4cdb73e740', '220dc160-cff8-59f6-a43f-56cafc4ad2ce', 20, 22, 'አሁን እንግዲህ አንተ ደግሞ የአገልጋይህን ቃል እንድትሰማ እለምንሃለሁ፤ በፊትህም ቁራሽ እንጀራ ላኑርልህ፤ መንገድም ትሄዳለህና ትበረታ ዘንድ ብላ” አለችው።'),
  ('894aac56-001e-5323-a449-d8c6da76c8f2', 'b5dad0c7-4385-59c4-a2f9-9e4cdb73e740', '220dc160-cff8-59f6-a43f-56cafc4ad2ce', 21, 23, 'እርሱ ግን፥ “አልበላም” ብሎ እንቢ አለ፤ ነገር ግን ብላቴኖቹና ሴቲቱ አስገደዱት፤ ቃላቸውንም ሰማ፤ ከምድርም ተነሥቶ በአልጋ ላይ ተቀመጠ።'),
  ('4637c0d5-ff38-52ff-acfa-34d7283a340b', 'b5dad0c7-4385-59c4-a2f9-9e4cdb73e740', '220dc160-cff8-59f6-a43f-56cafc4ad2ce', 22, 24, 'ለሴቲቱም የሰባ ጥጃ በቤት ነበራት፤ ፈጥና አረደችው፤ ዱቄቱንም ወስዳ ለወሰችው፤ ቂጣም እንጀራ አድርጋ ጋገረችው።'),
  ('9e8500b4-3f8b-5597-a2d2-2a4135b738f9', 'b5dad0c7-4385-59c4-a2f9-9e4cdb73e740', '220dc160-cff8-59f6-a43f-56cafc4ad2ce', 23, 25, 'በሳኦልና በብላቴኖቹም ፊት አቀረበችው፤ በልተውም ተነሡ፤ በዚያም ሌሊት ሄዱ።'),
  ('3e2a02c7-bedd-5929-a89e-bf89e4a87e79', 'a0a6764b-7245-5d49-ac6b-3fd77d8e9ff6', '1e1abd97-2817-5a55-a1b3-df8e8b381438', 1, 1, 'ፍልስጥኤማውያንም ጭፍሮቻቸውን ሁሉ ወደ አፌቅ ሰበሰቡ፤ እስራኤላውያንም በኢይዝራኤል ባለው ውኃ ምንጭ አጠገብ ሰፈሩ።'),
  ('863b729e-c826-5ac5-a372-0b2ce64d91eb', 'a0a6764b-7245-5d49-ac6b-3fd77d8e9ff6', '1e1abd97-2817-5a55-a1b3-df8e8b381438', 2, 2, 'የፍልስጥኤማውያንም አለቆች በመቶ በመቶ፥ በሺህ በሺህ እየሆኑ ያልፉ ነበር፤ ዳዊትና ሰዎቹም ከአንኩስ ጋር በኋለኛው ጭፍራ በኩል ያልፉ ነበር።'),
  ('2eb40f51-e95b-5da6-aa3e-cee0981f2772', 'a0a6764b-7245-5d49-ac6b-3fd77d8e9ff6', '1e1abd97-2817-5a55-a1b3-df8e8b381438', 3, 3, 'የፍልስጥኤማውያን አለቆች፥ “እነዚህ በኋላ የሚሄዱት እነማን ናቸው?” አሉ፤ አንኩስም የፍልስጥኤማውያንን አለቆች፥ “ይህ የእስራኤል ንጉሥ የሳኦል አገልጋይ ዳዊት ነው፤ እርሱ በእነዚህ ሁለት ዓመታት ከእኛ ጋር ነበረ፤ ወደ እኔም ከተጠጋበት ቀን ጀምሮ እስከ ዛሬ ድረስ ምንም አላገኘሁበትም” አላቸው።'),
  ('d2551184-dc94-53da-aa34-4f03342732a7', 'a0a6764b-7245-5d49-ac6b-3fd77d8e9ff6', '1e1abd97-2817-5a55-a1b3-df8e8b381438', 4, 4, 'የፍልስጥኤማውያን አለቆች ግን በእርሱ ላይ ተቈጥተው፥ “ይህን ሰው ወደ አመጣህበት ቦታ መልሰው፤ በሰልፉም ውስጥ ጠላት እንዳይሆነን ከእኛ ጋር ወደ ሰልፍ አይውረድ፤ ከጌታው ጋር በምን ይታረቃል? የእነዚህን ሰዎች ራስ በመቍረጥ አይደለምን?'),
  ('d4c08084-bdde-5780-ad55-a5b67b06bfd3', 'a0a6764b-7245-5d49-ac6b-3fd77d8e9ff6', '1e1abd97-2817-5a55-a1b3-df8e8b381438', 5, 5, 'ወይስ ሴቶች፦ ‘ሳኦል ሺህ ገደለ፥ ዳዊት ዐሥር ሺህ ገደለ’ ብለው በዘፈን የዘመሩለት ይህ ዳዊት አይደለምን?” አሉት።'),
  ('b52297f7-0422-55d0-a4a9-e1cdd11cc4a8', 'a0a6764b-7245-5d49-ac6b-3fd77d8e9ff6', '1e1abd97-2817-5a55-a1b3-df8e8b381438', 6, 6, 'አንኩስም ዳዊትን ጠርቶ፥ “ሕያው እግዚአብሔርን! አንተ በፊቴ ጻድቅና ደግ ነህ፤ ከእኔም ጋር በጭፍራው በኩል መውጣትህና መግባትህ በፊቴ መልካም ነው፤ ወደ እኔ ከመጣህ ጀምሮ እስከ ዛሬ ድረስ አንዳች ክፋት አላገኘሁብህም፤ ነገር ግን በአለቆች ዘንድ አልተወደድህም።'),
  ('03ab0dc4-5409-53a9-a787-37a30149834c', 'a0a6764b-7245-5d49-ac6b-3fd77d8e9ff6', '1e1abd97-2817-5a55-a1b3-df8e8b381438', 7, 7, 'አሁንም ተመልሰህ በሰላም ሂድ፤ በፍልስጥኤማውያንም አለቆች ዐይን ክፋት አታድርግ” አለው።'),
  ('02483389-f585-5471-afcc-08eb20646508', 'a0a6764b-7245-5d49-ac6b-3fd77d8e9ff6', '1e1abd97-2817-5a55-a1b3-df8e8b381438', 8, 8, 'ዳዊትም አንኩስን፥ “ምን አድርጌአለሁ? ሄጄስ ከጌታዬ ከንጉሡ ጠላቶች ጋር እንዳልዋጋ፥ በፊትህ ከተቀመጥሁ ጀምሬ እስከ ዛሬ ድረስ በእኔ በአገልጋይህ ምን በደል አግኝተህብኛል?” አለው።'),
  ('fa2b8cc8-91f3-5112-ab50-96d9d2079cda', 'a0a6764b-7245-5d49-ac6b-3fd77d8e9ff6', '1e1abd97-2817-5a55-a1b3-df8e8b381438', 9, 9, 'አንኩስም መልሶ ዳዊትን፥ “በዐይኔ ፊት ጻድቅ እንደ ሆንህ አውቃለሁ፤ ነገር ግን የፍልስጥኤማውያን አለቆች፦ ‘ከእኛ ጋር ወደ ሰልፍ አይወጣም’ አሉ።'),
  ('de7e5805-dbf9-50d0-a296-d89d1054519b', 'a0a6764b-7245-5d49-ac6b-3fd77d8e9ff6', '1e1abd97-2817-5a55-a1b3-df8e8b381438', 10, 10, 'አሁንም አንተ ከአንተም ጋር የመጡ የጌታህ ብላቴኖች ማልዳችሁ ተነሡ፤ ሲነጋም ተነሥታችሁ ወደ መጣችሁበት ሂዱ። ክፉ ነገርንም በልብህ አታኑር፤ በዐይኔ ፊት ጻድቅ ነህና፥ በነጋም ጊዜ ገሥግሣችሁ መንገዳችሁን ሂዱ” አለው። እነርሱም ሄዱ።'),
  ('74870fbc-7998-5132-a6f1-89ada1996ca9', 'a0a6764b-7245-5d49-ac6b-3fd77d8e9ff6', '1e1abd97-2817-5a55-a1b3-df8e8b381438', 11, 11, 'ዳዊትና ሰዎቹም ማልደው ይሄዱ ዘንድ፥ ወደ ፍልስጥኤማውያንም ሀገር ይመለሱ ዘንድ ተነሡ። ፍልስጥኤማውያንም ሊዋጉ ወደ ኢይዝራኤል ወጡ።'),
  ('9c1df217-eda6-5ac7-a895-457098b90fe6', '5c047041-c4eb-5fc6-a1b1-f0efe5bf4e7a', '21e7a6d8-7e61-5850-aaf2-39651b606bb9', 1, 1, 'እንዲህም ሆነ፤ ዳዊትና ሰዎቹ በሦስተኛው ቀን ወደ ሴቄላቅ በገቡ ጊዜ፥ አማሌቃውያን በአዜብ በሰቄላቅም ላይ ዘምተው ነበር፤ ሴቄላቅንም መትተው በእሳት አቃጥለዋት ነበር፥'),
  ('ad6e1b92-fb22-57e6-a2ba-4150b63b45bd', '5c047041-c4eb-5fc6-a1b1-f0efe5bf4e7a', '21e7a6d8-7e61-5850-aaf2-39651b606bb9', 2, 2, 'ሴቶቹንና በውስጥዋም የነበሩትን ሁሉ ከታናሽ እስከ ታላቅ ድረስ ማርከው ነበር፤ ሁሉንም ወስደው መንገዳቸውን ሄዱ እንጂ ሴቶችንም ሆነ ወንዶችን አልገደሉም።'),
  ('f038ef97-cbdc-57d1-a23e-105165f15630', '5c047041-c4eb-5fc6-a1b1-f0efe5bf4e7a', '21e7a6d8-7e61-5850-aaf2-39651b606bb9', 3, 3, 'ዳዊትና ሰዎቹም ወደ ከተማ በመጡ ጊዜ፥ እነሆ፥ በእሳት ተቃጥላ፥ ሚስቶቻቸውም ወንዶችና ሴቶች ልጆቻቸውም ተማርከው አገኙ።'),
  ('295737ef-e0b7-53c4-a719-54aac84865f7', '5c047041-c4eb-5fc6-a1b1-f0efe5bf4e7a', '21e7a6d8-7e61-5850-aaf2-39651b606bb9', 4, 4, 'ዳዊትና ከእርሱም ጋር የነበሩ ሕዝብ ድምፃቸውን ከፍ አድርገው ለማልቀስ ኀይል እስኪያጡ ድረስ አለቀሱ።'),
  ('d8593ddd-0f8b-5188-ad0b-79d53a796502', '5c047041-c4eb-5fc6-a1b1-f0efe5bf4e7a', '21e7a6d8-7e61-5850-aaf2-39651b606bb9', 5, 5, 'የዳዊትም ሁለቱ ሚስቶቹ ኢይዝራኤላዊቱ አኪናሆምና የቀርሜሎሳዊው የናባል ሚስት የነበረችው አቤግያ ተማርከው ነበር።'),
  ('7dac43e8-4a2f-572f-a690-a52ff3e14c80', '5c047041-c4eb-5fc6-a1b1-f0efe5bf4e7a', '21e7a6d8-7e61-5850-aaf2-39651b606bb9', 6, 6, 'ስለ ወንዶችና ስለ ሴቶች ልጆቻቸውም የሕዝቡ ሁሉ ልብ አዝኖ ነበርና ሕዝቡ ሊወግሩት ስለ ተናገሩ ዳዊት እጅግ ተጨነቀ፤ ዳዊት ግን በአምላኩ በእግዚአብሔር ራሱን አጽናና።'),
  ('d813e8dd-33ce-52bc-a1a2-20b63ecf6c5b', '5c047041-c4eb-5fc6-a1b1-f0efe5bf4e7a', '21e7a6d8-7e61-5850-aaf2-39651b606bb9', 7, 7, 'ዳዊትም የአቤሜሌክን ልጅ ካህኑን አብያታርን፥ “ኤፉዱን አቅርብልኝ” አለው፤ አብያታርም ኤፉዱን ለዳዊት አቀረበለት።'),
  ('ea14a63d-c06c-5925-a221-b396d0ad6d7a', '5c047041-c4eb-5fc6-a1b1-f0efe5bf4e7a', '21e7a6d8-7e61-5850-aaf2-39651b606bb9', 8, 8, 'ዳዊትም፥ “የእነዚህን ሠራዊት ፍለጋ ልከተልን? አገኛቸዋለሁን?” ብሎ እግዚአብሔርን ጠየቀ፤ እርሱም፥ “ታገኛቸዋለህና፥ ፈጽመህም ምርኮኞቹን ታድናለህና ፍለጋቸውን ተከተል” ብሎ መለሰለት።'),
  ('8d3b70e1-6a0a-5d5d-a397-a4e8a1991a0a', '5c047041-c4eb-5fc6-a1b1-f0efe5bf4e7a', '21e7a6d8-7e61-5850-aaf2-39651b606bb9', 9, 9, 'ዳዊትም ከእርሱም ጋር የነበሩት ስድስት መቶ ሰዎች ሄዱ፤ እስከ ቦሦር ወንዝ ድረስም መጡ፤ ከእነርሱም የቀሩት በዚያ ተቀመጡ።'),
  ('58ffc371-6cf4-58a6-ad9f-b3a64cd222fc', '5c047041-c4eb-5fc6-a1b1-f0efe5bf4e7a', '21e7a6d8-7e61-5850-aaf2-39651b606bb9', 10, 10, 'ዳዊትም ከእርሱም ጋር ያሉት አራት መቶ ሰዎች አሳደዱ፤ ሁለቱ መቶ ሰዎች ግን የቦሦር ወንዝን መሻገር ደክመዋልና በኋላ ቀሩ።'),
  ('303c7e1b-5f61-50af-a154-87b1d1bc3a53', '5c047041-c4eb-5fc6-a1b1-f0efe5bf4e7a', '21e7a6d8-7e61-5850-aaf2-39651b606bb9', 11, 11, 'በበረሃውም ውስጥ አንድ ግብፃዊ አግኝተው ወደ ዳዊት ይዘውት መጡ፤ እንጀራም ሰጡትና በላ፤ ውኃም አጠጡት።'),
  ('ec621788-03ea-59d9-a528-4de8ac2e124c', '5c047041-c4eb-5fc6-a1b1-f0efe5bf4e7a', '21e7a6d8-7e61-5850-aaf2-39651b606bb9', 12, 12, 'ከበለሱም ጥፍጥፍ ቍራጭ ሰጡትና በላ፤ ነፍሱም ወደ እርሱ ተመለሰች፤ ሦስት ቀንና ሦስት ሌሊት እንጀራ አልበላም፤ ውኃም አልጠጣም ነበርና።'),
  ('c5cc7f4c-0ccf-58b2-ac61-da0baf761c25', '5c047041-c4eb-5fc6-a1b1-f0efe5bf4e7a', '21e7a6d8-7e61-5850-aaf2-39651b606bb9', 13, 13, 'ዳዊትም፥ “አንተ የማን ነህ? ከወዴት መጣህ?” አለው። ያም ግብፃዊ ብላቴና፥ “እኔ የአማሌቃዊ ባሪያ ነኝ፤ ከሦስት ቀንም በፊት ታምሜ ነበርና ጌታዬ ጥሎኝ ሄደ።'),
  ('e5649327-81a5-54ce-afbf-bce3371ecb6b', '5c047041-c4eb-5fc6-a1b1-f0efe5bf4e7a', '21e7a6d8-7e61-5850-aaf2-39651b606bb9', 14, 14, 'እኛም በከሊታውያን አዜብ፥ በይሁዳም በኩል፥ በካሌብም አዜብ ላይ ዘመትን፥ ሴቄላቅንም በእሳት አቃጠልናት” አለው።'),
  ('efb2ded9-b229-515e-a8a2-66756eea4050', '5c047041-c4eb-5fc6-a1b1-f0efe5bf4e7a', '21e7a6d8-7e61-5850-aaf2-39651b606bb9', 15, 15, 'ዳዊትም፥ “ወደ እነዚያ ሠራዊት ልትመራኝ ትወድዳለህን?” አለው፥ እርሱም፥ “እንዳትገድለኝ፥ ለጌታዬም እጅ አሳልፈህ እንዳትሰጠኝ በአምላክ ማልልኝ፤ እኔም ወደ እነዚያ ሠራዊት እመራሃለሁ” አለው።'),
  ('783b2606-2ca9-564a-a14a-b12b1de9f780', '5c047041-c4eb-5fc6-a1b1-f0efe5bf4e7a', '21e7a6d8-7e61-5850-aaf2-39651b606bb9', 16, 16, 'ወደ እዚያም ባደረሰው ጊዜ፥ እነሆ፥ ከፍልስጥኤማውያንና ከይሁዳ ምድር ከወሰዱት ከብዙ ምርኮ ሁሉ የተነሣ በልተው፥ ጠጥተው፥ የበዓልም ቀን አድርገው፥ በምድር ሁሉ ላይ ተበትነው አገኛቸው።'),
  ('ef4d3d87-31f3-57c5-ab6b-773e8acbd113', '5c047041-c4eb-5fc6-a1b1-f0efe5bf4e7a', '21e7a6d8-7e61-5850-aaf2-39651b606bb9', 17, 17, 'ዳዊትም ሄዶ የአጥቢያ ኮከብ ከሚወጣበት ጀምሮ እስከ ማታ ድረስ ዳግመኛም በማግሥቱ መታቸው፤ ከእነርሱም በግመል ተቀምጠው ከሸሹት አራት መቶ ጐልማሶች በቀር አንድም ያመለጠ የለም።'),
  ('1adfb1fe-4af5-51c4-ab07-c2d945404504', '5c047041-c4eb-5fc6-a1b1-f0efe5bf4e7a', '21e7a6d8-7e61-5850-aaf2-39651b606bb9', 18, 18, 'ዳዊትም አማሌቃውያን የወሰዱትን ሁሉ አስጣላቸው፤ ሁለቱንም ሚስቶቹን አዳነ።'),
  ('48e69373-eec5-58ed-aaac-bfd21eaf7292', '5c047041-c4eb-5fc6-a1b1-f0efe5bf4e7a', '21e7a6d8-7e61-5850-aaf2-39651b606bb9', 19, 19, 'ከወንዶችና ከሴቶች ልጆች፥ ከወሰዱት ምርኮ ሁሉ፥ ታላቅም ሆነ፥ ታናሽም ሆነ፥ ምንም የተወላቸው የለም፤ ዳዊትም ሁሉን አስጣለ።'),
  ('c04f79ba-a827-5680-ad20-4420b7dc7eed', '5c047041-c4eb-5fc6-a1b1-f0efe5bf4e7a', '21e7a6d8-7e61-5850-aaf2-39651b606bb9', 20, 20, 'ዳዊትም የበጉንና የላሙን መንጋ ሁሉ ወሰደ፤ ምርኮውንም በፊቱ ነዱ፤ ያንም ምርኮ “የዳዊት ምርኮ” አሉት።'),
  ('6c368459-a53f-5fdc-a948-010efab2d8e2', '5c047041-c4eb-5fc6-a1b1-f0efe5bf4e7a', '21e7a6d8-7e61-5850-aaf2-39651b606bb9', 21, 21, 'ዳዊትም ደክመው ዳዊትን ይከተሉት ዘንድ ወዳልቻሉ፥ በቦሦር ወንዝ ወዳስቀራቸው ወደ ሁለቱ መቶ ሰዎች መጣ፤ እነርሱም ዳዊትን ከእርሱም ጋር የነበሩትን ሕዝብ ሊቀበሉ ወጡ፤ ዳዊትም ወደ ሕዝቡ በቀረበ ጊዜ ደኅንነቱን ጠየቁት።'),
  ('53f92844-4f0f-5ea9-af28-360186d42fcc', '5c047041-c4eb-5fc6-a1b1-f0efe5bf4e7a', '21e7a6d8-7e61-5850-aaf2-39651b606bb9', 22, 22, 'ከዳዊትም ጋር ከሄዱ ሰዎች ክፉዎቹና ዐመፀኞቹ ሁሉ፥ “እነዚህ ከእኛ ጋር አልመጡምና እየራሳቸው ሚስቶቻቸውንና ልጆቻቸውን ይዘው ይሂዱ እንጂ ካስጣልነው ምርኮ ምንም አንሰጣቸውም” አሉ።'),
  ('a8de5a5d-e084-5850-a275-60a89793580f', '5c047041-c4eb-5fc6-a1b1-f0efe5bf4e7a', '21e7a6d8-7e61-5850-aaf2-39651b606bb9', 23, 23, 'ዳዊትም አለ፥ “እግዚአብሔር አሳልፎ ከሰጠን በኋላ እንዲህ አታድርጉ፤ እርሱ ጠብቆናል፤ በእኛም ላይ የመጡትን ሠራዊት በእጃችን አሳልፎ ሰጥቶናል፤'),
  ('7cbccc7c-2895-5f23-affd-37b11f1c72c2', '5c047041-c4eb-5fc6-a1b1-f0efe5bf4e7a', '21e7a6d8-7e61-5850-aaf2-39651b606bb9', 24, 24, 'ይህንስ ነገር ማን ይሰማችኋል? እናንተ ከእነርሱ አትበልጡምና ወደ ጦርነት በሄዱት ድርሻ ልክ ጓዝ የጠበቁ ሰዎች ድርሻ እንዲሁ ነው።”'),
  ('1b99600e-9cdf-53bf-a1ff-e0e2023b59e8', '5c047041-c4eb-5fc6-a1b1-f0efe5bf4e7a', '21e7a6d8-7e61-5850-aaf2-39651b606bb9', 25, 25, 'ከዚያም ቀን ጀምሮ እስከ ዛሬ ድረስ ይህ ለእስራኤል ሥርዐትና ሕግ ሆነ።'),
  ('23f85a4f-1feb-58d1-a78d-a8dec014071f', '5c047041-c4eb-5fc6-a1b1-f0efe5bf4e7a', '21e7a6d8-7e61-5850-aaf2-39651b606bb9', 26, 26, 'ዳዊትም ወደ ሴቄላቅ በመጣ ጊዜ ለይሁዳ ሽማግሌዎችና ለወዳጆቹ፥ “እነሆ፥ ከእግዚአብሔር ጠላቶች ምርኮ በረከትን ተቀበሉ” ብሎ ከምርኮው ላከላቸው።'),
  ('dd876f89-ec0b-5f8b-a1b9-5bbe4d7930cb', '5c047041-c4eb-5fc6-a1b1-f0efe5bf4e7a', '21e7a6d8-7e61-5850-aaf2-39651b606bb9', 27, 27, 'በቤትሶር ለነበሩ፥ በራማ አዜብም ለነበሩ፥ በጌትም ለነበሩ፥'),
  ('2ebbef77-7fb4-5939-af6a-725cb3030f9c', '5c047041-c4eb-5fc6-a1b1-f0efe5bf4e7a', '21e7a6d8-7e61-5850-aaf2-39651b606bb9', 28, 28, 'በቄኔት ለነበሩ፥ በሳፌቅ ለነበሩ፥ በቴማት ለነበሩ፥'),
  ('24887546-063f-5a29-ac78-5cb69ef3960f', '5c047041-c4eb-5fc6-a1b1-f0efe5bf4e7a', '21e7a6d8-7e61-5850-aaf2-39651b606bb9', 29, 29, 'በቀርሜሎስ ለነበሩ፥ በይረሕምኤላውያንና በቄኔዛውያን ከተሞችም ለነበሩ፥'),
  ('6b363979-d6c1-5243-a9c6-bc449f90b201', '5c047041-c4eb-5fc6-a1b1-f0efe5bf4e7a', '21e7a6d8-7e61-5850-aaf2-39651b606bb9', 30, 30, 'በኢያሬሞት በቤርሳቤህ ለነበሩ፥ በኖባማ ለነበሩ፥'),
  ('dc3e6020-1553-5a12-afa5-be7398628796', '5c047041-c4eb-5fc6-a1b1-f0efe5bf4e7a', '21e7a6d8-7e61-5850-aaf2-39651b606bb9', 31, 31, 'በኬብሮን ለነበሩ፥ ዳዊትና ሰዎቹም በተመላለሱበት ስፍራ ለነበሩ ሰዎች ሁሉ ላከ።'),
  ('2d31bddb-77a5-536b-a7eb-78db94e79b7a', 'd05e8fd5-2994-538d-ae16-170fdabfb698', '023d38ff-0602-59d4-aa0b-163a59f5ea5f', 1, 1, 'ፍልስጥኤማውያንም ከእስራኤል ጋር ተዋጉ፤ የእስራኤልም ሰዎች ከፍልስጥኤማውያን ፊት ሸሹ፤ ተዋግተውም በጌላቡሄ ተራራ ላይ ወደቁ።'),
  ('14337a86-a908-5f0f-a702-7c30a690c6dc', 'd05e8fd5-2994-538d-ae16-170fdabfb698', '023d38ff-0602-59d4-aa0b-163a59f5ea5f', 2, 2, 'ፍልስጥኤማውያንም ሳኦልንና ልጆቹን ተከትለው አገኙአቸው። ፍልስጥኤማውያንም የሳኦልን ልጆች ዮናታንንና አሚናዳብን፥ ሜልኪሳንም ገደሉአቸው።'),
  ('bc31c6a3-e5d8-56ea-aa79-4c62e6962572', 'd05e8fd5-2994-538d-ae16-170fdabfb698', '023d38ff-0602-59d4-aa0b-163a59f5ea5f', 3, 3, 'ሰልፍም በሳኦል ላይ ጠነከረ፤ ቀስተኞችም አገኙት፤ ታፋውንም ወጉት።'),
  ('a08f05b4-33ce-5105-a495-f7d0a37f76d0', 'd05e8fd5-2994-538d-ae16-170fdabfb698', '023d38ff-0602-59d4-aa0b-163a59f5ea5f', 4, 4, 'ሳኦልም ጋሻ ጃግሬውን፥ “እነዚህ ቈላፋን መጥተው እንዳይወጉኝና እንዳይሳለቁብኝ ሰይፍህን መዝዘህ ውጋኝ” አለ። ጋሻ ጃግሬው ግን እጅግ ፈርቶ ነበርና እንቢ አለ። ሳኦልም ሰይፉን ወስዶ በላዩ ወደቀ።'),
  ('d27fe1d3-a28d-5281-a738-0f1c7af5c0c0', 'd05e8fd5-2994-538d-ae16-170fdabfb698', '023d38ff-0602-59d4-aa0b-163a59f5ea5f', 5, 5, 'ጋሻ ጃግሬውም ሳኦል እንደ ሞተ ባየ ጊዜ እርሱ ደግሞ በሰይፉ ላይ ወደቀ። ከእርሱም ጋር ሞተ።'),
  ('898cb776-4e8a-5400-a668-def530bd3ace', 'd05e8fd5-2994-538d-ae16-170fdabfb698', '023d38ff-0602-59d4-aa0b-163a59f5ea5f', 6, 6, 'በዚያም ቀን ሳኦል ሦስቱም ልጆቹ ጋሻ ጃግሬውም በአንድ ላይ ሞቱ።'),
  ('18af84cc-d5d9-5bae-ab98-cc8de7ba2d49', 'd05e8fd5-2994-538d-ae16-170fdabfb698', '023d38ff-0602-59d4-aa0b-163a59f5ea5f', 7, 7, 'በሸለቆውም ማዶና በዮርዳኖስ ማዶ የነበሩ እስራኤላውያን የእስራኤል ሰዎች እንደ ሸሹ፥ ሳኦልና ልጆቹም እንደ ሞቱ ባዩ ጊዜ ከተሞቹን ለቅቀው ሸሹ፤ ፍልስጥኤማውያንም መጥተው ተቀመጡባቸው።'),
  ('4b80d8d6-c4dc-5f05-a8d1-9a0f0f025cdd', 'd05e8fd5-2994-538d-ae16-170fdabfb698', '023d38ff-0602-59d4-aa0b-163a59f5ea5f', 8, 8, 'በማግሥቱም ፍልስጥኤማውያን የሞቱትን ለመግፈፍ በመጡ ጊዜ ሳኦልና ሦስቱ ልጆቹ በጌላቡሄ ተራራ ላይ ወድቀው አገኙአቸው።'),
  ('656deb58-be01-51ba-ae90-312f1d5c1ce3', 'd05e8fd5-2994-538d-ae16-170fdabfb698', '023d38ff-0602-59d4-aa0b-163a59f5ea5f', 9, 9, 'አገላብጠውም የጦር መሣሪያዎችን ገፈፉ፤ በዙሪያቸውም ላሉ ለጣዖታቱና ለሕዝቡ የምሥራች ይነግሩ ዘንድ ወደ ፍልስጥኤማውያን ሀገር ሁሉ ላኩ።'),
  ('792e9ac3-2e17-5d06-a3c5-477a4d3b7ca4', 'd05e8fd5-2994-538d-ae16-170fdabfb698', '023d38ff-0602-59d4-aa0b-163a59f5ea5f', 10, 10, 'የጦር መሣሪያውንም በአስታሮት መቅደስ ውስጥ አኖሩት። ሬሳውንም በቤትሶም ቅጥር ላይ አንጠለጠሉት።'),
  ('7b9e7576-635a-53cb-a6cd-9e6ee6865fa0', 'd05e8fd5-2994-538d-ae16-170fdabfb698', '023d38ff-0602-59d4-aa0b-163a59f5ea5f', 11, 11, 'ፍልስጥኤማውያንም በሳኦል ላይ ያደረጉትን የኢያቢስ ገለዓድ ሰዎች በሰሙ ጊዜ፥ ጀግኖች ሰዎች ሁሉ ተነሥተው ሌሊቱን ሁሉ ሄዱ፥'),
  ('4667419f-0c6c-5ec7-acfb-826381190561', 'd05e8fd5-2994-538d-ae16-170fdabfb698', '023d38ff-0602-59d4-aa0b-163a59f5ea5f', 12, 12, 'የሳኦልንም ሬሳ፥ የልጁ የዮናታንንም ሬሳ ከቤትሶም ቅጥር ላይ አወረዱ፤ ወደ ኢያቢስም አመጡአቸው፤ በዚያም አቃጠሉአቸው።'),
  ('e7950843-29c9-5d72-abae-bd4b39e53a5d', 'd05e8fd5-2994-538d-ae16-170fdabfb698', '023d38ff-0602-59d4-aa0b-163a59f5ea5f', 13, 13, 'አጥንቶቻቸውንም ወሰዱ፤ በኢያቢስም ባለው የእርሻ ቦታ ቀበሩአቸው፤ ሰባት ቀንም ጾሙ።'),
  ('d7e6cb43-3075-5699-a51f-3e790500c3a2', '93e280cc-fa4b-5de5-a17f-2921cff9225b', 'a81ffb53-9f45-5c39-ae42-9a103df138ee', 1, 1, 'እንዲህም ሆነ፤ ሳኦል ከሞተ በኋላ ዳዊት አማሌቃውያንን ከመግደል ተመለሰ፤ ዳዊትም በሴቄላቅ ሁለት ቀን ተቀመጠ።'),
  ('e7aba409-f32d-52a5-ad30-2da5c67ab9c5', '93e280cc-fa4b-5de5-a17f-2921cff9225b', 'a81ffb53-9f45-5c39-ae42-9a103df138ee', 2, 2, 'በሦስተኛውም ቀን፥ እነሆ፥ ከሰፈር ከሳኦል ወገን አንድ ሰው ልብሱን ቀድዶ፥ በራሱም ላይ ትቢያ ነስንሶ መጣ፤ ወደ ዳዊትም በመጣ ጊዜ በምድር ላይ ወድቆ ሰገደለት።'),
  ('c367a330-0ff6-5ced-a3ad-636783e137d4', '93e280cc-fa4b-5de5-a17f-2921cff9225b', 'a81ffb53-9f45-5c39-ae42-9a103df138ee', 3, 3, 'ዳዊትም፥ “ከወዴት መጣህ?” አለው፤ እርሱም፥ “ከእስራኤል ሰፈር አምልጬ መጣሁ” አለው።'),
  ('4fdd12be-dad4-5596-a724-d3f612e6fd50', '93e280cc-fa4b-5de5-a17f-2921cff9225b', 'a81ffb53-9f45-5c39-ae42-9a103df138ee', 4, 4, 'ዳዊትም፥ “ነገሩ ምንድን ነው? እስኪ ንገረኝ” አለው። እርሱም መልሶ፥ “ሕዝቡ ከሰልፉ ሸሽቶአል፤ ከሕዝቡም ብዙው ወደቁ፤ ሞቱም፤ ሳኦልና ልጁ ዮናታንም ደግሞ ሞተዋል” አለው።'),
  ('bd1f3a56-016b-5b95-a1d2-7592a1d6e3c5', '93e280cc-fa4b-5de5-a17f-2921cff9225b', 'a81ffb53-9f45-5c39-ae42-9a103df138ee', 5, 5, 'ዳዊትም ወሬውን ያመጣለትን ጐልማሳ፥ “ሳኦልና ልጁ ዮናታን እንደ ሞቱ እንዴት ዐወቅህ?” አለው።'),
  ('fc78524d-b851-5769-ac35-ff4fc98f5b96', '93e280cc-fa4b-5de5-a17f-2921cff9225b', 'a81ffb53-9f45-5c39-ae42-9a103df138ee', 6, 6, 'ወሬውን ያመጣለት ጎልማሳም አለ፥ “በጌላቡሄ ተራራ ተዋግተው ወደቁ፤ እነሆም፥ ሳኦል በጦሩ ላይ ተኝቶ ነበር፤ ሰረገሎችና ፈረሰኞችም ተከትለው ደረሱበት።'),
  ('a09bff78-b4b7-508c-ae06-3c9dcb6e37de', '93e280cc-fa4b-5de5-a17f-2921cff9225b', 'a81ffb53-9f45-5c39-ae42-9a103df138ee', 7, 7, 'ወደ ኋላውም ዘወር አለና እኔን አይቶ ጠራኝ፤ እኔም፦ እነሆኝ አልሁ።'),
  ('a480e77a-6e04-5873-a565-7e625ad3a72e', '93e280cc-fa4b-5de5-a17f-2921cff9225b', 'a81ffb53-9f45-5c39-ae42-9a103df138ee', 8, 8, 'እርሱም፦ አንተ ማን ነህ? አለኝ፤ እኔም አማሌቃዊ ነኝ ብዬ መለስሁለት።'),
  ('be2d53ce-54a8-591b-a4cb-5197ff6e5ec0', '93e280cc-fa4b-5de5-a17f-2921cff9225b', 'a81ffb53-9f45-5c39-ae42-9a103df138ee', 9, 9, 'እርሱም፦ ክፉ ጨለማ ይዞኛልና ደግሞ እስካሁን ድረስ ነፍሴ ገና ፈጽማ ሕያውት ናትና በላዬ ቆመህ ግደለኝ አለኝ።'),
  ('82bb80bf-2ced-586a-a5e8-856ce0d6a10f', '93e280cc-fa4b-5de5-a17f-2921cff9225b', 'a81ffb53-9f45-5c39-ae42-9a103df138ee', 10, 10, 'እኔም ከወደቀ በኋላ አለመዳኑን አይቼ በላዩ ቆሜ ገደልሁት፤ በራሱም ላይ የነበረውን ዘውድ፥ በክንዱም የነበረውን ቢተዋ ወሰድሁ፤ ወደዚህም ወደ ጌታዬ አመጣሁት።”'),
  ('98e69c95-cddf-570f-a2ff-19de40ecea68', '93e280cc-fa4b-5de5-a17f-2921cff9225b', 'a81ffb53-9f45-5c39-ae42-9a103df138ee', 11, 11, 'ዳዊትም ልብሱን ቀደደ፤ ከእርሱም ጋር የነበሩ ሰዎች ሁሉ ልብሳቸውን ቀደዱ።'),
  ('96815fda-2927-577e-a757-ef0f3bf764b8', '93e280cc-fa4b-5de5-a17f-2921cff9225b', 'a81ffb53-9f45-5c39-ae42-9a103df138ee', 12, 12, 'በጦር ወድቀዋልና ለሳኦልና ለልጁ ለዮናታን፥ ለይሁዳም ሕዝብ ለእስራኤልም ወገን እንባ እያፈሰሱ አለቀሱ፤ እስከ ማታም ድረስ ጾሙ።'),
  ('99d6bb56-6ca2-5b38-a5ee-0ea1445a956e', '93e280cc-fa4b-5de5-a17f-2921cff9225b', 'a81ffb53-9f45-5c39-ae42-9a103df138ee', 13, 13, 'ዳዊትም ወሬውን ያመጣለትን ጐልማሳ፥ “አንተ ከወዴት ነህ?” አለው፤ እርሱም፥ “እኔ የመጻተኛው የአማሌቃዊው ልጅ ነኝ” ብሎ መለሰለት።'),
  ('7bbb384c-0db0-5363-a3c0-d6dba6f156fd', '93e280cc-fa4b-5de5-a17f-2921cff9225b', 'a81ffb53-9f45-5c39-ae42-9a103df138ee', 14, 14, 'ዳዊትም፥ “ትገድለው ዘንድ እግዚአብሔር በቀባው ላይ እጅህን ስትዘረጋ እንዴት አልፈራህም?” አለው።'),
  ('98f6a673-f33f-5148-aba5-da201bb1d9be', '93e280cc-fa4b-5de5-a17f-2921cff9225b', 'a81ffb53-9f45-5c39-ae42-9a103df138ee', 15, 15, 'ዳዊትም ከብላቴኖቹ አንዱን ጠርቶ፥ “ሂድና ግደለው” አለው፤ ገደለውም።'),
  ('4c5c6a2b-7718-5229-a30d-0eddf774c240', '93e280cc-fa4b-5de5-a17f-2921cff9225b', 'a81ffb53-9f45-5c39-ae42-9a103df138ee', 16, 16, 'ዳዊትም፥ “እግዚአብሔር የቀባውን እኔ ገድያለሁ ብሎ አፍህ በላይህ መስክሮአልና ደምህ በራስህ ላይ ይሁን” አለው።')
